def format_phone_display(value):
    raw = (value or "").strip()
    digits = re.sub(r"\D+", "", raw)
    if len(digits) == 11 and digits.startswith("1"):
        digits = digits[1:]
    if len(digits) == 10:
        return f"({digits[0:3]}){digits[3:6]}-{digits[6:10]}"
    return raw


app.jinja_env.filters["fmt_phone"] = format_phone_display


def parse_json_object(raw, default=None):
    if isinstance(raw, dict):
        return raw
    if raw is None:
        return {} if default is None else default
    text = str(raw).strip()
    if not text:
        return {} if default is None else default
    try:
        parsed = json.loads(text)
        return parsed if isinstance(parsed, dict) else ({} if default is None else default)
    except Exception:
        return {} if default is None else default


def parse_flexible_datetime(value):
    if not value:
        return None
    text = str(value).strip()
    if not text:
        return None
    for fmt in ("%Y-%m-%d %H:%M:%S", "%Y-%m-%dT%H:%M:%S"):
        try:
            return datetime.strptime(text[:19], fmt)
        except ValueError:
            continue
    try:
        normalized = text.replace("Z", "+00:00")
        dt = datetime.fromisoformat(normalized)
        if dt.tzinfo is not None:
            return dt.astimezone(timezone.utc).replace(tzinfo=None)
        return dt
    except ValueError:
        return None


def format_long_date(value):
    dt = parse_flexible_datetime(value)
    if dt is None:
        return value or "-"
    return f"{dt.strftime('%A, %B')} {dt.day}, {dt.year}"


def format_est_datetime(value):
    dt = parse_flexible_datetime(value)
    if dt is None:
        return value or "-"
    dt_utc = dt.replace(tzinfo=timezone.utc)
    dt_est = dt_utc.astimezone(EST_TZ)
    return f"{dt_est.strftime('%A, %B')} {dt_est.day}, {dt_est.year} {dt_est.strftime('%I:%M %p')} ET"


app.jinja_env.filters["fmt_long_date"] = format_long_date
app.jinja_env.filters["fmt_est_datetime"] = format_est_datetime


def linkify_note(value):
    text = (value or "").strip()
    if not text:
        return ""
    safe = (
        text.replace("&", "&amp;")
        .replace("<", "&lt;")
        .replace(">", "&gt;")
    )
    safe = re.sub(
        r"([A-Za-z][A-Za-z0-9\.\-'\s]{1,80})\s+\((/person/\d+(?:\?property_id=\d+)?)\)",
        r'<a href="\2">\1</a>',
        safe,
    )
    safe = re.sub(
        r"(?<![\w\"'=])(https?://[^\s<]+)",
        r'<a href="\1" target="_blank">\1</a>',
        safe,
    )
    safe = re.sub(
        r"(?<![\w\"'=])(/person/\d+(?:\?property_id=\d+)?)",
        r'<a href="\1">\1</a>',
        safe,
    )
    return safe


app.jinja_env.filters["linkify_note"] = linkify_note


def app_auth_is_configured():
    if not APP_AUTH_ENABLED:
        return False
    if not APP_AUTH_USERNAME:
        return False
    return bool(APP_AUTH_PASSWORD_HASH or APP_AUTH_PASSWORD)


def verify_app_login(username, password):
    if not app_auth_is_configured():
        return False
    if not hmac.compare_digest((username or "").strip(), APP_AUTH_USERNAME):
        return False
    candidate = password or ""
    if APP_AUTH_PASSWORD_HASH:
        try:
            return check_password_hash(APP_AUTH_PASSWORD_HASH, candidate)
        except Exception:
            return False
    return hmac.compare_digest(candidate, APP_AUTH_PASSWORD)


def is_safe_next_path(value):
    target = (value or "").strip()
    if not target:
        return False
    if target.startswith("//"):
        return False
    parsed = urlsplit(target)
    if parsed.scheme or parsed.netloc:
        return False
    return target.startswith("/")


@app.context_processor
def inject_auth_state():
    return {
        "auth_enabled": APP_AUTH_ENABLED,
        "auth_user": session.get("auth_user", ""),
    }


@app.before_request
def require_login_if_enabled():
    if RUN_BACKGROUND_WORKERS:
        # Start idempotent worker threads when running under Gunicorn.
        start_bulk_sms_worker()
        start_email_validation_queue_worker()
        start_email_poll_worker()
        start_clever_leads_worker()
        start_untitled_leads_worker()
        start_website_leads_hold_worker()
        start_ads_dashboard_worker()
        if REFERRAL_MARKET_AUTO_REFRESH_ENABLED:
            start_referral_on_market_worker()
        start_reisift_new_records_worker()
        start_call_recording_worker()
        start_sms_analysis_worker()
        start_agent_refresh_worker()
    if not APP_AUTH_ENABLED:
        return None
    integration_api_allowlist = {
        "/api/webhooks/smrtphone/events",
        "/api/phone-activity/rollups",
        "/api/phone-activity/rollups/",
        "/api/webhooks/clever/events",
        "/api/call-recording-jobs",
        "/api/integrations/agent-trace/search",
        "/api/integrations/agent-trace/property",
        "/api/integrations/agents/lead-watch",
        "/api/integrations/agents/rerun-today",
        "/api/integrations/agents/reset-associations",
        "/api/integrations/contact-context/upsert",
    }
    if request.path in integration_api_allowlist:
        try:
            ensure_db()
            db = get_db()
            if integration_auth_ok(db, request):
                return None
        except Exception:
            pass
    endpoint = request.endpoint or ""
    if endpoint in {"login", "logout", "static"}:
        return None
    if request.path.startswith("/static/") or request.path == "/healthz":
        return None
    # Third-party callbacks must stay unauthenticated.
    if request.path.startswith("/webhooks/"):
        return None
    if request.path.startswith("/oauth/amazon/") or request.path.startswith("/oauth/roku/"):
        return None
    # External integrations authenticate via API key header.
    if request.path.startswith("/api/slack-comp-requests/"):
        return None
    if request.path.startswith("/api/integrations/"):
        return None
    if session.get("auth_ok"):
        return None
    if request.path.startswith("/api/"):
        return jsonify({"error": "Authentication required"}), 401
    next_target = request.full_path if request.query_string else request.path
    return redirect(url_for("login", next=next_target))


