def get_db():
    if "db" not in g:
        g.db = open_sqlite_connection()
    return g.db


def execute_with_retry(db, sql, params=(), retries=8, base_delay=0.2):
    for attempt in range(retries):
        try:
            return db.execute(sql, params)
        except sqlite3.OperationalError as exc:
            if "locked" not in str(exc).lower() or attempt >= retries - 1:
                raise
            time.sleep(base_delay * (attempt + 1))


def commit_with_retry(db, retries=8, base_delay=0.2):
    for attempt in range(retries):
        try:
            db.commit()
            return
        except sqlite3.OperationalError as exc:
            if "locked" not in str(exc).lower() or attempt >= retries - 1:
                raise
            time.sleep(base_delay * (attempt + 1))


@contextmanager
def agent_pipeline_guard(purpose="agent_pipeline", timeout_seconds=20):
    wait_seconds = max(1, int(timeout_seconds or 20))
    acquired = AGENT_PIPELINE_LOCK.acquire(timeout=wait_seconds)
    if not acquired:
        raise TimeoutError(f"agent pipeline busy ({purpose})")
    try:
        yield
    finally:
        AGENT_PIPELINE_LOCK.release()


@app.teardown_appcontext
def close_db(_error):
    db = g.pop("db", None)
    if db is not None:
        db.close()


def ensure_column(db, table_name, column_name, definition):
    cols = [r["name"] for r in db.execute(f"PRAGMA table_info({table_name})").fetchall()]
    if column_name not in cols:
        db.execute(f"ALTER TABLE {table_name} ADD COLUMN {definition}")


