def _extract_propertyleads_fields(payload):
    first_name = (
        extract_first_string_by_keys(
            payload,
            ["first_name", "firstName", "firstname", "First_Name", "First Name", "owner_first_name"],
        )
        or ""
    ).strip()
    last_name = (
        extract_first_string_by_keys(
            payload,
            ["last_name", "lastName", "lastname", "Last_Name", "Last Name", "owner_last_name"],
        )
        or ""
    ).strip()
    seller_name = " ".join([part for part in [first_name, last_name] if part]).strip()
    if not seller_name:
        seller_name = (
            extract_first_string_by_keys(payload, ["seller_name", "name", "full_name", "owner_name", "customer_name"])
            or ""
        ).strip()
        if seller_name and (not first_name or not last_name):
            parsed_name = _parse_seller_name_for_owner(seller_name)
            first_name = first_name or parsed_name.get("first_name") or ""
            last_name = last_name or parsed_name.get("last_name") or ""
    street = (
        extract_first_string_by_keys(
            payload,
            ["address", "property_address", "propertyAddress", "street_address", "streetAddress", "Property_Address"],
        )
        or ""
    ).strip()
    city = (
        extract_first_string_by_keys(payload, ["city", "City"])
        or ""
    ).strip()
    state = (
        extract_first_string_by_keys(payload, ["state", "State"])
        or ""
    ).strip().upper()
    postal_code = (
        extract_first_string_by_keys(payload, ["zip", "Zip", "zipcode", "postal_code", "postalCode"])
        or ""
    ).strip()
    address = ", ".join(
        [part for part in [street, ", ".join([p for p in [city, state] if p]).strip(), postal_code] if part]
    ).strip(", ")
    phone = normalize_phone(
        extract_first_string_by_keys(
            payload,
            [
                "phone",
                "phone_number",
                "phoneNumber",
                "mobile",
                "mobile_phone",
                "mobilePhone",
                "primary_phone",
                "Primary_Phone",
            ],
        )
        or ""
    )
    email = normalize_email(
        extract_first_string_by_keys(payload, ["email", "email_address", "emailAddress", "Email"])
        or ""
    )
    lead_id = (
        extract_first_string_by_keys(
            payload,
            ["lead_id", "leadId", "leadID", "Lead ID", "record_id", "recordId", "id", "uuid"],
        )
        or ""
    ).strip()
    return {
        "lead_id": lead_id,
        "county": (extract_first_string_by_keys(payload, ["county", "County"]) or "").strip(),
        "first_name": first_name,
        "last_name": last_name,
        "seller_name": seller_name,
        "street": street,
        "city": city,
        "state": state,
        "postal_code": postal_code,
        "address": address,
        "phone": phone,
        "email": email,
        "asking_price": (extract_first_string_by_keys(payload, ["asking_price", "Asking_Price", "askingPrice"]) or "").strip(),
        "how_long_owned_property": (
            extract_first_string_by_keys(payload, ["how_long_owned_property", "How_Long_Owned_Property"])
            or ""
        ).strip(),
        "repairs_maintenance_needed": (
            extract_first_string_by_keys(payload, ["repairs_maintenance_needed", "Repairs_Maintenance_Needed"])
            or ""
        ).strip(),
        "anyone_living_in_house": (
            extract_first_string_by_keys(payload, ["anyone_living_in_house", "Anyone_Living_In_House"])
            or ""
        ).strip(),
        "reason_for_selling": (
            extract_first_string_by_keys(payload, ["reason_for_selling", "Reason_for_Selling"])
            or ""
        ).strip(),
        "time_frame_to_sell": (
            extract_first_string_by_keys(payload, ["time_frame_to_sell", "Time_Frame_To_Sell"])
            or ""
        ).strip(),
        "comments": (extract_first_string_by_keys(payload, ["comments", "Comments"]) or "").strip(),
        "feedback": (extract_first_string_by_keys(payload, ["feedback", "Feedback"]) or "").strip(),
        "date_created": (extract_first_string_by_keys(payload, ["date_created", "Date Created"]) or "").strip(),
        "lead_cost": (extract_first_string_by_keys(payload, ["lead_cost", "Lead_Cost"]) or "").strip(),
    }


def _derive_propertyleads_lead_key(fields, payload):
    fields = fields if isinstance(fields, dict) else {}
    lead_id = str(fields.get("lead_id") or "").strip()
    if lead_id:
        return f"propertyleads:{lead_id}"
    email = normalize_email(fields.get("email") or "")
    if email:
        return f"propertyleads_email:{email}"
    phone = normalize_phone(fields.get("phone") or "")
    if phone:
        return f"propertyleads_phone:{phone}"
    address = _normalize_address_key(fields.get("address") or "")
    if address:
        return f"propertyleads_address:{address}"
    payload_hash = hashlib.sha256(json.dumps(payload or {}, sort_keys=True, default=str).encode("utf-8")).hexdigest()[:20]
    return f"propertyleads_payload:{payload_hash}"


def upsert_propertyleads_submission(
    db,
    fields,
    payload,
    *,
    status="captured",
    source_label="webhook",
    processing_result=None,
    reisift_property_uuid="",
    reisift_owner_uuid="",
    reisift_status=None,
    local_property_id=0,
    processed_at="",
):
    fields = fields if isinstance(fields, dict) else {}
    payload = payload if isinstance(payload, dict) else {}
    lead_key = _derive_propertyleads_lead_key(fields, payload)
    processing_blob = json.dumps(processing_result or {}) if processing_result is not None else None
    existing = db.execute(
        "SELECT id FROM propertyleads_lead_submissions WHERE lead_key = ? LIMIT 1",
        (lead_key,),
    ).fetchone()
    normalized_reisift_status = None
    if reisift_status is not None:
        normalized_reisift_status = normalize_whitespace(reisift_status or "new lead").lower() or "new lead"
    params = (
        str(fields.get("lead_id") or "").strip(),
        str(reisift_property_uuid or "").strip(),
        str(reisift_owner_uuid or "").strip(),
        str(fields.get("address") or "").strip(),
        normalize_phone(fields.get("phone") or "") or str(fields.get("phone") or "").strip(),
        normalize_email(fields.get("email") or "") or str(fields.get("email") or "").strip(),
        str(fields.get("seller_name") or "").strip(),
        "ppl_submission",
        str(fields.get("county") or "").strip(),
        str(fields.get("lead_cost") or "").strip(),
        str(source_label or "").strip(),
        json.dumps(payload or {}),
        processing_blob,
        str(status or "captured").strip() or "captured",
        normalized_reisift_status,
        int(local_property_id or 0),
        str(processed_at or "").strip() or None,
    )
    if existing:
        db.execute(
            """
            UPDATE propertyleads_lead_submissions
            SET lead_id = ?,
                reisift_property_uuid = ?,
                reisift_owner_uuid = ?,
                latest_address = ?,
                latest_phone = ?,
                latest_email = ?,
                latest_name = ?,
                latest_stage = ?,
                county = ?,
                lead_cost = ?,
                source_label = ?,
                latest_payload_json = ?,
                processing_result_json = COALESCE(?, processing_result_json),
                status = ?,
                reisift_status = COALESCE(?, reisift_status),
                local_property_id = COALESCE(NULLIF(?, 0), local_property_id),
                processed_at = COALESCE(?, processed_at),
                last_received_at = CURRENT_TIMESTAMP
            WHERE id = ?
            """,
            params + (existing["id"],),
        )
    else:
        db.execute(
            """
            INSERT INTO propertyleads_lead_submissions
                (lead_key, lead_id, reisift_property_uuid, reisift_owner_uuid, latest_address, latest_phone, latest_email,
                 latest_name, latest_stage, county, lead_cost, source_label, latest_payload_json, processing_result_json,
                 status, reisift_status, local_property_id, processed_at)
            VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, COALESCE(?, 'new lead'), ?, ?)
            """,
            (lead_key,) + params,
        )
    return lead_key


def _build_propertyleads_notes(payload, fields, source_label="webhook"):
    lines = [
        "Source: PropertyLeads.com PPL",
        f"Ingest Source: {source_label}",
    ]
    ordered_pairs = [
        ("Lead ID", fields.get("lead_id")),
        ("Date Created", fields.get("date_created")),
        ("County", fields.get("county")),
        ("Name", fields.get("seller_name")),
        ("Address", fields.get("address")),
        ("Phone", fields.get("phone")),
        ("Email", fields.get("email")),
        ("Asking Price", fields.get("asking_price")),
        ("How Long Owned Property", fields.get("how_long_owned_property")),
        ("Repairs / Maintenance Needed", fields.get("repairs_maintenance_needed")),
        ("Anyone Living In House", fields.get("anyone_living_in_house")),
        ("Reason For Selling", fields.get("reason_for_selling")),
        ("Time Frame To Sell", fields.get("time_frame_to_sell")),
        ("Comments", fields.get("comments")),
        ("Feedback", fields.get("feedback")),
        ("Lead Cost", fields.get("lead_cost")),
    ]
    for label, value in ordered_pairs:
        if value:
            lines.append(f"{label}: {value}")
    form_payload = payload.get("form") if isinstance(payload.get("form"), dict) else {}
    used_labels = {label for label, _ in ordered_pairs}
    for key in sorted(form_payload.keys(), key=lambda item: str(item).lower()):
        label = str(key or "").strip()
        value = str(form_payload.get(key) or "").strip()
        if not label or not value or label in used_labels:
            continue
        lines.append(f"{label}: {value}")
    return "\n".join(lines)


def _sync_propertyleads_existing_reisift_record(token, property_uuid, fields, notes, owner_uuid=""):
    property_uuid = normalize_uuid(property_uuid)
    owner_uuid = normalize_uuid(owner_uuid)
    fields = fields if isinstance(fields, dict) else {}
    out = {
        "ok": bool(property_uuid),
        "property_uuid": property_uuid,
        "owner_uuid": owner_uuid,
        "status_sync": None,
        "list_sync": None,
        "tag_sync": None,
        "note_sync": None,
        "contact_sync": None,
        "warnings": [],
    }
    if not token or not property_uuid:
        out["ok"] = False
        out["warnings"].append("missing_token_or_property_uuid")
        return out

    try:
        payload = fetch_reisift_property_payload(token, property_uuid)
        owner_uuid = owner_uuid or normalize_uuid(_reisift_find_owner_uuid(payload))
        out["owner_uuid"] = owner_uuid
    except Exception as exc:
        out["warnings"].append(f"fetch_property_failed: {exc}")

    try:
        out["status_sync"] = reisift_update_property_status(token, property_uuid, "new_lead")
    except Exception as exc:
        out["warnings"].append(f"status_sync_failed: {exc}")

    try:
        out["list_sync"] = reisift_sync_property_lists(token, property_uuid, ["PropertyLeadsPPL"])
    except Exception as exc:
        out["warnings"].append(f"list_sync_failed: {exc}")

    try:
        out["tag_sync"] = reisift_sync_property_tags(token, property_uuid, tags_to_add=["PropertyLeadsPPL"])
    except Exception as exc:
        out["warnings"].append(f"tag_sync_failed: {exc}")

    try:
        out["note_sync"] = reisift_append_property_note(token, property_uuid, notes)
    except Exception as exc:
        out["warnings"].append(f"note_sync_failed: {exc}")

    phone = fields.get("phone") or ""
    email = fields.get("email") or ""
    if owner_uuid and (phone or email):
        try:
            out["contact_sync"] = reisift_upsert_owner_contacts(
                token,
                owner_uuid,
                [{"number": phone, "type": "UNKNOWN"}] if phone else [],
                [email] if email else [],
            )
        except Exception as exc:
            out["warnings"].append(f"contact_sync_failed: {exc}")
    elif phone or email:
        out["warnings"].append("contact_sync_skipped_missing_owner_uuid")

    out["ok"] = True
    return out


def process_propertyleads_ppl_payload(db, payload, source_label="webhook"):
    if not isinstance(payload, dict):
        return {"ok": False, "error": "Invalid payload object.", "error_type": "validation", "slack_sent": False}
    fields = _extract_propertyleads_fields(payload)
    local_property_id = 0
    local_ctx = {}
    lead_key = _derive_propertyleads_lead_key(fields, payload)
    try:
        local_ctx = ensure_local_property_for_submitted_lead(
            db,
            source_label="PropertyLeads PPL",
            address=fields.get("address") or "",
            street=fields.get("street") or "",
            city=fields.get("city") or "",
            state=fields.get("state") or "",
            postal_code=fields.get("postal_code") or "",
            seller_name=fields.get("seller_name") or "",
            first_name=fields.get("first_name") or "",
            last_name=fields.get("last_name") or "",
            phone=fields.get("phone") or "",
            email=fields.get("email") or "",
            lead_key=lead_key,
            payload=payload,
        )
        local_property_id = int(local_ctx.get("property_id") or 0)
    except Exception as exc:
        log_app_error(
            db,
            source="propertyleads_local_property",
            error_message=str(exc),
            details=traceback.format_exc(),
            route="/webhooks/propertyleads/ppl",
            status_code=500,
        )
    lead_key = upsert_propertyleads_submission(
        db,
        fields,
        payload,
        status="received",
        source_label=source_label,
        local_property_id=local_property_id,
    )
    event_key = _derive_propertyleads_event_key(payload)
    if not event_key:
        payload_hash = hashlib.sha256(json.dumps(payload, sort_keys=True, default=str).encode("utf-8")).hexdigest()[:20]
        event_key = f"propertyleads:{payload_hash}"
    is_new = upsert_integration_event(db, PROPERTYLEADS_PPL_EVENT_SOURCE, event_key, payload)
    db.commit()
    if not is_new:
        upsert_propertyleads_submission(
            db,
            fields,
            payload,
            status="duplicate_event",
            source_label=source_label,
            processing_result={"ok": True, "duplicate": True, "event_key": event_key, "lead_key": lead_key},
            local_property_id=local_property_id,
        )
        db.commit()
        return {"ok": True, "duplicate": True, "event_key": event_key, "lead_key": lead_key, "slack_sent": False}

    if not fields.get("address"):
        err = "PropertyLeads payload missing property address."
        upsert_propertyleads_submission(
            db,
            fields,
            payload,
            status="failed_validation",
            source_label=source_label,
            processing_result={"ok": False, "event_key": event_key, "lead_key": lead_key, "error": err, "error_type": "validation"},
            local_property_id=local_property_id,
        )
        log_app_error(
            db,
            source="propertyleads_ppl_ingest",
            error_message=err,
            details=json.dumps({"event_key": event_key, "payload": payload}),
            route="/webhooks/propertyleads/ppl",
            status_code=400,
        )
        try:
            send_slack_notification(
                db,
                "\n".join(
                    [
                        "New PropertyLeads submission received",
                        "Mode: failed",
                        f"Lead ID: {fields.get('lead_id') or '-'}",
                        f"Address: {fields.get('address') or '-'}",
                        f"Name: {fields.get('seller_name') or '-'}",
                        f"Phone: {fields.get('phone') or '-'}",
                        f"Email: {fields.get('email') or '-'}",
                        f"Error: {err}",
                    ]
                ),
                channel="#acquisitions",
            )
        except Exception:
            pass
        db.commit()
        return {
            "ok": False,
            "event_key": event_key,
            "lead_key": lead_key,
            "error": err,
            "error_type": "validation",
            "slack_sent": True,
        }

    notes = _build_propertyleads_notes(payload, fields, source_label=source_label)
    owner_payload = {}
    if fields.get("first_name") or fields.get("last_name"):
        owner_payload["first_name"] = fields.get("first_name") or "Unknown"
        owner_payload["last_name"] = fields.get("last_name") or "Owner"
    if fields.get("email"):
        owner_payload["emails"] = [fields.get("email")]
    if fields.get("phone"):
        owner_payload["phones"] = [{"number": fields.get("phone"), "type": "UNKNOWN", "status": "UNKNOWN"}]
    create_payload = {
        "search": fields.get("address") or "",
        "street": fields.get("street") or "",
        "city": fields.get("city") or "",
        "state": fields.get("state") or "",
        "postal_code": fields.get("postal_code") or "",
        "status": "new_lead",
        "lists": "PropertyLeadsPPL",
        "tags": "PropertyLeadsPPL",
        "notes": notes,
        "owner": owner_payload,
        "skip_map_lookup": True,
    }

    created_uuid = ""
    owner_uuid = ""
    duplicate_existing = False
    duplicate_reason = ""
    contact_sync = None
    note_sync = None
    existing_sync = None
    enrich_result = None
    create_result = None
    mode = "processed"

    try:
        create_result = create_reisift_property_from_search(create_payload)
        created_uuid = str(create_result.get("created_uuid") or "").strip()
        owner_uuid = str(create_result.get("owner_uuid") or "").strip()
        duplicate_existing = bool(create_result.get("duplicate_existing"))
        duplicate_reason = str(create_result.get("duplicate_reason") or "").strip()
        contact_sync = create_result.get("owner_contact_sync")
        if duplicate_existing:
            mode = "sift_duplicate_existing"

        token = reisift_get_access_token() if created_uuid else None
        if token and not owner_uuid and created_uuid:
            try:
                owner_uuid = _reisift_find_owner_uuid(fetch_reisift_property_payload(token, created_uuid)) or owner_uuid
            except Exception:
                pass
        if token and owner_uuid and not contact_sync and not duplicate_existing and (fields.get("phone") or fields.get("email")):
            contact_sync = reisift_upsert_owner_contacts(
                token,
                owner_uuid,
                [{"number": fields.get("phone"), "type": "UNKNOWN"}] if fields.get("phone") else [],
                [fields.get("email")] if fields.get("email") else [],
            )
        if token and created_uuid and duplicate_existing:
            existing_sync = _sync_propertyleads_existing_reisift_record(token, created_uuid, fields, notes, owner_uuid=owner_uuid)
            owner_uuid = existing_sync.get("owner_uuid") or owner_uuid
            contact_sync = existing_sync.get("contact_sync") or contact_sync
            note_sync = existing_sync.get("note_sync")
        if token and created_uuid and not duplicate_existing:
            enrich_result = create_result.get("enrich")
        if local_property_id > 0:
            _set_local_property_uuid(db, local_property_id, created_uuid)
            _set_local_owner_uuid(db, local_property_id, owner_uuid)

        sift_link = _sift_record_url(created_uuid)
        slack_lines = [
            "New PropertyLeads submission received",
            f"Mode: {mode}",
            f"Lead ID: {fields.get('lead_id') or '-'}",
            f"County: {fields.get('county') or '-'}",
            f"Address: {fields.get('address') or '-'}",
            f"Name: {fields.get('seller_name') or '-'}",
            f"Phone: {fields.get('phone') or '-'}",
            f"Email: {fields.get('email') or '-'}",
            f"ReiSift Record: {sift_link or '-'}",
        ]
        if duplicate_reason:
            slack_lines.append(f"Reason: {duplicate_reason}")
        send_slack_notification(db, "\n".join(slack_lines), channel="#acquisitions")
        upsert_propertyleads_submission(
            db,
            fields,
            payload,
            status="processed",
            source_label=source_label,
            processing_result={
                "ok": True,
                "event_key": event_key,
                "lead_key": lead_key,
                "created_uuid": created_uuid,
                "owner_uuid": owner_uuid,
                "duplicate_existing": duplicate_existing,
                "duplicate_reason": duplicate_reason,
                "contact_sync": contact_sync,
                "note_sync": note_sync,
                "existing_sync": existing_sync,
            },
            reisift_property_uuid=created_uuid,
            reisift_owner_uuid=owner_uuid,
            reisift_status="new lead",
            local_property_id=local_property_id,
            processed_at=format_db_time(datetime.utcnow()),
        )
        db.commit()
        return {
            "ok": True,
            "event_key": event_key,
            "lead_key": lead_key,
            "created_uuid": created_uuid,
            "owner_uuid": owner_uuid,
            "duplicate_existing": duplicate_existing,
            "duplicate_reason": duplicate_reason,
            "contact_sync": contact_sync,
            "note_sync": note_sync,
            "existing_sync": existing_sync,
            "enrich": enrich_result,
            "create_result": create_result,
            "slack_sent": True,
        }
    except Exception as exc:
        err = str(exc)
        log_app_error(
            db,
            source="propertyleads_ppl_ingest",
            error_message=err,
            details=traceback.format_exc(),
            route="/webhooks/propertyleads/ppl",
            status_code=500,
        )
        recovery_result = None
        try:
            token = reisift_get_access_token()
            existing = reisift_find_existing_property_by_address(
                token,
                street=fields.get("street") or "",
                city=fields.get("city") or "",
                state=fields.get("state") or "",
                postal_code=fields.get("postal_code") or "",
                search_text=fields.get("address") or "",
            )
            recovered_uuid = normalize_uuid(existing.get("uuid") or "")
            if recovered_uuid:
                created_uuid = recovered_uuid
                existing_sync = _sync_propertyleads_existing_reisift_record(token, created_uuid, fields, notes, owner_uuid=owner_uuid)
                owner_uuid = existing_sync.get("owner_uuid") or owner_uuid
                contact_sync = existing_sync.get("contact_sync")
                note_sync = existing_sync.get("note_sync")
                if local_property_id > 0:
                    _set_local_property_uuid(db, local_property_id, created_uuid)
                    _set_local_owner_uuid(db, local_property_id, owner_uuid)
                recovery_result = {
                    "ok": True,
                    "recovered_uuid": created_uuid,
                    "matched_existing": existing,
                    "existing_sync": existing_sync,
                    "original_error": err,
                }
                sift_link = _sift_record_url(created_uuid)
                slack_lines = [
                    "New PropertyLeads submission received",
                    "Mode: sift_existing_recovered",
                    f"Lead ID: {fields.get('lead_id') or '-'}",
                    f"County: {fields.get('county') or '-'}",
                    f"Address: {fields.get('address') or '-'}",
                    f"Name: {fields.get('seller_name') or '-'}",
                    f"Phone: {fields.get('phone') or '-'}",
                    f"Email: {fields.get('email') or '-'}",
                    f"ReiSift Record: {sift_link or '-'}",
                    f"Recovered From Error: {err}",
                ]
                send_slack_notification(db, "\n".join(slack_lines), channel="#acquisitions")
                upsert_propertyleads_submission(
                    db,
                    fields,
                    payload,
                    status="processed",
                    source_label=source_label,
                    processing_result={
                        "ok": True,
                        "event_key": event_key,
                        "lead_key": lead_key,
                        "created_uuid": created_uuid,
                        "owner_uuid": owner_uuid,
                        "duplicate_existing": True,
                        "duplicate_reason": "Recovered existing REISift record after create/update failure.",
                        "contact_sync": contact_sync,
                        "note_sync": note_sync,
                        "existing_sync": existing_sync,
                        "recovery_result": recovery_result,
                    },
                    reisift_property_uuid=created_uuid,
                    reisift_owner_uuid=owner_uuid,
                    reisift_status="new lead",
                    local_property_id=local_property_id,
                    processed_at=format_db_time(datetime.utcnow()),
                )
                db.commit()
                return {
                    "ok": True,
                    "event_key": event_key,
                    "lead_key": lead_key,
                    "created_uuid": created_uuid,
                    "owner_uuid": owner_uuid,
                    "duplicate_existing": True,
                    "duplicate_reason": "Recovered existing REISift record after create/update failure.",
                    "contact_sync": contact_sync,
                    "note_sync": note_sync,
                    "existing_sync": existing_sync,
                    "recovery_result": recovery_result,
                    "slack_sent": True,
                }
        except Exception as recovery_exc:
            recovery_result = {"ok": False, "error": str(recovery_exc), "original_error": err}
            log_app_error(
                db,
                source="propertyleads_ppl_existing_recovery",
                error_message=str(recovery_exc),
                details=traceback.format_exc(),
                route="/webhooks/propertyleads/ppl",
                status_code=500,
            )

        sift_link = _sift_record_url(created_uuid)
        upsert_propertyleads_submission(
            db,
            fields,
            payload,
            status="failed",
            source_label=source_label,
            processing_result={
                "ok": False,
                "event_key": event_key,
                "lead_key": lead_key,
                "created_uuid": created_uuid,
                "error": err,
                "error_type": "server",
                "recovery_result": recovery_result,
            },
            reisift_property_uuid=created_uuid,
            reisift_owner_uuid=owner_uuid,
            reisift_status="new lead",
            local_property_id=local_property_id,
            processed_at=format_db_time(datetime.utcnow()),
        )
        try:
            send_slack_notification(
                db,
                "\n".join(
                    [
                        "New PropertyLeads submission received",
                        "Mode: failed",
                        f"Lead ID: {fields.get('lead_id') or '-'}",
                        f"County: {fields.get('county') or '-'}",
                        f"Address: {fields.get('address') or '-'}",
                        f"Name: {fields.get('seller_name') or '-'}",
                        f"Phone: {fields.get('phone') or '-'}",
                        f"Email: {fields.get('email') or '-'}",
                        f"ReiSift Record: {sift_link or '-'}",
                        f"Error: {err}",
                    ]
                ),
                channel="#acquisitions",
            )
        except Exception:
            pass
        db.commit()
        return {
            "ok": False,
            "event_key": event_key,
            "lead_key": lead_key,
            "created_uuid": created_uuid,
            "error": err,
            "error_type": "server",
            "slack_sent": True,
        }


def send_smrtphone_sms(to_number, message_body, from_number=None):
    api_key = get_smrtphone_api_key()
    if not api_key:
        raise ValueError("SmrtPhone API key is not set")

    headers = {
        "X-Auth-smrtPhone": api_key,
    }
    payload = {
        "from": (from_number or SMRTPHONE_FROM_NUMBER).strip(),
        "to": to_number,
        "message": message_body,
    }
    response = requests.post(SMRTPHONE_SEND_URL, data=payload, headers=headers, timeout=20)

    raw = {}
    try:
        raw = response.json()
    except ValueError:
        raw = {"raw_text": response.text}

    if not response.ok:
        raise ValueError(f"SmrtPhone send failed ({response.status_code}): {raw}")

    sms_id = extract_sms_id_from_payload(raw)
    if not sms_id and isinstance(raw, dict):
        raw_text = str(raw.get("raw_text") or "")
        m = re.search(r"(SM[a-fA-F0-9]{16,}|smsId[:=]\s*([A-Za-z0-9\-_]+))", raw_text)
        if m:
            sms_id = (m.group(2) or m.group(1) or "").replace("smsId=", "").replace("smsId:", "").strip()
    status = "Queued"
    if isinstance(raw, dict) and raw.get("status"):
        status = str(raw["status"]).strip().title()
    elif sms_id:
        status = "Sent"

    return {"sms_id": sms_id, "status": status, "raw": raw}


def fetch_smrtphone_recording_url(call_sid):
    api_key = get_smrtphone_api_key()
    if not api_key:
        raise ValueError("SmrtPhone API key is not set")
    clean_sid = (call_sid or "").strip()
    if not clean_sid:
        raise ValueError("call_sid is required")
    headers = {"X-Auth-smrtPhone": api_key}
    response = requests.get(
        "https://phone.smrt.studio/api/getRecordingUrl",
        headers=headers,
        params={"call_sid": clean_sid},
        timeout=20,
    )
    try:
        body = response.json()
    except ValueError:
        body = {"raw_text": response.text}
    if not response.ok:
        raise ValueError(f"SmrtPhone recording lookup failed ({response.status_code}): {body}")
    recording_url = ""
    if isinstance(body, dict):
        for key in ("recording_url", "recordingUrl", "url", "recording"):
            val = body.get(key)
            if isinstance(val, str) and val.strip():
                recording_url = val.strip()
                break
        if not recording_url:
            data = body.get("data")
            if isinstance(data, dict):
                for key in ("recording_url", "recordingUrl", "url", "recording"):
                    val = data.get(key)
                    if isinstance(val, str) and val.strip():
                        recording_url = val.strip()
                        break
    return {"call_sid": clean_sid, "recording_url": recording_url, "raw": body}


def transcribe_recording_with_openai(audio_bytes, filename="call_recording.mp3", mime_type="audio/mpeg"):
    api_key = os.getenv("OPENAI_API_KEY", "").strip()
    if not api_key:
        raise ValueError("OPENAI_API_KEY is not set")
    if not audio_bytes:
        raise ValueError("audio_bytes is empty")
    model = os.getenv("OPENAI_TRANSCRIBE_MODEL", "gpt-4o-mini-transcribe").strip() or "gpt-4o-mini-transcribe"
    files = {
        "file": (filename, io.BytesIO(audio_bytes), mime_type or "application/octet-stream"),
    }
    data = {"model": model}
    response = requests.post(
        "https://api.openai.com/v1/audio/transcriptions",
        headers={"Authorization": f"Bearer {api_key}"},
        data=data,
        files=files,
        timeout=120,
    )
    response.raise_for_status()
    payload = response.json()
    transcript = str(payload.get("text") or "").strip()
    if not transcript:
        raise ValueError("No transcript text returned")
    return {"transcript": transcript, "raw": payload}


def _infer_call_direction_from_numbers(db, from_number, to_number, agent_user_name=""):
    system_numbers = _known_system_numbers(db, refresh_seconds=300)
    from_norm = normalize_phone(from_number)
    to_norm = normalize_phone(to_number)
    if from_norm and from_norm in system_numbers and (not to_norm or to_norm not in system_numbers):
        return "Outbound"
    if to_norm and to_norm in system_numbers and (not from_norm or from_norm not in system_numbers):
        return "Inbound"
    # smrtPhone often includes userName for team-originated outbound calls.
    if (agent_user_name or "").strip() and from_norm:
        return "Outbound"
    if from_norm and not to_norm and from_norm in system_numbers:
        return "Outbound"
    if to_norm and not from_norm and to_norm in system_numbers:
        return "Inbound"
    return "Unknown"


def _lookup_call_party_names_from_smrt_events(db, call_sid):
    sid = (call_sid or "").strip()
    if not sid:
        return "", ""
    like_tokens = (
        f'%\"callId\": \"{sid}\"%',
        f'%\"callId\":\"{sid}\"%',
        f'%\"call_sid\": \"{sid}\"%',
        f'%\"call_sid\":\"{sid}\"%',
    )
    rows = db.execute(
        """
        SELECT payload_json
        FROM smrtphone_webhook_events
        WHERE event_type = 'call_completed'
          AND (
              payload_json LIKE ?
              OR payload_json LIKE ?
              OR payload_json LIKE ?
              OR payload_json LIKE ?
          )
        ORDER BY id DESC
        LIMIT 20
        """,
        like_tokens,
    ).fetchall()
    for r in rows:
        payload = parse_json_object(r["payload_json"] or "{}")
        webhook = payload.get("webhook") if isinstance(payload.get("webhook"), dict) else payload
        caller = (
            extract_first_string_by_keys(webhook, ["userName", "user_name", "agentName", "callerName"])
            or extract_first_string_by_keys(webhook, ["callerIdName", "caller_id_name"])
            or ""
        ).strip()
        callee = (extract_first_string_by_keys(webhook, ["contactName", "contact_name"]) or "").strip()
        if caller or callee:
            return caller, callee
    return "", ""


def _word_count(text):
    return len(re.findall(r"[A-Za-z0-9']+", text or ""))


def _apply_call_analysis_guardrails(transcript_text, analysis, context):
    transcript = (transcript_text or "").strip()
    low = transcript.lower()
    analysis = dict(analysis or {})
    direction = (context.get("direction") or analysis.get("call_direction") or "Unknown").strip().title()
    caller_name = (context.get("caller_name") or "").strip() or "Caller"
    callee_name = (context.get("callee_name") or "").strip() or "recipient"
    call_outcome = (context.get("call_outcome") or "").strip().lower()

    voicemail_markers = [
        "please leave your message",
        "leave your message",
        "at the tone",
        "after the tone",
        "mailbox",
        "voicemail",
        "voice mail",
    ]
    mailbox_full = "mailbox is full" in low or "mailbox full" in low
    looks_voicemail = any(m in low for m in voicemail_markers)
    short_audio = _word_count(transcript) <= 18

    if mailbox_full:
        analysis["call_outcome_type"] = "No Answer"
        analysis["voicemail_left"] = "No"
        analysis["call_stage"] = "Intro Outreach"
        analysis["sentiment"] = "Neutral"
        analysis["seller_interest"] = "Unknown"
        analysis["next_best_step"] = "Follow Up"
        analysis["next_step_reason"] = "Mailbox is full; voicemail channel is not currently usable."
        analysis["line_diagnostics"] = list(
            dict.fromkeys((analysis.get("line_diagnostics") or []) + ["Mailbox full. Prefer SMS or another channel."])
        )
        analysis["summary"] = (
            f"{direction} call from {caller_name} to {callee_name} reached a full voicemail box; "
            "no message could be left and no two-way conversation occurred."
        )
        return analysis

    if looks_voicemail and short_audio:
        analysis["call_outcome_type"] = "Voicemail"
        if call_outcome in NO_ANSWER_OUTCOMES:
            analysis["call_outcome_type"] = "No Answer"
        if (analysis.get("voicemail_left") or "").strip() not in {"Yes", "No"}:
            analysis["voicemail_left"] = "Unknown"
        analysis["call_stage"] = "Intro Outreach"
        analysis["seller_interest"] = "Unknown"
        analysis["sentiment"] = "Neutral"
        analysis["summary"] = (
            f"{direction} call from {caller_name} to {callee_name} reached voicemail; "
            "no clear two-way conversation was captured."
        )
        if not (analysis.get("next_step_reason") or "").strip():
            analysis["next_step_reason"] = "Voicemail/no-answer call; continue follow-up cadence by channel fit."
        if not (analysis.get("caller_intent") or "").strip():
            analysis["caller_intent"] = "Initial outreach"
        if not (analysis.get("next_best_step") or "").strip():
            analysis["next_best_step"] = "Follow Up"
        return analysis

    # Keep "wholesaler" inquiries grounded and consistent for inbound calls.
    if direction == "Inbound" and "wholesaler" in low:
        analysis["call_outcome_type"] = "Answered"
        if not (analysis.get("summary") or "").strip():
            analysis["summary"] = (
                f"Inbound lead call from {caller_name} to {callee_name}. "
                "Caller asked whether the team is a wholesaler."
            )
        if not (analysis.get("caller_intent") or "").strip():
            analysis["caller_intent"] = "Verify investor/wholesaler identity"
        if not (analysis.get("next_best_step") or "").strip():
            analysis["next_best_step"] = "Follow Up"
        if not (analysis.get("next_step_reason") or "").strip():
            analysis["next_step_reason"] = "Clarify fit and continue qualification if lead remains engaged."
        if (analysis.get("voicemail_left") or "").strip() not in {"Yes", "No", "Not Applicable"}:
            analysis["voicemail_left"] = "Not Applicable"

    # Avoid impossible phrasing when transcript is near-empty or highly uncertain.
    if short_audio and "request a package" in (analysis.get("summary") or "").lower():
        analysis["summary"] = (
            f"{direction} call between {caller_name} and {callee_name} was too brief for reliable interpretation."
        )
    return analysis


def _short_text(value, max_len=180):
    text = re.sub(r"\s+", " ", str(value or "").strip())
    if len(text) <= max_len:
        return text
    return text[: max_len - 1].rstrip() + "..."


def _infer_call_direction_without_db(context):
    from_norm = normalize_phone(context.get("from_number") or "")
    to_norm = normalize_phone(context.get("to_number") or "")
    owned = set()
    env_owned = str(SMRTPHONE_OWNED_NUMBERS or "").replace("\n", ",").replace(";", ",")
    for raw in [SMRTPHONE_FROM_NUMBER] + SMRTPHONE_OWNED_DEFAULT_NUMBERS + [x.strip() for x in env_owned.split(",") if x.strip()]:
        n = normalize_phone(raw)
        if n:
            owned.add(n)
    if from_norm and from_norm in owned and (not to_norm or to_norm not in owned):
        return "Outbound"
    if to_norm and to_norm in owned and (not from_norm or from_norm not in owned):
        return "Inbound"
    return "Unknown"


def compose_call_summary(context, analysis, transcript_text):
    direction_candidate = (analysis.get("call_direction") or "").strip().title()
    if direction_candidate in {"", "Unknown", "Undetermined"}:
        direction_candidate = (context.get("direction") or "").strip().title()
    if direction_candidate in {"", "Unknown", "Undetermined"}:
        direction_candidate = _infer_call_direction_without_db(context)
    direction = direction_candidate or "Unknown"
    outcome = (analysis.get("call_outcome_type") or "").strip().title()
    voicemail_left = (analysis.get("voicemail_left") or "").strip().title()
    caller = (context.get("caller_name") or "").strip() or ("Team" if direction == "Outbound" else "Lead")
    callee = (context.get("callee_name") or "").strip() or ("Lead" if direction == "Outbound" else "Team")
    from_number = format_phone_display(context.get("from_number") or "")
    to_number = format_phone_display(context.get("to_number") or "")
    generic_labels = {"our team", "lead contact", "lead caller", "team", "lead", "recipient"}
    if caller.strip().lower() in generic_labels:
        caller = from_number or caller
    if callee.strip().lower() in generic_labels:
        callee = to_number or callee
    transcript = (transcript_text or "").strip()
    model_summary = re.sub(r"\s+", " ", str(analysis.get("summary") or "").strip())
    key_fact = re.sub(
        r"\s+",
        " ",
        str((analysis.get("key_facts") or [""])[0] if isinstance(analysis.get("key_facts"), list) else "").strip(),
    )

    if direction == "Outbound":
        intro = f"Outbound call by {caller} to {callee or to_number or 'lead'}."
    elif direction == "Inbound":
        intro = f"Inbound call from {caller or from_number or 'lead'} to {callee or 'team'}."
    else:
        intro = "Call direction could not be determined with confidence."

    if outcome in {"Voicemail", "No Answer", "Busy", "Failed"}:
        msg_state = "no voicemail details available"
        if voicemail_left == "Yes":
            msg_state = "voicemail was left"
        elif voicemail_left == "No":
            msg_state = "no voicemail was left"
        elif voicemail_left == "Not Applicable":
            msg_state = "voicemail not applicable"
        detail = f" Outcome: {outcome}; {msg_state}."
        if transcript and voicemail_left == "Yes":
            detail += f" Message summary: {re.sub(r'\\s+', ' ', str(model_summary or key_fact or transcript).strip())}"
        elif model_summary:
            detail += f" Notes: {model_summary}"
        return (intro + detail).strip()

    if outcome == "Answered":
        detail = f" Outcome: Answered conversation between {caller} and {callee or 'the lead'}."
        if model_summary:
            detail += f" Summary: {model_summary}"
        elif key_fact:
            detail += f" Key point: {key_fact}"
        return (intro + detail).strip()

    detail = f" Outcome: {outcome or 'Unknown'}."
    if model_summary:
        detail += f" Summary: {model_summary}"
    return (intro + detail).strip()


def compose_sms_signal_detail(signal_row):
    row = dict(signal_row or {})
    payload_obj = parse_json_object(row.get("payload_json") or "{}")
    messages = payload_obj.get("messages") if isinstance(payload_obj.get("messages"), list) else []
    if not messages:
        return str(row.get("summary_text") or payload_obj.get("summary") or "").strip() or "-"

    last_msg = messages[-1] if messages else {}
    direction = str(last_msg.get("direction") or "").strip().title()
    from_number = format_phone_display(last_msg.get("from_number") or "")
    to_number = format_phone_display(last_msg.get("to_number") or "")
    from_label = from_number or "Unknown Sender"
    to_label = to_number or "Unknown Recipient"
    if direction not in {"Inbound", "Outbound"}:
        direction = "Unknown"
    header = f"{direction} SMS from {from_label} to {to_label}."

    lines = []
    for msg in messages:
        ts = str(msg.get("sent_at") or msg.get("created_at") or "").strip()
        d = str(msg.get("direction") or "").strip().title() or "Unknown"
        fnum = format_phone_display(msg.get("from_number") or "") or "Unknown"
        tnum = format_phone_display(msg.get("to_number") or "") or "Unknown"
        body = str(msg.get("body") or "").replace("\r\n", "\n").replace("\r", "\n").strip()
        meta = f"[{ts}] {d} {fnum} -> {tnum}" if ts else f"{d} {fnum} -> {tnum}"
        if body:
            lines.append(f"{meta}\n{body}")
        else:
            lines.append(meta)

    return f"{header}\n\n" + "\n\n".join(lines)


def analyze_call_transcript_with_openai(transcript_text, property_id=None, person_id=None, context=None):
    api_key = os.getenv("OPENAI_API_KEY", "").strip()
    if not api_key:
        raise ValueError("OPENAI_API_KEY is not set")
    transcript = (transcript_text or "").strip()
    if not transcript:
        raise ValueError("transcript_text is required")
    context = context or {}
    model = os.getenv("OPENAI_MODEL", "gpt-4.1-mini").strip() or "gpt-4.1-mini"
    schema = {
        "name": "call_analysis",
        "schema": {
            "type": "object",
            "additionalProperties": False,
            "properties": {
                "summary": {"type": "string"},
                "caller_intent": {"type": "string"},
                "seller_interest": {
                    "type": "string",
                    "enum": ["High", "Medium", "Low", "Not Interested", "Unknown"],
                },
                "sentiment": {
                    "type": "string",
                    "enum": ["Positive", "Neutral", "Negative", "Mixed", "Unknown"],
                },
                "call_direction": {"type": "string", "enum": ["Outbound", "Inbound", "Unknown"]},
                "call_outcome_type": {
                    "type": "string",
                    "enum": ["Answered", "Voicemail", "No Answer", "Busy", "Failed", "Solicitation", "Wrong Number", "Unknown"],
                },
                "voicemail_left": {"type": "string", "enum": ["Yes", "No", "Unknown", "Not Applicable"]},
                "call_stage": {
                    "type": "string",
                    "enum": ["Intro Outreach", "Fact Finding", "Appointment Setting", "Follow Up", "Disposition", "Unknown"],
                },
                "key_facts": {"type": "array", "items": {"type": "string"}},
                "objections": {"type": "array", "items": {"type": "string"}},
                "line_diagnostics": {"type": "array", "items": {"type": "string"}},
                "next_best_step": {
                    "type": "string",
                    "enum": [
                        "Schedule Appointment",
                        "Follow Up",
                        "Escalate To Relative",
                        "Deep Dive",
                        "Mark Not Interested",
                        "Mark Opt Out",
                        "No Action",
                    ],
                },
                "next_step_reason": {"type": "string"},
                "caller_improvement": {"type": "array", "items": {"type": "string"}},
                "confidence": {"type": "number"},
            },
            "required": [
                "summary",
                "caller_intent",
                "seller_interest",
                "sentiment",
                "call_direction",
                "call_outcome_type",
                "voicemail_left",
                "call_stage",
                "key_facts",
                "objections",
                "line_diagnostics",
                "next_best_step",
                "next_step_reason",
                "caller_improvement",
                "confidence",
            ],
        },
        "strict": True,
    }
    meta = {
        "direction": (context.get("direction") or "Unknown"),
        "call_outcome": (context.get("call_outcome") or "Unknown"),
        "from_number": (context.get("from_number") or ""),
        "to_number": (context.get("to_number") or ""),
        "caller_name": (context.get("caller_name") or ""),
        "callee_name": (context.get("callee_name") or ""),
        "timestamp": (context.get("timestamp") or ""),
    }
    user_prompt = (
        "Analyze this call transcript for lead management.\n"
        f"Property ID: {property_id or '-'} | Person ID: {person_id or '-'}\n\n"
        f"Call metadata: {json.dumps(meta, ensure_ascii=True)}\n\n"
        "Return concise, factual JSON only. Focus on intent, call mechanics, and practical next step.\n"
        "Use names from metadata only; do not invent person or company names.\n"
        "If this appears to be voicemail/no-answer/short call, say so explicitly and avoid speculative interpretations.\n\n"
        f"Transcript:\n{transcript}"
    )
    response = requests.post(
        "https://api.openai.com/v1/responses",
        headers={"Authorization": f"Bearer {api_key}", "Content-Type": "application/json"},
        json={
            "model": model,
            "input": [
                {
                    "role": "system",
                    "content": [
                        {
                            "type": "input_text",
                            "text": "You are a call QA and lead-management analyst for a real estate CRM.",
                        }
                    ],
                },
                {"role": "user", "content": [{"type": "input_text", "text": user_prompt}]},
            ],
            "text": {
                "format": {
                    "type": "json_schema",
                    "name": schema["name"],
                    "schema": schema["schema"],
                    "strict": True,
                }
            },
        },
        timeout=60,
    )
    response.raise_for_status()
    data = response.json()
    output_text = (data.get("output_text") or "").strip()
    if output_text:
        parsed = json.loads(output_text)
        return _apply_call_analysis_guardrails(transcript, parsed, meta)
    for item in data.get("output", []):
        for part in item.get("content", []):
            if part.get("type") in {"output_text", "text"} and part.get("text"):
                parsed = json.loads(part["text"])
                return _apply_call_analysis_guardrails(transcript, parsed, meta)
    raise ValueError("No JSON output returned by call analyzer")


def call_skipsherpa_person_lookup(first_name, last_name, street, city="", state="", zipcode="", middle_name="", db=None):
    api_key = get_skipsherpa_api_key(db)
    if not api_key:
        raise ValueError("SKIPSHERPA_API_KEY is not set")
    first_name, middle_name, last_name = normalize_first_middle_last(first_name, middle_name, last_name)

    payload = {
        "person_lookups": [
            {
                    "first_name": (first_name or "").strip() or None,
                    "middle_name": (middle_name or "").strip() or None,
                    "last_name": (last_name or "").strip() or None,
                "mailing_addresses": [
                    {
                        "street": (street or "").strip(),
                        "city": (city or "").strip() or None,
                        "state": (state or "").strip() or None,
                        "zipcode": (zipcode or "").strip() or None,
                    }
                ],
            }
        ]
    }
    response = requests.put(
        f"{SKIPSHERPA_BASE_URL}/api/beta6/person",
        headers={"API-Key": api_key, "Content-Type": "application/json"},
        json=payload,
        timeout=45,
    )
    try:
        data = response.json()
    except ValueError:
        data = {"raw_text": response.text}
    if not response.ok:
        if response.status_code == 404 and isinstance(data, dict) and "person_results" in data:
            return {"request": payload, "response": data}
        emit_provider_alert(
            source="provider_skipsherpa",
            error_message=f"SkipSherpa person lookup failed ({response.status_code}).",
            details=_provider_alert_text(data),
            route="call_skipsherpa_person_lookup",
            status_code=response.status_code,
        )
        raise ValueError(f"SkipSherpa person lookup failed ({response.status_code}): {data}")
    return {"request": payload, "response": data}


