def get_recent_clever_webhook_records(db, limit=20, event_type_filter=""):
    try:
        limit = max(1, min(int(limit or 20), 100))
    except Exception:
        limit = 20
    filter_value = (event_type_filter or "").strip().lower()
    rows = db.execute(
        """
        SELECT id, event_type, event_key, processing_status, error_text, payload_json, headers_json, received_at
        FROM clever_webhook_events
        ORDER BY id DESC
        LIMIT ?
        """,
        (limit * 5,),
    ).fetchall()
    items = []
    for row in rows:
        event_type = str(row["event_type"] or "").strip()
        if filter_value and event_type.lower() != filter_value:
            continue
        payload = parse_json_object(row["payload_json"] or "{}", default={})
        headers = parse_json_object(row["headers_json"] or "{}", default={})
        items.append(
            {
                "id": int(row["id"]),
                "received_at": str(row["received_at"] or "").strip(),
                "event_type": event_type,
                "event_key": str(row["event_key"] or "").strip(),
                "processing_status": str(row["processing_status"] or "").strip(),
                "error_text": str(row["error_text"] or "").strip(),
                "headers": headers if isinstance(headers, dict) else {},
                "payload": payload if isinstance(payload, dict) else {},
            }
        )
        if len(items) >= limit:
            break
    return items


def _redact_clever_log_value(key, value):
    key_text = str(key or "").strip().lower()
    if any(token in key_text for token in ["authorization", "password", "token", "api_key", "integration_key", "secret", "key"]):
        return "[redacted]"
    if isinstance(value, dict):
        return {str(k): _redact_clever_log_value(k, v) for k, v in value.items()}
    if isinstance(value, list):
        return [_redact_clever_log_value(key, item) for item in value]
    return value


def _clever_safe_header_map(req):
    safe_keys = {
        "Content-Type",
        "User-Agent",
        "X-Forwarded-For",
        "X-Forwarded-Proto",
        "X-Forwarded-Host",
        "CF-Connecting-IP",
        "CF-IPCountry",
    }
    out = {}
    for key in safe_keys:
        value = req.headers.get(key)
        if value is not None and str(value).strip():
            out[key] = str(value)
    return out


def add_person_note(db, person_id, source, note_body, payload=None):
    if not person_id:
        return
    db.execute(
        """
        INSERT INTO person_notes (person_id, source, note_body, payload_json)
        VALUES (?, ?, ?, ?)
        """,
        (
            person_id,
            (source or "").strip() or "System",
            (note_body or "").strip(),
            json.dumps(payload, indent=2) if payload is not None else None,
        ),
    )


def log_email_validation_result(db, person_id, email_value, touch_status, validation_result, property_id=None):
    try:
        person_id = int(person_id or 0)
    except Exception:
        person_id = 0
    email_value = normalize_email(email_value)
    if not person_id or not email_value:
        return
    provider_status = str((validation_result or {}).get("provider_status") or "").strip() or str(touch_status or "").strip()
    touch_status = str(touch_status or "").strip() or "Unknown"
    status_low = touch_status.lower()
    if status_low == "valid":
        note_body = f"EmailListVerify marked {email_value} as valid ({provider_status})."
    elif status_low == "unknown":
        note_body = f"EmailListVerify marked {email_value} as unknown ({provider_status})."
    else:
        note_body = f"EmailListVerify marked {email_value} as undeliverable ({provider_status})."
    payload = {
        "email": email_value,
        "touchpoint_status": touch_status,
        "provider_status": provider_status,
        "validation_result": validation_result or {},
    }
    add_person_note(db, person_id, "EmailListVerify", note_body, payload)
    if property_id is None:
        property_id = find_property_id_for_person(db, person_id)
    try:
        property_id = int(property_id or 0)
    except Exception:
        property_id = 0
    if property_id > 0:
        db.execute(
            """
            INSERT INTO activity_log (property_id, person_id, activity_type, outcome, note)
            VALUES (?, ?, ?, ?, ?)
            """,
            (property_id, person_id, "Email Validation", touch_status, note_body),
        )


def get_setting(db, key, default=""):
    row = db.execute("SELECT value FROM app_settings WHERE key = ?", ((key or "").strip(),)).fetchone()
    if not row:
        return default
    return row["value"] if row["value"] is not None else default


def set_setting(db, key, value):
    key = (key or "").strip()
    db.execute(
        """
        INSERT INTO app_settings (key, value, updated_at)
        VALUES (?, ?, ?)
        ON CONFLICT(key) DO UPDATE SET
            value = excluded.value,
            updated_at = excluded.updated_at
        """,
        (key, (value or "").strip(), datetime.utcnow().strftime("%Y-%m-%d %H:%M:%S")),
    )


def _parse_uploaded_json_rows(upload):
    if not upload:
        return []
    raw = upload.read()
    if isinstance(raw, bytes):
        raw = raw.decode("utf-8", errors="ignore")
    raw = (raw or "").strip()
    if not raw:
        return []
    parsed = json.loads(raw)
    if isinstance(parsed, dict):
        if isinstance(parsed.get("rows"), list):
            parsed = parsed.get("rows")
        else:
            parsed = [parsed]
    if not isinstance(parsed, list):
        raise ValueError("Uploaded JSON must be an array of row objects.")
    cleaned = []
    for item in parsed:
        if isinstance(item, dict):
            cleaned.append(item)
    return cleaned


def import_referral_bundle_rows(db, realtor_rows, referral_rows, push_rows):
    counts = {
        "referral_realtors": 0,
        "reisift_referrals": 0,
        "referral_push_activity": 0,
    }

    for r in realtor_rows:
        db.execute(
            """
            INSERT INTO referral_realtors (id, first_name, last_name, email, phone, brokerage, target_markets, created_at)
            VALUES (?, ?, ?, ?, ?, ?, ?, ?)
            ON CONFLICT(id) DO UPDATE SET
                first_name = excluded.first_name,
                last_name = excluded.last_name,
                email = excluded.email,
                phone = excluded.phone,
                brokerage = excluded.brokerage,
                target_markets = excluded.target_markets,
                created_at = excluded.created_at
            """,
            (
                r.get("id"),
                r.get("first_name"),
                r.get("last_name"),
                r.get("email"),
                r.get("phone"),
                r.get("brokerage"),
                r.get("target_markets"),
                r.get("created_at"),
            ),
        )
        counts["referral_realtors"] += 1

    for r in referral_rows:
        db.execute(
            """
            INSERT INTO reisift_referrals (
                id, property_uuid, status, full_address, owner_names, payload_json,
                referral_status, winning_realtor_id, referral_notes, is_active, last_synced_at
            )
            VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
            ON CONFLICT(property_uuid) DO UPDATE SET
                status = excluded.status,
                full_address = excluded.full_address,
                owner_names = excluded.owner_names,
                payload_json = excluded.payload_json,
                referral_status = excluded.referral_status,
                winning_realtor_id = excluded.winning_realtor_id,
                referral_notes = excluded.referral_notes,
                is_active = excluded.is_active,
                last_synced_at = excluded.last_synced_at
            """,
            (
                r.get("id"),
                r.get("property_uuid"),
                r.get("status"),
                r.get("full_address"),
                r.get("owner_names"),
                r.get("payload_json"),
                r.get("referral_status"),
                r.get("winning_realtor_id"),
                r.get("referral_notes"),
                r.get("is_active"),
                r.get("last_synced_at"),
            ),
        )
        counts["reisift_referrals"] += 1

    for r in push_rows:
        db.execute(
            """
            INSERT INTO referral_push_activity (
                id, property_uuid, realtor_id, to_number, message_body, status, external_id, response_json, created_at
            )
            VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)
            ON CONFLICT(id) DO UPDATE SET
                property_uuid = excluded.property_uuid,
                realtor_id = excluded.realtor_id,
                to_number = excluded.to_number,
                message_body = excluded.message_body,
                status = excluded.status,
                external_id = excluded.external_id,
                response_json = excluded.response_json,
                created_at = excluded.created_at
            """,
            (
                r.get("id"),
                r.get("property_uuid"),
                r.get("realtor_id"),
                r.get("to_number"),
                r.get("message_body"),
                r.get("status"),
                r.get("external_id"),
                r.get("response_json"),
                r.get("created_at"),
            ),
        )
        counts["referral_push_activity"] += 1
    return counts


