def _split_csv_values(raw_value):
    if raw_value is None:
        return []
    values = []
    seen = set()
    for part in re.split(r"[,;\n]+", str(raw_value or "")):
        cleaned = normalize_whitespace(part)
        if cleaned and cleaned.lower() not in seen:
            seen.add(cleaned.lower())
            values.append(cleaned)
    return values


def _normalize_ad_platform(value):
    raw = normalize_whitespace(value).lower().replace("ads", "").replace("advertising", "").strip()
    if raw in {"google", "google ads"}:
        return "google"
    if raw in {"facebook", "fb", "meta", "facebook / meta"}:
        return "meta"
    if raw in {"amazon", "amazon ads"}:
        return "amazon"
    if raw in {"roku", "roku ads"}:
        return "roku"
    return raw


def _ad_platform_label(platform):
    key = _normalize_ad_platform(platform)
    return AD_PLATFORM_LABELS.get(key, normalize_whitespace(platform).title() or "Unknown")


def _normalize_ad_campaign_status(value):
    raw = normalize_whitespace(str(value or "").replace("_", " "))
    low = raw.lower()
    if not low:
        return "Unknown"
    mapping = {
        "enabled": "Live",
        "active": "Live",
        "live": "Live",
        "serving": "Live",
        "delivery": "Live",
        "paused": "Paused",
        "pause": "Paused",
        "stopped": "Stopped",
        "removed": "Stopped",
        "deleted": "Stopped",
        "archived": "Stopped",
        "in review": "In Review",
        "review": "In Review",
        "under review": "In Review",
        "disapproved": "Disapproved",
        "rejected": "Disapproved",
        "limited": "Limited",
        "pending": "Pending",
        "draft": "Draft",
        "not eligible": "Not Eligible",
        "eligible": "Live",
    }
    return mapping.get(low, raw.title())


def _ad_status_is_live(value):
    status = _normalize_ad_campaign_status(value).lower()
    return status in {"live", "active", "enabled", "serving"}


def _normalize_metric_float(value):
    if value in (None, ""):
        return 0.0
    try:
        return round(float(value), 4)
    except Exception:
        digits = re.sub(r"[^0-9.\-]", "", str(value))
        try:
            return round(float(digits), 4)
        except Exception:
            return 0.0


def _normalize_metric_int(value):
    if value in (None, ""):
        return 0
    try:
        return int(round(float(value)))
    except Exception:
        digits = re.sub(r"[^0-9\-]", "", str(value))
        try:
            return int(digits)
        except Exception:
            return 0


def _parse_iso_date_only(value):
    text = normalize_whitespace(value)
    if not text:
        return None
    try:
        return datetime.strptime(text[:10], "%Y-%m-%d").date()
    except ValueError:
        return None


def _ads_period_bounds(start_date="", end_date="", lookback_days=ADS_DEFAULT_LOOKBACK_DAYS):
    today = datetime.now(EST_TZ).date()
    end = _parse_iso_date_only(end_date) or today
    start = _parse_iso_date_only(start_date)
    if not start:
        days = max(int(lookback_days or ADS_DEFAULT_LOOKBACK_DAYS), 1)
        start = end - timedelta(days=days - 1)
    if start > end:
        start, end = end, start
    return start.isoformat(), end.isoformat()


def _normalize_google_ads_customer_id(value):
    return re.sub(r"\D", "", str(value or ""))


def _normalize_google_ads_conversion_action_id(value):
    return re.sub(r"\D", "", str(value or ""))


def _normalize_meta_account_id(value):
    cleaned = normalize_whitespace(value).lower().replace("act_", "")
    return re.sub(r"\D", "", cleaned)


def _normalize_roku_account_id(value):
    return normalize_whitespace(value)


def _normalize_report_row_keys(row):
    if not isinstance(row, dict):
        return {}
    normalized = {}
    for key, value in row.items():
        clean_key = re.sub(r"[^a-z0-9]+", "_", normalize_whitespace(key).lower()).strip("_")
        if clean_key:
            normalized[clean_key] = value
    return normalized


def _amazon_ads_base_url(region):
    region_key = normalize_whitespace(region or "na").lower()
    mapping = {
        "na": "https://advertising-api.amazon.com",
        "eu": "https://advertising-api-eu.amazon.com",
        "fe": "https://advertising-api-fe.amazon.com",
    }
    return mapping.get(region_key, mapping["na"])


def _build_amazon_authorize_url(client_id, redirect_uri, state, scope=AMAZON_ADS_DEFAULT_SCOPE):
    params = {
        "client_id": client_id,
        "scope": scope,
        "response_type": "code",
        "redirect_uri": redirect_uri,
        "state": state,
    }
    return f"{AMAZON_LWA_AUTHORIZE_URL}?{urlencode(params)}"


def _build_roku_authorize_url(developer_app_uid, client_id, redirect_uri):
    params = {
        "developer_app_uid": developer_app_uid,
        "client_id": client_id,
        "redirect_uri": redirect_uri,
    }
    return f"{ROKU_ADS_AUTHORIZE_URL}?{urlencode(params)}"


def _google_ads_headers(settings, access_token):
    headers = {
        "Authorization": f"Bearer {access_token}",
        "developer-token": settings.get("google_developer_token", ""),
        "Content-Type": "application/json",
        "Accept": "application/json",
    }
    login_customer_id = _normalize_google_ads_customer_id(settings.get("google_login_customer_id"))
    if login_customer_id:
        headers["login-customer-id"] = login_customer_id
    return headers


def _google_ads_exchange_refresh_token(settings):
    response = requests.post(
        "https://oauth2.googleapis.com/token",
        data={
            "client_id": settings.get("google_client_id", ""),
            "client_secret": settings.get("google_client_secret", ""),
            "refresh_token": settings.get("google_refresh_token", ""),
            "grant_type": "refresh_token",
        },
        timeout=30,
    )
    if not response.ok:
        try:
            payload = response.json()
        except Exception:
            payload = response.text
        raise RuntimeError(f"Google Ads token exchange failed ({response.status_code}): {payload}")
    payload = response.json() or {}
    access_token = str(payload.get("access_token") or "").strip()
    if not access_token:
        raise RuntimeError("Google Ads token exchange did not return an access token.")
    return access_token


def _google_ads_extract_error(response):
    request_id = (response.headers.get("request-id") or "").strip()
    try:
        payload = response.json()
    except Exception:
        payload = response.text
    if isinstance(payload, dict):
        error_obj = payload.get("error")
        if isinstance(error_obj, dict):
            message = normalize_whitespace(error_obj.get("message"))
            details = error_obj.get("details")
            detail_text = ""
            if isinstance(details, list) and details:
                detail_text = normalize_whitespace(json.dumps(details, ensure_ascii=True, default=str))
            parts = [part for part in [message, detail_text] if part]
            combined = " | ".join(parts) if parts else normalize_whitespace(json.dumps(payload, ensure_ascii=True, default=str))
        else:
            combined = normalize_whitespace(json.dumps(payload, ensure_ascii=True, default=str))
    else:
        combined = normalize_whitespace(str(payload))
    if request_id:
        combined = f"{combined} (request-id: {request_id})" if combined else f"request-id: {request_id}"
    return combined or f"HTTP {response.status_code}"


def _google_ads_post(settings, customer_id, service_method, body):
    customer_id = _normalize_google_ads_customer_id(customer_id)
    if not customer_id:
        raise RuntimeError("Google Ads customer ID is missing.")
    access_token = _google_ads_exchange_refresh_token(settings)
    base_headers = _google_ads_headers(settings, access_token)
    login_customer_id = _normalize_google_ads_customer_id(settings.get("google_login_customer_id"))
    attempts = [dict(base_headers)]
    if login_customer_id:
        attempts.append({k: v for k, v in base_headers.items() if k.lower() != "login-customer-id"})
        if login_customer_id != customer_id:
            child_headers = dict(base_headers)
            child_headers["login-customer-id"] = customer_id
            attempts.append(child_headers)
    last_error = ""
    for headers in attempts:
        response = requests.post(
            f"https://googleads.googleapis.com/{GOOGLE_ADS_API_VERSION}/customers/{customer_id}/googleAds:{service_method}",
            headers=headers,
            json=body,
            timeout=90,
        )
        if response.ok:
            try:
                return response.json()
            except Exception as exc:
                raise RuntimeError(f"Google Ads {service_method} returned invalid JSON: {exc}") from exc
        current_error = _google_ads_extract_error(response)
        last_error = current_error
        if response.status_code != 403 or "USER_PERMISSION_DENIED" not in current_error.upper():
            break
    raise RuntimeError(f"Google Ads {service_method} failed ({response.status_code}): {last_error}")


def _google_ads_post_rest_method(settings, customer_id, rest_method, body):
    customer_id = _normalize_google_ads_customer_id(customer_id)
    if not customer_id:
        raise RuntimeError("Google Ads customer ID is missing.")
    access_token = _google_ads_exchange_refresh_token(settings)
    base_headers = _google_ads_headers(settings, access_token)
    login_customer_id = _normalize_google_ads_customer_id(settings.get("google_login_customer_id"))
    attempts = [dict(base_headers)]
    if login_customer_id:
        attempts.append({k: v for k, v in base_headers.items() if k.lower() != "login-customer-id"})
        if login_customer_id != customer_id:
            child_headers = dict(base_headers)
            child_headers["login-customer-id"] = customer_id
            attempts.append(child_headers)
    last_error = ""
    for headers in attempts:
        response = requests.post(
            f"https://googleads.googleapis.com/{GOOGLE_ADS_API_VERSION}/customers/{customer_id}:{rest_method}",
            headers=headers,
            json=body,
            timeout=90,
        )
        if response.ok:
            try:
                return response.json()
            except Exception as exc:
                raise RuntimeError(f"Google Ads {rest_method} returned invalid JSON: {exc}") from exc
        current_error = _google_ads_extract_error(response)
        last_error = current_error
        if response.status_code != 403 or "USER_PERMISSION_DENIED" not in current_error.upper():
            break
    raise RuntimeError(f"Google Ads {rest_method} failed ({response.status_code}): {last_error}")


def _google_ads_lead_feedback_customer_id(settings):
    explicit = _normalize_google_ads_customer_id(settings.get("google_conversion_customer_id"))
    if explicit:
        return explicit
    customer_ids = settings.get("google_customer_ids") or []
    return _normalize_google_ads_customer_id(customer_ids[0]) if customer_ids else ""


def _google_ads_customer_resource_id(value):
    text = normalize_whitespace(value)
    if not text:
        return ""
    match = re.search(r"customers/(\d+)", text)
    if match:
        return _normalize_google_ads_customer_id(match.group(1))
    return _normalize_google_ads_customer_id(text)


def _google_ads_lead_feedback_customer_candidates(settings, preferred_customer_id=""):
    seen = set()
    ordered = []
    for raw in [
        preferred_customer_id,
        settings.get("google_conversion_customer_id"),
        *list(settings.get("google_customer_ids") or []),
    ]:
        customer_id = _normalize_google_ads_customer_id(raw)
        if not customer_id or customer_id in seen:
            continue
        ordered.append(customer_id)
        seen.add(customer_id)
    return ordered


def _google_ads_normalize_phone_for_upload(value):
    digits = re.sub(r"\D", "", str(value or ""))
    if len(digits) == 10:
        return f"+1{digits}"
    if len(digits) == 11 and digits.startswith("1"):
        return f"+{digits}"
    return ""


def _google_ads_sha256(value):
    clean = str(value or "").strip()
    if not clean:
        return ""
    return hashlib.sha256(clean.encode("utf-8")).hexdigest()


def _google_ads_lead_user_identifiers(email="", phone=""):
    identifiers = []
    clean_email = normalize_email(email)
    if clean_email:
        identifiers.append({"hashedEmail": _google_ads_sha256(clean_email)})
    clean_phone = _google_ads_normalize_phone_for_upload(phone)
    if clean_phone:
        identifiers.append({"hashedPhoneNumber": _google_ads_sha256(clean_phone)})
    return identifiers


def _google_ads_conversion_action_resource_name(customer_id, action_id):
    customer_id = _normalize_google_ads_customer_id(customer_id)
    action_id = _normalize_google_ads_conversion_action_id(action_id)
    if not customer_id or not action_id:
        return ""
    return f"customers/{customer_id}/conversionActions/{action_id}"


def _google_ads_conversion_datetime_text(dt_obj=None, tz_name="America/New_York"):
    tz = get_zoneinfo_safe(tz_name)
    if dt_obj is None:
        dt_obj = datetime.now(tz)
    elif dt_obj.tzinfo is None:
        dt_obj = dt_obj.replace(tzinfo=tz)
    else:
        dt_obj = dt_obj.astimezone(tz)
    return dt_obj.isoformat(sep=" ", timespec="seconds")


def _google_ads_lead_feedback_conversion_at(lead, stage_key):
    stage_value = normalize_whitespace(stage_key).lower()
    day_offset = 1 if stage_value == "qualified" else 2 if stage_value == "converted" else 0
    base_value = ""
    if isinstance(lead, dict):
        base_value = (
            str(lead.get("first_received_at") or "").strip()
            or str(lead.get("last_received_at") or "").strip()
        )
    base_dt = parse_iso_datetime(base_value) or parse_db_time(base_value) or datetime.utcnow()
    if base_dt.tzinfo is None:
        base_dt = base_dt.replace(tzinfo=timezone.utc)
    return base_dt + timedelta(days=day_offset)


def _google_ads_partial_failure_text(payload):
    error_obj = payload.get("partialFailureError") if isinstance(payload, dict) else None
    if not isinstance(error_obj, dict) or not error_obj:
        return ""
    message = normalize_whitespace(error_obj.get("message"))
    details = error_obj.get("details")
    detail_text = normalize_whitespace(json.dumps(details, ensure_ascii=True, default=str)) if details else ""
    return " | ".join(part for part in [message, detail_text] if part).strip()


def _google_ads_friendly_partial_failure_message(raw_text):
    text = normalize_whitespace(raw_text)
    upper = text.upper()
    if "TOO_RECENT_CONVERSION_ACTION" in upper or "TRY IMPORTING AGAIN IN 6 HOURS" in upper:
        return (
            "Google Ads found the correct conversion action, but it was created too recently. "
            "Google requires about 6 hours before the first offline lead import can be accepted. "
            "Please try again later."
        )
    return text


def _google_ads_search_stream_results(settings, customer_id, query):
    payload = _google_ads_post(
        settings,
        customer_id,
        "searchStream",
        {
            "query": "\n".join(line.strip() for line in str(query or "").strip().splitlines()),
        },
    )
    batches = payload if isinstance(payload, list) else [payload]
    rows = []
    for batch in batches:
        if not isinstance(batch, dict):
            continue
        results = batch.get("results")
        if not isinstance(results, list):
            continue
        for item in results:
            if isinstance(item, dict):
                rows.append(item)
    return rows


def _google_ads_find_customer_for_campaign(settings, campaign_id):
    campaign_id = re.sub(r"\D", "", str(campaign_id or ""))
    if not campaign_id:
        return ""
    query = f"""
        SELECT
          customer.id,
          campaign.id
        FROM campaign
        WHERE campaign.id = {campaign_id}
          AND campaign.status != 'REMOVED'
    """
    for customer_id in _google_ads_lead_feedback_customer_candidates(settings):
        try:
            rows = _google_ads_search_stream_results(settings, customer_id, query)
        except Exception:
            continue
        for item in rows:
            customer = item.get("customer") or {}
            resolved_customer_id = _normalize_google_ads_customer_id(customer.get("id")) or customer_id
            if resolved_customer_id:
                return resolved_customer_id
    return ""


def _google_ads_resolve_lead_feedback_action(settings, stage_key, campaign_id=""):
    stage_value = normalize_whitespace(stage_key).lower()
    if stage_value not in {"qualified", "converted"}:
        raise RuntimeError(f"Unsupported Google Ads lead feedback stage: {stage_key}")
    category = "QUALIFIED_LEAD" if stage_value == "qualified" else "CONVERTED_LEAD"
    preferred_customer_id = _google_ads_find_customer_for_campaign(settings, campaign_id)
    customer_candidates = _google_ads_lead_feedback_customer_candidates(settings, preferred_customer_id=preferred_customer_id)
    if not customer_candidates:
        raise RuntimeError("Google Ads conversion customer ID is missing.")
    query = f"""
        SELECT
          customer.id,
          conversion_action.id,
          conversion_action.resource_name,
          conversion_action.name,
          conversion_action.category,
          conversion_action.status,
          conversion_action.type,
          conversion_action.primary_for_goal,
          conversion_action.include_in_conversions_metric,
          conversion_action.owner_customer
        FROM conversion_action
        WHERE conversion_action.status = 'ENABLED'
          AND conversion_action.type = 'UPLOAD_CLICKS'
          AND conversion_action.category = '{category}'
    """
    candidates = []
    for customer_id in customer_candidates:
        try:
            rows = _google_ads_search_stream_results(settings, customer_id, query)
        except Exception:
            continue
        for item in rows:
            action = item.get("conversionAction") or {}
            action_id = _normalize_google_ads_conversion_action_id(action.get("id"))
            if not action_id:
                continue
            owner_customer_id = _google_ads_customer_resource_id(action.get("ownerCustomer"))
            candidates.append(
                {
                    "id": action_id,
                    "resource_name": normalize_whitespace(action.get("resourceName")),
                    "name": normalize_whitespace(action.get("name")) or f"{stage_value.title()} Lead",
                    "category": normalize_whitespace(action.get("category")).upper(),
                    "status": normalize_whitespace(action.get("status")).upper(),
                    "type": normalize_whitespace(action.get("type")).upper(),
                    "primary_for_goal": bool(action.get("primaryForGoal")),
                    "include_in_conversions_metric": bool(action.get("includeInConversionsMetric")),
                    "search_customer_id": customer_id,
                    "upload_customer_id": owner_customer_id or customer_id,
                    "owner_customer_id": owner_customer_id,
                }
            )
    if not candidates:
        raise RuntimeError(
            f"No enabled Google Ads conversion action was found for {stage_value.title()} Lead. "
            f"Create an Import from clicks conversion action with goal type {stage_value.title()} lead."
        )
    if preferred_customer_id:
        matching_customer_candidates = [
            item
            for item in candidates
            if item.get("upload_customer_id") == preferred_customer_id or item.get("search_customer_id") == preferred_customer_id
        ]
        if matching_customer_candidates:
            candidates = matching_customer_candidates
    distinct_upload_customers = {item.get("upload_customer_id") for item in candidates if item.get("upload_customer_id")}
    explicit_customer = _normalize_google_ads_customer_id(settings.get("google_conversion_customer_id"))
    if len(distinct_upload_customers) > 1 and not preferred_customer_id and not explicit_customer:
        raise RuntimeError(
            "Multiple Google Ads accounts have lead-stage conversion actions configured. "
            "Set Google Conversion Customer ID in Ads settings so DeepSift knows which account to upload into."
        )
    candidates.sort(
        key=lambda item: (
            1 if preferred_customer_id and item.get("upload_customer_id") == preferred_customer_id else 0,
            1 if explicit_customer and item.get("upload_customer_id") == explicit_customer else 0,
            1 if item.get("include_in_conversions_metric") else 0,
            1 if item.get("primary_for_goal") else 0,
            int(item.get("id") or 0),
        ),
        reverse=True,
    )
    chosen = candidates[0]
    return {
        "customer_id": chosen.get("search_customer_id") or chosen.get("upload_customer_id") or customer_candidates[0],
        "upload_customer_id": chosen.get("upload_customer_id") or chosen.get("search_customer_id") or customer_candidates[0],
        "preferred_customer_id": preferred_customer_id,
        "stage_key": stage_value,
        "category": category,
        "action_id": chosen["id"],
        "resource_name": chosen["resource_name"] or _google_ads_conversion_action_resource_name(chosen.get("upload_customer_id") or chosen.get("search_customer_id") or customer_candidates[0], chosen["id"]),
        "action_name": chosen["name"],
        "candidate_count": len(candidates),
        "candidates": candidates,
    }


def upload_google_ads_lead_funnel_conversion(
    settings,
    *,
    conversion_action_id="",
    gclid,
    email="",
    phone="",
    lead_id=0,
    stage_key="qualified",
    conversion_at=None,
    campaign_id="",
):
    request_customer_id = _google_ads_lead_feedback_customer_id(settings)
    if not request_customer_id:
        raise RuntimeError("Google Ads conversion customer ID is missing.")
    resolved_action = None
    action_id = _normalize_google_ads_conversion_action_id(conversion_action_id)
    if not action_id:
        resolved_action = _google_ads_resolve_lead_feedback_action(settings, stage_key, campaign_id=campaign_id)
        action_id = _normalize_google_ads_conversion_action_id(resolved_action.get("action_id"))
        request_customer_id = _normalize_google_ads_customer_id(resolved_action.get("upload_customer_id")) or request_customer_id
    if not action_id:
        raise RuntimeError("Google Ads conversion action could not be resolved.")
    gclid = str(gclid or "").strip()
    if not gclid:
        raise RuntimeError("This lead does not have a GCLID, so it cannot be uploaded back to Google Ads.")

    conversion = {
        "gclid": gclid,
        "conversionAction": (
            normalize_whitespace((resolved_action or {}).get("resource_name"))
            or _google_ads_conversion_action_resource_name(request_customer_id, action_id)
        ),
        "conversionDateTime": _google_ads_conversion_datetime_text(conversion_at),
        "conversionValue": 1.0,
        "currencyCode": "USD",
        "orderId": f"deepsift-website-lead-{int(lead_id or 0)}-{str(stage_key or 'lead').strip().lower()}",
        "conversionEnvironment": "WEB",
    }
    user_identifiers = _google_ads_lead_user_identifiers(email=email, phone=phone)
    if user_identifiers:
        conversion["userIdentifiers"] = user_identifiers

    response = _google_ads_post_rest_method(
        settings,
        request_customer_id,
        "uploadClickConversions",
        {
            "conversions": [conversion],
            "partialFailure": True,
        },
    )
    partial_failure_text = _google_ads_partial_failure_text(response)
    if partial_failure_text:
        raise RuntimeError(f"Google Ads partial failure: {_google_ads_friendly_partial_failure_message(partial_failure_text)}")
    results = response.get("results") if isinstance(response, dict) else None
    if not isinstance(results, list) or not results:
        raise RuntimeError("Google Ads upload returned no successful conversion results.")
    return {
        "ok": True,
        "customer_id": request_customer_id,
        "conversion_action_id": action_id,
        "conversion_action": conversion.get("conversionAction"),
        "resolved_action": resolved_action,
        "conversion_date_time": conversion.get("conversionDateTime"),
        "response": response,
        "result": results[0],
    }


def _google_ads_display_status(campaign_status, primary_status):
    status = _normalize_ad_campaign_status(campaign_status)
    primary = _normalize_ad_campaign_status(primary_status)
    status_low = status.lower()
    primary_low = primary.lower()
    if status_low == "live":
        if primary_low in {"paused", "stopped", "disapproved", "in review", "limited", "pending", "not eligible"}:
            return primary
        return "Live"
    if status_low != "unknown":
        return status
    if primary_low != "unknown":
        return primary
    return "Unknown"


def _google_ads_parse_search_stream_rows(stream_payload, customer_id):
    batches = stream_payload if isinstance(stream_payload, list) else [stream_payload]
    rows = []
    for batch in batches:
        if not isinstance(batch, dict):
            continue
        results = batch.get("results")
        if not isinstance(results, list):
            continue
        for item in results:
            if not isinstance(item, dict):
                continue
            campaign = item.get("campaign") or {}
            metrics = item.get("metrics") or {}
            segments = item.get("segments") or {}
            customer = item.get("customer") or {}
            campaign_id = normalize_whitespace(campaign.get("id"))
            metric_date = normalize_whitespace(segments.get("date"))
            if not campaign_id:
                continue
            cost_micros = _normalize_metric_float(metrics.get("costMicros"))
            rows.append(
                {
                    "platform": "google",
                    "account_id": normalize_whitespace(customer.get("id")) or customer_id,
                    "campaign_id": campaign_id,
                    "campaign_name": normalize_whitespace(campaign.get("name")) or campaign_id,
                    "campaign_status": _google_ads_display_status(campaign.get("status"), campaign.get("primaryStatus")),
                    "campaign_site": "Google",
                    "campaign_goal": normalize_whitespace(campaign.get("advertisingChannelType")),
                    "metric_date": metric_date,
                    "spend": round(cost_micros / 1_000_000.0, 4),
                    "impressions": _normalize_metric_int(metrics.get("impressions")),
                    "clicks": _normalize_metric_int(metrics.get("clicks")),
                    "reach": _normalize_metric_int(metrics.get("uniqueUsers")),
                    "conversions": _normalize_metric_float(metrics.get("conversions")),
                    "_current_snapshot": bool(not metric_date),
                    "raw": item,
                }
            )
    return rows


def _meta_graph_get(path, params, access_token):
    url = f"https://graph.facebook.com/{META_GRAPH_API_VERSION}/{path.lstrip('/')}"
    payload = dict(params or {})
    payload["access_token"] = access_token
    items = []
    while url:
        response = requests.get(url, params=payload if "?" not in url else None, timeout=90)
        if not response.ok:
            try:
                error_payload = response.json()
            except Exception:
                error_payload = response.text
            if isinstance(error_payload, dict):
                err = error_payload.get("error") if isinstance(error_payload.get("error"), dict) else {}
                code = err.get("code")
                subcode = err.get("error_subcode")
                if int(code or 0) == 190 and int(subcode or 0) == 463:
                    raise RuntimeError(
                        "Meta access token expired. Exchange a fresh Meta user token for a long-lived token in Settings -> Ad Platforms."
                    )
            raise RuntimeError(f"Meta API request failed ({response.status_code}): {error_payload}")
        data = response.json() or {}
        if isinstance(data.get("data"), list):
            items.extend(data.get("data") or [])
        else:
            return data
        paging = data.get("paging") or {}
        next_url = paging.get("next")
        if next_url:
            url = next_url
            payload = {}
        else:
            url = ""
    return items


def _exchange_meta_long_lived_access_token(app_id, app_secret, user_access_token):
    response = requests.get(
        f"https://graph.facebook.com/{META_GRAPH_API_VERSION}/oauth/access_token",
        params={
            "grant_type": "fb_exchange_token",
            "client_id": app_id,
            "client_secret": app_secret,
            "fb_exchange_token": user_access_token,
        },
        timeout=60,
    )
    try:
        payload = response.json()
    except Exception:
        payload = {"raw": response.text}
    if not response.ok:
        raise RuntimeError(f"Meta long-lived token exchange failed ({response.status_code}): {payload}")
    access_token = normalize_whitespace(payload.get("access_token"))
    if not access_token:
        raise RuntimeError("Meta long-lived token exchange did not return an access token.")
    return payload if isinstance(payload, dict) else {}


def _fetch_meta_accessible_accounts(access_token):
    rows = _meta_graph_get(
        "me/adaccounts",
        {
            "fields": "id,account_id,name,account_status",
            "limit": 200,
        },
        access_token,
    )
    return rows if isinstance(rows, list) else []


def _meta_conversion_value(actions):
    if not isinstance(actions, list):
        return 0.0
    total = 0.0
    for action in actions:
        if not isinstance(action, dict):
            continue
        action_type = normalize_whitespace(action.get("action_type")).lower()
        if not action_type:
            continue
        include = (
            "lead" in action_type
            or "purchase" in action_type
            or "complete_registration" in action_type
            or "submit_application" in action_type
            or action_type in {"contact", "schedule", "subscribe", "start_trial"}
        )
        if not include:
            continue
        total += _normalize_metric_float(action.get("value"))
    return round(total, 4)


def _exchange_amazon_authorization_code(client_id, client_secret, code, redirect_uri):
    response = requests.post(
        AMAZON_LWA_TOKEN_URL,
        data={
            "grant_type": "authorization_code",
            "code": code,
            "client_id": client_id,
            "client_secret": client_secret,
            "redirect_uri": redirect_uri,
        },
        timeout=60,
    )
    try:
        payload = response.json()
    except Exception:
        payload = {"raw": response.text}
    if not response.ok:
        raise RuntimeError(f"Amazon token exchange failed ({response.status_code}): {payload}")
    return payload if isinstance(payload, dict) else {}


def _fetch_amazon_ads_profiles(client_id, access_token, region):
    response = requests.get(
        f"{_amazon_ads_base_url(region)}/v2/profiles",
        headers={
            "Authorization": f"Bearer {access_token}",
            "Amazon-Advertising-API-ClientId": client_id,
            "Accept": "application/json",
        },
        timeout=60,
    )
    if not response.ok:
        try:
            payload = response.json()
        except Exception:
            payload = response.text
        raise RuntimeError(f"Amazon profile lookup failed ({response.status_code}): {payload}")
    payload = response.json()
    return payload if isinstance(payload, list) else []


def _amazon_account_ids_from_profile(profile):
    if not isinstance(profile, dict):
        return []
    values = []

    def collect(obj):
        if isinstance(obj, dict):
            for value in obj.values():
                collect(value)
        elif isinstance(obj, list):
            for value in obj:
                collect(value)
        elif isinstance(obj, str):
            text = normalize_whitespace(obj)
            if text:
                values.append(text)

    collect(profile)
    explicit_ids = []
    for text in values:
        if re.match(r"^amzn1\.ads-account\.", text, re.IGNORECASE) or re.match(r"^entity[a-z0-9]+$", text, re.IGNORECASE):
            explicit_ids.append(text)
    if explicit_ids:
        return list(dict.fromkeys(explicit_ids))

    account_info = profile.get("accountInfo") if isinstance(profile.get("accountInfo"), dict) else {}
    fallback_values = [
        profile.get("accountId"),
        profile.get("entityId"),
        profile.get("advertiserId"),
        profile.get("sellerId"),
        profile.get("vendorCode"),
        account_info.get("accountId"),
        account_info.get("entityId"),
        account_info.get("id"),
        account_info.get("advertiserId"),
        account_info.get("sellerId"),
        account_info.get("vendorCode"),
    ]
    normalized = [normalize_whitespace(value) for value in fallback_values if normalize_whitespace(value)]
    return list(dict.fromkeys(normalized))


def _amazon_account_ids_from_profiles(profiles):
    ids = []
    for profile in profiles if isinstance(profiles, list) else []:
        ids.extend(_amazon_account_ids_from_profile(profile))
    return list(dict.fromkeys(ids))


def _amazon_profile_matches_account(profile, account_id):
    target = normalize_whitespace(account_id).lower()
    if not target:
        return False
    return any(value.lower() == target for value in _amazon_account_ids_from_profile(profile))


def _amazon_profile_ids_from_profiles(profiles):
    ids = []
    for profile in profiles if isinstance(profiles, list) else []:
        if not isinstance(profile, dict):
            continue
        profile_id = normalize_whitespace(profile.get("profileId") or profile.get("id"))
        if profile_id:
            ids.append(profile_id)
    return list(dict.fromkeys(ids))


def _exchange_amazon_refresh_token(client_id, client_secret, refresh_token):
    response = requests.post(
        AMAZON_LWA_TOKEN_URL,
        data={
            "grant_type": "refresh_token",
            "refresh_token": refresh_token,
            "client_id": client_id,
            "client_secret": client_secret,
        },
        timeout=60,
    )
    try:
        payload = response.json()
    except Exception:
        payload = {"raw": response.text}
    if not response.ok:
        raise RuntimeError(f"Amazon refresh-token exchange failed ({response.status_code}): {payload}")
    access_token = normalize_whitespace(payload.get("access_token"))
    if not access_token:
        raise RuntimeError("Amazon refresh-token exchange did not return an access token.")
    return access_token


