def _amazon_sponsored_tv_campaigns_once(settings, access_token, profile_id, next_token=""):
    base_url = _amazon_ads_base_url(settings.get("amazon_region"))
    normalized_token = normalize_whitespace(next_token)
    attempts = []
    candidates = [
        {
            "method": "get",
            "url": f"{base_url}/st/campaigns",
            "kwargs": {
                "params": {"nextToken": normalized_token} if normalized_token else {},
            },
        },
        {
            "method": "post",
            "url": f"{base_url}/st/campaigns/list",
            "kwargs": {
                "json": {"nextToken": normalized_token} if normalized_token else {},
            },
        },
    ]
    headers = _amazon_ads_headers(settings, access_token, profile_id=profile_id)
    for candidate in candidates:
        request_kwargs = dict(candidate["kwargs"])
        request_kwargs["headers"] = headers
        request_kwargs["timeout"] = 60
        response = requests.request(candidate["method"], candidate["url"], **request_kwargs)
        try:
            body = response.json()
        except Exception:
            body = {"raw": response.text}
        if response.ok:
            return body if isinstance(body, dict) else {"items": body if isinstance(body, list) else []}
        attempts.append(
            {
                "method": candidate["method"].upper(),
                "url": candidate["url"],
                "status_code": response.status_code,
                "body": body,
            }
        )
        if response.status_code not in {403, 404, 405}:
            break
    raise RuntimeError(f"Amazon Sponsored TV campaign fetch failed: {attempts}")


def _fetch_amazon_campaign_snapshots(settings, access_token, profile_id):
    rows = []
    seen = set()
    next_token = ""
    for _ in range(10):
        body = _amazon_sponsored_tv_campaigns_once(settings, access_token, profile_id, next_token=next_token)
        for item in _amazon_extract_campaign_list(body):
            if not isinstance(item, dict):
                continue
            raw_campaign_id = normalize_whitespace(
                item.get("campaignId")
                or item.get("campaign_id")
                or item.get("id")
                or item.get("campaignIdentifier")
            )
            if not raw_campaign_id:
                continue
            dedupe_key = (normalize_whitespace(profile_id), raw_campaign_id)
            if dedupe_key in seen:
                continue
            seen.add(dedupe_key)
            rows.append(
                {
                    "platform": "amazon",
                    "account_id": normalize_whitespace(profile_id),
                    "campaign_id": raw_campaign_id,
                    "campaign_name": normalize_whitespace(
                        item.get("name")
                        or item.get("campaignName")
                        or item.get("campaign_name")
                    )
                    or raw_campaign_id,
                    "campaign_status": _normalize_ad_campaign_status(
                        item.get("state")
                        or item.get("status")
                        or item.get("campaignStatus")
                        or item.get("servingStatus")
                    ),
                    "campaign_site": _ad_campaign_site("amazon", profile_id),
                    "campaign_goal": "Sponsored TV",
                    "metric_date": "",
                    "spend": 0.0,
                    "impressions": 0,
                    "clicks": 0,
                    "reach": 0,
                    "conversions": 0.0,
                    "_current_snapshot": True,
                    "raw": item,
                }
            )
        next_token = _amazon_campaign_next_token(body)
        if not next_token:
            break
    return rows


def _amazon_report_rows_to_dashboard_rows(profile_id, report_rows, snapshots_by_campaign):
    rows = []
    for item in report_rows if isinstance(report_rows, list) else []:
        if not isinstance(item, dict):
            continue
        normalized_item = _normalize_report_row_keys(item)
        campaign_id = normalize_whitespace(
            normalized_item.get("campaign_id")
            or item.get("campaignId")
            or item.get("campaign_id")
            or item.get("id")
        )
        metric_date = normalize_whitespace(
            normalized_item.get("date")
            or normalized_item.get("metric_date")
            or item.get("date")
        )
        if not campaign_id or not metric_date:
            continue
        snapshot = snapshots_by_campaign.get(campaign_id) or {}
        rows.append(
            {
                "platform": "amazon",
                "account_id": normalize_whitespace(profile_id),
                "campaign_id": campaign_id,
                "campaign_name": snapshot.get("campaign_name")
                or normalize_whitespace(normalized_item.get("campaign_name") or item.get("campaignName"))
                or campaign_id,
                "campaign_status": snapshot.get("campaign_status")
                or _normalize_ad_campaign_status(
                    normalized_item.get("campaign_status")
                    or item.get("campaignStatus")
                    or item.get("status")
                ),
                "campaign_site": _ad_campaign_site("amazon", profile_id),
                "campaign_goal": snapshot.get("campaign_goal") or "Sponsored TV",
                "metric_date": metric_date,
                "spend": _normalize_metric_float(
                    normalized_item.get("cost")
                    or normalized_item.get("spend")
                    or item.get("cost")
                    or item.get("spend")
                ),
                "impressions": _normalize_metric_int(normalized_item.get("impressions") or item.get("impressions")),
                "clicks": _normalize_metric_int(normalized_item.get("clicks") or item.get("clicks")),
                "reach": _normalize_metric_int(
                    normalized_item.get("reach")
                    or normalized_item.get("household_reach")
                    or item.get("reach")
                    or item.get("householdReach")
                ),
                "conversions": _normalize_metric_float(
                    normalized_item.get("conversions")
                    or normalized_item.get("purchases_14d")
                    or normalized_item.get("attributed_conversions_14d")
                    or item.get("conversions")
                    or item.get("purchases14d")
                ),
                "raw": item,
            }
        )
    return rows


def _amazon_zero_metric_rows_for_missing_snapshots(profile_id, metric_date, snapshots_by_campaign, report_rows):
    metric_date = normalize_whitespace(metric_date)
    if not metric_date or not isinstance(snapshots_by_campaign, dict) or not snapshots_by_campaign:
        return []
    report_campaign_ids = set()
    for item in report_rows if isinstance(report_rows, list) else []:
        if not isinstance(item, dict):
            continue
        normalized_item = _normalize_report_row_keys(item)
        campaign_id = normalize_whitespace(
            normalized_item.get("campaign_id")
            or item.get("campaignId")
            or item.get("campaign_id")
            or item.get("id")
        )
        if campaign_id:
            report_campaign_ids.add(campaign_id)
    rows = []
    for campaign_id, snapshot in snapshots_by_campaign.items():
        if campaign_id in report_campaign_ids:
            continue
        rows.append(
            {
                "platform": "amazon",
                "account_id": normalize_whitespace(profile_id),
                "campaign_id": campaign_id,
                "campaign_name": snapshot.get("campaign_name") or campaign_id,
                "campaign_status": snapshot.get("campaign_status") or "Unknown",
                "campaign_site": snapshot.get("campaign_site") or _ad_campaign_site("amazon", profile_id),
                "campaign_goal": snapshot.get("campaign_goal") or "Sponsored TV",
                "metric_date": metric_date,
                "spend": 0.0,
                "impressions": 0,
                "clicks": 0,
                "reach": 0,
                "conversions": 0.0,
                "raw": snapshot.get("raw") or snapshot,
                "_synthetic_zero_metric": True,
            }
        )
    return rows


def _amazon_live_campaign_history_diagnostics(snapshots_by_campaign, report_rows, end_date):
    snapshots_by_campaign = snapshots_by_campaign if isinstance(snapshots_by_campaign, dict) else {}
    report_index = {}
    for item in report_rows if isinstance(report_rows, list) else []:
        if not isinstance(item, dict):
            continue
        normalized_item = _normalize_report_row_keys(item)
        campaign_id = normalize_whitespace(
            normalized_item.get("campaign_id")
            or item.get("campaignId")
            or item.get("campaign_id")
            or item.get("id")
        )
        metric_date = normalize_whitespace(
            normalized_item.get("date")
            or normalized_item.get("metric_date")
            or item.get("date")
        )
        if not campaign_id or not metric_date:
            continue
        bucket = report_index.setdefault(campaign_id, {"dates": set(), "rows": 0})
        bucket["rows"] += 1
        bucket["dates"].add(metric_date)
    diagnostics = []
    for campaign_id, snapshot in snapshots_by_campaign.items():
        status = _normalize_ad_campaign_status(snapshot.get("campaign_status"))
        if not _ad_status_is_live(status):
            continue
        campaign_name = normalize_whitespace(snapshot.get("campaign_name")) or campaign_id
        report_info = report_index.get(campaign_id)
        if not report_info or not report_info["dates"]:
            diagnostics.append(f"Live campaign '{campaign_name}' has no dated report rows yet.")
            continue
        dates = sorted(report_info["dates"])
        includes_end_date = normalize_whitespace(end_date) in report_info["dates"]
        diagnostics.append(
            "Live campaign '"
            + campaign_name
            + "' has "
            + str(len(dates))
            + " dated row(s) from "
            + dates[0]
            + " to "
            + dates[-1]
            + (" and includes today." if includes_end_date else " but does not include today.")
        )
    return diagnostics


