def slack_upload_file_external(db, channel_id, file_path, title="", initial_comment=""):
    settings = get_slack_settings(db)
    token = (settings.get("bot_token") or "").strip()
    if not token:
        raise ValueError("Slack bot token is not configured; XLSX upload requires files:write.")
    channel = (channel_id or "").strip()
    if not channel:
        raise ValueError("Slack channel_id is missing.")
    path = Path(file_path)
    if not path.exists():
        raise ValueError(f"File not found: {file_path}")
    size = path.stat().st_size
    filename = path.name
    headers = {"Authorization": f"Bearer {token}"}
    prep = requests.post(
        "https://slack.com/api/files.getUploadURLExternal",
        headers=headers,
        data={"filename": filename, "length": str(size)},
        timeout=30,
    )
    prep.raise_for_status()
    prep_data = prep.json()
    if not prep_data.get("ok"):
        raise ValueError(f"Slack upload URL failed: {prep_data.get('error') or prep_data}")
    upload_url = prep_data.get("upload_url")
    file_id = prep_data.get("file_id")
    with path.open("rb") as fh:
        upload = requests.post(
            upload_url,
            headers={"Content-Type": "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet"},
            data=fh,
            timeout=90,
        )
    if not upload.ok:
        raise ValueError(f"Slack file binary upload failed ({upload.status_code}): {upload.text}")
    complete = requests.post(
        "https://slack.com/api/files.completeUploadExternal",
        headers=headers,
        data={
            "files": json.dumps([{"id": file_id, "title": title or filename}]),
            "channel_id": channel,
            "initial_comment": initial_comment or "",
        },
        timeout=30,
    )
    complete.raise_for_status()
    complete_data = complete.json()
    if not complete_data.get("ok"):
        raise ValueError(f"Slack complete upload failed: {complete_data.get('error') or complete_data}")
    return {"ok": True, "file_id": file_id, "response": complete_data}


def process_slack_comp_request(request_id):
    db = open_sqlite_connection()
    try:
        row = db.execute("SELECT * FROM slack_comp_requests WHERE id = ? LIMIT 1", (int(request_id),)).fetchone()
        if not row:
            return
        db.execute(
            """
            UPDATE slack_comp_requests
            SET status = 'Running',
                started_at = CURRENT_TIMESTAMP,
                completed_at = NULL,
                summary_text = '',
                analysis_json = '',
                report_path = '',
                slack_file_id = '',
                error_message = ''
            WHERE id = ?
            """,
            (request_id,),
        )
        commit_with_retry(db)

        property_context = {}
        address = normalize_whitespace(row["address"] or "")
        if int(row["property_id"] or 0) > 0:
            address, property_context = _property_context_for_comp(db, int(row["property_id"]))
        if not address:
            raise ValueError("Comp request has no address.")

        analysis = run_manual_comping_skill_analysis(
            address,
            property_context=property_context,
            requested_by=row["slack_user_name"] or row["slack_user_id"] or "Slack",
        )
        subject = analysis.get("subject_property") if isinstance(analysis.get("subject_property"), dict) else {}
        filename_base = _slugify_filename(subject.get("address") or address)
        report_path = _comping_output_dir() / f"{filename_base}-comp-report-{int(request_id)}.xlsx"
        generate_manual_comping_xlsx(analysis, report_path)
        summary_text = _slack_text_limit(analysis.get("summary_text") or f"Comp report completed for {address}.", limit=2200)
        initial_comment = f"SIFT comp report completed for {address}.\n\n{summary_text}"
        upload_result = slack_upload_file_external(
            db,
            row["slack_channel_id"],
            report_path,
            title=f"SIFT Comp Report - {address}",
            initial_comment=_slack_text_limit(initial_comment, limit=2800),
        )
        db.execute(
            """
            UPDATE slack_comp_requests
            SET status = 'Completed',
                summary_text = ?,
                analysis_json = ?,
                report_path = ?,
                slack_file_id = ?,
                completed_at = CURRENT_TIMESTAMP
            WHERE id = ?
            """,
            (
                analysis.get("summary_text") or "",
                json.dumps(analysis, ensure_ascii=True),
                str(report_path),
                upload_result.get("file_id") or "",
                request_id,
            ),
        )
        commit_with_retry(db)
        if row["response_url"]:
            try:
                send_slack_response_url(row["response_url"], f"Comp report #{request_id} finished and XLSX was uploaded.", response_type="ephemeral")
            except Exception:
                pass
    except Exception as exc:
        db.rollback()
        message = f"Comp report #{request_id} failed: {exc}"
        try:
            db.execute(
                """
                UPDATE slack_comp_requests
                SET status = 'Failed', error_message = ?, completed_at = CURRENT_TIMESTAMP
                WHERE id = ?
                """,
                (str(exc), request_id),
            )
            log_app_error(
                db,
                source="slack_comp_worker",
                error_message=str(exc),
                details=traceback.format_exc(),
                route="/webhooks/slack/command",
                status_code=500,
            )
            commit_with_retry(db)
        except Exception:
            db.rollback()
        try:
            row = row if "row" in locals() else None
            if row and row["response_url"]:
                send_slack_response_url(row["response_url"], message, response_type="in_channel", replace_original=False)
        except Exception:
            pass
    finally:
        db.close()


def launch_slack_comp_request(request_id):
    worker = threading.Thread(target=process_slack_comp_request, args=(int(request_id),), daemon=True)
    worker.start()
    return worker


def enqueue_slack_comp_request(db, target, raw_text="", channel_id="", user_id="", user_name="", response_url=""):
    property_id = int(target.get("property_id") or 0)
    address = normalize_whitespace(target.get("address") or "")
    cur = db.execute(
        """
        INSERT INTO slack_comp_requests (
            status, property_id, address, raw_text, slack_channel_id, slack_user_id,
            slack_user_name, response_url
        )
        VALUES ('Queued', ?, ?, ?, ?, ?, ?, ?)
        """,
        (property_id or None, address, raw_text, channel_id, user_id, user_name, response_url),
    )
    request_id = int(cur.lastrowid or 0)
    return request_id


def _slack_comp_job_payload(db, row):
    if row is None:
        return None
    item = dict(row)
    property_context = {}
    address = normalize_whitespace(item.get("address") or "")
    property_id = int(item.get("property_id") or 0)
    if property_id > 0:
        address, property_context = _property_context_for_comp(db, property_id)
    item["address"] = address
    item["property_context"] = property_context
    return item


def claim_slack_comp_request_for_codex(db):
    row = db.execute(
        """
        SELECT *
        FROM slack_comp_requests
        WHERE status = 'Queued'
        ORDER BY id ASC
        LIMIT 1
        """
    ).fetchone()
    if row is None:
        return None
    db.execute(
        """
        UPDATE slack_comp_requests
        SET status = 'Claimed',
            started_at = CURRENT_TIMESTAMP,
            completed_at = NULL,
            summary_text = '',
            analysis_json = '',
            report_path = '',
            slack_file_id = '',
            error_message = ''
        WHERE id = ?
        """,
        (int(row["id"]),),
    )
    claimed = db.execute("SELECT * FROM slack_comp_requests WHERE id = ? LIMIT 1", (int(row["id"]),)).fetchone()
    return _slack_comp_job_payload(db, claimed)


def save_slack_comp_report_upload(db, request_id, uploaded_file=None, file_b64="", filename="", summary_text="", analysis_json=""):
    row = db.execute("SELECT * FROM slack_comp_requests WHERE id = ? LIMIT 1", (int(request_id),)).fetchone()
    if row is None:
        raise ValueError(f"Comp request #{request_id} not found.")
    target_dir = _comping_output_dir()
    filename = _slugify_filename(filename or row["address"] or f"comp-request-{request_id}", fallback=f"comp-request-{request_id}")
    if not filename.lower().endswith(".xlsx"):
        filename = f"{filename}.xlsx"
    report_path = target_dir / f"codex-{int(request_id)}-{filename}"
    if uploaded_file is not None:
        uploaded_file.save(report_path)
    elif file_b64:
        report_path.write_bytes(base64.b64decode(file_b64))
    else:
        raise ValueError("XLSX file is required.")
    if not report_path.exists() or report_path.stat().st_size <= 0:
        raise ValueError("Uploaded XLSX file was empty.")
    address = normalize_whitespace(row["address"] or "")
    if int(row["property_id"] or 0) > 0 and not address:
        try:
            address, _context = _property_context_for_comp(db, int(row["property_id"]))
        except Exception:
            address = f"property #{int(row['property_id'])}"
    initial_comment = _slack_text_limit(
        "\n\n".join(
            [
                f"SIFT Codex comp report completed for {address or f'request #{request_id}'}.",
                summary_text,
            ]
        ),
        limit=2800,
    )
    upload_result = slack_upload_file_external(
        db,
        row["slack_channel_id"],
        report_path,
        title=f"SIFT Codex Comp Report - {address or f'request #{request_id}'}",
        initial_comment=initial_comment,
    )
    db.execute(
        """
        UPDATE slack_comp_requests
        SET status = 'Completed',
            summary_text = ?,
            analysis_json = ?,
            report_path = ?,
            slack_file_id = ?,
            error_message = '',
            completed_at = CURRENT_TIMESTAMP
        WHERE id = ?
        """,
        (
            summary_text or "",
            analysis_json or "",
            str(report_path),
            upload_result.get("file_id") or "",
            int(request_id),
        ),
    )
    return {"ok": True, "request_id": int(request_id), "report_path": str(report_path), "slack_file_id": upload_result.get("file_id") or ""}


def fail_slack_comp_request(db, request_id, error_message):
    message = normalize_whitespace(error_message or "") or "Codex comp worker failed."
    row = db.execute("SELECT * FROM slack_comp_requests WHERE id = ? LIMIT 1", (int(request_id),)).fetchone()
    if row is None:
        raise ValueError(f"Comp request #{request_id} not found.")
    db.execute(
        """
        UPDATE slack_comp_requests
        SET status = 'Failed',
            error_message = ?,
            completed_at = CURRENT_TIMESTAMP
        WHERE id = ?
        """,
        (message, int(request_id)),
    )
    if row["response_url"]:
        try:
            send_slack_response_url(row["response_url"], f"SIFT Codex comp request #{request_id} failed: {message}", response_type="in_channel")
        except Exception:
            pass
    return {"ok": True, "request_id": int(request_id), "error_message": message}


def verify_slack_signature(req, signing_secret):
    secret = (signing_secret or "").strip()
    if not secret:
        return False, "Missing Slack signing secret configuration"
    timestamp = (req.headers.get("X-Slack-Request-Timestamp") or "").strip()
    signature = (req.headers.get("X-Slack-Signature") or "").strip()
    if not timestamp or not signature:
        return False, "Missing Slack signature headers"
    try:
        ts = int(timestamp)
    except ValueError:
        return False, "Invalid Slack timestamp"
    now_ts = int(time.time())
    if abs(now_ts - ts) > 60 * 5:
        return False, "Slack timestamp too old"
    body = req.get_data(as_text=True) or ""
    basestring = f"v0:{timestamp}:{body}"
    digest = hmac.new(secret.encode("utf-8"), basestring.encode("utf-8"), hashlib.sha256).hexdigest()
    expected = f"v0={digest}"
    if not hmac.compare_digest(expected, signature):
        return False, "Slack signature mismatch"
    return True, ""


def upsert_integration_event(db, source, event_key, payload):
    key = (event_key or "").strip()
    if not key:
        db.execute(
            "INSERT INTO integration_events (source, event_key, payload_json) VALUES (?, NULL, ?)",
            ((source or "").strip(), json.dumps(payload or {})),
        )
        return True
    exists = db.execute(
        "SELECT id FROM integration_events WHERE source = ? AND event_key = ?",
        ((source or "").strip(), key),
    ).fetchone()
    if exists:
        return False
    db.execute(
        "INSERT INTO integration_events (source, event_key, payload_json) VALUES (?, ?, ?)",
        ((source or "").strip(), key, json.dumps(payload or {})),
    )
    return True


def _normalize_untitled_email_values(*raw_values):
    emails = []
    seen = set()
    for raw_value in raw_values:
        if raw_value is None:
            continue
        if isinstance(raw_value, (list, tuple, set)):
            candidates = raw_value
        else:
            candidates = re.split(r"[,;\n]+", str(raw_value))
        for candidate in candidates:
            email = normalize_email(candidate)
            if email and email not in seen:
                seen.add(email)
                emails.append(email)
    return emails


def _format_untitled_email_values(*raw_values):
    return ", ".join(_normalize_untitled_email_values(*raw_values))


def _untitled_campaign_emails(prepared_row):
    if not isinstance(prepared_row, dict):
        return []
    return _normalize_untitled_email_values(
        prepared_row.get("email"),
        prepared_row.get("personal_email"),
    )


def _emailoctopus_member_id(email_address):
    return hashlib.md5((normalize_email(email_address) or "").encode("utf-8")).hexdigest()


def _safe_response_payload(response):
    try:
        return response.json()
    except Exception:
        return (response.text or "").strip()


def verify_email_with_emaillistverify(api_key, email_address):
    email_address = normalize_email(email_address)
    if not api_key:
        return {
            "ok": False,
            "provider": "emaillistverify",
            "email": email_address,
            "provider_status": "missing_api_key",
            "normalized_status": "awaiting_emaillistverify_config",
            "is_valid": False,
            "raw": "",
        }
    if not email_address:
        return {
            "ok": False,
            "provider": "emaillistverify",
            "email": "",
            "provider_status": "missing_email",
            "normalized_status": "missing_email",
            "is_valid": False,
            "raw": "",
        }
    response = requests.get(
        f"{EMAILLISTVERIFY_BASE_URL.rstrip('/')}/verifyEmail",
        params={"secret": api_key, "email": email_address},
        timeout=20,
    )
    raw_text = (response.text or "").strip()
    provider_status = raw_text.strip().lower()
    if not response.ok:
        emit_provider_alert(
            source="provider_emaillistverify",
            error_message=f"EmailListVerify request failed ({response.status_code}).",
            details=raw_text or "Unknown error",
            route="verify_email_with_emaillistverify",
            status_code=response.status_code,
        )
        raise ValueError(f"EmailListVerify failed ({response.status_code}): {raw_text or 'Unknown error'}")
    normalized_status = "error"
    if provider_status in {"ok", "valid"}:
        normalized_status = "valid"
    elif _is_emaillistverify_accept_all_status(provider_status):
        normalized_status = "unknown"
    elif provider_status in {"failed", "invalid", "incorrect"}:
        normalized_status = "invalid"
    elif provider_status == "unknown":
        normalized_status = "unknown"
    elif provider_status in {"key_not_valid", "missing_api_key"}:
        normalized_status = "awaiting_emaillistverify_config"
    elif "key" in provider_status and "valid" in provider_status:
        normalized_status = "awaiting_emaillistverify_config"
    elif _is_provider_capacity_issue(provider_status, raw_text):
        normalized_status = "awaiting_emaillistverify_provider_attention"
    elif normalized_status == "error":
        normalized_status = "unknown"
    return {
        "ok": normalized_status in {"valid", "invalid", "unknown"},
        "provider": "emaillistverify",
        "email": email_address,
        "provider_status": provider_status,
        "normalized_status": normalized_status,
        "is_valid": normalized_status == "valid",
        "raw": raw_text,
    }


def queue_touchpoint_email_validation(db, touchpoint_id, person_id, email_value, source="skiptrace"):
    try:
        touchpoint_id = int(touchpoint_id or 0)
    except Exception:
        touchpoint_id = 0
    email_value = normalize_email(email_value)
    if not touchpoint_id or not email_value:
        return None
    existing = db.execute(
        """
        SELECT id, queue_status
        FROM email_validation_queue
        WHERE touchpoint_id = ?
        LIMIT 1
        """,
        (touchpoint_id,),
    ).fetchone()
    now_stamp = format_db_time(datetime.utcnow())
    if existing:
        db.execute(
            """
            UPDATE email_validation_queue
            SET person_id = ?,
                email_value = ?,
                source = ?,
                run_after = ?,
                updated_at = CURRENT_TIMESTAMP,
                queue_status = CASE
                    WHEN lower(COALESCE(queue_status, '')) IN ('completed', 'skipped')
                        THEN queue_status
                    ELSE 'Queued'
                END
            WHERE id = ?
            """,
            (person_id, email_value, (source or "skiptrace").strip() or "skiptrace", now_stamp, existing["id"]),
        )
        return int(existing["id"])
    cur = db.execute(
        """
        INSERT INTO email_validation_queue (touchpoint_id, person_id, email_value, source, queue_status, run_after)
        VALUES (?, ?, ?, ?, 'Queued', ?)
        """,
        (touchpoint_id, person_id, email_value, (source or "skiptrace").strip() or "skiptrace", now_stamp),
    )
    return int(cur.lastrowid or 0)


def _append_touchpoint_note(existing_note, extra_line):
    existing = (existing_note or "").strip()
    extra = (extra_line or "").strip()
    if not extra:
        return existing
    if not existing:
        return extra
    if extra in existing:
        return existing
    return f"{existing}\n{extra}"


def run_touchpoint_email_validation_queue_once(limit=10):
    ensure_db()
    db = open_sqlite_connection()
    processed = 0
    updated = 0
    try:
        try:
            limit = max(1, min(50, int(limit)))
        except Exception:
            limit = 10
        settings = get_anonymous_email_marketing_settings(db)
        api_key = (settings.get("emaillistverify_api_key") or "").strip()
        if not api_key:
            return {"ok": True, "skipped": "awaiting_emaillistverify_config", "attempted": 0, "updated": 0}
        now_stamp = format_db_time(datetime.utcnow())
        rows = db.execute(
            """
            SELECT q.id, q.touchpoint_id, q.person_id, q.email_value, q.attempts, q.source,
                   t.status AS touchpoint_status, t.note AS touchpoint_note, t.value AS touchpoint_value
            FROM email_validation_queue q
            JOIN touchpoints t ON t.id = q.touchpoint_id
            WHERE lower(COALESCE(t.channel_type, '')) = 'email'
              AND lower(COALESCE(q.queue_status, 'queued')) IN ('queued', 'retry')
              AND COALESCE(q.run_after, '') <= ?
            ORDER BY q.id ASC
            LIMIT ?
            """,
            (now_stamp, limit),
        ).fetchall()
        for row in rows:
            processed += 1
            queue_id = int(row["id"])
            touchpoint_id = int(row["touchpoint_id"])
            email_value = normalize_email(row["touchpoint_value"] or row["email_value"] or "")
            touch_status = (row["touchpoint_status"] or "").strip()
            touch_status_norm = touch_status.lower()
            if not email_value:
                db.execute(
                    """
                    UPDATE email_validation_queue
                    SET queue_status = 'Skipped',
                        validation_status = 'missing_email',
                        validation_raw = '',
                        processed_at = ?,
                        updated_at = CURRENT_TIMESTAMP
                    WHERE id = ?
                    """,
                    (now_stamp, queue_id),
                )
                continue
            if touch_status_norm == "valid":
                db.execute(
                    """
                    UPDATE email_validation_queue
                    SET queue_status = 'Completed',
                        validation_status = 'valid',
                        validation_raw = '',
                        processed_at = ?,
                        updated_at = CURRENT_TIMESTAMP
                    WHERE id = ?
                    """,
                    (now_stamp, queue_id),
                )
                continue
            if touch_status_norm in BLOCKED_CONTACT_STATUSES:
                db.execute(
                    """
                    UPDATE email_validation_queue
                    SET queue_status = 'Skipped',
                        validation_status = ?,
                        validation_raw = '',
                        processed_at = ?,
                        updated_at = CURRENT_TIMESTAMP
                    WHERE id = ?
                    """,
                    (touch_status_norm or "blocked", now_stamp, queue_id),
                )
                continue
            try:
                validation_result = verify_email_with_emaillistverify(api_key, email_value)
            except Exception as exc:
                validation_result = {
                    "ok": False,
                    "provider": "emaillistverify",
                    "email": email_value,
                    "provider_status": "error",
                    "normalized_status": "error",
                    "is_valid": False,
                    "raw": str(exc),
                }
            normalized_status = (validation_result.get("normalized_status") or "").strip().lower()
            if normalized_status in {"awaiting_emaillistverify_config", "awaiting_emaillistverify_provider_attention", "error"}:
                retry_minutes = 15 if normalized_status == "awaiting_emaillistverify_config" else 60
                db.execute(
                    """
                    UPDATE email_validation_queue
                    SET queue_status = 'Retry',
                        validation_status = ?,
                        validation_raw = ?,
                        attempts = COALESCE(attempts, 0) + 1,
                        run_after = ?,
                        updated_at = CURRENT_TIMESTAMP
                    WHERE id = ?
                    """,
                    (
                        normalized_status,
                        json.dumps(validation_result, ensure_ascii=True, sort_keys=True),
                        format_db_time(datetime.utcnow() + timedelta(minutes=retry_minutes)),
                        queue_id,
                    ),
                )
                continue
            if normalized_status == "valid":
                new_touch_status = "Valid"
            elif normalized_status == "unknown":
                new_touch_status = "Unknown"
            else:
                new_touch_status = "Undeliverable"
            provider_status = (validation_result.get("provider_status") or normalized_status or "error").strip()
            note_line = (
                f"EmailListVerify checked {now_stamp}: {provider_status}."
                if new_touch_status == "Valid"
                else (
                    f"EmailListVerify checked {now_stamp}: marked unknown ({provider_status})."
                    if new_touch_status == "Unknown"
                    else f"EmailListVerify checked {now_stamp}: marked undeliverable ({provider_status})."
                )
            )
            merged_note = _append_touchpoint_note(row["touchpoint_note"], note_line)
            db.execute(
                """
                UPDATE touchpoints
                SET status = ?,
                    note = ?,
                    value = ?
                WHERE id = ?
                """,
                (new_touch_status, merged_note, email_value, touchpoint_id),
            )
            log_email_validation_result(
                db,
                row["person_id"],
                email_value,
                new_touch_status,
                validation_result,
            )
            db.execute(
                """
                UPDATE email_validation_queue
                SET queue_status = 'Completed',
                    validation_status = ?,
                    validation_raw = ?,
                    processed_at = ?,
                    attempts = COALESCE(attempts, 0) + 1,
                    updated_at = CURRENT_TIMESTAMP
                WHERE id = ?
                """,
                (
                    normalized_status or ("valid" if new_touch_status == "Valid" else "error"),
                    json.dumps(validation_result, ensure_ascii=True, sort_keys=True),
                    now_stamp,
                    queue_id,
                ),
            )
            updated += 1
        db.commit()
        return {"ok": True, "attempted": processed, "updated": updated}
    except Exception as exc:
        db.rollback()
        log_app_error(
            db,
            source="email_validation_queue_worker",
            error_message=str(exc),
            details=traceback.format_exc(),
            route="run_touchpoint_email_validation_queue_once",
            status_code=500,
        )
        db.commit()
        return {"ok": False, "error": str(exc), "attempted": processed, "updated": updated}
    finally:
        db.close()


def emailoctopus_upsert_contact(api_key, list_id, email_address, contact_status="PENDING", tags=None):
    email_address = normalize_email(email_address)
    if not api_key:
        raise ValueError("EmailOctopus API key is missing")
    if not list_id:
        raise ValueError("EmailOctopus list id is missing")
    if not email_address:
        raise ValueError("Email address is missing")
    base_url = EMAILOCTOPUS_BASE_URL.rstrip("/")
    create_payload = {
        "api_key": api_key,
        "email_address": email_address,
        "status": (contact_status or "PENDING").strip().upper() or "PENDING",
    }
    clean_tags = [str(tag).strip() for tag in (tags or []) if str(tag).strip()]
    if clean_tags:
        create_payload["tags"] = list(dict.fromkeys(clean_tags))
    response = requests.post(
        f"{base_url}/lists/{quote_plus(list_id)}/contacts",
        headers={"Content-Type": "application/json"},
        json=create_payload,
        timeout=20,
    )
    payload = _safe_response_payload(response)
    if response.ok:
        payload_dict = payload if isinstance(payload, dict) else {}
        return {
            "ok": True,
            "action": "created",
            "status": str(payload_dict.get("status") or create_payload["status"]).strip().upper(),
            "contact_id": str(payload_dict.get("id") or payload_dict.get("contact_id") or _emailoctopus_member_id(email_address)),
            "response": payload,
        }
    error_code = ""
    if isinstance(payload, dict):
        error_code = str(payload.get("code") or payload.get("error") or "").strip().upper()
    if error_code == "MEMBER_EXISTS_WITH_EMAIL_ADDRESS" or response.status_code == 409:
        update_payload = {
            "api_key": api_key,
            "status": create_payload["status"],
        }
        if clean_tags:
            update_payload["tags"] = {tag: True for tag in clean_tags}
        member_id = _emailoctopus_member_id(email_address)
        update_response = requests.put(
            f"{base_url}/lists/{quote_plus(list_id)}/contacts/{member_id}",
            headers={"Content-Type": "application/json"},
            json=update_payload,
            timeout=20,
        )
        update_payload_body = _safe_response_payload(update_response)
        if update_response.ok:
            update_dict = update_payload_body if isinstance(update_payload_body, dict) else {}
            return {
                "ok": True,
                "action": "updated",
                "status": str(update_dict.get("status") or update_payload["status"]).strip().upper(),
                "contact_id": str(update_dict.get("id") or update_dict.get("contact_id") or member_id),
                "response": update_payload_body,
            }
        raise ValueError(
            f"EmailOctopus update failed ({update_response.status_code}): {json.dumps(update_payload_body) if isinstance(update_payload_body, dict) else update_payload_body}"
        )
    raise ValueError(
        f"EmailOctopus create failed ({response.status_code}): {json.dumps(payload) if isinstance(payload, dict) else payload}"
    )


def emailoctopus_set_contact_status(api_key, list_id, email_address, status="UNSUBSCRIBED"):
    email_address = normalize_email(email_address)
    if not api_key or not list_id or not email_address:
        return {"ok": False, "skipped": "missing_config_or_email"}
    member_id = _emailoctopus_member_id(email_address)
    response = requests.put(
        f"{EMAILOCTOPUS_BASE_URL.rstrip('/')}/lists/{quote_plus(list_id)}/contacts/{member_id}",
        headers={"Content-Type": "application/json"},
        json={"api_key": api_key, "status": (status or "UNSUBSCRIBED").strip().upper() or "UNSUBSCRIBED"},
        timeout=20,
    )
    payload = _safe_response_payload(response)
    if response.ok:
        payload_dict = payload if isinstance(payload, dict) else {}
        return {
            "ok": True,
            "status": str(payload_dict.get("status") or status).strip().upper(),
            "contact_id": str(payload_dict.get("id") or payload_dict.get("contact_id") or member_id),
            "response": payload,
        }
    if isinstance(payload, dict):
        error_code = str(payload.get("code") or payload.get("error") or "").strip().upper()
        if error_code in {"MEMBER_NOT_FOUND", "CONTACT_NOT_FOUND"}:
            return {"ok": True, "status": "UNSUBSCRIBED", "contact_id": member_id, "response": payload}
    raise ValueError(
        f"EmailOctopus status update failed ({response.status_code}): {json.dumps(payload) if isinstance(payload, dict) else payload}"
    )


def upsert_anonymous_email_campaign_registry(db, normalized_email, source="manual_import", source_identifier="", first_name="", last_name="", status="already_sent", notes=""):
    normalized_email = normalize_email(normalized_email)
    if not normalized_email:
        return False
    timestamp = format_db_time(datetime.utcnow())
    db.execute(
        """
        INSERT INTO anonymous_email_campaign_registry (
            normalized_email, source, source_identifier, first_name, last_name, status, notes, created_at, updated_at
        )
        VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)
        ON CONFLICT(normalized_email) DO UPDATE SET
            source = excluded.source,
            source_identifier = CASE
                WHEN COALESCE(excluded.source_identifier, '') <> '' THEN excluded.source_identifier
                ELSE anonymous_email_campaign_registry.source_identifier
            END,
            first_name = CASE
                WHEN COALESCE(excluded.first_name, '') <> '' THEN excluded.first_name
                ELSE anonymous_email_campaign_registry.first_name
            END,
            last_name = CASE
                WHEN COALESCE(excluded.last_name, '') <> '' THEN excluded.last_name
                ELSE anonymous_email_campaign_registry.last_name
            END,
            status = excluded.status,
            notes = CASE
                WHEN COALESCE(excluded.notes, '') <> '' THEN excluded.notes
                ELSE anonymous_email_campaign_registry.notes
            END,
            updated_at = excluded.updated_at
        """,
        (
            normalized_email,
            (source or "manual_import").strip() or "manual_import",
            (source_identifier or "").strip(),
            (first_name or "").strip(),
            (last_name or "").strip(),
            (status or "already_sent").strip() or "already_sent",
            (notes or "").strip(),
            timestamp,
            timestamp,
        ),
    )
    return True


def _import_emailoctopus_export_reader(db, reader, source="emailoctopus_export", source_label=""):
    inserted = 0
    rows_seen = 0
    label = (source_label or source or "EmailOctopus export").strip()
    for row in reader:
        rows_seen += 1
        email_address = normalize_email(row.get("Email address") or row.get("email") or "")
        if not email_address:
            continue
        upsert_anonymous_email_campaign_registry(
            db,
            email_address,
            source=source,
            source_identifier=row.get("Identifier") or row.get("id") or "",
            first_name=row.get("First name") or "",
            last_name=row.get("Last name") or "",
            status="already_sent",
            notes=f"Imported from {label}",
        )
        inserted += 1
    return {"ok": True, "rows_seen": rows_seen, "emails_imported": inserted, "source_label": label}


def import_emailoctopus_export_csv(db, csv_path, source="emailoctopus_export"):
    path = Path(csv_path).expanduser()
    if not path.exists():
        raise FileNotFoundError(f"CSV not found: {path}")
    with path.open("r", encoding="utf-8-sig", newline="") as handle:
        reader = csv.DictReader(handle)
        result = _import_emailoctopus_export_reader(db, reader, source=source, source_label=path.name)
    result["path"] = str(path)
    return result


def import_emailoctopus_export_upload(db, upload, source="emailoctopus_export_upload"):
    if not upload:
        raise ValueError("Choose an EmailOctopus export CSV to import.")
    raw = upload.read()
    if isinstance(raw, bytes):
        raw = raw.decode("utf-8-sig", errors="ignore")
    raw = raw or ""
    reader = csv.DictReader(io.StringIO(raw))
    result = _import_emailoctopus_export_reader(
        db,
        reader,
        source=source,
        source_label=getattr(upload, "filename", "") or "uploaded CSV",
    )
    result["filename"] = getattr(upload, "filename", "") or ""
    return result


def _untitled_email_tags(prepared_row):
    tags = ["Untitled Anonymous Lead"]
    lead_category = str(prepared_row.get("lead_category") or "").strip()
    if lead_category:
        tags.append(f"Untitled {lead_category.title()}")
    return list(dict.fromkeys(tags))


