def run_website_step1_hold_once():
    ensure_db()
    db = open_sqlite_connection()
    try:
        now_utc = format_db_time(datetime.utcnow())
        rows = db.execute(
            """
            SELECT id, lead_key, latest_address, latest_phone, latest_email, latest_name, latest_stage,
                   hold_expires_at, step1_payload_json, reisift_property_uuid, reisift_owner_uuid, local_property_id
            FROM website_lead_submissions
            WHERE status = 'pending_step2'
              AND hold_expires_at IS NOT NULL
              AND hold_expires_at <= ?
            ORDER BY id ASC
            LIMIT 100
            """,
            (now_utc,),
        ).fetchall()
        notified = 0
        for row in rows:
            step1_payload = parse_json_object(row["step1_payload_json"] or "{}")
            fields = _extract_website_lead_fields(step1_payload) if isinstance(step1_payload, dict) else {}
            merged_fields = {
                "stage": (fields.get("stage") or row["latest_stage"] or "").strip(),
                "address": (fields.get("address") or row["latest_address"] or "").strip(),
                "street": (fields.get("street") or "").strip(),
                "city": (fields.get("city") or "").strip(),
                "state": (fields.get("state") or "").strip(),
                "postal_code": (fields.get("postal_code") or "").strip(),
                "seller_name": (fields.get("seller_name") or row["latest_name"] or "").strip(),
                "phone": (fields.get("phone") or row["latest_phone"] or "").strip(),
                "email": (fields.get("email") or row["latest_email"] or "").strip(),
            }
            created_uuid = str(row["reisift_property_uuid"] or "").strip()
            owner_uuid = str(row["reisift_owner_uuid"] or "").strip()
            local_property_id = int((row["local_property_id"] if "local_property_id" in row.keys() else 0) or 0)
            create_result = None
            contact_sync = None
            note_sync = None
            list_sync = None
            tag_sync = None
            duplicate_existing = False
            duplicate_reason = ""
            mode = "step1_only_timeout"
            status_value = "timed_out_step1_only"
            note_body = "Website lead processing result\nResult: timed_out\nMode: step1_only_timeout"
            note_payload = {
                "lead_key": row["lead_key"],
                "latest_address": merged_fields.get("address") or "",
                "latest_phone": merged_fields.get("phone") or "",
                "latest_email": merged_fields.get("email") or "",
                "hold_expires_at": row["hold_expires_at"],
            }
            processing_result = {
                "mode": mode,
                "reason": "Step-2 not received within hold window",
                "processed_at": now_utc,
                "created_uuid": created_uuid,
                "owner_uuid": owner_uuid,
                "duplicate_existing": duplicate_existing,
                "duplicate_reason": duplicate_reason,
                "create_result": create_result,
                "contact_sync": contact_sync,
                "note_sync": note_sync,
                "list_sync": list_sync,
                "tag_sync": tag_sync,
            }
            should_notify = False
            slack_result = {"sent": False, "error": ""}
            error_text = ""

            try:
                if merged_fields["address"] and not created_uuid:
                    owner_name_split = _parse_seller_name_for_owner(merged_fields.get("seller_name") or "")
                    owner_payload = {}
                    if owner_name_split.get("first_name") or owner_name_split.get("last_name"):
                        owner_payload["first_name"] = owner_name_split.get("first_name") or "Unknown"
                        owner_payload["last_name"] = owner_name_split.get("last_name") or "Owner"
                    if merged_fields.get("email"):
                        owner_payload["emails"] = [merged_fields.get("email")]
                    if merged_fields.get("phone"):
                        owner_payload["phones"] = [{"number": merged_fields.get("phone"), "type": "UNKNOWN", "status": "UNKNOWN"}]
                    notes = _build_website_lead_notes(step1_payload, merged_fields, source_label="step1_timeout_worker")
                    additional_note = _build_website_additional_note(step1_payload)
                    create_payload = {
                        "search": merged_fields.get("address") or "",
                        "street": merged_fields.get("street") or "",
                        "city": merged_fields.get("city") or "",
                        "state": merged_fields.get("state") or "",
                        "postal_code": merged_fields.get("postal_code") or "",
                        "status": "new_lead",
                        "lists": "Carrot",
                        "tags": build_website_reisift_tags("Stage1", step1_payload),
                        "notes": f"{notes}\n\n{additional_note}".strip() if additional_note else notes,
                        "owner": owner_payload,
                        "force_map_lookup": True,
                    }
                    create_result = create_reisift_property_from_search(create_payload)
                    created_uuid = str(create_result.get("created_uuid") or "").strip()
                    owner_uuid = str(create_result.get("owner_uuid") or "").strip()
                    duplicate_existing = bool(create_result.get("duplicate_existing"))
                    duplicate_reason = str(create_result.get("duplicate_reason") or "").strip()
                    if duplicate_existing:
                        mode = "step1_only_timeout_duplicate"
                    if created_uuid:
                        token = reisift_get_access_token()
                        if token and not owner_uuid:
                            try:
                                owner_uuid = _reisift_find_owner_uuid(fetch_reisift_property_payload(token, created_uuid)) or owner_uuid
                            except Exception:
                                pass
                        if token and owner_uuid and (merged_fields.get("email") or merged_fields.get("phone")):
                            contact_sync = reisift_upsert_owner_contacts(
                                token,
                                owner_uuid,
                                [{"number": merged_fields.get("phone"), "type": "UNKNOWN"}] if merged_fields.get("phone") else [],
                                [merged_fields.get("email")] if merged_fields.get("email") else [],
                            )
                        if token and created_uuid and additional_note:
                            note_sync = reisift_append_property_note(token, created_uuid, additional_note)
                if created_uuid:
                    try:
                        token = reisift_get_access_token()
                        try:
                            list_sync = reisift_sync_property_lists(token, created_uuid, ["Carrot"])
                        except Exception as exc:
                            list_sync = {"ok": False, "property_uuid": created_uuid, "error": str(exc)}
                        tag_sync = reisift_append_property_tags(
                            token,
                            created_uuid,
                            _website_reisift_tags_list("Stage1", step1_payload),
                        )
                    except Exception as exc:
                        tag_sync = {"ok": False, "property_uuid": created_uuid, "error": str(exc)}

                should_notify = True
                note_payload.update(
                    {
                        "created_uuid": created_uuid,
                        "owner_uuid": owner_uuid,
                        "duplicate_existing": duplicate_existing,
                        "duplicate_reason": duplicate_reason,
                    }
                )
            except Exception as exc:
                err = str(exc)
                mode = "step1_only_timeout_failed"
                status_value = "timed_out_step1_only_failed"
                if "Could not parse property address without map lookup." in err:
                    mode = "step1_only_timeout_incomplete_address"
                    status_value = "timed_out_step1_only_incomplete_address"
                error_text = err
                should_notify = True
                note_body = f"Website lead processing result\nResult: timed_out_failed\nMode: {mode}\nError: {err}"
                note_payload.update({"error": err, "create_result": create_result})
                processing_result = {
                    "mode": mode,
                    "reason": "Step-2 not received within hold window",
                    "processed_at": now_utc,
                    "error": err,
                    "created_uuid": created_uuid,
                    "owner_uuid": owner_uuid,
                    "duplicate_existing": duplicate_existing,
                    "duplicate_reason": duplicate_reason,
                    "create_result": create_result,
                    "contact_sync": contact_sync,
                    "note_sync": note_sync,
                    "list_sync": list_sync,
                    "tag_sync": tag_sync,
                }
                log_app_error(
                    db,
                    source="website_lead_hold_worker",
                    error_message=err,
                    details=traceback.format_exc(),
                    route="run_website_step1_hold_once",
                    status_code=500,
                )

            try:
                local_ctx = ensure_local_property_for_submitted_lead(
                    db,
                    source_label="Website",
                    address=merged_fields.get("address") or "",
                    street=merged_fields.get("street") or "",
                    city=merged_fields.get("city") or "",
                    state=merged_fields.get("state") or "",
                    postal_code=merged_fields.get("postal_code") or "",
                    seller_name=merged_fields.get("seller_name") or "",
                    first_name=merged_fields.get("first_name") or "",
                    last_name=merged_fields.get("last_name") or "",
                    phone=merged_fields.get("phone") or "",
                    email=merged_fields.get("email") or "",
                    property_uuid=created_uuid,
                    owner_uuid=owner_uuid,
                    existing_property_id=local_property_id,
                    lead_key=row["lead_key"],
                    payload=step1_payload if isinstance(step1_payload, dict) else {},
                )
                local_property_id = int(local_ctx.get("property_id") or local_property_id)
            except Exception as local_exc:
                log_app_error(
                    db,
                    source="website_local_property",
                    error_message=str(local_exc),
                    details=traceback.format_exc(),
                    route="run_website_step1_hold_once:local_property",
                    status_code=500,
                )

            if should_notify:
                sift_link = _sift_record_url(created_uuid)
                slack_lines = [
                    "Website Lead SIFT Handling",
                    f"Stage: {merged_fields.get('stage') or '-'}",
                    "Step Type: step1",
                    f"Mode: {mode}",
                    f"Address: {merged_fields.get('address') or '-'}",
                    f"Name: {merged_fields.get('seller_name') or '-'}",
                    f"Phone: {merged_fields.get('phone') or '-'}",
                    f"Email: {merged_fields.get('email') or '-'}",
                    f"SIFT Record: {sift_link or '-'}",
                    "Reason: Step-2 not received within 10 minutes.",
                ]
                if duplicate_reason:
                    slack_lines.append(f"Reason Detail: {duplicate_reason}")
                if error_text:
                    slack_lines.append(f"Error: {error_text}")
                try:
                    send_slack_notification(db, "\n".join(slack_lines))
                    slack_result["sent"] = True
                    notified += 1
                except Exception as exc:
                    slack_result["error"] = str(exc)
                    log_app_error(
                        db,
                        source="website_lead_hold_worker",
                        error_message=str(exc),
                        details=traceback.format_exc(),
                        route="run_website_step1_hold_once:slack",
                        status_code=500,
                    )

            processing_result.update(
                {
                    "mode": mode,
                    "created_uuid": created_uuid,
                    "owner_uuid": owner_uuid,
                    "duplicate_existing": duplicate_existing,
                    "duplicate_reason": duplicate_reason,
                    "create_result": create_result,
                    "contact_sync": contact_sync,
                    "note_sync": note_sync,
                    "list_sync": list_sync,
                    "tag_sync": tag_sync,
                    "slack_result": slack_result,
                }
            )
            db.execute(
                """
                UPDATE website_lead_submissions
                SET status = ?,
                    reisift_property_uuid = COALESCE(NULLIF(?, ''), reisift_property_uuid),
                    reisift_owner_uuid = COALESCE(NULLIF(?, ''), reisift_owner_uuid),
                    local_property_id = COALESCE(NULLIF(?, 0), local_property_id),
                    processed_at = ?,
                    processing_result_json = ?,
                    hold_expires_at = NULL
                WHERE id = ?
                """,
                (
                    status_value,
                    created_uuid,
                    owner_uuid,
                    local_property_id,
                    now_utc,
                    json.dumps(processing_result),
                    int(row["id"]),
                ),
            )
            add_website_webhook_note(
                db,
                str(row["lead_key"] or ""),
                str(row["lead_key"] or ""),
                note_body,
                note_payload,
            )
        db.commit()
        return {"ok": True, "timed_out": len(rows), "notified": notified}
    except Exception as exc:
        db.rollback()
        log_app_error(
            db,
            source="website_lead_hold_worker",
            error_message=str(exc),
            details=traceback.format_exc(),
            route="run_website_step1_hold_once",
            status_code=500,
        )
        db.commit()
        return {"ok": False, "error": str(exc)}
    finally:
        db.close()


def start_website_leads_hold_worker():
    global WEBSITE_LEADS_HOLD_WORKER_STARTED
    if WEBSITE_LEADS_HOLD_WORKER_STARTED:
        return
    WEBSITE_LEADS_HOLD_WORKER_STARTED = True

    def worker():
        while True:
            try:
                run_website_step1_hold_once()
            except Exception:
                pass
            time.sleep(WEBSITE_STEP1_HOLD_POLL_SECONDS)

    thread = threading.Thread(target=worker, daemon=True)
    thread.start()


def _queue_call_analysis_lead_action(db, job_row, analysis):
    property_id = job_row["property_id"]
    person_id = job_row["person_id"]
    if not property_id:
        return
    next_step = (analysis.get("next_best_step") or "Follow Up").strip()
    mapping = {
        "Schedule Appointment": ("ScheduleAppointment", "High"),
        "Follow Up": ("FollowUpTouchDue", "Medium"),
        "Escalate To Relative": ("EscalateToRelativeOutreach", "High"),
        "Deep Dive": ("EscalateToDeepDiveResearch", "High"),
        "Mark Not Interested": ("HumanReviewDisposition", "High"),
        "Mark Opt Out": ("HumanReviewDisposition", "High"),
        "No Action": ("ReviewInboundAndNextBestAction", "Low"),
    }
    action_type, priority = mapping.get(next_step, ("ReviewInboundAndNextBestAction", "Medium"))
    reason = (
        f"Call analysis recommends: {next_step}. "
        f"Intent: {(analysis.get('caller_intent') or 'Unknown')}. "
        f"Sentiment: {(analysis.get('sentiment') or 'Unknown')}."
    )
    _upsert_lead_action(
        db,
        int(property_id),
        person_id,
        action_type,
        priority,
        reason,
        {
            "source": "call_recording_analysis",
            "call_sid": job_row["call_sid"],
            "recording_url": job_row["recording_url"],
            "analysis": analysis,
        },
    )


def _create_agent_diagnosis_review_action(db, property_id, person_id, call_sid, diagnosis, attempted_fix, proposed_resolution, priority="Medium", extra=None):
    if not property_id:
        return False
    reason = (
        f"Agent diagnosis for call {call_sid or '-'}: {diagnosis}. "
        f"Attempted: {attempted_fix}. Proposed: {proposed_resolution}."
    )
    payload = {
        "source": "agent_call_issue_handler",
        "call_sid": call_sid,
        "diagnosis": diagnosis,
        "attempted_fix": attempted_fix,
        "proposed_resolution": proposed_resolution,
    }
    if extra:
        payload["extra"] = extra
    return _upsert_lead_action(
        db,
        int(property_id),
        person_id,
        "AgentDiagnosisReview",
        priority,
        reason,
        payload,
    )


def _recommend_no_answer_next_step(db, property_id, person_id):
    prop = db.execute("SELECT status FROM properties WHERE id = ?", (property_id,)).fetchone()
    status = _normalize_reisift_status((prop["status"] if prop else "") or "")
    if status in {"not interested", "opt-out", "dead lead"}:
        return "No Action", "Lead status is dispositioned; no-answer call should not trigger additional outreach."

    row = db.execute(
        """
        SELECT COUNT(*) AS c
        FROM call_recording_jobs
        WHERE property_id = ?
          AND COALESCE(person_id, 0) = COALESCE(?, 0)
          AND (
                lower(payload_json) LIKE '%\"call_outcome\": \"missed\"%'
             OR lower(payload_json) LIKE '%\"call_outcome\": \"no_answer\"%'
             OR lower(payload_json) LIKE '%\"call_outcome\": \"failed\"%'
             OR lower(payload_json) LIKE '%\"calloutcome\": \"missed\"%'
             OR lower(payload_json) LIKE '%\"calloutcome\": \"no_answer\"%'
             OR lower(payload_json) LIKE '%\"calloutcome\": \"failed\"%'
          )
        """,
        (property_id, person_id),
    ).fetchone()
    no_answer_attempts = int((row["c"] if row else 0) or 0)

    if no_answer_attempts >= 3:
        return "Escalate To Relative", "Three or more no-answer outcomes detected; escalate outreach path."
    if status in {"new lead", "no contact new lead"}:
        return "Follow Up", "New lead with no answer; retry follow-up cadence."
    return "Follow Up", "No-answer outcome; keep lead in follow-up workflow."


def _detect_audio_extension(content_type, fallback_url=""):
    ctype = (content_type or "").split(";")[0].strip().lower()
    guessed_ext = mimetypes.guess_extension(ctype) if ctype else None
    if guessed_ext:
        return guessed_ext
    path = urlsplit(fallback_url or "").path or ""
    if "." in path:
        ext = "." + path.rsplit(".", 1)[-1].lower()
        if len(ext) <= 6:
            return ext
    return ".mp3"


def process_single_call_recording_job(db, job_row, force_reanalyze=False):
    job_id = int(job_row["id"])
    call_sid = (job_row["call_sid"] or "").strip()
    recording_url = (job_row["recording_url"] or "").strip()
    from_number = (job_row["from_number"] or "").strip()
    to_number = (job_row["to_number"] or "").strip()
    property_id = job_row["property_id"]
    person_id = job_row["person_id"]
    payload_obj = parse_json_object(job_row["payload_json"] or "{}")
    webhook = payload_obj.get("webhook") if isinstance(payload_obj.get("webhook"), dict) else {}
    call_outcome = str(
        webhook.get("callOutcome")
        or webhook.get("call_outcome")
        or payload_obj.get("call_outcome")
        or ""
    ).strip()
    agent_user_name = (
        extract_first_string_by_keys(webhook, ["userName", "user_name", "agentName"])
        or ""
    ).strip()
    caller_name = (
        extract_first_string_by_keys(webhook, ["userName", "user_name", "agentName", "callerName"])
        or extract_first_string_by_keys(webhook, ["callerIdName", "caller_id_name"])
        or ""
    ).strip()
    callee_name = (
        extract_first_string_by_keys(webhook, ["contactName", "contact_name"])
        or ""
    ).strip()
    if not caller_name or not callee_name:
        event_caller, event_callee = _lookup_call_party_names_from_smrt_events(db, call_sid)
        caller_name = caller_name or event_caller
        callee_name = callee_name or event_callee
    call_direction = _infer_call_direction_from_numbers(db, from_number, to_number, agent_user_name=agent_user_name)

    # Keep call-job context fresh even when initial webhook could not map property/person.
    if not property_id or not _get_local_property_uuid(db, property_id):
        resolved_ctx = resolve_shared_event_context(
            db,
            from_number,
            to_number,
            fallback_property_id=property_id,
            force_reisift=True,
            search_reisift=True,
        ) or {}
        if (not property_id) and int(resolved_ctx.get("property_id") or 0):
            property_id = int(resolved_ctx.get("property_id") or 0)
        if (not person_id) and int(resolved_ctx.get("person_id") or 0):
            person_id = int(resolved_ctx.get("person_id") or 0)
        if property_id or person_id:
            db.execute(
                """
                UPDATE call_recording_jobs
                SET property_id = COALESCE(?, property_id),
                    person_id = COALESCE(?, person_id),
                    updated_at = CURRENT_TIMESTAMP
                WHERE id = ?
                """,
                (property_id, person_id, job_id),
            )
    analysis_context = {
        "direction": call_direction,
        "call_outcome": call_outcome,
        "from_number": from_number,
        "to_number": to_number,
        "caller_name": caller_name or ("Our Team" if call_direction == "Outbound" else "Lead Caller"),
        "callee_name": callee_name or ("Lead Contact" if call_direction == "Outbound" else "Our Team"),
        "timestamp": extract_first_string_by_keys(webhook, ["date", "timestamp", "completed_at"]),
    }

    existing_transcript = (job_row["transcript_text"] or "").strip()
    # Retry recording-url lookup if not present yet.
    lookup_raw = {}
    fetch_status = (job_row["fetch_status"] or "Queued").strip()
    if not recording_url and not (force_reanalyze and existing_transcript):
        lookup = fetch_smrtphone_recording_url(call_sid)
        lookup_raw = lookup.get("raw") or {}
        recording_url = (lookup.get("recording_url") or "").strip()
        fetch_status = "Fetched" if recording_url else "No Recording URL"
        db.execute(
            """
            UPDATE call_recording_jobs
            SET recording_url = ?, fetch_status = ?, payload_json = ?, updated_at = CURRENT_TIMESTAMP
            WHERE id = ?
            """,
            (
                recording_url,
                fetch_status,
                json.dumps({**payload_obj, "recording_lookup": lookup_raw}),
                job_id,
            ),
        )
        if not recording_url:
            outcome = (call_outcome or "").strip().lower()
            analysis_status = "No Recording"
            no_recording_summary = ""
            if outcome in NO_ANSWER_OUTCOMES:
                if outcome == "failed":
                    no_recording_summary = (
                        f"{call_direction} call failed before conversation started."
                    )
                else:
                    no_recording_summary = (
                        f"{call_direction} call resulted in no answer/voicemail; recording was not available."
                    )
                if property_id:
                    recommended_step, reason = _recommend_no_answer_next_step(db, int(property_id), person_id)
                    upsert_agent_signal(
                        db,
                        source_type="call",
                        source_key=f"call-no-answer:{call_sid}",
                        property_id=property_id,
                        person_id=person_id,
                        channel="CALL",
                        intent="No Answer",
                        sentiment="Unknown",
                        confidence=0.85,
                        recommended_next_step=recommended_step,
                        summary_text=f"No-answer call outcome. {reason}",
                        is_spam=False,
                        do_not_contact=False,
                        payload={"call_sid": call_sid, "call_outcome": outcome, "reason": reason},
                    )
                    route_new_agent_signals_once(db, limit=25)
                    trigger_agent_pipeline_refresh(db, property_id=int(property_id), reason="call_no_answer")
            else:
                no_recording_summary = (
                    f"{call_direction} call completed but no recording URL was returned by provider."
                )
                if property_id:
                    _create_agent_diagnosis_review_action(
                        db,
                        property_id=int(property_id),
                        person_id=person_id,
                        call_sid=call_sid,
                        diagnosis="Recording URL unavailable for completed call",
                        attempted_fix="Attempted smrtPhone recording lookup using call SID",
                        proposed_resolution="Monitor for delayed recording availability or validate provider recording configuration.",
                        priority="Medium",
                        extra={"fetch_status": fetch_status},
                    )
            db.execute(
                "UPDATE call_recording_jobs SET analysis_status = ?, summary_text = ?, updated_at = CURRENT_TIMESTAMP WHERE id = ?",
                (analysis_status, no_recording_summary, job_id),
            )
            if property_id:
                trigger_agent_pipeline_refresh(db, property_id=int(property_id), reason="call_no_recording")
            return {"job_id": job_id, "status": "no_recording_url", "call_outcome": outcome}

    if force_reanalyze and existing_transcript:
        transcription = {"transcript": existing_transcript, "raw": {"source": "existing_transcript"}}
        transcript = existing_transcript
    else:
        audio_res = requests.get(recording_url, timeout=60)
        audio_res.raise_for_status()
        audio_bytes = audio_res.content
        ext = _detect_audio_extension(audio_res.headers.get("content-type"), recording_url)
        filename = f"{call_sid or f'call_{job_id}'}{ext}"
        mime_type = (audio_res.headers.get("content-type") or "").split(";")[0].strip() or "application/octet-stream"
        transcription = transcribe_recording_with_openai(audio_bytes, filename=filename, mime_type=mime_type)
        transcript = (transcription.get("transcript") or "").strip()
    analysis = analyze_call_transcript_with_openai(
        transcript,
        property_id=property_id,
        person_id=person_id,
        context=analysis_context,
    )
    summary_text = compose_call_summary(analysis_context, analysis, transcript)

    db.execute(
        """
        UPDATE call_recording_jobs
        SET fetch_status = 'Fetched',
            analysis_status = 'Completed',
            transcript_text = ?,
            summary_text = ?,
            analysis_json = ?,
            payload_json = ?,
            updated_at = CURRENT_TIMESTAMP
        WHERE id = ?
        """,
        (
            transcript,
            summary_text,
            json.dumps(analysis),
            json.dumps(
                {
                    **payload_obj,
                    "recording_url": recording_url,
                    "transcription_raw": transcription.get("raw") or {},
                    "analysis": analysis,
                    "analysis_context": analysis_context,
                }
            ),
            job_id,
        ),
    )
    if person_id:
        note_body = (
            f"Call analyzed for SID {call_sid}.\n"
            f"Direction: {analysis.get('call_direction') or call_direction}\n"
            f"Outcome: {analysis.get('call_outcome_type') or (call_outcome or '-')}\n"
            f"Summary: {summary_text or '-'}\n"
            f"Intent: {analysis.get('caller_intent') or '-'}\n"
            f"Recommended Next Step: {analysis.get('next_best_step') or '-'}\n"
            f"Coaching: {', '.join(analysis.get('caller_improvement') or []) or '-'}"
        )
        add_person_note(db, person_id, "Call Recording Analysis", note_body, analysis)

    intent_l = str(analysis.get("caller_intent") or "").strip().lower()
    summary_l = str(summary_text or "").strip().lower()
    outcome_l = str(analysis.get("call_outcome_type") or "").strip().lower()
    call_is_spam = any(
        token in intent_l or token in summary_l
        for token in ["solicitor", "solicitation", "wrong number", "spam call"]
    ) or outcome_l in {"solicitation", "wrong number"}

    upsert_agent_signal(
        db,
        source_type="call",
        source_key=f"call:{call_sid}",
        property_id=property_id,
        person_id=person_id,
        channel="CALL",
        intent=(analysis.get("caller_intent") or "").strip(),
        sentiment=(analysis.get("sentiment") or "Unknown").strip(),
        confidence=float(analysis.get("confidence") or 0.0),
        recommended_next_step=(analysis.get("next_best_step") or "").strip(),
        summary_text=summary_text,
        is_spam=call_is_spam,
        do_not_contact=(analysis.get("next_best_step") in {"Mark Not Interested", "Mark Opt Out"}),
        payload={"call_sid": call_sid, "analysis": analysis, "recording_url": recording_url},
    )
    route_new_agent_signals_once(db, limit=25)
    if property_id:
        trigger_agent_pipeline_refresh(db, property_id=int(property_id), reason="call_analysis")
    return {"job_id": job_id, "status": "completed", "call_sid": call_sid, "next_step": analysis.get("next_best_step")}


def run_call_recording_analysis_once(limit=2, statuses=None, created_after=None, force_reanalyze=False):
    ensure_db()
    db = open_sqlite_connection()
    try:
        with agent_pipeline_guard("call_recording_analysis", timeout_seconds=20):
            where = []
            params = []
            use_statuses = statuses or ["Pending", "Retry"]
            if use_statuses:
                placeholders = ",".join(["?"] * len(use_statuses))
                where.append(f"analysis_status IN ({placeholders})")
                params.extend(use_statuses)
            if created_after:
                where.append("created_at >= ?")
                params.append(created_after)
            where_sql = ("WHERE " + " AND ".join(where)) if where else ""
            rows = db.execute(
                f"""
                SELECT *
                FROM call_recording_jobs
                {where_sql}
                ORDER BY id ASC
                LIMIT ?
                """,
                tuple(params + [max(1, int(limit))]),
            ).fetchall()
            processed = 0
            completed = 0
            failed = 0
            details = []
            for row in rows:
                processed += 1
                try:
                    out = process_single_call_recording_job(db, row, force_reanalyze=force_reanalyze)
                    details.append(out)
                    if out.get("status") == "completed":
                        completed += 1
                except Exception as exc:
                    failed += 1
                    payload = parse_json_object(row["payload_json"] or "{}")
                    retry_count = int(payload.get("retry_count", 0) or 0) + 1
                    payload["retry_count"] = retry_count
                    payload["error"] = str(exc)
                    db.execute(
                        """
                        UPDATE call_recording_jobs
                        SET analysis_status = ?,
                            fetch_status = CASE WHEN fetch_status = 'Queued' THEN 'Error' ELSE fetch_status END,
                            payload_json = ?,
                            updated_at = CURRENT_TIMESTAMP
                        WHERE id = ?
                        """,
                        (
                            "Retry" if retry_count < CALL_ANALYSIS_MAX_RETRIES else "Failed",
                            json.dumps(payload),
                            row["id"],
                        ),
                    )
                    if row["property_id"]:
                        _create_agent_diagnosis_review_action(
                            db,
                            property_id=int(row["property_id"]),
                            person_id=row["person_id"],
                            call_sid=row["call_sid"],
                            diagnosis="Call analysis failed",
                            attempted_fix=f"Automatic retry {retry_count}/{CALL_ANALYSIS_MAX_RETRIES}",
                            proposed_resolution=(
                                "Retry analysis automatically."
                                if retry_count < CALL_ANALYSIS_MAX_RETRIES
                                else "Retries exhausted; review payload/provider recording quality."
                            ),
                            priority="Medium" if retry_count < CALL_ANALYSIS_MAX_RETRIES else "High",
                            extra={"error": str(exc)},
                        )
                    details.append({"job_id": row["id"], "status": "error", "error": str(exc)})
                    log_app_error(
                        db,
                        source="call_recording_worker",
                        error_message=str(exc),
                        details=traceback.format_exc(),
                        route="run_call_recording_analysis_once",
                        status_code=500,
                    )
            db.commit()
            return {"ok": True, "processed": processed, "completed": completed, "failed": failed, "details": details}
    except TimeoutError:
        return {"ok": True, "skipped": "agent_pipeline_busy"}
    except Exception as exc:
        db.rollback()
        log_app_error(
            db,
            source="call_recording_worker",
            error_message=str(exc),
            details=traceback.format_exc(),
            route="run_call_recording_analysis_once",
            status_code=500,
        )
        db.commit()
        return {"ok": False, "error": str(exc)}
    finally:
        db.close()


def start_call_recording_worker():
    global CALL_RECORDING_WORKER_STARTED
    if CALL_RECORDING_WORKER_STARTED or not CALL_RECORDING_WORKER_ENABLED:
        return
    CALL_RECORDING_WORKER_STARTED = True

    def worker():
        while True:
            try:
                run_call_recording_analysis_once(limit=2)
            except Exception:
                pass
            time.sleep(CALL_RECORDING_POLL_SECONDS)

    thread = threading.Thread(target=worker, daemon=True)
    thread.start()


def rerun_call_analysis_for_today(db, limit=600):
    cutoff = format_db_time(est_yesterday_start_utc())
    rows = db.execute(
        """
        SELECT *
        FROM call_recording_jobs
        WHERE created_at >= ?
        ORDER BY id ASC
        LIMIT ?
        """,
        (cutoff, max(1, int(limit))),
    ).fetchall()
    processed = 0
    completed = 0
    failed = 0
    details = []
    for row in rows:
        processed += 1
        try:
            out = process_single_call_recording_job(db, row, force_reanalyze=True)
            details.append(out)
            if out.get("status") == "completed":
                completed += 1
        except Exception as exc:
            failed += 1
            payload = parse_json_object(row["payload_json"] or "{}")
            payload["force_rerun_error"] = str(exc)
            db.execute(
                """
                UPDATE call_recording_jobs
                SET analysis_status = 'Retry',
                    payload_json = ?,
                    updated_at = CURRENT_TIMESTAMP
                WHERE id = ?
                """,
                (json.dumps(payload), row["id"]),
            )
            details.append({"job_id": row["id"], "status": "error", "error": str(exc)})
            log_app_error(
                db,
                source="call_recording_worker",
                error_message=str(exc),
                details=traceback.format_exc(),
                route="rerun_call_analysis_for_today",
                status_code=500,
            )
    return {"ok": True, "cutoff": cutoff, "processed": processed, "completed": completed, "failed": failed, "details": details[:150]}


def upsert_agent_signal(
    db,
    source_type,
    source_key,
    property_id=None,
    person_id=None,
    channel="",
    intent="",
    sentiment="",
    confidence=0.0,
    recommended_next_step="",
    summary_text="",
    is_spam=False,
    do_not_contact=False,
    payload=None,
):
    row = db.execute("SELECT id FROM agent_signals WHERE source_key = ?", ((source_key or "").strip(),)).fetchone()
    payload_json = json.dumps(payload or {})
    insert_args = (
        (source_type or "").strip() or "unknown",
        (source_key or "").strip(),
        property_id,
        person_id,
        (channel or "").strip(),
        (intent or "").strip(),
        (sentiment or "").strip(),
        float(confidence or 0.0),
        (recommended_next_step or "").strip(),
        (summary_text or "").strip(),
        1 if is_spam else 0,
        1 if do_not_contact else 0,
        payload_json,
    )
    update_args = (
        (source_type or "").strip() or "unknown",
        property_id,
        person_id,
        (channel or "").strip(),
        (intent or "").strip(),
        (sentiment or "").strip(),
        float(confidence or 0.0),
        (recommended_next_step or "").strip(),
        (summary_text or "").strip(),
        1 if is_spam else 0,
        1 if do_not_contact else 0,
        payload_json,
    )
    if row:
        db.execute(
            """
            UPDATE agent_signals
            SET source_type = ?, property_id = ?, person_id = ?, channel = ?, intent = ?, sentiment = ?,
                confidence = ?, recommended_next_step = ?, summary_text = ?, is_spam = ?, do_not_contact = ?,
                payload_json = ?, routing_status = 'new', updated_at = CURRENT_TIMESTAMP
            WHERE source_key = ?
            """,
            update_args + ((source_key or "").strip(),),
        )
        return row["id"]
    cur = db.execute(
        """
        INSERT INTO agent_signals
        (source_type, source_key, property_id, person_id, channel, intent, sentiment, confidence, recommended_next_step, summary_text, is_spam, do_not_contact, payload_json)
        VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
        """,
        insert_args,
    )
    return cur.lastrowid


def _normalize_reisift_status(status_value):
    raw = str(status_value or "").strip().lower().replace("_", " ")
    raw = re.sub(r"\s+", " ", raw).strip()
    aliases = {
        "new_lead": "new lead",
        "no contact new lead": "no contact new lead",
        "nurture new lead": "nurture new lead",
        "hot lead": "hot lead",
        "warm lead": "warm lead",
        "cold lead": "cold lead",
        "ghosting lead": "ghosting lead",
        "dead leads": "dead lead",
        "dead lead": "dead lead",
        "not interested": "not interested",
        "not_interested": "not interested",
        "opt out": "opt-out",
        "opt-out": "opt-out",
        "listed": "listed",
        "refer lead": "refer lead",
        "refer_lead": "refer lead",
    }
    return aliases.get(raw, raw)


def _reisift_status_slug(status_value, default="new_lead"):
    raw = str(status_value or "").strip().lower().replace("-", " ").replace("_", " ")
    raw = re.sub(r"\s+", " ", raw).strip()
    if not raw:
        return default
    aliases = {
        "new lead": "new_lead",
        "no contact new lead": "no_contact_new_lead",
        "nurture new lead": "nurture_new_lead",
        "hot lead": "hot_lead",
        "warm lead": "warm_lead",
        "cold lead": "cold_lead",
        "ghosting lead": "ghosting_lead",
        "dead lead": "dead_lead",
        "dead leads": "dead_lead",
        "not interested": "not_interested",
        "opt out": "opt_out",
        "opt-out": "opt_out",
        "listed": "listed",
        "refer lead": "refer_lead",
    }
    return aliases.get(raw, raw.replace(" ", "_"))


def _reisift_status_label(status_value, default="New Lead"):
    normalized = _normalize_reisift_status(status_value)
    if not normalized:
        normalized = _normalize_reisift_status(default)
    aliases = {
        "new lead": "New Lead",
        "no contact new lead": "No Contact New Lead",
        "nurture new lead": "Nurture New Lead",
        "hot lead": "Hot Lead",
        "warm lead": "Warm Lead",
        "cold lead": "Cold Lead",
        "ghosting lead": "Ghosting Lead",
        "dead lead": "Dead Lead",
        "not interested": "Not Interested",
        "opt-out": "Opt-Out",
        "listed": "Listed",
        "refer lead": "Refer Lead",
    }
    return aliases.get(normalized, " ".join(part.capitalize() for part in normalized.split()) or default)


def _reisift_create_status_value(status_value, default="new_lead"):
    raw = str(status_value or "").strip()
    normalized_default = _reisift_status_slug(default or "new_lead", default="new_lead")
    if not raw:
        return normalized_default
    return _reisift_status_slug(raw, default=normalized_default)


def _playbook_priority_for_action(property_status, action_type, fallback_priority):
    status_key = _normalize_reisift_status(property_status)
    row = REISIFT_PLAYBOOK_PRIORITY.get(status_key, {})
    return row.get(action_type, fallback_priority)


def _map_signal_to_action(signal_row, property_status=""):
    next_step = (signal_row["recommended_next_step"] or "").strip()
    mapping = {
        "Schedule Appointment": ("ScheduleAppointment", "High"),
        "Follow Up": ("FollowUpTouchDue", "Medium"),
        "Escalate To Relative": ("EscalateToRelativeOutreach", "High"),
        "Deep Dive": ("EscalateToDeepDiveResearch", "High"),
        "Mark Not Interested": ("HumanReviewDisposition", "High"),
        "Mark Opt Out": ("HumanReviewDisposition", "High"),
        "No Action": ("ReviewInboundAndNextBestAction", "Low"),
    }
    action_type, base_priority = mapping.get(next_step, ("ReviewInboundAndNextBestAction", "Medium"))
    priority = _playbook_priority_for_action(property_status, action_type, base_priority)
    return action_type, priority


def route_new_agent_signals_once(db, limit=50):
    rows = db.execute(
        """
        SELECT *
        FROM agent_signals
        WHERE routing_status = 'new'
        ORDER BY id ASC
        LIMIT ?
        """,
        (max(1, int(limit)),),
    ).fetchall()
    routed = 0
    skipped = 0
    system_numbers = _known_system_numbers(db, refresh_seconds=300)

    def _signal_rollup_context(signal_row, payload_obj):
        signal_row = dict(signal_row) if isinstance(signal_row, sqlite3.Row) else (signal_row if isinstance(signal_row, dict) else {})
        payload_obj = payload_obj if isinstance(payload_obj, dict) else {}
        signal_obj = payload_obj.get("signal") if isinstance(payload_obj.get("signal"), dict) else {}
        analysis_obj = payload_obj.get("analysis") if isinstance(payload_obj.get("analysis"), dict) else {}
        source_key = str(signal_row.get("source_key") or "").strip()

        phones_all = []

        def _add_phone(raw):
            n = normalize_phone(raw)
            if n and n not in phones_all:
                phones_all.append(n)

        # Capture all possible phone hints from signal payload variants.
        for scope in [signal_obj, payload_obj, analysis_obj]:
            if not isinstance(scope, dict):
                continue
            for k in ["counterpart", "phone", "counterpart_number", "from", "to", "from_number", "to_number", "caller", "callee"]:
                _add_phone(scope.get(k))
        tail = source_key.rsplit(":", 1)[-1] if ":" in source_key else ""
        _add_phone(tail)

        # Prefer third-party phone; never roll up on owned/system numbers.
        third_party_phone = next((n for n in phones_all if n not in system_numbers), "")
        if not third_party_phone:
            for n in phones_all:
                if n:
                    third_party_phone = n
                    break

        property_id = int(signal_row.get("property_id") or 0)
        person_id = int(signal_row.get("person_id") or 0) or None
        reisift_uuid = ""

        # Direct UUID in payload if available.
        reisift_uuid = normalize_uuid(
            extract_first_string_by_keys(signal_obj, ["reisift_property_uuid", "property_uuid", "uuid"])
            or extract_first_string_by_keys(payload_obj, ["reisift_property_uuid", "property_uuid", "uuid"])
        )
        if not reisift_uuid and property_id > 0:
            reisift_uuid = _get_local_property_uuid(db, property_id)

        # Resolve by third-party phone when UUID/property missing.
        if not reisift_uuid and third_party_phone:
            resolved = resolve_shared_contact_context_by_numbers(
                db,
                [third_party_phone],
                fallback_property_id=property_id,
                force_reisift=False,
                search_reisift=True,
            ) or {}
            if int(resolved.get("property_id") or 0):
                property_id = int(resolved.get("property_id") or 0)
            if int(resolved.get("person_id") or 0):
                person_id = int(resolved.get("person_id") or 0)
            resolved_uuid = normalize_uuid(resolved.get("reisift_property_uuid") or "")
            if resolved_uuid:
                reisift_uuid = resolved_uuid
            if (not reisift_uuid) and property_id > 0:
                reisift_uuid = _get_local_property_uuid(db, property_id)

        lead_key = ""
        if reisift_uuid:
            lead_key = f"uuid:{reisift_uuid}"
        elif third_party_phone:
            lead_key = f"phone:{third_party_phone}"
        elif property_id > 0:
            lead_key = f"property:{property_id}"
        else:
            lead_key = f"source:{source_key or 'unresolved'}"

        return {
            "lead_key": lead_key,
            "property_id": property_id,
            "person_id": person_id,
            "reisift_property_uuid": reisift_uuid,
            "third_party_phone": third_party_phone,
            "phones_all": phones_all,
        }

    for row in rows:
        property_id = int(row["property_id"] or 0)
        person_id = int(row["person_id"] or 0) or None
        payload = parse_json_object(row["payload_json"] or "{}")
        roll = _signal_rollup_context(row, payload)
        rollup_key = str(roll.get("lead_key") or "").strip() or f"source:{row['source_key']}"
        property_id = int(roll.get("property_id") or 0)
        person_id = int(roll.get("person_id") or 0) or None
        reisift_uuid = normalize_uuid(roll.get("reisift_property_uuid") or "")
        third_party_phone = normalize_phone(roll.get("third_party_phone") or "")
        snapshot = {
            "lead_key": rollup_key,
            "phones": ([third_party_phone] if third_party_phone else []),
            "reisift_property_uuid": reisift_uuid,
        }

        if property_id > 0 or person_id:
            db.execute(
                """
                UPDATE agent_signals
                SET property_id = COALESCE(?, property_id),
                    person_id = COALESCE(?, person_id),
                    payload_json = ?,
                    updated_at = CURRENT_TIMESTAMP
                WHERE id = ?
                """,
                (
                    (property_id or None),
                    person_id,
                    json.dumps({**payload, "lead_key": rollup_key, "snapshot": snapshot}),
                    int(row["id"]),
                ),
            )

        prop_status = ""
        prop = db.execute("SELECT status FROM properties WHERE id = ?", (property_id,)).fetchone()
        if prop:
            prop_status = str((prop["status"] if prop else "") or "").strip().lower()
        is_conflict = bool(row["do_not_contact"]) and prop_status in ACTIVE_LEAD_STATUSES

        action_type = ""
        priority = ""
        reason_text = ""
        if is_conflict:
            action_type = "HumanReviewDisposition"
            priority = "High"
            reason_text = "Conflict detected: do-not-contact signal conflicts with active lead status. Human review required."
        elif row["is_spam"]:
            action_type = "ReviewInboundAndNextBestAction"
            priority = "Low"
            reason_text = "Signal classified as spam/solicitation. Verify and dismiss if not business related."
        else:
            action_type, priority = _map_signal_to_action(row, prop_status)
            reason_text = (
                f"Agent signal ({row['source_type']}) recommends: {(row['recommended_next_step'] or 'review')}. "
                f"Priority derived from ReiSift playbook status '{prop_status or '-'}'."
            )

        created = _upsert_lead_action(
            db,
            int(property_id),
            person_id,
            action_type,
            priority,
            reason_text,
            {
                "signal_id": row["id"],
                "signal": payload,
                "source_key": row["source_key"],
                "lead_key": rollup_key,
                "snapshot": snapshot,
                "unmapped": 1 if int(property_id or 0) == 0 else 0,
            },
            dedupe_key_override=f"leadwatch:{rollup_key}",
            contact_classification=str(
                extract_first_string_by_keys(payload, ["classification"])
                or extract_first_string_by_keys(payload.get("signal") if isinstance(payload.get("signal"), dict) else {}, ["classification"])
                or ("unknown" if not row["is_spam"] else "spam")
            ).strip().lower(),
        )

        _close_other_pending_leadwatch_actions(
            db,
            rollup_key,
            f"leadwatch:{rollup_key}",
            phone_tokens=([third_party_phone] if third_party_phone else []),
        )

        if property_id > 0:
            _close_unmapped_actions_for_source_key(db, row["source_key"], int(property_id))

        db.execute(
            "UPDATE agent_signals SET routing_status = 'routed', updated_at = CURRENT_TIMESTAMP WHERE id = ?",
            (row["id"],),
        )
        if created:
            routed += 1
        else:
            skipped += 1
    dedupe = dedupe_pending_lead_actions_by_rollup(db)
    return {"processed": len(rows), "routed": routed, "skipped": skipped, "dedupe": dedupe}


def _system_phone_numbers(db):
    vals = set()
    configured_owned = []
    for chunk in [SMRTPHONE_OWNED_NUMBERS, get_setting(db, "smrtphone_owned_numbers", "")]:
        txt = str(chunk or "").replace("\n", ",").replace(";", ",")
        configured_owned.extend([p.strip() for p in txt.split(",") if p.strip()])
    for raw in (
        [SMRTPHONE_FROM_NUMBER, get_setting(db, "deep_dive_smrtphone_from", ""), get_setting(db, "referral_smrtphone_from", "")]
        + SMRTPHONE_OWNED_DEFAULT_NUMBERS
        + configured_owned
    ):
        n = normalize_phone(raw)
        if n:
            vals.add(n)
    return vals


def _infer_system_numbers_from_smrt_events(db, cutoff=None):
    vals = set()
    rows = db.execute(
        """
        SELECT event_type, from_number, to_number, payload_json, received_at
        FROM smrtphone_webhook_events
        WHERE event_type IN ('inbound', 'outbound')
          AND (? IS NULL OR received_at >= ?)
        ORDER BY id DESC
        LIMIT 1200
        """,
        (cutoff, cutoff),
    ).fetchall()
    for r in rows:
        payload = parse_json_object(r["payload_json"])
        event_name = extract_first_string_by_keys(payload, ["event", "eventType"]).lower()
        from_n = normalize_phone(r["from_number"])
        to_n = normalize_phone(r["to_number"])
        if event_name == "smsoutgoing":
            if from_n:
                vals.add(from_n)
        elif event_name == "smsincoming":
            if to_n:
                vals.add(to_n)
    return vals


def _known_system_numbers(db, refresh_seconds=300):
    base = set(_system_phone_numbers(db))
    now_utc = datetime.utcnow()
    try:
        expires_at = SYSTEM_PHONE_CACHE.get("expires_at")
        cached_numbers = set(SYSTEM_PHONE_CACHE.get("numbers") or set())
        if isinstance(expires_at, datetime) and expires_at > now_utc and cached_numbers:
            return base | cached_numbers
    except Exception:
        pass
    inferred = set()
    try:
        cutoff = format_db_time(now_utc - timedelta(days=30))
        inferred = _infer_system_numbers_from_smrt_events(db, cutoff=cutoff)
    except Exception:
        inferred = set()
    SYSTEM_PHONE_CACHE["numbers"] = set(inferred)
    SYSTEM_PHONE_CACHE["expires_at"] = now_utc + timedelta(seconds=max(60, int(refresh_seconds or 300)))
    return base | inferred


def _thread_counterpart(system_numbers, direction, from_number, to_number):
    from_norm = normalize_phone(from_number)
    to_norm = normalize_phone(to_number)
    if direction == "outbound":
        return to_norm or from_norm
    if direction == "inbound":
        return from_norm or to_norm
    if from_norm and from_norm not in system_numbers:
        return from_norm
    if to_norm and to_norm not in system_numbers:
        return to_norm
    return from_norm or to_norm


def _counterparty_candidates(db, from_number, to_number):
    from_norm = normalize_phone(from_number)
    to_norm = normalize_phone(to_number)
    system_numbers = _known_system_numbers(db, refresh_seconds=300)
    candidates = []
    for n in [from_norm, to_norm]:
        if n and n not in system_numbers and n not in candidates:
            candidates.append(n)
    for n in [from_norm, to_norm]:
        if n and n not in candidates:
            candidates.append(n)
    return candidates


def _extract_phone_values_by_keys(payload, keys):
    keyset = {str(k).strip().lower() for k in (keys or []) if str(k).strip()}
    if not keyset:
        return []
    queue = [payload]
    values = []
    seen = set()
    while queue:
        current = queue.pop(0)
        if isinstance(current, dict):
            for k, v in current.items():
                if str(k).strip().lower() in keyset:
                    if isinstance(v, list):
                        for item in v:
                            norm = normalize_phone(str(item or ""))
                            if len(norm) == 10 and norm not in seen:
                                seen.add(norm)
                                values.append(norm)
                    else:
                        norm = normalize_phone(str(v or ""))
                        if len(norm) == 10 and norm not in seen:
                            seen.add(norm)
                            values.append(norm)
                if isinstance(v, (dict, list)):
                    queue.append(v)
        elif isinstance(current, list):
            for item in current:
                if isinstance(item, (dict, list)):
                    queue.append(item)
    return values


def _smrtphone_external_number_candidates(db, payload, webhook, from_number="", to_number=""):
    system_numbers = _known_system_numbers(db, refresh_seconds=300)
    preferred_keys = [
        "phone_number_caller",
        "phoneNumberCaller",
        "phone_number_agent",
        "phoneNumberAgent",
        "leadPhone",
        "lead_phone",
        "contactPhone",
        "contact_phone",
        "customerPhone",
        "customer_phone",
        "callerPhone",
        "caller_phone",
        "phone",
        "phoneNumber",
        "phone_number",
        "mobile",
        "mobilePhone",
        "mobile_phone",
        "counterpart",
        "counterpart_number",
        "customerNumber",
        "customer_number",
        "remoteNumber",
        "remote_number",
        "participantPhone",
        "participant_phone",
        "ani",
        "dnis",
        "from",
        "from_number",
        "fromNumber",
        "to",
        "to_number",
        "toNumber",
        "caller",
        "callee",
        "destination",
    ]
    candidates = []
    seen = set()
    for source in [payload, webhook]:
        for number in _extract_phone_values_by_keys(source, preferred_keys):
            if number and number not in seen:
                seen.add(number)
                candidates.append(number)
    for number in _counterparty_candidates(db, from_number, to_number):
        if number and number not in seen:
            seen.add(number)
            candidates.append(number)
    external = [number for number in candidates if number not in system_numbers]
    return external or candidates


def resolve_shared_contact_context_by_numbers(
    db,
    numbers,
    fallback_property_id=None,
    force_reisift=False,
    search_reisift=True,
):
    """
    Shared resolver for call and SMS pipelines.
    Prefers non-system numbers, reuses cached context, and only falls back to ReiSift when allowed.
    """
    system_numbers = _known_system_numbers(db, refresh_seconds=300)
    norms = []
    for raw in numbers or []:
        n = normalize_phone(raw)
        if n and n not in norms:
            norms.append(n)
    result = {
        "phone_norm": "",
        "property_id": int(fallback_property_id or 0) or None,
        "person_id": None,
        "reisift_property_uuid": "",
        "reisift_full_address": "",
        "reisift_owner_name": "",
        "reisift_property_status": "",
        "source": "",
    }
    fallback_uuid = _get_local_property_uuid(db, result["property_id"])
    if fallback_uuid:
        result["reisift_property_uuid"] = fallback_uuid
        result["source"] = "fallback_property"
        return result

    def _merge_context(ctx, source_label):
        if not ctx:
            return False
        merged = False
        if not result["phone_norm"]:
            result["phone_norm"] = normalize_phone(ctx.get("phone_norm") or "") or ""
        ctx_pid = int(ctx.get("property_id") or 0) or None
        ctx_person = int(ctx.get("person_id") or 0) or None
        ctx_uuid = normalize_uuid(ctx.get("reisift_property_uuid") or "")
        if (not result["property_id"]) and ctx_pid:
            result["property_id"] = ctx_pid
            merged = True
        if (not result["person_id"]) and ctx_person:
            result["person_id"] = ctx_person
            merged = True
        if (not result["reisift_property_uuid"]) and ctx_uuid:
            result["reisift_property_uuid"] = ctx_uuid
            merged = True
        if (not result["reisift_full_address"]) and str(ctx.get("reisift_full_address") or "").strip():
            result["reisift_full_address"] = str(ctx.get("reisift_full_address") or "").strip()
            merged = True
        if (not result["reisift_owner_name"]) and str(ctx.get("reisift_owner_name") or "").strip():
            result["reisift_owner_name"] = str(ctx.get("reisift_owner_name") or "").strip()
            merged = True
        if (not result["reisift_property_status"]) and str(ctx.get("reisift_property_status") or "").strip():
            result["reisift_property_status"] = str(ctx.get("reisift_property_status") or "").strip()
            merged = True
        if merged and (not result["source"]):
            result["source"] = source_label
        return merged

    ordered = [n for n in norms if n not in system_numbers] + [n for n in norms if n in system_numbers]
    for n in ordered:
        cached = get_cached_contact_context(db, n)
        if cached:
            cdict = dict(cached)
            cdict["phone_norm"] = n
            _merge_context(cdict, "cache")
            if result["reisift_property_uuid"] or result["property_id"]:
                return result
        if not search_reisift:
            continue
        resolved = resolve_property_context_by_phone(
            db,
            n,
            search_reisift=True,
            force_reisift=bool(force_reisift),
        ) or {}
        if resolved:
            resolved["phone_norm"] = normalize_phone(resolved.get("phone_norm") or n) or n
            _merge_context(resolved, str(resolved.get("source") or "resolver"))
            if result["reisift_property_uuid"] or result["property_id"]:
                return result
    if result["property_id"] and not result["reisift_property_uuid"]:
        result["reisift_property_uuid"] = _get_local_property_uuid(db, result["property_id"])
    return result


def resolve_shared_event_context(
    db,
    from_number,
    to_number,
    fallback_property_id=None,
    force_reisift=False,
    search_reisift=True,
):
    return resolve_shared_contact_context_by_numbers(
        db,
        _counterparty_candidates(db, from_number, to_number),
        fallback_property_id=fallback_property_id,
        force_reisift=force_reisift,
        search_reisift=search_reisift,
    )


def _apply_sms_analysis_guardrails(messages, analysis):
    analysis = dict(analysis or {})
    msgs = list(messages or [])
    if not msgs:
        return analysis
    latest = msgs[-1]
    latest_dir = (latest.get("direction") or "").strip().lower()
    latest_body = (latest.get("body") or "").strip().lower()
    inbound_count = sum(1 for m in msgs if (m.get("direction") or "").strip().lower() == "inbound")

    intro_markers = [
        "we received your",
        "let us know when",
        "when you are available",
        "when you're available",
        "best time to call",
    ]
    if latest_dir == "outbound" and inbound_count <= 1 and any(x in latest_body for x in intro_markers):
        analysis["intent"] = "Initial outreach and availability check"
        analysis["sentiment"] = "Neutral"
        analysis["conversation_type"] = "Business"
        analysis["recommended_next_step"] = "Follow Up"
        analysis["summary"] = (
            "Outbound introductory outreach asking for availability; no clear seller disposition yet."
        )
        facts = list(analysis.get("key_facts") or [])
        facts.append("Latest outbound SMS is an introductory availability check.")
        analysis["key_facts"] = list(dict.fromkeys(facts))[:8]
        analysis["confidence"] = max(float(analysis.get("confidence") or 0.0), 0.85)
    return analysis


def analyze_sms_thread_with_openai(messages, property_id=None, person_id=None, counterpart=""):
    api_key = os.getenv("OPENAI_API_KEY", "").strip()
    if not api_key:
        raise ValueError("OPENAI_API_KEY is not set")
    if not messages:
        raise ValueError("messages required")
    model = os.getenv("OPENAI_MODEL", "gpt-4.1-mini").strip() or "gpt-4.1-mini"
    text_lines = []
    for m in messages:
        ts = m.get("sent_at") or m.get("created_at") or ""
        direction = (m.get("direction") or "").strip().title()
        body = (m.get("body") or "").strip()
        if not body:
            continue
        text_lines.append(f"[{ts}] {direction}: {body}")
    transcript = "\n".join(text_lines)[:16000]
    schema = {
        "name": "sms_thread_analysis",
        "schema": {
            "type": "object",
            "additionalProperties": False,
            "properties": {
                "summary": {"type": "string"},
                "intent": {"type": "string"},
                "sentiment": {"type": "string", "enum": ["Positive", "Neutral", "Negative", "Mixed", "Unknown"]},
                "conversation_type": {"type": "string", "enum": ["Business", "Spam", "Wrong Number", "Unknown"]},
                "recommended_next_step": {
                    "type": "string",
                    "enum": [
                        "Schedule Appointment",
                        "Follow Up",
                        "Escalate To Relative",
                        "Deep Dive",
                        "Mark Not Interested",
                        "Mark Opt Out",
                        "No Action",
                    ],
                },
                "confidence": {"type": "number"},
                "key_facts": {"type": "array", "items": {"type": "string"}},
            },
            "required": ["summary", "intent", "sentiment", "conversation_type", "recommended_next_step", "confidence", "key_facts"],
        },
        "strict": True,
    }
    prompt = (
        "Analyze this SMS thread for lead management.\n"
        f"Property ID: {property_id or '-'} | Person ID: {person_id or '-'} | Counterpart: {counterpart or '-'}\n"
        "Return only valid JSON.\n"
        "If the latest message is an outbound intro/availability check from our team (for example: we received your SMS, let us know when available), "
        "treat intent as initial outreach and sentiment as neutral unless a clear inbound response indicates otherwise."
        f"\n\nThread:\n{transcript}"
    )
    response = requests.post(
        "https://api.openai.com/v1/responses",
        headers={"Authorization": f"Bearer {api_key}", "Content-Type": "application/json"},
        json={
            "model": model,
            "input": [
                {"role": "system", "content": [{"type": "input_text", "text": "You are an SMS conversation analyst for a real estate CRM."}]},
                {"role": "user", "content": [{"type": "input_text", "text": prompt}]},
            ],
            "text": {"format": {"type": "json_schema", "name": schema["name"], "schema": schema["schema"], "strict": True}},
        },
        timeout=60,
    )
    response.raise_for_status()
    data = response.json()
    output_text = (data.get("output_text") or "").strip()
    if output_text:
        analysis = json.loads(output_text)
        return _apply_sms_analysis_guardrails(messages, analysis)
    for item in data.get("output", []):
        for part in item.get("content", []):
            if part.get("type") in {"output_text", "text"} and part.get("text"):
                analysis = json.loads(part["text"])
                return _apply_sms_analysis_guardrails(messages, analysis)
    raise ValueError("No JSON output returned by sms analyzer")


def run_sms_analysis_once(lookback_days=14, limit_threads=30, start_utc=None):
    ensure_db()
    db = open_sqlite_connection()
    lock_acquired = False
    try:
        lock_acquired = AGENT_PIPELINE_LOCK.acquire(timeout=20)
        if not lock_acquired:
            return {"ok": True, "skipped": "agent_pipeline_busy"}
        if start_utc is not None:
            cutoff = format_db_time(start_utc)
        else:
            cutoff = format_db_time(datetime.utcnow() - timedelta(days=max(1, int(lookback_days))))
        rows = db.execute(
            """
            SELECT id, property_id, person_id, direction, from_number, to_number, body, status, sent_at, created_at
            FROM communications
            WHERE upper(channel) = 'SMS'
              AND COALESCE(sent_at, created_at) >= ?
            ORDER BY COALESCE(sent_at, created_at) ASC, id ASC
            """,
            (cutoff,),
        ).fetchall()
        system_numbers = _system_phone_numbers(db)
        phone_resolution_cache = {}
        threads = {}
        for r in rows:
            direction = str(r["direction"] or "").strip().lower()
            counterpart = _thread_counterpart(system_numbers, direction, r["from_number"], r["to_number"])
            if not counterpart:
                continue
            resolved_property_id = int(r["property_id"] or 0)
            resolved_person_id = int(r["person_id"] or 0)
            phone_key = normalize_phone(counterpart)
            if phone_key and (not resolved_property_id):
                cached_resolution = phone_resolution_cache.get(phone_key)
                if cached_resolution is None:
                    cached_resolution = resolve_shared_contact_context_by_numbers(
                        db,
                        [phone_key],
                        fallback_property_id=resolved_property_id,
                        force_reisift=False,
                        search_reisift=True,
                    )
                    phone_resolution_cache[phone_key] = cached_resolution
                if cached_resolution:
                    resolved_property_id = int(cached_resolution.get("property_id") or 0)
                    resolved_person_id = int(cached_resolution.get("person_id") or 0)
            key = f"{resolved_property_id}:{resolved_person_id}:{counterpart}"
            t = threads.setdefault(
                key,
                {
                    "thread_key": key,
                    "property_id": resolved_property_id or None,
                    "person_id": resolved_person_id or None,
                    "counterpart": counterpart,
                    "messages": [],
                },
            )
            t["messages"].append(dict(r))
        thread_list = sorted(threads.values(), key=lambda x: (x["messages"][-1].get("sent_at") or x["messages"][-1].get("created_at") or ""), reverse=True)
        processed = 0
        analyzed = 0
        failed = 0
        touched_property_ids = set()
        details = []
        for t in thread_list[: max(1, int(limit_threads))]:
            processed += 1
            msgs = t["messages"]
            hash_input = "\n".join([f"{m.get('direction','')}|{m.get('from_number','')}|{m.get('to_number','')}|{m.get('body','')}" for m in msgs])
            transcript_hash = hashlib.sha1(hash_input.encode("utf-8", errors="ignore")).hexdigest()
            state = db.execute("SELECT transcript_hash FROM sms_thread_state WHERE thread_key = ?", (t["thread_key"],)).fetchone()
            last_at = msgs[-1].get("sent_at") or msgs[-1].get("created_at") or format_db_time(datetime.utcnow())
            if state and (state["transcript_hash"] or "") == transcript_hash:
                db.execute(
                    "UPDATE sms_thread_state SET last_message_at = ?, message_count = ?, updated_at = CURRENT_TIMESTAMP WHERE thread_key = ?",
                    (last_at, len(msgs), t["thread_key"]),
                )
                details.append({"thread_key": t["thread_key"], "status": "unchanged"})
                continue
            try:
                analysis = analyze_sms_thread_with_openai(
                    msgs,
                    property_id=t["property_id"],
                    person_id=t["person_id"],
                    counterpart=t["counterpart"],
                )
                sentiment = (analysis.get("sentiment") or "Unknown").strip()
                intent = (analysis.get("intent") or "").strip()
                recommended = (analysis.get("recommended_next_step") or "").strip()
                conv_type = (analysis.get("conversation_type") or "Unknown").strip()
                is_spam = conv_type.lower() in {"spam", "wrong number"}
                dnc = recommended in {"Mark Opt Out", "Mark Not Interested"}
                upsert_agent_signal(
                    db,
                    source_type="sms",
                    source_key=f"sms_thread:{t['thread_key']}:{transcript_hash}",
                    property_id=t["property_id"],
                    person_id=t["person_id"],
                    channel="SMS",
                    intent=intent,
                    sentiment=sentiment,
                    confidence=float(analysis.get("confidence") or 0.0),
                    recommended_next_step=recommended,
                    summary_text=(analysis.get("summary") or "").strip(),
                    is_spam=is_spam,
                    do_not_contact=dnc,
                    payload={"thread_key": t["thread_key"], "counterpart": t["counterpart"], "analysis": analysis, "messages": msgs},
                )
                analyzed += 1
                if int(t.get("property_id") or 0):
                    touched_property_ids.add(int(t["property_id"]))
                details.append({"thread_key": t["thread_key"], "status": "analyzed", "recommended_next_step": recommended})
            except Exception as exc:
                failed += 1
                details.append({"thread_key": t["thread_key"], "status": "error", "error": str(exc)})
                log_app_error(
                    db,
                    source="sms_analysis_worker",
                    error_message=str(exc),
                    details=traceback.format_exc(),
                    route="run_sms_analysis_once",
                    status_code=500,
                )
            db.execute(
                """
                INSERT INTO sms_thread_state (thread_key, property_id, person_id, counterpart_number, last_message_at, message_count, transcript_hash)
                VALUES (?, ?, ?, ?, ?, ?, ?)
                ON CONFLICT(thread_key) DO UPDATE SET
                    property_id = excluded.property_id,
                    person_id = excluded.person_id,
                    counterpart_number = excluded.counterpart_number,
                    last_message_at = excluded.last_message_at,
                    message_count = excluded.message_count,
                    transcript_hash = excluded.transcript_hash,
                    updated_at = CURRENT_TIMESTAMP
                """,
                (t["thread_key"], t["property_id"], t["person_id"], t["counterpart"], last_at, len(msgs), transcript_hash),
            )
        route_summary = route_new_agent_signals_once(db, limit=200)
        for pid in list(sorted(touched_property_ids))[:50]:
            enqueue_agent_refresh(
                db,
                property_id=int(pid),
                reason="sms_analysis_complete",
                delay_seconds=SMS_DECISION_DELAY_SECONDS,
            )
        db.commit()
        return {"ok": True, "processed": processed, "analyzed": analyzed, "failed": failed, "routed": route_summary.get("routed", 0), "details": details[:50]}
    except Exception as exc:
        db.rollback()
        log_app_error(
            db,
            source="sms_analysis_worker",
            error_message=str(exc),
            details=traceback.format_exc(),
            route="run_sms_analysis_once",
            status_code=500,
        )
        db.commit()
        return {"ok": False, "error": str(exc)}
    finally:
        if lock_acquired:
            AGENT_PIPELINE_LOCK.release()
        db.close()


def start_sms_analysis_worker():
    global SMS_ANALYSIS_WORKER_STARTED
    if SMS_ANALYSIS_WORKER_STARTED or not SMS_ANALYSIS_WORKER_ENABLED:
        return
    SMS_ANALYSIS_WORKER_STARTED = True

    def worker():
        while True:
            try:
                run_sms_analysis_once(lookback_days=14, limit_threads=20)
            except Exception:
                pass
            time.sleep(SMS_ANALYSIS_POLL_SECONDS)

    thread = threading.Thread(target=worker, daemon=True)
    thread.start()


def build_today_lead_watch_snapshot(db, limit=60):
    cutoff_dt = est_yesterday_start_utc()
    cutoff = format_db_time(cutoff_dt)
    leads = {}
    system_numbers = _known_system_numbers(db, refresh_seconds=300)
    phone_to_key = {}
    addr_to_key = {}
    resolution_rows = db.execute(
        """
        SELECT lead_key, classification_override, ignore_agent2,
               suggested_property_id, suggested_property_uuid,
               approved_property_id, approved_property_uuid,
               status, notes, updated_at
        FROM agent3_lead_resolutions
        """
    ).fetchall()
    resolution_map = {str(r["lead_key"]): dict(r) for r in resolution_rows}

    def _best_cached_context_for_phones(phone_values):
        norms = []
        for raw in phone_values or []:
            n = normalize_phone(raw)
            if n:
                norms.append(n)
        norms = list(dict.fromkeys(norms))
        if not norms:
            return None
        placeholders = ",".join(["?"] * len(norms))
        try:
            return db.execute(
                f"""
                SELECT *
                FROM external_contact_context
                WHERE phone_norm IN ({placeholders})
                ORDER BY
                    CASE WHEN COALESCE(reisift_property_uuid, '') <> '' THEN 0 ELSE 1 END,
                    datetime(COALESCE(last_seen_at, first_seen_at)) DESC,
                    id DESC
                LIMIT 1
                """,
                tuple(norms),
            ).fetchone()
        except Exception:
            return None
    referrals = db.execute(
        """
        SELECT rr.property_uuid, rr.status, rr.full_address, rr.owner_names, rr.referral_status, rr.referral_notes,
               rr.last_synced_at, rr.on_market_status, rr.winning_realtor_id,
               wr.first_name AS winning_realtor_first_name, wr.last_name AS winning_realtor_last_name
        FROM reisift_referrals rr
        LEFT JOIN referral_realtors wr ON wr.id = rr.winning_realtor_id
        WHERE rr.is_active = 1
        """
    ).fetchall()
    referral_push_rows = db.execute(
        """
        SELECT p.property_uuid, p.status AS push_status, p.to_number, p.created_at, r.first_name, r.last_name, r.brokerage
        FROM referral_push_activity p
        LEFT JOIN referral_realtors r ON r.id = p.realtor_id
        ORDER BY p.id DESC
        LIMIT 2000
        """
    ).fetchall()
    referral_by_addr = {}
    referral_by_uuid = {}
    for rr in referrals:
        key = normalize_address_key(rr["full_address"])
        if key:
            referral_by_addr[key] = dict(rr)
        uuid_key = normalize_uuid(rr["property_uuid"] or "")
        if uuid_key:
            referral_by_uuid[uuid_key] = dict(rr)
    referral_push_by_uuid = {}
    referral_uuid_by_phone = {}
    for pr in referral_push_rows:
        pu = str(pr["property_uuid"] or "").strip()
        if not pu:
            continue
        referral_push_by_uuid.setdefault(pu, []).append(dict(pr))
        phone_norm = normalize_phone(pr["to_number"])
        if phone_norm and phone_norm not in referral_uuid_by_phone:
            referral_uuid_by_phone[phone_norm] = pu

    def _touch(
        key,
        label,
        occurred_at,
        property_id=None,
        person_id=None,
        direction="",
        event_type="",
        source="",
        classification="",
        address_hint="",
        phone_norm="",
        clever_related=False,
    ):
        if not key:
            return
        key = str(key).strip()
        if phone_norm:
            phone_to_key[phone_norm] = key
        if address_hint:
            addr_key = normalize_address_key(address_hint)
            if addr_key:
                addr_to_key[addr_key] = key
        row = leads.get(key)
        if not row:
            row = {
                "lead_key": key,
                "label": label or key,
                "property_id": property_id,
                "person_id": person_id,
                "classification": (classification or "unknown").strip().lower(),
                "sources": set(),
                "address_hints": set(),
                "sms_inbound": 0,
                "sms_outbound": 0,
                "calls": 0,
                "events": 0,
                "last_activity_at": occurred_at or "",
                "phones": set(),
                "clever_related": bool(clever_related),
                "referral": {},
                "agent_summary": "",
                "recommended": "",
            }
            leads[key] = row
        if property_id and not row.get("property_id"):
            row["property_id"] = property_id
        if person_id and not row.get("person_id"):
            row["person_id"] = person_id
        if classification and row.get("classification") in {"", "unknown"}:
            row["classification"] = classification.strip().lower()
        if source:
            row["sources"].add(source)
        if address_hint:
            row["address_hints"].add(address_hint)
        if phone_norm:
            row["phones"].add(phone_norm)
        if clever_related:
            row["clever_related"] = True
        if (event_type or "").upper() == "CALL":
            row["calls"] += 1
        elif (event_type or "").upper() == "SMS":
            if (direction or "").lower() == "inbound":
                row["sms_inbound"] += 1
            else:
                row["sms_outbound"] += 1
        row["events"] += 1
        if occurred_at and (not row["last_activity_at"] or occurred_at > row["last_activity_at"]):
            row["last_activity_at"] = occurred_at

    # Seed window leads even if no call/SMS has happened yet.
    for rr in referrals:
        synced_at = str(rr["last_synced_at"] or "")
        if synced_at and synced_at < cutoff:
            continue
        uuid = normalize_uuid(rr["property_uuid"] or "")
        if not uuid:
            continue
        addr = str(rr["full_address"] or "").strip()
        addr_key = normalize_address_key(addr) if addr else ""
        existing_key = addr_to_key.get(addr_key, "") if addr_key else ""
        lead_key = existing_key or f"uuid:{uuid}"
        _touch(
            key=lead_key,
            label=(addr or f"ReiSIFT {uuid}"),
            occurred_at=(synced_at or cutoff),
            property_id=None,
            person_id=None,
            source="reisift_referral",
            classification="potential_seller",
            address_hint=addr,
            clever_related=True,
        )

    prop_rows = db.execute(
        """
        SELECT p.id, p.created_at, a.street, a.city, a.state, a.postal_code
        FROM properties p
        JOIN addresses a ON a.id = p.property_address_id
        WHERE p.created_at >= ?
        ORDER BY p.created_at DESC
        LIMIT 500
        """,
        (cutoff,),
    ).fetchall()
    for p in prop_rows:
        label = f"{p['street']}, {p['city']}, {p['state']} {p['postal_code']}".strip(", ")
        addr_key = normalize_address_key(label)
        lead_key = f"property:{int(p['id'])}"
        if addr_key:
            addr_to_key[addr_key] = lead_key
        _touch(
            key=lead_key,
            label=label,
            occurred_at=str(p["created_at"] or ""),
            property_id=int(p["id"]),
            event_type="SYSTEM",
            source="property",
            classification="potential_seller",
            address_hint=label,
        )

    comm_rows = db.execute(
        """
        SELECT c.id, c.property_id, c.person_id, c.channel, c.direction, c.from_number, c.to_number, c.body, c.sent_at, c.external_id
        FROM communications c
        WHERE c.sent_at >= ?
          AND upper(c.channel) = 'SMS'
        ORDER BY c.sent_at DESC
        LIMIT 1500
        """,
        (cutoff,),
    ).fetchall()
    sms_external_ids = set()
    for c in comm_rows:
        external_id = str(c["external_id"] or "").strip()
        if external_id:
            sms_external_ids.add(external_id)
        body = str(c["body"] or "")
        candidates = extract_address_candidates(body)
        from_num = normalize_phone(c["from_number"] if "from_number" in c.keys() else "")
        to_num = normalize_phone(c["to_number"] if "to_number" in c.keys() else "")
        counterpart_num = to_num if str(c["direction"] or "").lower() == "outbound" else from_num
        if counterpart_num in system_numbers:
            counterpart_num = ""
        lead_key = f"property:{int(c['property_id'])}" if c["property_id"] else ""
        if not lead_key and counterpart_num and phone_to_key.get(counterpart_num):
            lead_key = phone_to_key.get(counterpart_num, "")
        if not lead_key and counterpart_num and referral_uuid_by_phone.get(counterpart_num):
            pu = normalize_uuid(referral_uuid_by_phone.get(counterpart_num) or "")
            if pu:
                lead_key = f"uuid:{pu}"
        if not lead_key and candidates:
            addr_norm = normalize_address_key(candidates[0])
            if addr_norm:
                lead_key = addr_to_key.get(addr_norm, f"address:{addr_norm}")
        if not lead_key and counterpart_num:
            lead_key = phone_to_key.get(counterpart_num, f"phone:{counterpart_num}")
        if not lead_key:
            continue
        signal = classify_unknown_contact_text(body)
        clever_related = "clever" in body.lower()
        _touch(
            key=lead_key,
            label=(
                (
                    str((referral_by_uuid.get(lead_key.split("uuid:", 1)[1]) or {}).get("full_address") or "").strip()
                    if lead_key.startswith("uuid:")
                    else ""
                )
                or (candidates[0] if candidates else lead_key)
            ),
            occurred_at=str(c["sent_at"] or ""),
            property_id=c["property_id"],
            person_id=c["person_id"],
            direction=str(c["direction"] or ""),
            event_type="SMS",
            source="communications",
            classification=signal["classification"],
            address_hint=(candidates[0] if candidates else ""),
            phone_norm=counterpart_num,
            clever_related=clever_related,
        )

    event_rows = db.execute(
        """
        SELECT id, event_type, from_number, to_number, sms_id, processing_status, payload_json, received_at
        FROM smrtphone_webhook_events
        WHERE received_at >= ?
        ORDER BY id DESC
        LIMIT 2500
        """,
        (cutoff,),
    ).fetchall()
    for e in event_rows:
        payload = parse_json_object(e["payload_json"])
        msg = extract_first_string_by_keys(payload, ["message", "body", "text"])
        event_name = extract_first_string_by_keys(payload, ["event", "eventType"])
        direction = "inbound"
        if "outgoing" in (event_name or "").lower() or (str(e["event_type"] or "").lower() == "outbound"):
            direction = "outbound"
        sms_id = str(payload.get("smsId") or payload.get("sms_id") or e["sms_id"] or "").strip()
        if str(e["event_type"] or "").lower() == "status":
            continue
        if sms_id and sms_id in sms_external_ids:
            continue
        candidates = extract_address_candidates(msg)
        classification_info = classify_unknown_contact_text(msg)
        phone_norm = normalize_phone(e["from_number"] if direction == "inbound" else e["to_number"])
        if phone_norm in system_numbers:
            phone_norm = ""
        ctx = get_cached_contact_context(db, phone_norm) if phone_norm else None
        lead_key = ""
        label = ""
        prop_id = None
        person_id = None
        if ctx and ctx["property_id"]:
            prop_id = int(ctx["property_id"])
            person_id = ctx["person_id"]
            lead_key = f"property:{prop_id}"
            label = f"Property {prop_id}"
        elif phone_norm and phone_to_key.get(phone_norm):
            lead_key = phone_to_key.get(phone_norm, "")
            label = lead_key
        elif phone_norm and referral_uuid_by_phone.get(phone_norm):
            pu = normalize_uuid(referral_uuid_by_phone.get(phone_norm) or "")
            if pu:
                lead_key = f"uuid:{pu}"
                label = str((referral_by_uuid.get(pu) or {}).get("full_address") or "").strip() or f"ReiSIFT {pu}"
        elif candidates:
            addr_norm = normalize_address_key(candidates[0])
            if addr_norm:
                lead_key = addr_to_key.get(addr_norm, f"address:{addr_norm}")
                label = candidates[0]
        elif phone_norm:
            lead_key = f"phone:{phone_norm}"
            label = f"Phone {phone_norm}"
        if not lead_key:
            continue
        clever_related = "clever" in msg.lower()
        _touch(
            key=lead_key,
            label=label or lead_key,
            occurred_at=str(e["received_at"] or ""),
            property_id=prop_id,
            person_id=person_id,
            direction=direction,
            event_type="SMS",
            source=f"smrtphone:{str(e['event_type'] or '').lower()}",
            classification=(ctx["classification"] if ctx else classification_info["classification"]),
            address_hint=(candidates[0] if candidates else ""),
            phone_norm=phone_norm,
            clever_related=clever_related,
        )

    call_rows = db.execute(
        """
        SELECT id, property_id, person_id, from_number, to_number, summary_text, created_at
        FROM call_recording_jobs
        WHERE created_at >= ?
        ORDER BY id DESC
        LIMIT 1000
        """,
        (cutoff,),
    ).fetchall()
    for c in call_rows:
        summary = str(c["summary_text"] or "")
        candidates = extract_address_candidates(summary)
        lead_key = f"property:{int(c['property_id'])}" if c["property_id"] else ""
        phone_candidates = []
        for raw in [c["from_number"], c["to_number"]]:
            n = normalize_phone(raw)
            if n and n not in system_numbers:
                phone_candidates.append(n)
        if not lead_key:
            for pn in phone_candidates:
                if pn in phone_to_key:
                    lead_key = phone_to_key[pn]
                    break
        if not lead_key:
            for pn in phone_candidates:
                pu = normalize_uuid(referral_uuid_by_phone.get(pn) or "")
                if pu:
                    lead_key = f"uuid:{pu}"
                    break
        if not lead_key:
            for num in [c["from_number"], c["to_number"]]:
                ctx = get_cached_contact_context(db, num)
                if ctx and ctx["property_id"]:
                    lead_key = f"property:{int(ctx['property_id'])}"
                    break
        if not lead_key and candidates:
            addr_norm = normalize_address_key(candidates[0])
            if addr_norm:
                lead_key = addr_to_key.get(addr_norm, f"address:{addr_norm}")
        if not lead_key and phone_candidates:
            lead_key = f"phone:{phone_candidates[0]}"
        if not lead_key:
            continue
        signal = classify_unknown_contact_text(summary)
        _touch(
            key=lead_key,
            label=(candidates[0] if candidates else (f"Phone {phone_candidates[0]}" if phone_candidates else lead_key)),
            occurred_at=str(c["created_at"] or ""),
            property_id=c["property_id"],
            person_id=c["person_id"],
            event_type="CALL",
            source="call_recording_jobs",
            classification=signal["classification"],
            address_hint=(candidates[0] if candidates else ""),
            phone_norm=(phone_candidates[0] if phone_candidates else ""),
            clever_related=("clever" in summary.lower()),
        )

    def _canonical_lead_row_key(row):
        # Canonical identity: uuid -> third-party phone -> lead key.
        row_uuid = ""
        for ph in list(row.get("phones") or []):
            pu = normalize_uuid(referral_uuid_by_phone.get(normalize_phone(ph) or "") or "")
            if pu:
                row_uuid = pu
                break
        if not row_uuid:
            ctx = _best_cached_context_for_phones(list(row.get("phones") or []))
            if ctx:
                row_uuid = normalize_uuid(ctx["reisift_property_uuid"] or "")
        if not row_uuid:
            pid = int(row.get("property_id") or 0)
            if pid > 0:
                row_uuid = _get_local_property_uuid(db, pid)
        if row_uuid:
            return f"uuid:{row_uuid}"
        phones = sorted([normalize_phone(x) for x in list(row.get("phones") or []) if normalize_phone(x)])
        non_system = [p for p in phones if p not in system_numbers]
        if non_system:
            return f"phone:{non_system[0]}"
        if phones:
            return f"phone:{phones[0]}"
        lk = str(row.get("lead_key") or "").strip()
        if lk:
            return lk
        return "lead:unresolved"

    # Merge fragmented keys into canonical roll-up rows.
    merged = {}
    for key, row in list(leads.items()):
        canonical = _canonical_lead_row_key(row)
        tgt = merged.get(canonical)
        if not tgt:
            merged[canonical] = row
            if canonical != key:
                row["lead_key"] = canonical
            continue
        tgt["person_id"] = tgt.get("person_id") or row.get("person_id")
        if row.get("classification") and tgt.get("classification") in {"", "unknown"}:
            tgt["classification"] = row.get("classification")
        tgt["sources"] = set(list(tgt.get("sources") or set()) + list(row.get("sources") or set()))
        tgt["address_hints"] = set(list(tgt.get("address_hints") or set()) + list(row.get("address_hints") or set()))
        tgt["phones"] = set(list(tgt.get("phones") or set()) + list(row.get("phones") or set()))
        tgt["sms_inbound"] = int(tgt.get("sms_inbound") or 0) + int(row.get("sms_inbound") or 0)
        tgt["sms_outbound"] = int(tgt.get("sms_outbound") or 0) + int(row.get("sms_outbound") or 0)
        tgt["calls"] = int(tgt.get("calls") or 0) + int(row.get("calls") or 0)
        tgt["events"] = int(tgt.get("events") or 0) + int(row.get("events") or 0)
        tgt["clever_related"] = bool(tgt.get("clever_related") or row.get("clever_related"))
        if (row.get("last_activity_at") or "") > (tgt.get("last_activity_at") or ""):
            tgt["last_activity_at"] = row.get("last_activity_at")
        if not tgt.get("label") and row.get("label"):
            tgt["label"] = row.get("label")
    leads = merged

    def _elapsed_label(dt_value):
        dt = parse_db_time(dt_value)
        if not dt:
            return "unknown elapsed time"
        delta = datetime.utcnow() - dt
        total_minutes = max(0, int(delta.total_seconds() // 60))
        if total_minutes < 60:
            return f"{total_minutes} minute(s)"
        hours = total_minutes // 60
        if hours < 48:
            return f"{hours} hour(s)"
        days = hours // 24
        return f"{days} day(s)"

    def _agent2_resolution_for_lead(row_dict):
        property_id = int(row_dict.get("property_id") or 0)
        phones = row_dict.get("phones") or []
        lead_key = str(row_dict.get("lead_key") or "").strip()
        referral = row_dict.get("referral") if isinstance(row_dict.get("referral"), dict) else {}
        action_rows = []
        if property_id > 0:
            action_rows = db.execute(
                """
                SELECT id, action_type, priority, status, reason, due_at, updated_at, created_at
                FROM lead_management_actions
                WHERE property_id = ?
                ORDER BY COALESCE(updated_at, created_at) DESC, id DESC
                LIMIT 30
                """,
                (property_id,),
            ).fetchall()
        elif phones:
            found = {}
            for ph in phones[:4]:
                token = normalize_phone(ph)
                if not token:
                    continue
                for r in db.execute(
                    """
                    SELECT id, action_type, priority, status, reason, due_at, updated_at, created_at
                    FROM lead_management_actions
                    WHERE property_id = 0
                      AND payload_json LIKE ?
                    ORDER BY COALESCE(updated_at, created_at) DESC, id DESC
                    LIMIT 20
                    """,
                    (f"%{token}%",),
                ).fetchall():
                    found[int(r["id"])] = dict(r)
            if lead_key:
                for r in db.execute(
                    """
                    SELECT id, action_type, priority, status, reason, due_at, updated_at, created_at
                    FROM lead_management_actions
                    WHERE property_id = 0
                      AND payload_json LIKE ?
                    ORDER BY COALESCE(updated_at, created_at) DESC, id DESC
                    LIMIT 20
                    """,
                    (f"%{lead_key}%",),
                ).fetchall():
                    found[int(r["id"])] = dict(r)
            action_rows = [found[k] for k in sorted(found.keys(), reverse=True)]
        pending = [dict(r) for r in action_rows if str(r["status"] or "").strip().lower() == "pending"]
        all_rows = [dict(r) for r in action_rows]
        latest = pending[0] if pending else (all_rows[0] if all_rows else {})
        last_action = str(latest.get("action_type") or "No Agent 2 action yet")
        last_when = str(latest.get("updated_at") or latest.get("created_at") or "")
        elapsed = _elapsed_label(last_when)

        rec = "No Agent 2 action needed right now."
        reason = "No pending action is currently due."
        elapsed_days = 0.0
        dt = parse_db_time(last_when)
        if dt:
            elapsed_days = max(0.0, (datetime.utcnow() - dt).total_seconds() / 86400.0)
        action_type = str(latest.get("action_type") or "")
        if pending:
            if action_type == "ScheduleAppointment":
                rec = "Schedule/confirm a call today."
                reason = f"It has been {elapsed} since scheduling action was last touched."
            elif action_type == "FollowUpTouchDue":
                rec = "Send follow-up SMS now, then place a call if no reply."
                reason = f"It has been {elapsed} since the follow-up action update."
            elif action_type == "ReviewInboundAndNextBestAction":
                rec = "Review inbound context and send a targeted reply."
                reason = f"It has been {elapsed} since this review action was updated."
            elif action_type == "EscalateToRelativeOutreach":
                rec = "Escalate outreach to relatives/neighbors and log outcome."
                reason = f"It has been {elapsed} since escalation became pending."
            elif action_type == "EscalateToDeepDiveResearch":
                rec = "Move lead into Deep Dive workflow and start alternate contact attempts."
                reason = f"It has been {elapsed} since deep-dive escalation was queued."
            elif action_type == "HumanReviewDisposition":
                rec = "Update disposition/status and align ReiSift status."
                reason = f"It has been {elapsed} since disposition review was queued."
            elif action_type == "AgentDiagnosisReview":
                rec = "Resolve agent diagnosis issue, then continue outreach cadence."
                reason = f"It has been {elapsed} since diagnosis review was queued."
            if elapsed_days >= 3:
                rec = rec + " Escalate priority due to age."
                reason = reason + " Action is stale (>3 days)."
        else:
            if row_dict.get("classification") in {"potential_seller", "unknown"} and not row_dict.get("unresolved"):
                rec = "Create next-touch action: call or SMS based on prior response."
                reason = "Lead is mapped but has no active Agent 2 pending action."

        on_market = str(referral.get("on_market_status") or "").strip().lower()
        referral_status = str(referral.get("referral_status") or "").strip()
        winning_name = " ".join(
            x for x in [str(referral.get("winning_realtor_first_name") or "").strip(), str(referral.get("winning_realtor_last_name") or "").strip()] if x
        ).strip()
        if on_market in {"listed", "on market", "active", "coming soon"}:
            if winning_name:
                rec = f"Follow up with listing realtor ({winning_name}) and update ReiSift referral status."
            else:
                rec = "Identify listing realtor, then update ReiSift referral status and notes."
            reason = (
                f"Referral appears on-market ({on_market or 'listed'})"
                + (f" with status '{referral_status}'." if referral_status else ".")
            )

        due_at = str(latest.get("due_at") or "")
        due_txt = format_est_datetime(due_at) if due_at else "-"
        timeline = f"It's been {elapsed} since {last_action}. Due: {due_txt}."
        return {
            "timeline": timeline,
            "recommendation": rec,
            "reason": reason,
            "last_action": last_action,
            "elapsed": elapsed,
            "due_at": due_at,
            "pending_count": len(pending),
            "total_count": len(all_rows),
        }

    rows = []
    for v in leads.values():
        resolution = resolution_map.get(v["lead_key"]) or {}
        approved_property_id = int(resolution.get("approved_property_id") or 0)
        approved_property_uuid = normalize_uuid(resolution.get("approved_property_uuid") or "")
        effective_property_id = approved_property_id or int(v["property_id"] or 0)
        effective_property_uuid = approved_property_uuid
        effective_classification = (
            (resolution.get("classification_override") or "").strip().lower()
            or (v["classification"] or "unknown")
        )
        ignore_agent2 = int(resolution.get("ignore_agent2") or 0)
        if not effective_property_uuid:
            for ph in list(v.get("phones") or []):
                pu = normalize_uuid(referral_uuid_by_phone.get(normalize_phone(ph) or "") or "")
                if pu:
                    effective_property_uuid = pu
                    break
        if not effective_property_uuid:
            ctx = _best_cached_context_for_phones(list(v.get("phones") or []))
            if not ctx and str(v.get("lead_key") or "").startswith("phone:"):
                lead_phone = normalize_phone(str(v.get("lead_key") or "").split(":", 1)[1])
                if lead_phone:
                    ctx = get_cached_contact_context(db, lead_phone)
            if ctx:
                cached_uuid = normalize_uuid(ctx["reisift_property_uuid"] or "")
                if cached_uuid:
                    effective_property_uuid = cached_uuid
                if not effective_property_id and int(ctx["property_id"] or 0):
                    effective_property_id = int(ctx["property_id"] or 0)
                if not v["label"] and str(ctx["reisift_full_address"] or "").strip():
                    v["label"] = str(ctx["reisift_full_address"] or "").strip()
        referral_data = {}
        for hint in list(v["address_hints"]):
            rk = normalize_address_key(hint)
            if rk and rk in referral_by_addr:
                referral_data = dict(referral_by_addr[rk])
                break
        if not referral_data:
            # fallback by row label/address-ish
            rk = normalize_address_key(v["label"])
            if rk and rk in referral_by_addr:
                referral_data = dict(referral_by_addr[rk])
        if not effective_property_uuid and referral_data:
            effective_property_uuid = normalize_uuid(referral_data.get("property_uuid") or "")
        effective_label = v["label"]
        if effective_property_id:
            prow = db.execute(
                """
                SELECT a.street, a.city, a.state, a.postal_code
                FROM properties p
                LEFT JOIN addresses a ON a.id = p.property_address_id
                WHERE p.id = ?
                """,
                (effective_property_id,),
            ).fetchone()
            if prow:
                addr_lbl = " ".join(
                    [
                        str(prow["street"] or "").strip(),
                        str(prow["city"] or "").strip(),
                        str(prow["state"] or "").strip(),
                        str(prow["postal_code"] or "").strip(),
                    ]
                ).strip()
                if addr_lbl:
                    effective_label = re.sub(r"\s+", " ", addr_lbl)
        pushes = []
        if referral_data:
            pushes = referral_push_by_uuid.get(str(referral_data.get("property_uuid") or "").strip(), [])[:5]
        summary_bits = []
        summary_bits.append(f"SMS out {int(v['sms_outbound'])}, SMS in {int(v['sms_inbound'])}, calls {int(v['calls'])}.")
        if v["clever_related"] or referral_data:
            summary_bits.append("Lead appears to be Clever/referral sourced.")
        if effective_classification in {"spam", "solicitor"}:
            summary_bits.append("Current classification suggests suppressing Agent 2 escalation.")
        if ignore_agent2:
            summary_bits.append("Manually flagged to ignore Agent 2.")
        recommended = "Continue monitoring"
        if effective_classification in {"spam", "solicitor"} or ignore_agent2:
            recommended = "No Agent 2 action (monitor only)"
        elif effective_property_id or effective_property_uuid:
            recommended = "Route to Agent 2 playbook for next touchpoint"
        else:
            recommended = "Resolve property link (address/phone) before Agent 2 action"
        rows.append(
            {
                "lead_key": v["lead_key"],
                "label": effective_label,
                "property_id": effective_property_id,
                "reisift_property_uuid": effective_property_uuid,
                "open_record_url": _sift_record_url(effective_property_uuid),
                "person_id": v["person_id"] or 0,
                "classification": effective_classification,
                "sources": sorted(list(v["sources"]))[:6],
                "address_hints": sorted(list(v["address_hints"]))[:4],
                "phones": sorted(list(v["phones"]))[:4],
                "sms_inbound": int(v["sms_inbound"]),
                "sms_outbound": int(v["sms_outbound"]),
                "calls": int(v["calls"]),
                "events": int(v["events"]),
                "last_activity_at": v["last_activity_at"] or "",
                "unresolved": 0 if (effective_property_id or effective_property_uuid) else 1,
                "ignore_agent2": 1 if ignore_agent2 else 0,
                "resolution_status": str(resolution.get("status") or ""),
                "suggested_property_id": int(resolution.get("suggested_property_id") or 0),
                "suggested_property_uuid": normalize_uuid(resolution.get("suggested_property_uuid") or ""),
                "resolution_updated_at": str(resolution.get("updated_at") or ""),
                "resolution_notes": str(resolution.get("notes") or ""),
                "clever_related": bool(v["clever_related"] or bool(referral_data)),
                "referral": referral_data,
                "referral_pushes": pushes,
                "agent_summary": " ".join(summary_bits),
                "recommended": recommended,
                "agent2_resolution": _agent2_resolution_for_lead(
                    {
                        "lead_key": v["lead_key"],
                        "property_id": effective_property_id,
                        "phones": sorted(list(v["phones"]))[:4],
                        "classification": effective_classification,
                        "unresolved": 0 if (effective_property_id or effective_property_uuid) else 1,
                        "referral": referral_data,
                    }
                ),
            }
        )
    rows.sort(key=lambda r: ((r["last_activity_at"] or ""), r["events"]), reverse=True)
    rows = rows[: max(1, min(200, int(limit or 60)))]
    unresolved_count = sum(1 for r in rows if r["unresolved"])
    unresolved_active_count = sum(
        1
        for r in rows
        if r["unresolved"] and not r["ignore_agent2"] and r["classification"] not in {"spam", "solicitor"}
    )
    return {
        "cutoff_utc": cutoff,
        "count": len(rows),
        "unresolved_count": unresolved_count,
        "unresolved_active_count": unresolved_active_count,
        "items": rows,
    }


def build_agent_advisor_snapshot(db, window_hours=72):
    cutoff_dt = datetime.utcnow() - timedelta(hours=max(1, int(window_hours or 72)))
    cutoff = format_db_time(cutoff_dt)
    snapshot = {
        "window_hours": int(window_hours or 72),
        "window_cutoff": cutoff,
        "generated_at": format_db_time(datetime.utcnow()),
    }

    signal_counts = db.execute(
        """
        SELECT
            SUM(CASE WHEN source_type = 'sms' THEN 1 ELSE 0 END) AS sms_total,
            SUM(CASE WHEN source_type = 'call' THEN 1 ELSE 0 END) AS call_total,
            SUM(CASE WHEN routing_status = 'new' THEN 1 ELSE 0 END) AS new_total,
            SUM(CASE WHEN routing_status = 'routed' THEN 1 ELSE 0 END) AS routed_total,
            SUM(CASE WHEN do_not_contact = 1 THEN 1 ELSE 0 END) AS dnc_total,
            SUM(CASE WHEN is_spam = 1 THEN 1 ELSE 0 END) AS spam_total
        FROM agent_signals
        WHERE updated_at >= ?
        """,
        (cutoff,),
    ).fetchone()
    snapshot["signals"] = {
        "sms_total": int((signal_counts["sms_total"] if signal_counts else 0) or 0),
        "call_total": int((signal_counts["call_total"] if signal_counts else 0) or 0),
        "new_total": int((signal_counts["new_total"] if signal_counts else 0) or 0),
        "routed_total": int((signal_counts["routed_total"] if signal_counts else 0) or 0),
        "dnc_total": int((signal_counts["dnc_total"] if signal_counts else 0) or 0),
        "spam_total": int((signal_counts["spam_total"] if signal_counts else 0) or 0),
    }

    action_counts = db.execute(
        """
        SELECT
            SUM(CASE WHEN status = 'Pending' THEN 1 ELSE 0 END) AS pending_total,
            SUM(CASE WHEN status = 'Pending' AND priority = 'High' THEN 1 ELSE 0 END) AS high_pending_total,
            SUM(CASE WHEN status = 'Completed' AND updated_at >= ? THEN 1 ELSE 0 END) AS completed_recent
        FROM lead_management_actions
        """,
        (cutoff,),
    ).fetchone()
    stale_counts = db.execute(
        """
        SELECT
            SUM(CASE WHEN status = 'Pending' AND datetime(updated_at) <= datetime('now', '-2 day') THEN 1 ELSE 0 END) AS stale_pending_2d
        FROM lead_management_actions
        """
    ).fetchone()
    snapshot["actions"] = {
        "pending_total": int((action_counts["pending_total"] if action_counts else 0) or 0),
        "high_pending_total": int((action_counts["high_pending_total"] if action_counts else 0) or 0),
        "completed_recent": int((action_counts["completed_recent"] if action_counts else 0) or 0),
        "stale_pending_2d": int((stale_counts["stale_pending_2d"] if stale_counts else 0) or 0),
    }

    call_counts = db.execute(
        """
        SELECT
            SUM(CASE WHEN analysis_status = 'Completed' AND updated_at >= ? THEN 1 ELSE 0 END) AS completed_recent,
            SUM(CASE WHEN analysis_status IN ('Pending', 'Retry') THEN 1 ELSE 0 END) AS pending_total,
            SUM(CASE WHEN analysis_status = 'Failed' THEN 1 ELSE 0 END) AS failed_total
        FROM call_recording_jobs
        """,
        (cutoff,),
    ).fetchone()
    snapshot["calls"] = {
        "completed_recent": int((call_counts["completed_recent"] if call_counts else 0) or 0),
        "pending_total": int((call_counts["pending_total"] if call_counts else 0) or 0),
        "failed_total": int((call_counts["failed_total"] if call_counts else 0) or 0),
    }

    latest_run = db.execute(
        """
        SELECT id, status, created_at, completed_at, summary_json
        FROM lead_monitor_runs
        ORDER BY id DESC
        LIMIT 1
        """
    ).fetchone()
    snapshot["latest_run"] = {
        "id": int(latest_run["id"]) if latest_run else 0,
        "status": str(latest_run["status"]) if latest_run else "",
        "created_at": str(latest_run["created_at"]) if latest_run else "",
        "completed_at": str(latest_run["completed_at"]) if latest_run else "",
        "summary": parse_json_object(latest_run["summary_json"]) if latest_run else {},
    }

    pending_actions = db.execute(
        """
        SELECT id, property_id, person_id, action_type, priority, status, reason, updated_at
        FROM lead_management_actions
        WHERE status = 'Pending'
        ORDER BY
            CASE priority WHEN 'High' THEN 0 WHEN 'Medium' THEN 1 ELSE 2 END,
            updated_at ASC,
            id ASC
        LIMIT 8
        """
    ).fetchall()
    snapshot["top_pending_actions"] = [
        {
            "id": int(r["id"]),
            "property_id": int(r["property_id"] or 0),
            "person_id": int(r["person_id"] or 0),
            "action_type": str(r["action_type"] or ""),
            "priority": str(r["priority"] or ""),
            "reason": str(r["reason"] or ""),
            "updated_at": str(r["updated_at"] or ""),
        }
        for r in pending_actions
    ]
    snapshot["lead_watch_today"] = build_agent3_lead_watch_snapshot_from_logs(db, limit=80)
    return snapshot


def build_agent_advisor_recommendations(snapshot):
    signals = snapshot.get("signals", {})
    actions = snapshot.get("actions", {})
    calls = snapshot.get("calls", {})
    lead_watch = snapshot.get("lead_watch_today", {})
    recs = []
    if int(actions.get("high_pending_total", 0)) > 0:
        recs.append(
            {
                "priority": "High",
                "title": "Clear high-priority lead actions",
                "reason": f"{actions.get('high_pending_total', 0)} high-priority items are pending.",
                "next_step": "Review and approve/dismiss high-priority items first.",
            }
        )
    if int(signals.get("new_total", 0)) > 0:
        recs.append(
            {
                "priority": "High" if int(signals.get("new_total", 0)) >= 5 else "Medium",
                "title": "Route new communication signals",
                "reason": f"{signals.get('new_total', 0)} signals remain unrouted.",
                "next_step": "Run SMS/call analysis routing and confirm resulting actions.",
            }
        )
    if int(calls.get("pending_total", 0)) > 0:
        recs.append(
            {
                "priority": "Medium",
                "title": "Process pending call analysis",
                "reason": f"{calls.get('pending_total', 0)} call recordings are waiting.",
                "next_step": "Run call analysis to keep lead intent current.",
            }
        )
    if int(actions.get("stale_pending_2d", 0)) > 0:
        recs.append(
            {
                "priority": "Medium",
                "title": "Resolve stale pending actions",
                "reason": f"{actions.get('stale_pending_2d', 0)} pending actions are older than 2 days.",
                "next_step": "Escalate stale items to explicit owner decisions.",
            }
        )
    if int(signals.get("dnc_total", 0)) > 0:
        recs.append(
            {
                "priority": "High",
                "title": "Validate do-not-contact constraints",
                "reason": f"{signals.get('dnc_total', 0)} recent signals indicate do-not-contact risk.",
                "next_step": "Confirm no outbound actions are queued for these leads.",
            }
        )
    unresolved_active = int(lead_watch.get("unresolved_active_count", 0) or 0)
    if unresolved_active > 0:
        recs.append(
            {
                "priority": "High" if unresolved_active >= 3 else "Medium",
                "title": "Resolve unresolved leads from today's intake",
                "reason": f"{unresolved_active} unresolved lead(s) still need property linkage or classification.",
                "next_step": "Use Agent 3 lead-watch resolution to connect by partial address or suppress spam/solicitors.",
            }
        )
    if not recs:
        recs.append(
            {
                "priority": "Low",
                "title": "Pipeline stable",
                "reason": "No high-risk backlog was detected.",
                "next_step": "Continue normal monitoring cadence.",
            }
        )
    return recs[:6]


def fallback_agent_advisor_summary(snapshot, recommendations):
    signals = snapshot.get("signals", {})
    actions = snapshot.get("actions", {})
    calls = snapshot.get("calls", {})
    lead_watch = snapshot.get("lead_watch_today", {})
    lines = [
        f"Window: last {snapshot.get('window_hours', 72)}h",
        (
            f"Signals - SMS: {signals.get('sms_total', 0)}, Calls: {signals.get('call_total', 0)}, "
            f"New: {signals.get('new_total', 0)}, Routed: {signals.get('routed_total', 0)}"
        ),
        (
            f"Actions - Pending: {actions.get('pending_total', 0)}, High Priority: {actions.get('high_pending_total', 0)}, "
            f"Stale >2d: {actions.get('stale_pending_2d', 0)}"
        ),
        (
            f"Call Analysis - Pending: {calls.get('pending_total', 0)}, "
            f"Completed (window): {calls.get('completed_recent', 0)}, Failed: {calls.get('failed_total', 0)}"
        ),
        (
            f"Lead Watch (Today ET) - Total: {lead_watch.get('count', 0)}, "
            f"Unresolved: {lead_watch.get('unresolved_count', 0)}, "
            f"Actionable Unresolved: {lead_watch.get('unresolved_active_count', 0)}"
        ),
        "Top Recommendations:",
    ]
    for idx, rec in enumerate(recommendations[:4], start=1):
        lines.append(f"{idx}. [{rec['priority']}] {rec['title']} - {rec['next_step']}")
    return "\n".join(lines)


def generate_agent_advisor_summary_with_openai(snapshot, recommendations):
    api_key = os.getenv("OPENAI_API_KEY", "").strip()
    if not api_key:
        return {"mode": "fallback", "summary_text": fallback_agent_advisor_summary(snapshot, recommendations), "json": {}}
    model = os.getenv("OPENAI_MODEL", "gpt-4.1-mini").strip() or "gpt-4.1-mini"
    schema = {
        "name": "agent_advisor_summary",
        "schema": {
            "type": "object",
            "additionalProperties": False,
            "properties": {
                "executive_summary": {"type": "string"},
                "top_priorities": {"type": "array", "items": {"type": "string"}},
                "risks": {"type": "array", "items": {"type": "string"}},
                "next_12h_plan": {"type": "array", "items": {"type": "string"}},
            },
            "required": ["executive_summary", "top_priorities", "risks", "next_12h_plan"],
        },
    }
    prompt = (
        "You are Agent 3 (Advisor Synthesizer) for a real-estate CRM.\n"
        "Create a concise operator brief from the snapshot and deterministic recommendations.\n"
        "Focus on actionability and risk control.\n\n"
        f"Snapshot JSON:\n{json.dumps(snapshot, ensure_ascii=True)}\n\n"
        f"Recommendations JSON:\n{json.dumps(recommendations, ensure_ascii=True)}"
    )
    response = requests.post(
        "https://api.openai.com/v1/responses",
        headers={"Authorization": f"Bearer {api_key}", "Content-Type": "application/json"},
        json={
            "model": model,
            "input": [
                {
                    "role": "system",
                    "content": [{"type": "input_text", "text": "You synthesize CRM agent outputs into prioritized, practical briefings."}],
                },
                {"role": "user", "content": [{"type": "input_text", "text": prompt}]},
            ],
            "text": {"format": {"type": "json_schema", "name": schema["name"], "schema": schema["schema"], "strict": True}},
        },
        timeout=60,
    )
    response.raise_for_status()
    data = response.json()
    output_text = (data.get("output_text") or "").strip()
    payload = json.loads(output_text) if output_text else {}
    if not payload:
        for item in data.get("output", []):
            for part in item.get("content", []):
                if part.get("type") in {"output_text", "text"} and part.get("text"):
                    payload = json.loads(part["text"])
                    break
            if payload:
                break
    if not payload:
        raise ValueError("No JSON output returned by advisor summary")
    summary_text = (
        f"{payload.get('executive_summary', '').strip()}\n\n"
        f"Top priorities:\n- " + "\n- ".join(payload.get("top_priorities", [])[:5]) + "\n\n"
        f"Risks:\n- " + "\n- ".join(payload.get("risks", [])[:5]) + "\n\n"
        f"Next 12h plan:\n- " + "\n- ".join(payload.get("next_12h_plan", [])[:6])
    ).strip()
    return {"mode": "openai", "summary_text": summary_text, "json": payload}


def answer_agent_advisor_question(question, snapshot, recommendations, qa_history):
    q = (question or "").strip()
    if not q:
        raise ValueError("Question is required.")
    api_key = os.getenv("OPENAI_API_KEY", "").strip()
    if not api_key:
        return (
            "OPENAI_API_KEY is not configured, so this is deterministic guidance.\n"
            + fallback_agent_advisor_summary(snapshot, recommendations)
        )
    model = os.getenv("OPENAI_MODEL", "gpt-4.1-mini").strip() or "gpt-4.1-mini"
    compact_history = [{"q": (h.get("question") or "")[:300], "a": (h.get("response_text") or "")[:500]} for h in qa_history[:6]]
    prompt = (
        "You are Agent 3 (Advisor Synthesizer). Answer the operator's question using only provided context.\n"
        "If context is insufficient, state exactly what is missing.\n\n"
        f"Question: {q}\n\n"
        f"Snapshot: {json.dumps(snapshot, ensure_ascii=True)}\n\n"
        f"Deterministic recommendations: {json.dumps(recommendations, ensure_ascii=True)}\n\n"
        f"Recent Q&A: {json.dumps(compact_history, ensure_ascii=True)}"
    )
    response = requests.post(
        "https://api.openai.com/v1/responses",
        headers={"Authorization": f"Bearer {api_key}", "Content-Type": "application/json"},
        json={
            "model": model,
            "input": [
                {"role": "system", "content": [{"type": "input_text", "text": "Answer operational CRM questions clearly and directly."}]},
                {"role": "user", "content": [{"type": "input_text", "text": prompt}]},
            ],
        },
        timeout=60,
    )
    response.raise_for_status()
    data = response.json()
    text = (data.get("output_text") or "").strip()
    if text:
        return text
    for item in data.get("output", []):
        for part in item.get("content", []):
            if part.get("type") in {"output_text", "text"} and part.get("text"):
                return str(part["text"]).strip()
    raise ValueError("No output returned by advisor Q&A")


def maybe_run_agent3_end_of_day_refresh(db):
    now_est = datetime.now(EST_TZ)
    # Run nightly closeout near end of day ET.
    if now_est.hour < 23:
        return {"ran": False, "reason": "before_eod_window"}
    eod_key = now_est.strftime("%Y-%m-%d")
    exists = db.execute(
        "SELECT id FROM agent_advisor_logs WHERE log_type = 'eod' AND question = ? LIMIT 1",
        (eod_key,),
    ).fetchone()
    if exists:
        return {"ran": False, "reason": "already_recorded", "eod_key": eod_key}
    snapshot = build_agent_advisor_snapshot(db, window_hours=24)
    recommendations = build_agent_advisor_recommendations(snapshot)
    summary_result = generate_agent_advisor_summary_with_openai(snapshot, recommendations)
    db.execute(
        """
        INSERT INTO agent_advisor_logs (log_type, question, response_text, response_json, snapshot_json)
        VALUES ('eod', ?, ?, ?, ?)
        """,
        (
            eod_key,
            summary_result.get("summary_text") or "",
            json.dumps(summary_result.get("json") or {}),
            json.dumps(snapshot),
        ),
    )
    db.commit()
    return {"ran": True, "eod_key": eod_key}


def run_bulk_sms_tick():
    run_sequence_tick()
    ensure_db()
    db = open_sqlite_connection()
    try:
        active_jobs = db.execute(
            "SELECT * FROM bulk_sms_jobs WHERE status = 'Active' ORDER BY id ASC"
        ).fetchall()
        now_utc = datetime.utcnow()

        for job in active_jobs:
            item = db.execute(
                """
                SELECT * FROM bulk_sms_job_items
                WHERE job_id = ? AND status IN ('Pending', 'Retry')
                  AND (next_attempt_at IS NULL OR next_attempt_at <= ?)
                ORDER BY id ASC
                LIMIT 1
                """,
                (job["id"], format_db_time(now_utc)),
            ).fetchone()

            if not item:
                remaining = db.execute(
                    "SELECT COUNT(*) AS c FROM bulk_sms_job_items WHERE job_id = ? AND status IN ('Pending', 'Retry')",
                    (job["id"],),
                ).fetchone()["c"]
                if remaining == 0:
                    db.execute(
                        "UPDATE bulk_sms_jobs SET status = 'Completed', finished_at = ? WHERE id = ?",
                        (format_db_time(now_utc), job["id"]),
                    )
                continue

            now_est = datetime.now(EST_TZ)
            open_est = bulk_window_next_open(now_est)
            if open_est > now_est:
                item_next = open_est.astimezone(timezone.utc).replace(tzinfo=None)
                db.execute(
                    "UPDATE bulk_sms_job_items SET next_attempt_at = ? WHERE id = ?",
                    (format_db_time(item_next), item["id"]),
                )
                continue

            to_number = item["to_number"]
            message = job["message"]
            from_number = get_deep_dive_sms_number(db)
            try:
                sent = send_smrtphone_sms(to_number, message, from_number=from_number)
                status = sent.get("status") or "Sent"
                cur = db.execute(
                    """
                    INSERT INTO communications (property_id, person_id, channel, direction, from_number, to_number, body, status, is_read, sent_at, external_id)
                    VALUES (?, ?, 'SMS', 'Outbound', ?, ?, ?, ?, 1, ?, ?)
                    """,
                    (
                        item["property_id"],
                        item["person_id"],
                        from_number,
                        to_number,
                        message,
                        status,
                        format_db_time(now_utc),
                        sent.get("sms_id"),
                    ),
                )
                update_person_outreach_status_for_sms(db, item["person_id"], "outbound_success")
                db.execute(
                    """
                    UPDATE bulk_sms_job_items
                    SET status = 'Sent', attempts = attempts + 1, sent_comm_id = ?, external_id = ?, last_error = ''
                    WHERE id = ?
                    """,
                    (cur.lastrowid, sent.get("sms_id"), item["id"]),
                )
            except Exception as exc:
                apply_touchpoint_status_inference(db, to_number, str(exc))
                db.execute(
                    """
                    UPDATE bulk_sms_job_items
                    SET status = 'Retry', attempts = attempts + 1, last_error = ?
                    WHERE id = ?
                    """,
                    (str(exc), item["id"]),
                )

            min_i = max(2, int(job["min_interval_minutes"] or 2))
            max_i = max(min_i, int(job["max_interval_minutes"] or 5))
            gap = random.randint(min_i, max_i)
            next_est = bulk_window_adjust(datetime.now(EST_TZ) + timedelta(minutes=gap))
            next_utc = next_est.astimezone(timezone.utc).replace(tzinfo=None)
            db.execute(
                """
                UPDATE bulk_sms_job_items
                SET next_attempt_at = ?
                WHERE job_id = ? AND status IN ('Pending', 'Retry') AND (next_attempt_at IS NULL OR next_attempt_at <= ?)
                """,
                (format_db_time(next_utc), job["id"], format_db_time(now_utc)),
            )

        db.commit()
    finally:
        db.close()

def fetch_obituary_text(url):
    headers = {"User-Agent": "Mozilla/5.0 (compatible; DeepProspectCRM/1.0)"}
    response = requests.get(url, timeout=12, headers=headers)
    response.raise_for_status()

    page = response.text
    page = re.sub(r"(?is)<script[^>]*>.*?</script>", " ", page)
    page = re.sub(r"(?is)<style[^>]*>.*?</style>", " ", page)
    text = re.sub(r"(?is)<[^>]+>", " ", page)
    text = unescape(text)
    text = re.sub(r"\s+", " ", text).strip()

    anchor = re.search(
        r"(Obituary|It is with deep sorrow|passed away|survived by).{0,4000}",
        text,
        re.IGNORECASE,
    )
    if anchor:
        return anchor.group(0)
    return text[:4000]


def clean_name(candidate):
    cleaned = re.sub(r"\b(the late|late|beloved|dear|cherished)\b", "", candidate, flags=re.I)
    cleaned = re.sub(r"[^A-Za-z'\-\s]", " ", cleaned)
    cleaned = re.sub(r"\s+", " ", cleaned).strip(" ,;")
    words = cleaned.split()
    if len(words) < 2:
        return ""
    if words[0].lower() in {"her", "his", "their", "and"}:
        return ""
    return " ".join(words[:4])


def split_candidate_names(block):
    compact = re.sub(r"\s+", " ", block).strip(" .;")
    compact = compact.replace(";", ",")
    chunks = re.split(r",|\band\b", compact, flags=re.I)
    names = []
    for chunk in chunks:
        name = clean_name(chunk)
        if name:
            names.append(name)
    return list(dict.fromkeys(names))


def normalize_name_token(token):
    t = re.sub(r"[^A-Za-z'\-\.]", "", (token or "").strip())
    return t.strip()


def split_name_first_middle_last(full_name):
    raw = re.sub(r"\s+", " ", (full_name or "").strip())
    if not raw:
        return ("Unknown", "", "Unknown", "")
    tokens = [normalize_name_token(t) for t in raw.split(" ") if normalize_name_token(t)]
    if not tokens:
        return ("Unknown", "", "Unknown", "")

    suffixes = {"jr", "jr.", "sr", "sr.", "ii", "iii", "iv", "v"}
    particles = {"de", "del", "la", "le", "van", "von", "di", "da", "st", "saint"}

    suffix = ""
    while len(tokens) > 1 and tokens[-1].lower() in suffixes:
        suffix = tokens.pop()

    first_name = tokens[0]
    if len(tokens) == 1:
        return (first_name, "", "Unknown", suffix)

    middle_tokens = []
    if len(tokens) >= 3 and tokens[-2].lower() in particles:
        last_name = f"{tokens[-2]} {tokens[-1]}"
        middle_tokens = tokens[1:-2]
    else:
        last_name = tokens[-1]
        middle_tokens = tokens[1:-1]
    middle_name = " ".join([m for m in middle_tokens if m]).strip()
    return (first_name, middle_name, last_name, suffix)


def split_name_first_last(full_name):
    first_name, _middle_name, last_name, suffix = split_name_first_middle_last(full_name)
    return (first_name, last_name, suffix)


def normalize_first_last(first_name, last_name):
    combined = " ".join([str(first_name or "").strip(), str(last_name or "").strip()]).strip()
    first, last, _suffix = split_name_first_last(combined)
    return first, last


def normalize_first_middle_last(first_name, middle_name, last_name):
    combined = " ".join(
        [str(first_name or "").strip(), str(middle_name or "").strip(), str(last_name or "").strip()]
    ).strip()
    first, middle, last, _suffix = split_name_first_middle_last(combined)
    return first, middle, last


def normalize_people_name_data(db):
    rows = db.execute("SELECT id, first_name, middle_name, last_name FROM people").fetchall()
    for r in rows:
        first = (r["first_name"] or "").strip()
        middle = (r["middle_name"] or "").strip()
        last = (r["last_name"] or "").strip()
        n_first, n_middle, n_last = normalize_first_middle_last(first, middle, last)
        if not n_first:
            n_first = first or "Unknown"
        if n_middle is None:
            n_middle = middle or ""
        if not n_last:
            n_last = last or "Unknown"
        if n_first != first or n_middle != middle or n_last != last:
            db.execute(
                "UPDATE people SET first_name = ?, middle_name = ?, last_name = ? WHERE id = ?",
                (n_first, n_middle, n_last, r["id"]),
            )


def parse_obituary_relationships(text):
    parsed = {
        "subject_status": "Unknown",
        "surviving_relatives": [],
        "preceded_relatives": [],
        "notes": [],
    }

    lower = text.lower()
    if re.search(r"\b(widow|widower)\b", lower) or re.search(
        r"preceded in death by (his|her) (husband|wife)", lower
    ):
        parsed["subject_status"] = "Widowed"
    elif re.search(r"survived by (his|her) (husband|wife|spouse)", lower):
        parsed["subject_status"] = "Married"

    spouse_match = re.search(
        r"survived by (?:his|her) (husband|wife|spouse)\s+([A-Z][A-Za-z'\-]+(?:\s+[A-Z][A-Za-z'\-]+){0,3})",
        text,
    )
    if spouse_match:
        parsed["surviving_relatives"].append(
            {
                "name": spouse_match.group(1).strip(),
                "relationship_type": "Spouse",
                "relative_status": "Living",
                "marital_status": "Married",
                "spouse_name": "",
            }
        )

    sentence_parts = re.split(r"(?<=[\.!?])\s+", text)
    kin_terms = "|".join(sorted(RELATION_TYPE_MAP.keys(), key=len, reverse=True))

    for sentence in sentence_parts:
        s_lower = sentence.lower()
        is_surviving = any(
            token in s_lower
            for token in ["survived by", "leaves behind", "also survived by", "is survived by"]
        )
        is_preceded = any(token in s_lower for token in ["preceded in death by", "predeceased by"])

        if not is_surviving and not is_preceded:
            continue

        for match in re.finditer(
            rf"(?:his|her|their)\s+({kin_terms})\s*(?:,|:)?\s*([^.;]+)",
            sentence,
            re.IGNORECASE,
        ):
            raw_type = match.group(1).lower()
            rel_type = RELATION_TYPE_MAP.get(raw_type, "Relative")
            raw_names = match.group(2)

            married_pairs = re.findall(
                r"([A-Z][A-Za-z'\-]+(?:\s+[A-Z][A-Za-z'\-]+){0,2})\s*\(([^)]+)\)",
                raw_names,
            )
            consumed = set()

            for primary, spouse in married_pairs:
                p_name = clean_name(primary)
                s_name = clean_name(spouse)
                if p_name:
                    parsed_target = parsed["surviving_relatives"] if is_surviving else parsed["preceded_relatives"]
                    parsed_target.append(
                        {
                            "name": p_name,
                            "relationship_type": rel_type,
                            "relative_status": "Living" if is_surviving else "Deceased",
                            "marital_status": "Married" if s_name else "Unknown",
                            "spouse_name": s_name,
                        }
                    )
                    consumed.add(p_name)
                if s_name and is_surviving:
                    parsed["surviving_relatives"].append(
                        {
                            "name": s_name,
                            "relationship_type": "In-Law",
                            "relative_status": "Living",
                            "marital_status": "Married",
                            "spouse_name": p_name,
                        }
                    )
                    consumed.add(s_name)

            for name in split_candidate_names(raw_names):
                if name in consumed:
                    continue
                parsed_target = parsed["surviving_relatives"] if is_surviving else parsed["preceded_relatives"]
                parsed_target.append(
                    {
                        "name": name,
                        "relationship_type": rel_type,
                        "relative_status": "Living" if is_surviving else "Deceased",
                        "marital_status": "Unknown",
                        "spouse_name": "",
                    }
                )

    def dedupe(items):
        seen = set()
        out = []
        for item in items:
            key = (item["name"].lower(), item["relationship_type"], item["relative_status"])
            if item["name"] and key not in seen:
                out.append(item)
                seen.add(key)
        return out

    parsed["surviving_relatives"] = dedupe(parsed["surviving_relatives"])
    parsed["preceded_relatives"] = dedupe(parsed["preceded_relatives"])
    return parsed


def find_or_create_person_by_full_name(db, full_name, notes=""):
    first_name, last_name, suffix = split_name_first_last(full_name)
    if first_name == "Unknown" and last_name == "Unknown":
        return None

    row = db.execute(
        """
        SELECT id FROM people
        WHERE lower(first_name) = lower(?) AND lower(last_name) = lower(?)
        LIMIT 1
        """,
        (first_name, last_name),
    ).fetchone()
    if row:
        if notes:
            extra = f"{notes} ParsedSuffix:{suffix}".strip() if suffix else notes
            db.execute(
                "UPDATE people SET notes = trim(coalesce(notes,'') || ' ' || ?) WHERE id = ?",
                (extra, row["id"]),
            )
        return row["id"]

    create_notes = f"{notes} ParsedSuffix:{suffix}".strip() if suffix else notes
    return create_person(db, first_name, last_name, notes=create_notes)


def find_or_create_person_by_full_name_smart(db, full_name, notes=""):
    cleaned = clean_name(full_name) or (full_name or "").strip()
    parts = [p for p in cleaned.split() if p]
    if len(parts) < 2:
        return find_or_create_person_by_full_name(db, cleaned, notes=notes)
    first_name, last_name, suffix = split_name_first_last(cleaned)
    exact = db.execute(
        """
        SELECT id
        FROM people
        WHERE lower(first_name) = lower(?) AND lower(last_name) = lower(?)
        LIMIT 1
        """,
        (first_name, last_name),
    ).fetchone()
    if exact:
        if notes:
            extra = f"{notes} ParsedSuffix:{suffix}".strip() if suffix else notes
            db.execute("UPDATE people SET notes = trim(coalesce(notes,'') || ' ' || ?) WHERE id = ?", (extra, exact["id"]))
        return exact["id"]

    last_token = (last_name or "").split(" ")[-1].lower()
    candidates = db.execute(
        """
        SELECT id, first_name, last_name
        FROM people
        WHERE lower(first_name) = lower(?)
        """,
        (first_name,),
    ).fetchall()
    for c in candidates:
        c_last = (c["last_name"] or "").strip().lower()
        c_parts = [x for x in c_last.split() if x]
        if c_last == last_name.lower() or (c_parts and c_parts[-1] == last_token):
            if notes:
                extra = f"{notes} ParsedSuffix:{suffix}".strip() if suffix else notes
                db.execute("UPDATE people SET notes = trim(coalesce(notes,'') || ' ' || ?) WHERE id = ?", (extra, c["id"]))
            return c["id"]

    create_notes = f"{notes} ParsedSuffix:{suffix}".strip() if suffix else notes
    return create_person(db, first_name, last_name, notes=create_notes)


def relationship_exists(db, subject_person_id, related_person_id, relationship_type):
    row = db.execute(
        """
        SELECT id
        FROM person_relationships
        WHERE subject_person_id = ? AND related_person_id = ? AND lower(relationship_type) = lower(?)
        LIMIT 1
        """,
        (subject_person_id, related_person_id, relationship_type),
    ).fetchone()
    return bool(row)


def find_or_create_person_by_name_parts(db, first_name, last_name, notes=""):
    first_name, last_name = normalize_first_last(first_name, last_name)
    first_name = first_name or "Unknown"
    last_name = last_name or "Unknown"
    row = db.execute(
        """
        SELECT id FROM people
        WHERE lower(first_name) = lower(?) AND lower(last_name) = lower(?)
        LIMIT 1
        """,
        (first_name, last_name),
    ).fetchone()
    if row:
        if notes:
            db.execute(
                "UPDATE people SET notes = trim(coalesce(notes,'') || ' ' || ?) WHERE id = ?",
                (notes, row["id"]),
            )
        return row["id"]
    return create_person(db, first_name, last_name, notes=notes)



def extract_obituary_context(raw_text, name, width=260):
    if not raw_text:
        return ""
    if not name:
        return re.sub(r"\s+", " ", raw_text[:width]).strip()

    idx = raw_text.lower().find(name.lower())
    if idx < 0:
        return re.sub(r"\s+", " ", raw_text[:width]).strip()

    start = max(0, idx - (width // 2))
    end = min(len(raw_text), idx + len(name) + (width // 2))
    snippet = raw_text[start:end]
    return re.sub(r"\s+", " ", snippet).strip()
def import_obituary_into_property(db, property_id, subject_person_id, source_url):
    raw_text = fetch_obituary_text(source_url)
    extracted = parse_obituary_relationships(raw_text)

    db.execute(
        """
        INSERT INTO obituary_sources (property_id, subject_person_id, source_url, raw_text, extracted_json)
        VALUES (?, ?, ?, ?, ?)
        """,
        (property_id, subject_person_id, source_url, raw_text, json.dumps(extracted)),
    )

    inserted_relationships = 0
    created_people = 0

    for item in extracted["surviving_relatives"] + extracted["preceded_relatives"]:
        count_before = db.execute("SELECT COUNT(*) AS c FROM people").fetchone()["c"]
        relative_id = find_or_create_person_by_full_name_smart(
            db,
            item["name"],
            notes=f"Imported from obituary: {source_url}",
        )
        count_after = db.execute("SELECT COUNT(*) AS c FROM people").fetchone()["c"]
        if count_after > count_before:
            created_people += 1

        context = extract_obituary_context(raw_text, item['name'])
        note = f"Obituary import ({item['relative_status']}, marital: {item['marital_status']}) | Source: {context}"
        if not relationship_exists(db, subject_person_id, relative_id, item["relationship_type"]):
            db.execute(
                """
                INSERT INTO person_relationships (subject_person_id, related_person_id, relationship_type, note)
                VALUES (?, ?, ?, ?)
                """,
                (subject_person_id, relative_id, item["relationship_type"], note),
            )
            inserted_relationships += 1

        spouse_name = item.get("spouse_name", "").strip()
        if spouse_name:
            spouse_id = find_or_create_person_by_full_name_smart(
                db,
                spouse_name,
                notes=f"Imported spouse from obituary: {source_url}",
            )
            if not relationship_exists(db, relative_id, spouse_id, "Spouse"):
                db.execute(
                    """
                    INSERT INTO person_relationships (subject_person_id, related_person_id, relationship_type, note)
                    VALUES (?, ?, ?, ?)
                    """,
                    (relative_id, spouse_id, "Spouse", "Inferred from obituary structure"),
                )

    db.execute(
        """
        INSERT INTO activity_log (property_id, person_id, activity_type, outcome, note)
        VALUES (?, ?, ?, ?, ?)
        """,
        (
            property_id,
            subject_person_id,
            "Obituary Import",
            f"Imported {inserted_relationships} relationships",
            f"URL: {source_url} | Subject status: {extracted['subject_status']}",
        ),
    )
    add_person_note(
        db,
        subject_person_id,
        "Obituary Import",
        f"Imported obituary from {source_url}",
        {"source_url": source_url, "summary": extracted},
    )

    return {
        "subject_status": extracted["subject_status"],
        "created_people": created_people,
        "inserted_relationships": inserted_relationships,
        "surviving_relatives": extracted["surviving_relatives"],
        "preceded_relatives": extracted["preceded_relatives"],
    }


def call_openai_obituary_agent(obituary_text, subject_name=""):
    api_key = os.getenv("OPENAI_API_KEY", "").strip()
    if not api_key:
        raise ValueError("OPENAI_API_KEY is not set")

    model = os.getenv("OPENAI_MODEL", "gpt-4.1-mini")
    schema = {
        "name": "obituary_relationships",
        "schema": {
            "type": "object",
            "additionalProperties": False,
            "properties": {
                "subject_name": {"type": "string"},
                "subject_status": {
                    "type": "string",
                    "enum": ["Married", "Widowed", "Single", "Unknown"],
                },
                "relations": {
                    "type": "array",
                    "items": {
                        "type": "object",
                        "additionalProperties": False,
                        "properties": {
                            "name": {"type": "string"},
                            "relationship": {"type": "string"},
                            "status": {"type": "string", "enum": ["Living", "Deceased", "Unknown"]},
                            "marital_status": {
                                "type": "string",
                                "enum": ["Married", "Widowed", "Single", "Unknown"],
                            },
                            "spouse_name": {"type": "string"},
                            "note": {"type": "string"},
                        },
                        "required": ["name", "relationship", "status", "marital_status", "spouse_name", "note"],
                    },
                },
            },
            "required": ["subject_name", "subject_status", "relations"],
        },
        "strict": True,
    }

    prompt = (
        "Extract every named individual in this obituary and map each person to the subject. "
        "Return only schema-valid JSON. Treat phrases like 'preceded in death by' as Deceased. "
        "If a relative is listed with spouse wording, map in-law or spouse explicitly. "
        "Do not merge distinct names."
    )

    payload = {
        "model": model,
        "input": [
            {
                "role": "system",
                "content": [
                    {
                        "type": "input_text",
                        "text": "You are a high-precision obituary relationship extractor for CRM enrichment.",
                    }
                ],
            },
            {
                "role": "user",
                "content": [
                    {
                        "type": "input_text",
                        "text": f"Subject: {subject_name or 'Unknown'}\n\n{prompt}\n\nObituary text:\n{obituary_text}",
                    }
                ],
            },
        ],
        "text": {
            "format": {
                "type": "json_schema",
                "name": schema["name"],
                "schema": schema["schema"],
                "strict": True,
            }
        },
    }

    response = requests.post(
        "https://api.openai.com/v1/responses",
        headers={
            "Authorization": f"Bearer {api_key}",
            "Content-Type": "application/json",
        },
        json=payload,
        timeout=30,
    )
    response.raise_for_status()
    data = response.json()

    output_text = data.get("output_text", "").strip()
    if output_text:
        return json.loads(output_text)

    for item in data.get("output", []):
        for part in item.get("content", []):
            if part.get("type") in {"output_text", "text"} and part.get("text"):
                return json.loads(part["text"])

    raise ValueError("No JSON output returned by obituary agent")


def normalize_ai_obituary_result(ai_result):
    subject_status = ai_result.get("subject_status", "Unknown")
    relations = ai_result.get("relations", [])

    normalized = {
        "subject_status": subject_status,
        "surviving_relatives": [],
        "preceded_relatives": [],
    }

    for rel in relations:
        name = (rel.get("name") or "").strip()
        if not name:
            continue

        status = (rel.get("status") or "Unknown").strip()
        item = {
            "name": name,
            "relationship_type": (rel.get("relationship") or "Relative").strip() or "Relative",
            "relative_status": status,
            "marital_status": (rel.get("marital_status") or "Unknown").strip(),
            "spouse_name": (rel.get("spouse_name") or "").strip(),
            "note": (rel.get("note") or "AI obituary extraction").strip(),
        }
        if status == "Deceased":
            normalized["preceded_relatives"].append(item)
        else:
            normalized["surviving_relatives"].append(item)

    return normalized


def import_normalized_obituary(db, property_id, subject_person_id, source_url, raw_text, normalized):
    db.execute(
        """
        INSERT INTO obituary_sources (property_id, subject_person_id, source_url, raw_text, extracted_json)
        VALUES (?, ?, ?, ?, ?)
        """,
        (property_id, subject_person_id, source_url, raw_text, json.dumps(normalized)),
    )

    inserted_relationships = 0
    created_people = 0

    for item in normalized["surviving_relatives"] + normalized["preceded_relatives"]:
        count_before = db.execute("SELECT COUNT(*) AS c FROM people").fetchone()["c"]
        relative_id = find_or_create_person_by_full_name_smart(
            db,
            item["name"],
            notes=f"Imported from obituary: {source_url}",
        )
        count_after = db.execute("SELECT COUNT(*) AS c FROM people").fetchone()["c"]
        if count_after > count_before:
            created_people += 1

        context = extract_obituary_context(raw_text, item['name'])
        note = f"Obituary import ({item['relative_status']}, marital: {item['marital_status']}) | {item.get('note', '')} | Source: {context}".strip()
        if not relationship_exists(db, subject_person_id, relative_id, item["relationship_type"]):
            db.execute(
                """
                INSERT INTO person_relationships (subject_person_id, related_person_id, relationship_type, note)
                VALUES (?, ?, ?, ?)
                """,
                (subject_person_id, relative_id, item["relationship_type"], note),
            )
            inserted_relationships += 1

        spouse_name = item.get("spouse_name", "").strip()
        if spouse_name:
            spouse_id = find_or_create_person_by_full_name_smart(
                db,
                spouse_name,
                notes=f"Imported spouse from obituary: {source_url}",
            )
            if not relationship_exists(db, relative_id, spouse_id, "Spouse"):
                db.execute(
                    """
                    INSERT INTO person_relationships (subject_person_id, related_person_id, relationship_type, note)
                    VALUES (?, ?, ?, ?)
                    """,
                    (relative_id, spouse_id, "Spouse", "Inferred from obituary extraction"),
                )

    db.execute(
        """
        INSERT INTO activity_log (property_id, person_id, activity_type, outcome, note)
        VALUES (?, ?, ?, ?, ?)
        """,
        (
            property_id,
            subject_person_id,
            "Obituary Import",
            f"Imported {inserted_relationships} relationships",
            f"URL: {source_url} | Subject status: {normalized['subject_status']}",
        ),
    )
    add_person_note(
        db,
        subject_person_id,
        "Obituary Import",
        f"Imported obituary from {source_url}",
        {
            "source_url": source_url,
            "normalized": normalized,
            "raw_excerpt": raw_text[:1200],
        },
    )

    return {
        "subject_status": normalized["subject_status"],
        "created_people": created_people,
        "inserted_relationships": inserted_relationships,
        "surviving_relatives": normalized["surviving_relatives"],
        "preceded_relatives": normalized["preceded_relatives"],
        "raw_excerpt": raw_text[:2000],
    }


def import_obituary_ai_into_property(db, property_id, subject_person_id, source_url, subject_name=""):
    raw_text = fetch_obituary_text(source_url)
    ai_result = call_openai_obituary_agent(raw_text, subject_name=subject_name)
    normalized = normalize_ai_obituary_result(ai_result)
    return import_normalized_obituary(db, property_id, subject_person_id, source_url, raw_text, normalized)


def parse_expansion_url_map(raw_text):
    def key_for(name):
        return re.sub(r"[^a-z0-9]+", " ", (name or "").lower()).strip()

    mapping = {}
    for line in (raw_text or "").splitlines():
        item = line.strip()
        if not item:
            continue
        parts = re.split(r"\s*\|\s*|\s*=\s*", item, maxsplit=1)
        if len(parts) != 2:
            continue
        name = clean_name(parts[0]) or parts[0].strip()
        url = parts[1].strip()
        if not name or not url.lower().startswith("http"):
            continue
        mapping[key_for(name)] = url
    return mapping


def location_hint_for_name(raw_text, name):
    if not raw_text or not name:
        return ""
    pattern = re.compile(
        rf"{re.escape(name)}[^.{{}}]{{0,120}}?\b(?:of|from|in)\s+([A-Z][A-Za-z\-\s]+,\s*[A-Z]{{2}})",
        re.IGNORECASE,
    )
    m = pattern.search(raw_text)
    if m:
        return m.group(1).strip()
    return ""


def obituary_item_confidence(item, depth=1):
    base = 0.82 if depth == 1 else 0.74
    status = (item.get("relative_status") or "").strip().lower()
    rel = (item.get("relationship_type") or "").strip().lower()
    note = (item.get("note") or "").strip().lower()
    if status in {"living", "deceased"}:
        base += 0.04
    if rel in {"spouse", "child", "sibling", "parent"}:
        base += 0.03
    if any(t in note for t in ["inferred", "possible", "uncertain", "guess"]):
        base -= 0.18
    return round(max(0.25, min(0.98, base)), 2)


def log_obituary_expansion_item(
    db,
    run_id,
    property_id,
    subject_person_id,
    related_person_id,
    depth,
    person_name,
    relationship_type,
    relative_status,
    confidence,
    processing_status,
    source_url,
    note,
    details=None,
):
    db.execute(
        """
        INSERT INTO obituary_expansion_items
        (run_id, property_id, subject_person_id, related_person_id, depth, person_name, relationship_type, relative_status, confidence, processing_status, source_url, note, details_json)
        VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
        """,
        (
            run_id,
            property_id,
            subject_person_id,
            related_person_id,
            depth,
            person_name,
            relationship_type,
            relative_status,
            confidence,
            processing_status,
            source_url,
            note,
            json.dumps(details or {}),
        ),
    )


def import_obituary_ai_with_expansion(
    db,
    property_id,
    subject_person_id,
    source_url,
    subject_name="",
    expand_deceased=False,
    max_depth=1,
    expansion_url_map=None,
):
    max_depth = max(1, min(3, int(max_depth or 1)))
    expansion_url_map = expansion_url_map or {}
    run_cur = db.execute(
        """
        INSERT INTO obituary_expansion_runs (property_id, root_subject_person_id, root_source_url, max_depth, expand_deceased, status)
        VALUES (?, ?, ?, ?, ?, 'Running')
        """,
        (property_id, subject_person_id, source_url, max_depth, 1 if expand_deceased else 0),
    )
    run_id = run_cur.lastrowid
    queue = [(subject_person_id, source_url, 1, subject_name or "")]
    visited = set()
    processed = 0
    queued_secondary = 0
    missing_secondary = 0
    low_confidence = 0
    errors = []

    while queue:
        current_person_id, current_url, depth, current_subject_name = queue.pop(0)
        key = (current_person_id, current_url.strip().lower())
        if key in visited:
            continue
        visited.add(key)
        try:
            summary = import_obituary_ai_into_property(
                db,
                property_id=property_id,
                subject_person_id=current_person_id,
                source_url=current_url,
                subject_name=current_subject_name,
            )
            processed += 1
            raw_text = (summary.get("raw_excerpt") or "").strip()
            for item in (summary.get("surviving_relatives") or []) + (summary.get("preceded_relatives") or []):
                full_name = (item.get("name") or "").strip()
                if not full_name:
                    continue
                related_id = find_or_create_person_by_full_name_smart(db, full_name)
                conf = obituary_item_confidence(item, depth=depth)
                if conf < 0.65:
                    low_confidence += 1
                rel_status = (item.get("relative_status") or "Unknown").strip()
                rel_type = (item.get("relationship_type") or "Relative").strip()
                loc_hint = location_hint_for_name(raw_text, full_name)
                status = "Imported"
                note_bits = []
                if loc_hint:
                    note_bits.append(f"location hint: {loc_hint}")
                if expand_deceased and depth < max_depth and rel_status.lower() == "deceased":
                    lookup_key = re.sub(r"[^a-z0-9]+", " ", full_name.lower()).strip()
                    next_url = expansion_url_map.get(lookup_key, "")
                    if next_url:
                        next_person = db.execute("SELECT first_name, last_name FROM people WHERE id = ?", (related_id,)).fetchone()
                        next_name = f"{next_person['first_name']} {next_person['last_name']}".strip() if next_person else full_name
                        queue.append((related_id, next_url, depth + 1, next_name))
                        status = "Queued Secondary Search"
                        queued_secondary += 1
                    else:
                        status = "Missing Secondary URL"
                        missing_secondary += 1
                log_obituary_expansion_item(
                    db=db,
                    run_id=run_id,
                    property_id=property_id,
                    subject_person_id=current_person_id,
                    related_person_id=related_id,
                    depth=depth,
                    person_name=full_name,
                    relationship_type=rel_type,
                    relative_status=rel_status,
                    confidence=conf,
                    processing_status=status,
                    source_url=current_url,
                    note="; ".join(note_bits),
                    details={"marital_status": item.get("marital_status"), "spouse_name": item.get("spouse_name"), "ai_note": item.get("note")},
                )
        except Exception as exc:
            errors.append(str(exc))
            log_obituary_expansion_item(
                db=db,
                run_id=run_id,
                property_id=property_id,
                subject_person_id=current_person_id,
                related_person_id=None,
                depth=depth,
                person_name=current_subject_name or f"Person {current_person_id}",
                relationship_type="",
                relative_status="",
                confidence=0.25,
                processing_status="Failed",
                source_url=current_url,
                note=str(exc),
                details={"error": str(exc)},
            )

    summary = {
        "processed_obituaries": processed,
        "queued_secondary": queued_secondary,
        "missing_secondary_url": missing_secondary,
        "low_confidence_count": low_confidence,
        "errors": errors,
        "expand_deceased": bool(expand_deceased),
        "max_depth": max_depth,
    }
    db.execute(
        """
        UPDATE obituary_expansion_runs
        SET status = ?, summary_json = ?, completed_at = ?
        WHERE id = ?
        """,
        ("Completed" if not errors else "Completed with Warnings", json.dumps(summary), format_db_time(datetime.utcnow()), run_id),
    )
    return {"run_id": run_id, **summary}


def reisift_get_access_token():
    api_key = os.getenv("REISIFT_API_KEY", "").strip()
    email = os.getenv("REISIFT_EMAIL", "").strip()
    password = os.getenv("REISIFT_PASSWORD", "").strip()
    if api_key:
        try:
            verify = requests.get(
                f"{REISIFT_BASE_URL}/api/internal/user/",
                headers={
                    "Authorization": f"Bearer {api_key}",
                    "x-reisift-ui-version": REISIFT_UI_VERSION,
                },
                timeout=15,
            )
            if verify.ok:
                return api_key
        except requests.RequestException:
            pass

    if not email or not password:
        raise ValueError("Missing REISIFT credentials. Set REISIFT_EMAIL and REISIFT_PASSWORD.")

    response = requests.post(
        f"{REISIFT_BASE_URL}/api/token/",
        headers={"Content-Type": "application/json"},
        json={"email": email, "password": password, "remember": True, "agree": True},
        timeout=20,
    )
    response.raise_for_status()
    payload = response.json()
    token = (payload.get("access") or "").strip()
    if not token:
        raise ValueError("REISIFT login did not return an access token.")
    return token


def reisift_auth_headers(token, extra=None):
    headers = {
        "Authorization": f"Bearer {token}",
        "Content-Type": "application/json",
        "x-reisift-ui-version": REISIFT_UI_VERSION,
    }
    if isinstance(extra, dict):
        headers.update(extra)
    return headers


def reisift_task_writes_enabled():
    return bool(REISIFT_TASK_WRITE_ENABLED)


def ensure_reisift_task_writes_enabled():
    if not reisift_task_writes_enabled():
        raise ValueError(
            "ReiSift task writes are disabled (REISIFT_TASK_WRITE_ENABLED=false). "
            "Task actions remain notification-only in this app."
        )


def _reisift_due_tomorrow_noon_utc_text(now_dt=None):
    now_et = (now_dt or datetime.utcnow().replace(tzinfo=timezone.utc)).astimezone(EST_TZ)
    due_local = (now_et + timedelta(days=1)).replace(hour=12, minute=0, second=0, microsecond=0)
    due_utc = due_local.astimezone(timezone.utc)
    return due_utc.strftime("%Y-%m-%dT%H:%M:%S.000Z")


def reisift_create_task(
    token,
    *,
    title,
    address,
    assigned_to_property,
    assigned_to_user,
    due_date=None,
    all_day=False,
    notes=None,
):
    task_payload = {
        "title": str(title or "").strip(),
        "all_day": bool(all_day),
        "round_robin": False,
        "address": str(address or "").strip(),
        "event_type": "task",
        "assigned_to_property": str(assigned_to_property or "").strip(),
        "assigned_to_role": None,
        "assigned_to_user": str(assigned_to_user or "").strip(),
        "assigned_to_users": None,
        "due_date": str(due_date or _reisift_due_tomorrow_noon_utc_text()).strip(),
        "recurrence": None,
        "notes": notes if notes else None,
    }
    if not task_payload["title"]:
        raise ValueError("Task title is required.")
    if not task_payload["address"]:
        raise ValueError("Task address is required.")
    if not task_payload["assigned_to_property"]:
        raise ValueError("Task assigned_to_property is required.")
    if not task_payload["assigned_to_user"]:
        raise ValueError("Task assigned_to_user is required.")

    response = requests.post(
        f"{REISIFT_BASE_URL}/api/internal/task/",
        headers=reisift_auth_headers(token),
        json=task_payload,
        timeout=30,
    )
    try:
        body = response.json()
    except ValueError:
        body = {"raw_text": response.text}
    if not response.ok:
        raise ValueError(f"ReiSift task create failed ({response.status_code}): {body}")
    return {"request": task_payload, "response": body}


def parse_csv_list(value):
    if isinstance(value, list):
        return [str(x).strip() for x in value if str(x).strip()]
    raw = str(value or "").strip()
    if not raw:
        return []
    return [x.strip() for x in raw.split(",") if x.strip()]


def _reisift_find_first_map_id(payload):
    stack = [payload]
    while stack:
        current = stack.pop(0)
        if isinstance(current, dict):
            for key in ("map_id", "id"):
                if key in current:
                    candidate = str(current.get(key) or "").strip()
                    if candidate and candidate.isdigit():
                        return candidate
            for value in current.values():
                if isinstance(value, (dict, list)):
                    stack.append(value)
        elif isinstance(current, list):
            for item in current:
                if isinstance(item, (dict, list)):
                    stack.append(item)
    return ""


def _reisift_find_first_address_dict(payload):
    stack = [payload]
    while stack:
        current = stack.pop(0)
        if isinstance(current, dict):
            if any(k in current for k in ("street", "city", "state", "postal_code", "zip")):
                street = (current.get("street") or current.get("address1") or "").strip()
                city = (current.get("city") or "").strip()
                state = (current.get("state") or "").strip()
                postal_code = (current.get("postal_code") or current.get("zip") or current.get("zipcode") or "").strip()
                if street and city:
                    return {
                        "street": street,
                        "city": city,
                        "state": state,
                        "postal_code": postal_code,
                    }
            for value in current.values():
                if isinstance(value, (dict, list)):
                    stack.append(value)
        elif isinstance(current, list):
            for item in current:
                if isinstance(item, (dict, list)):
                    stack.append(item)
    return {"street": "", "city": "", "state": "", "postal_code": ""}


def _reisift_find_first_owner_dict(payload):
    stack = [payload]
    while stack:
        current = stack.pop(0)
        if isinstance(current, dict):
            owner = current.get("owner")
            if isinstance(owner, dict):
                return owner
            if any(k in current for k in ("first_name", "last_name", "full_name", "phones", "emails")):
                return current
            for value in current.values():
                if isinstance(value, (dict, list)):
                    stack.append(value)
        elif isinstance(current, list):
            for item in current:
                if isinstance(item, (dict, list)):
                    stack.append(item)
    return {}


def _reisift_find_owner_uuid(payload):
    if not isinstance(payload, (dict, list)):
        return ""
    queue = [payload]
    while queue:
        current = queue.pop(0)
        if isinstance(current, dict):
            for key in ("owner_uuid", "owner_id"):
                candidate = str(current.get(key) or "").strip()
                if candidate:
                    return candidate
            owner = current.get("owner")
            if isinstance(owner, dict):
                for key in ("uuid", "id"):
                    candidate = str(owner.get(key) or "").strip()
                    if candidate:
                        return candidate
            owners = current.get("owners")
            if isinstance(owners, list):
                for owner_item in owners:
                    if not isinstance(owner_item, dict):
                        continue
                    for key in ("uuid", "id"):
                        candidate = str(owner_item.get(key) or "").strip()
                        if candidate:
                            return candidate
            for value in current.values():
                if isinstance(value, (dict, list)):
                    queue.append(value)
        elif isinstance(current, list):
            for item in current:
                if isinstance(item, (dict, list)):
                    queue.append(item)
    return ""


def _reisift_parse_owner_name(owner):
    if not isinstance(owner, dict):
        return {"first_name": "", "last_name": ""}
    first = (owner.get("first_name") or "").strip()
    last = (owner.get("last_name") or "").strip()
    if first and last:
        return {"first_name": first, "last_name": last}
    full = (owner.get("full_name") or owner.get("name") or "").strip()
    if full:
        parts = full.split()
        if len(parts) == 1:
            return {"first_name": parts[0], "last_name": ""}
        return {"first_name": parts[0], "last_name": " ".join(parts[1:]).strip()}
    return {"first_name": first, "last_name": last}


def _reisift_parse_owner_emails(owner):
    emails = []
    seen = set()
    if not isinstance(owner, dict):
        return emails
    for item in owner.get("emails") or []:
        value = ""
        if isinstance(item, dict):
            value = (item.get("email") or item.get("value") or "").strip()
        else:
            value = str(item or "").strip()
        key = value.lower()
        if not value or key in seen:
            continue
        seen.add(key)
        emails.append(value)
    return emails


def _reisift_parse_phone_tags(raw_tags):
    tags = []
    seen = set()

    def add_tag(value):
        text = str(value or "").strip()
        key = text.lower()
        if not text or key in seen:
            return
        seen.add(key)
        tags.append(text)

    if isinstance(raw_tags, list):
        for item in raw_tags:
            if isinstance(item, str):
                add_tag(item)
            elif isinstance(item, dict):
                for key, value in item.items():
                    if value in (True, "true", "True", 1, "1"):
                        add_tag(key)
            else:
                add_tag(item)
    elif isinstance(raw_tags, dict):
        for key, value in raw_tags.items():
            if value in (True, "true", "True", 1, "1"):
                add_tag(key)
    elif isinstance(raw_tags, str):
        for part in parse_csv_list(raw_tags):
            add_tag(part)

    return tags


def _reisift_parse_owner_phones(owner):
    phones = []
    seen = set()
    if not isinstance(owner, dict):
        return phones
    for item in owner.get("phones") or []:
        number = ""
        p_type = "UNKNOWN"
        p_status = "UNKNOWN"
        if isinstance(item, dict):
            number = (item.get("number") or item.get("phone") or "").strip()
            p_type = (item.get("type") or "UNKNOWN").strip().upper()
            p_status = (item.get("status") or "UNKNOWN").strip().upper()
            raw_tags = item.get("tags")
        else:
            number = str(item or "").strip()
            raw_tags = []
        norm = normalize_phone(number)
        if not number or not norm or norm in seen:
            continue
        seen.add(norm)
        phones.append(
            {
                "number": norm,
                "type": p_type,
                "tags": _reisift_parse_phone_tags(raw_tags),
                "status": p_status,
            }
        )
    return phones


def _reisift_build_property_create_payload(address_info_payload, input_payload):
    input_payload = input_payload or {}
    source_address = _reisift_find_first_address_dict(address_info_payload)
    source_owner = _reisift_find_first_owner_dict(address_info_payload)
    source_owner_name = _reisift_parse_owner_name(source_owner)
    source_owner_emails = _reisift_parse_owner_emails(source_owner)
    source_owner_phones = _reisift_parse_owner_phones(source_owner)

    override_owner = input_payload.get("owner") if isinstance(input_payload.get("owner"), dict) else {}
    first_name = (override_owner.get("first_name") or source_owner_name["first_name"] or "").strip() or "Unknown"
    last_name = (override_owner.get("last_name") or source_owner_name["last_name"] or "").strip() or "Owner"
    company = override_owner.get("company")

    override_emails = override_owner.get("emails")
    if isinstance(override_emails, list) and override_emails:
        emails = [str(x).strip() for x in override_emails if str(x).strip()]
    else:
        emails = source_owner_emails

    override_phones = override_owner.get("phones")
    if isinstance(override_phones, list) and override_phones:
        normalized = []
        seen = set()
        for p in override_phones:
            if isinstance(p, dict):
                num = normalize_phone(p.get("number") or p.get("phone") or "")
                p_type = (p.get("type") or "UNKNOWN").strip().upper()
                p_status = (p.get("status") or "UNKNOWN").strip().upper()
            else:
                num = normalize_phone(str(p or ""))
                p_type = "UNKNOWN"
                p_status = "UNKNOWN"
            if not num or num in seen:
                continue
            seen.add(num)
            normalized.append({"number": num, "type": p_type, "tags": [], "status": p_status})
        phones = normalized
    else:
        phones = source_owner_phones

    owner_address = {
        "street": (override_owner.get("address_street") or source_address["street"] or "").strip(),
        "city": (override_owner.get("address_city") or source_address["city"] or "").strip(),
        "state": (override_owner.get("address_state") or source_address["state"] or "").strip(),
        "postal_code": (override_owner.get("address_postal_code") or source_address["postal_code"] or "").strip(),
    }

    property_address = {
        "street": (input_payload.get("street") or source_address["street"] or "").strip(),
        "city": (input_payload.get("city") or source_address["city"] or "").strip(),
        "state": (input_payload.get("state") or source_address["state"] or "").strip(),
        "postal_code": (input_payload.get("postal_code") or source_address["postal_code"] or "").strip(),
    }

    if not property_address["street"] or not property_address["city"]:
        raise ValueError("ReiSift address-info did not return a valid property address.")

    lists = parse_csv_list(input_payload.get("lists"))
    tags = parse_csv_list(input_payload.get("tags"))
    status = _reisift_create_status_value(input_payload.get("status") or input_payload.get("reisift_status"), default="new_lead")
    notes = (input_payload.get("notes") or "").strip()

    owner_payload = {
        "first_name": first_name,
        "last_name": last_name,
        "company": company if company else None,
        "address": owner_address,
        "emails": emails,
        "emails_info": {e: {"verified": False} for e in emails},
        "primary_email": None,
        "phones": phones,
        "primary_phone": None,
    }
    return {
        "address": property_address,
        "status": status,
        "lists": lists,
        "tags": tags,
        "notes": notes,
        "owner": owner_payload,
    }


US_STATE_CODE_MAP = {
    "alabama": "AL", "alaska": "AK", "arizona": "AZ", "arkansas": "AR", "california": "CA",
    "colorado": "CO", "connecticut": "CT", "delaware": "DE", "florida": "FL", "georgia": "GA",
    "hawaii": "HI", "idaho": "ID", "illinois": "IL", "indiana": "IN", "iowa": "IA",
    "kansas": "KS", "kentucky": "KY", "louisiana": "LA", "maine": "ME", "maryland": "MD",
    "massachusetts": "MA", "michigan": "MI", "minnesota": "MN", "mississippi": "MS", "missouri": "MO",
    "montana": "MT", "nebraska": "NE", "nevada": "NV", "new hampshire": "NH", "new jersey": "NJ",
    "new mexico": "NM", "new york": "NY", "north carolina": "NC", "north dakota": "ND", "ohio": "OH",
    "oklahoma": "OK", "oregon": "OR", "pennsylvania": "PA", "rhode island": "RI", "south carolina": "SC",
    "south dakota": "SD", "tennessee": "TN", "texas": "TX", "utah": "UT", "vermont": "VT",
    "virginia": "VA", "washington": "WA", "west virginia": "WV", "wisconsin": "WI", "wyoming": "WY",
    "district of columbia": "DC",
}
US_STATE_NAME_BY_CODE = {code: name.title() for name, code in US_STATE_CODE_MAP.items()}


def _normalize_state_code(value):
    raw = re.sub(r"[,\s]+", " ", str(value or "")).strip()
    if not raw:
        return ""
    if re.fullmatch(r"[A-Za-z]{2}", raw):
        return raw.upper()
    lowered = raw.lower().replace(".", "").strip()
    if lowered in US_STATE_CODE_MAP:
        return US_STATE_CODE_MAP[lowered]
    compact = re.sub(r"[^a-z]", "", lowered)
    for state_name, code in US_STATE_CODE_MAP.items():
        if compact == re.sub(r"[^a-z]", "", state_name):
            return code
    letters = re.sub(r"[^A-Za-z]", "", raw)
    if len(letters) >= 2:
        return letters[:2].upper()
    return raw[:2].upper()


def _normalize_postal_code(value):
    raw = str(value or "").strip()
    if not raw:
        return ""
    match = re.search(r"\b(\d{5})(?:-(\d{4}))?\b", raw)
    if match:
        return f"{match.group(1)}-{match.group(2)}" if match.group(2) else match.group(1)
    digits = re.sub(r"\D", "", raw)
    if len(digits) == 9:
        return f"{digits[:5]}-{digits[5:]}"
    if len(digits) >= 5:
        return digits[:5]
    return raw


def _normalize_city_value(value, state_code=""):
    city = re.sub(r"[,\s]+", " ", str(value or "")).strip(" ,")
    if not city:
        return ""
    if state_code:
        city = re.sub(rf"(?i)\b{re.escape(state_code)}\b\s*$", "", city).strip(" ,")
        full_state = US_STATE_NAME_BY_CODE.get(state_code.upper(), "")
        if full_state:
            city = re.sub(rf"(?i)\b{re.escape(full_state)}\b\s*$", "", city).strip(" ,")
    for state_name, code in US_STATE_CODE_MAP.items():
        city = re.sub(rf"(?i)\b{re.escape(state_name.title())}\b\s*$", "", city).strip(" ,")
        city = re.sub(rf"(?i)\b{re.escape(code)}\b\s*$", "", city).strip(" ,")
    return re.sub(r"\s{2,}", " ", city).strip(" ,")


def _normalize_street_value(value):
    street = re.sub(r"[,\s]+", " ", str(value or "")).strip(" ,")
    if not street:
        return ""
    street = re.sub(
        r"(?i)^\s*(\d+[A-Za-z]?)\s+(?:to|through|thru)\s+(\d+[A-Za-z]?)(\s+)",
        r"\1-\2\3",
        street,
    )
    return street.strip(" ,")


def _strip_city_state_suffix_from_street(street, city="", state_code=""):
    street_text = _normalize_street_value(street)
    if not street_text:
        return ""
    if city:
        escaped_city = re.escape(city)
        state_variants = []
        if state_code:
            state_variants.append(re.escape(state_code))
            full_state = US_STATE_NAME_BY_CODE.get(state_code.upper(), "")
            if full_state:
                state_variants.append(re.escape(full_state))
        state_part = rf"(?:[\s,]+(?:{'|'.join(state_variants)}))?" if state_variants else ""
        street_text = re.sub(
            rf"(?i)[\s,]+{escaped_city}{state_part}\s*$",
            "",
            street_text,
        ).strip(" ,")
    if state_code:
        full_state = US_STATE_NAME_BY_CODE.get(state_code.upper(), "")
        if full_state:
            street_text = re.sub(rf"(?i)[\s,]+{re.escape(full_state)}\s*$", "", street_text).strip(" ,")
        street_text = re.sub(rf"(?i)[\s,]+{re.escape(state_code)}\s*$", "", street_text).strip(" ,")
    return street_text


def _normalize_address_components(street="", city="", state="", postal_code="", raw_address=""):
    state_code = _normalize_state_code(state)
    postal = _normalize_postal_code(postal_code)
    city_value = _normalize_city_value(city, state_code=state_code)
    street_value = _normalize_street_value(street)
    if raw_address and (not street_value or not city_value):
        parsed = _parse_search_address_simple(raw_address)
        street_value = street_value or (parsed.get("street") or "")
        city_value = city_value or (parsed.get("city") or "")
        state_code = state_code or (parsed.get("state") or "")
        postal = postal or (parsed.get("postal_code") or "")
    city_value = _normalize_city_value(city_value, state_code=state_code)
    street_value = _strip_city_state_suffix_from_street(street_value, city=city_value, state_code=state_code)
    full_address = ", ".join([part for part in [street_value, city_value, state_code, postal] if part]).strip(", ")
    return {
        "street": street_value,
        "city": city_value,
        "state": state_code,
        "postal_code": postal,
        "address": full_address,
    }


def _parse_search_address_simple(search):
    text = (search or "").strip()
    text = re.sub(r"\s*,\s*(?:United States|USA|US)\s*$", "", text, flags=re.IGNORECASE)
    text = re.sub(r"\s+", " ", text).strip()
    # Clever lead format can include: "7 Jessica Lane in Dover, NJ 07801"
    text = re.sub(
        r"^(.*?)\s+in\s+([^,]+,\s*(?:[A-Za-z]{2}|[A-Za-z ]+)\s+\d{5}(?:-\d{4})?)$",
        r"\1, \2",
        text,
        flags=re.IGNORECASE,
    )
    street = city = state = postal_code = ""

    m = re.match(r"^(.*?),\s*([^,]+),\s*([A-Za-z]{2}|[A-Za-z ]+),?\s+(\d{5}(?:-\d{4})?)\s*$", text)
    if m:
        street, city, state, postal_code = m.group(1).strip(), m.group(2).strip(), m.group(3).strip(), m.group(4).strip()
    else:
        m2 = re.match(
            r"^(.*?\b(?:st|street|ave|avenue|rd|road|dr|drive|ln|lane|blvd|boulevard|ct|court|pl|place|way|pkwy|parkway|cir|circle|trl|trail|ter|terrace|hwy|highway)\b)\s+([^,]+),?\s+([A-Za-z]{2})\s+(\d{5}(?:-\d{4})?)\s*$",
            text,
            flags=re.IGNORECASE,
        )
        if m2:
            street, city, state, postal_code = m2.group(1).strip(), m2.group(2).strip(), m2.group(3).strip(), m2.group(4).strip()
    if (not street or not city) and text:
        # Heuristic fallback for step-1 style addresses such as:
        # "59 Mayfair Dr West Orange NJ 07052"
        raw_tokens = [t for t in re.split(r"\s+", text) if t]
        tokens = [re.sub(r"[^\w#-]", "", t) for t in raw_tokens]
        if len(tokens) >= 4:
            zip_candidate = tokens[-1]
            state_candidate = tokens[-2].upper()
            has_zip = bool(re.fullmatch(r"\d{5}(?:-\d{4})?", zip_candidate))
            has_state = bool(re.fullmatch(r"[A-Z]{2}", state_candidate))
            if has_zip and has_state:
                postal_code = zip_candidate
                state = state_candidate
                body = tokens[:-2]
                if body:
                    street_suffixes = {
                        "st", "street", "ave", "avenue", "rd", "road", "dr", "drive", "ln", "lane",
                        "blvd", "boulevard", "ct", "court", "pl", "place", "way", "pkwy", "parkway",
                        "cir", "circle", "trl", "trail", "ter", "terrace", "hwy", "highway",
                    }
                    best = None
                    best_score = -10**9
                    for i in range(1, len(body)):
                        street_tokens = body[:i]
                        city_tokens = body[i:]
                        score = 0
                        if not street_tokens or not city_tokens:
                            continue
                        if re.fullmatch(r"\d+[A-Za-z]?", street_tokens[0]):
                            score += 4
                        if any(t.lower() in street_suffixes for t in street_tokens):
                            score += 5
                        if 2 <= len(street_tokens) <= 8:
                            score += 2
                        if 1 <= len(city_tokens) <= 4:
                            score += 3
                        if all(re.fullmatch(r"[A-Za-z'.-]+", c) for c in city_tokens):
                            score += 1
                        if score > best_score:
                            best_score = score
                            best = (street_tokens, city_tokens)
                    if best:
                        street = " ".join(best[0]).strip()
                        city = " ".join(best[1]).strip()
    normalized = _normalize_address_components(street=street, city=city, state=state, postal_code=postal_code)
    return {
        "street": normalized["street"],
        "city": normalized["city"],
        "state": normalized["state"],
        "postal_code": normalized["postal_code"],
    }


def _reisift_build_property_create_payload_from_input(input_payload):
    input_payload = input_payload or {}
    search = (input_payload.get("search") or input_payload.get("address_search") or "").strip()
    parsed = _parse_search_address_simple(search)
    property_address = _normalize_address_components(
        street=(input_payload.get("street") or parsed["street"] or "").strip(),
        city=(input_payload.get("city") or parsed["city"] or "").strip(),
        state=(input_payload.get("state") or parsed["state"] or "").strip(),
        postal_code=(input_payload.get("postal_code") or parsed["postal_code"] or "").strip(),
        raw_address=search,
    )
    if not property_address["street"] or not property_address["city"]:
        raise ValueError("Could not parse property address without map lookup.")

    override_owner = input_payload.get("owner") if isinstance(input_payload.get("owner"), dict) else {}
    owner_name = _reisift_parse_owner_name(override_owner)
    first_name = (override_owner.get("first_name") or owner_name["first_name"] or "").strip() or "Unknown"
    last_name = (override_owner.get("last_name") or owner_name["last_name"] or "").strip() or "Owner"
    emails = _reisift_parse_owner_emails(override_owner)
    phones = _reisift_parse_owner_phones(override_owner)
    owner_address = _normalize_address_components(
        street=(override_owner.get("address_street") or property_address["street"]).strip(),
        city=(override_owner.get("address_city") or property_address["city"]).strip(),
        state=(override_owner.get("address_state") or property_address["state"]).strip(),
        postal_code=(override_owner.get("address_postal_code") or property_address["postal_code"]).strip(),
    )
    lists = parse_csv_list(input_payload.get("lists"))
    tags = parse_csv_list(input_payload.get("tags"))
    notes = (input_payload.get("notes") or "").strip()
    return {
        "address": {
            "street": property_address["street"],
            "city": property_address["city"],
            "state": property_address["state"],
            "postal_code": property_address["postal_code"],
        },
        "status": _reisift_create_status_value(input_payload.get("status") or input_payload.get("reisift_status"), default="new_lead"),
        "lists": lists,
        "tags": tags,
        "notes": notes,
        "owner": {
            "first_name": first_name,
            "last_name": last_name,
            "company": override_owner.get("company"),
            "address": {
                "street": owner_address["street"],
                "city": owner_address["city"],
                "state": owner_address["state"],
                "postal_code": owner_address["postal_code"],
            },
            "emails": emails,
            "emails_info": {e: {"verified": False} for e in emails},
            "primary_email": None,
            "phones": phones,
            "primary_phone": None,
        },
    }


def reisift_enrich_property_uuid(token, property_uuid):
    property_uuid = str(property_uuid or "").strip()
    if not property_uuid:
        raise ValueError("property_uuid is required for enrich.")
    enrich_payload = {
        "query": {
            "must": {
                "properties": [property_uuid],
            },
        },
        "enrich_property": True,
        "enrich_owner": True,
        "replace_owner": False,
    }
    response = requests.post(
        f"{REISIFT_BASE_URL}/api/internal/property/enrich/",
        headers=reisift_auth_headers(token),
        json=enrich_payload,
        timeout=45,
    )
    try:
        body = response.json()
    except ValueError:
        body = {"raw_text": response.text}
    if not response.ok:
        raise ValueError(f"ReiSift enrich failed ({response.status_code}): {body}")
    return {"request": enrich_payload, "response": body}


def reisift_update_property_status(token, property_uuid, status_slug):
    property_uuid = str(property_uuid or "").strip()
    status_slug = str(status_slug or "").strip()
    if not property_uuid:
        raise ValueError("property_uuid is required for status update.")
    if not status_slug:
        raise ValueError("status_slug is required for status update.")
    attempted_statuses = []
    candidates = []
    for candidate in [
        status_slug,
        _normalize_reisift_status(status_slug),
        _reisift_status_slug(status_slug, default=status_slug),
        _reisift_status_label(status_slug, default="New Lead"),
    ]:
        value = str(candidate or "").strip()
        if value and value not in candidates:
            candidates.append(value)

    last_error = None
    for candidate in candidates:
        response = requests.post(
            f"{REISIFT_BASE_URL}/api/internal/property/{property_uuid}/status/",
            headers=reisift_auth_headers(token),
            json={"status": candidate},
            timeout=30,
        )
        try:
            body = response.json()
        except ValueError:
            body = {"raw_text": response.text}
        attempted_statuses.append({"status": candidate, "status_code": response.status_code})
        if response.ok:
            return {
                "request": {"status": candidate},
                "response": body,
                "attempted_statuses": attempted_statuses,
            }
        last_error = (response.status_code, body)
        status_errors = body.get("status") if isinstance(body, dict) else None
        invalid_choice = isinstance(status_errors, list) and any(
            "not a valid status choice" in str(item or "").lower() for item in status_errors
        )
        if not invalid_choice:
            raise ValueError(f"ReiSift status update failed ({response.status_code}): {body}")

    if last_error is None:
        raise ValueError("ReiSift status update failed: no status candidates were attempted.")
    raise ValueError(
        f"ReiSift status update failed after trying {candidates} ({last_error[0]}): {last_error[1]}"
    )


def reisift_upsert_owner_contacts(token, owner_uuid, phones, emails):
    owner_uuid = str(owner_uuid or "").strip()
    if not owner_uuid:
        return {"ok": False, "error": "owner_uuid missing"}
    out = {"ok": True, "owner_uuid": owner_uuid, "phones": None, "emails": None}
    normalized_phones = []
    seen_phones = set()
    for p in phones or []:
        if isinstance(p, dict):
            number = normalize_phone(p.get("number") or p.get("phone") or "")
            p_type = (p.get("type") or "UNKNOWN").strip().upper()
            raw_tags = p.get("tags") if isinstance(p.get("tags"), list) else []
        else:
            number = normalize_phone(str(p or ""))
            p_type = "UNKNOWN"
            raw_tags = []
        if not number or number in seen_phones:
            continue
        seen_phones.add(number)
        tags = []
        seen_tags = set()
        for t in raw_tags:
            tag = str(t or "").strip()
            low = tag.lower()
            if not tag or low in seen_tags:
                continue
            seen_tags.add(low)
            tags.append(tag)
        normalized_phones.append({"type": p_type or "UNKNOWN", "tags": tags, "number": number})

    normalized_emails = []
    seen_emails = set()
    for e in emails or []:
        val = str(e or "").strip().lower()
        if not val or val in seen_emails:
            continue
        seen_emails.add(val)
        normalized_emails.append(val)

    if normalized_phones:
        phone_payload = {"phones": normalized_phones}
        phone_res = requests.post(
            f"{REISIFT_BASE_URL}/api/internal/owner/{owner_uuid}/upsert-phones/",
            headers=reisift_auth_headers(token),
            json=phone_payload,
            timeout=30,
        )
        try:
            phone_body = phone_res.json()
        except ValueError:
            phone_body = {"raw_text": phone_res.text}
        if not phone_res.ok:
            raise ValueError(f"ReiSift owner phone upsert failed ({phone_res.status_code}): {phone_body}")
        out["phones"] = {"request": phone_payload, "response": phone_body}

    if normalized_emails:
        email_payload = {"emails": normalized_emails}
        email_res = requests.post(
            f"{REISIFT_BASE_URL}/api/internal/owner/{owner_uuid}/upsert-emails/",
            headers=reisift_auth_headers(token),
            json=email_payload,
            timeout=30,
        )
        try:
            email_body = email_res.json()
        except ValueError:
            email_body = {"raw_text": email_res.text}
        if not email_res.ok:
            raise ValueError(f"ReiSift owner email upsert failed ({email_res.status_code}): {email_body}")
        out["emails"] = {"request": email_payload, "response": email_body}

    return out


def _reisift_phone_type_from_touchpoint(channel_label):
    label = str(channel_label or "").strip().lower()
    if label == "mobile":
        return "MOBILE"
    if label == "landline":
        return "LANDLINE"
    if label == "voip":
        return "VOIP"
    if label == "fax":
        return "FAX"
    return "UNKNOWN"


def _property_address_string(db, property_id):
    try:
        row = db.execute(
            """
            SELECT a.street, a.city, a.state, a.postal_code
            FROM properties p
            LEFT JOIN addresses a ON a.id = p.property_address_id
            WHERE p.id = ?
            LIMIT 1
            """,
            (int(property_id or 0),),
        ).fetchone()
    except Exception:
        return ""
    if not row:
        return ""
    return ", ".join(
        [
            str(row["street"] or "").strip(),
            str(row["city"] or "").strip(),
            str(row["state"] or "").strip(),
            str(row["postal_code"] or "").strip(),
        ]
    ).strip(", ").strip()


def collect_person_contact_items_for_reisift_sync(db, person_ids):
    clean_ids = _clean_person_ids(person_ids)
    if not clean_ids:
        return [], []

    phone_items = []
    email_items = []
    seen_phone = set()
    seen_email = set()
    placeholders = ",".join(["?"] * len(clean_ids))

    for row in _get_ranked_phone_touchpoints_for_people(db, clean_ids):
        value = str(row["value"] or "").strip()
        phone_norm = normalize_phone(value)
        if not phone_norm or phone_norm in seen_phone:
            continue
        seen_phone.add(phone_norm)
        phone_items.append(
            {
                "number": value,
                "type": _reisift_phone_type_from_touchpoint(row["channel_label"]),
                "tags": list(row.get("phone_tags") or []),
            }
        )

    people_rows = db.execute(
        f"""
        SELECT id, primary_phone, primary_email
        FROM people
        WHERE id IN ({placeholders})
        """,
        tuple(clean_ids),
    ).fetchall()
    for row in people_rows:
        primary_phone = str(row["primary_phone"] or "").strip()
        primary_email = str(row["primary_email"] or "").strip()
        phone_norm = normalize_phone(primary_phone)
        email_norm = primary_email.lower()
        if phone_norm and phone_norm not in seen_phone:
            seen_phone.add(phone_norm)
            phone_items.append({"number": primary_phone, "type": "UNKNOWN", "tags": []})
        if primary_email and email_norm not in seen_email:
            seen_email.add(email_norm)
            email_items.append(primary_email)

    tp_rows = db.execute(
        f"""
        SELECT channel_type, value
        FROM touchpoints
        WHERE person_id IN ({placeholders})
          AND lower(channel_type) = 'email'
        ORDER BY id ASC
        """,
        tuple(clean_ids),
    ).fetchall()
    for tp in tp_rows:
        value = str(tp["value"] or "").strip()
        if not value:
            continue
        email_norm = value.lower()
        if email_norm in seen_email:
            continue
        seen_email.add(email_norm)
        email_items.append(value)

    return phone_items, email_items


def sync_skiptrace_contacts_to_reisift_owner(db, property_id, phone_items=None, email_items=None):
    property_id = int(property_id or 0)
    phones_in = phone_items if isinstance(phone_items, list) else []
    emails_in = email_items if isinstance(email_items, list) else []
    out = {
        "ok": False,
        "property_id": property_id,
        "property_uuid": "",
        "owner_uuid": "",
        "phones_attempted": 0,
        "emails_attempted": 0,
        "error": "",
        "result": None,
        "tag_sync": None,
    }

    emails = []
    seen_email = set()
    for e in emails_in:
        if isinstance(e, dict):
            value = str(e.get("email") or e.get("value") or "").strip().lower()
        else:
            value = str(e or "").strip().lower()
        if not value or value in seen_email:
            continue
        seen_email.add(value)
        emails.append(value)

    if not phones_in and not emails:
        out["ok"] = True
        out["result"] = {"skipped": True, "reason": "no_contacts"}
        return out

    property_uuid = _get_local_property_uuid(db, property_id)
    owner_uuid = ""
    has_owner_col = _table_has_column(db, "properties", "reisift_owner_uuid")
    if has_owner_col:
        try:
            row = db.execute("SELECT reisift_owner_uuid FROM properties WHERE id = ? LIMIT 1", (property_id,)).fetchone()
            owner_uuid = normalize_uuid((row["reisift_owner_uuid"] if row else "") or "")
        except Exception:
            owner_uuid = ""
    out["property_uuid"] = normalize_uuid(property_uuid or "")

    try:
        token = reisift_get_access_token()
    except Exception as exc:
        out["error"] = str(exc)
        return out

    property_payload = {}
    existing_owner = {}
    existing_phones_by_number = {}
    existing_emails = set()
    if out["property_uuid"]:
        try:
            property_payload = fetch_reisift_property_payload(token, out["property_uuid"]) or {}
        except Exception as exc:
            out["error"] = f"Owner lookup failed before skiptrace sync: {exc}"
            return out
        existing_owner = _reisift_find_first_owner_dict(property_payload)
        for item in _reisift_parse_owner_phones(existing_owner):
            normalized = normalize_phone(item.get("number") or "")
            if not normalized:
                continue
            existing_phones_by_number[normalized] = item
        existing_emails = {
            str(value or "").strip().lower()
            for value in _reisift_parse_owner_emails(existing_owner)
            if str(value or "").strip()
        }

    if not owner_uuid and property_payload:
        owner_uuid = _reisift_find_owner_uuid(property_payload) or ""
        if owner_uuid and has_owner_col:
            try:
                db.execute(
                    """
                    UPDATE properties
                    SET reisift_owner_uuid = ?
                    WHERE id = ?
                      AND (reisift_owner_uuid IS NULL OR trim(reisift_owner_uuid) = '')
                    """,
                    (owner_uuid, property_id),
                )
            except Exception:
                pass
    out["owner_uuid"] = owner_uuid
    if not owner_uuid:
        out["error"] = "No ReiSift owner UUID available for skiptrace contact sync."
        return out

    phones = []
    seen_phone = set()
    for p in phones_in:
        if isinstance(p, dict):
            number = normalize_phone(p.get("number") or p.get("phone") or "")
            p_type = (p.get("type") or "UNKNOWN").strip().upper() or "UNKNOWN"
            raw_tags = p.get("tags") if isinstance(p.get("tags"), list) else []
        else:
            number = normalize_phone(str(p or ""))
            p_type = "UNKNOWN"
            raw_tags = []
        if not number or number in seen_phone:
            continue
        seen_phone.add(number)
        existing_phone = existing_phones_by_number.get(number) or {}
        if p_type == "UNKNOWN" and str(existing_phone.get("type") or "").strip():
            p_type = str(existing_phone.get("type") or "").strip().upper() or "UNKNOWN"
        merged_tags = []
        seen_tags = set()
        for tag_value in ["Relative", *(existing_phone.get("tags") or []), *raw_tags]:
            tag = str(tag_value or "").strip()
            key = tag.lower()
            if not tag or key in seen_tags:
                continue
            seen_tags.add(key)
            merged_tags.append(tag)
        phones.append({"number": number, "type": p_type, "tags": merged_tags})

    emails = [value for value in emails if str(value or "").strip().lower() not in existing_emails]
    out["phones_attempted"] = len(phones)
    out["emails_attempted"] = len(emails)
    if not phones and not emails:
        out["ok"] = True
        out["result"] = {"skipped": True, "reason": "no_new_contacts"}
        return out

    try:
        sync_result = reisift_upsert_owner_contacts(token, owner_uuid, phones, emails)
    except Exception as exc:
        out["error"] = str(exc)
        return out

    full_address = _property_address_string(db, property_id)
    for p in phones:
        linked_person = find_person_id_by_phone(db, p["number"])
        upsert_cached_contact_context(
            db,
            p["number"],
            property_id=property_id,
            person_id=linked_person,
            classification="potential_seller",
            source="skiptrace_sync",
            confidence=0.9,
            notes="Skiptrace contact synced to ReiSift owner as Relative.",
            reisift_property_uuid=out["property_uuid"],
            reisift_full_address=full_address,
            reisift_owner_name="",
            reisift_property_status="",
            last_reisift_lookup_at=format_db_time(datetime.utcnow()),
        )

    out["ok"] = bool(sync_result.get("ok"))
    out["result"] = sync_result
    if out["ok"] and phones and out["property_uuid"]:
        try:
            out["tag_sync"] = reisift_append_property_tags(
                token,
                out["property_uuid"],
                build_reisift_skiptrace_tags(),
            )
        except Exception as exc:
            out["tag_sync"] = {
                "ok": False,
                "property_uuid": out["property_uuid"],
                "error": str(exc),
            }
    return out


def create_reisift_property_from_search(input_payload):
    search = (input_payload.get("search") or input_payload.get("address_search") or "").strip()
    if not search:
        raise ValueError("search is required.")
    token = reisift_get_access_token()

    use_map_lookup = bool(input_payload.get("force_map_lookup")) or (
        not REISIFT_DISABLE_MAP_LOOKUP and not bool(input_payload.get("skip_map_lookup"))
    )
    map_id = None
    autocomplete_payload = {}
    address_info_payload = {}
    map_lookup_fallback_used = False
    map_lookup_fallback_reason = ""
    create_payload = None
    if use_map_lookup:
        try:
            autocomplete_body = {
                "search": search,
                "entity_types": input_payload.get("entity_types")
                or ["state", "county", "municipality", "address", "zip"],
            }
            autocomplete = requests.post(
                f"{REISIFT_MAP_BASE_URL}/properties/search-autocomplete/",
                headers=reisift_auth_headers(token),
                json=autocomplete_body,
                timeout=30,
            )
            autocomplete.raise_for_status()
            autocomplete_payload = autocomplete.json()
            map_id = _reisift_find_first_map_id(autocomplete_payload)
            if map_id:
                address_info_res = requests.post(
                    f"{REISIFT_BASE_URL}/api/internal/property/address-info-from-map-id/",
                    headers=reisift_auth_headers(token),
                    json={"map_id": map_id},
                    timeout=30,
                )
                address_info_res.raise_for_status()
                address_info_payload = address_info_res.json()
                create_payload = _reisift_build_property_create_payload(address_info_payload, input_payload)
            else:
                map_lookup_fallback_reason = "Could not resolve map_id from ReiSift map autocomplete response."
        except Exception as exc:
            map_lookup_fallback_reason = str(exc) or "ReiSift map lookup failed."

        if create_payload is None:
            create_payload = _reisift_build_property_create_payload_from_input(input_payload)
            map_lookup_fallback_used = True
    else:
        create_payload = _reisift_build_property_create_payload_from_input(input_payload)
    create_res = requests.post(
        f"{REISIFT_BASE_URL}/api/internal/property/",
        headers=reisift_auth_headers(token),
        json=create_payload,
        timeout=45,
    )
    create_body = {}
    try:
        create_body = create_res.json()
    except ValueError:
        create_body = {"raw_text": create_res.text}
    if not create_res.ok:
        if create_res.status_code == 400 and isinstance(create_body, dict):
            non_field_errors = create_body.get("non_field_errors")
            property_list = create_body.get("property")
            duplicate_reason = ""
            if isinstance(non_field_errors, list) and non_field_errors:
                duplicate_reason = str(non_field_errors[0] or "").strip()
            existing_uuid = ""
            if isinstance(property_list, list) and property_list:
                existing_uuid = str(property_list[0] or "").strip()
            if existing_uuid:
                return {
                    "search": search,
                    "map_id": map_id,
                    "map_lookup_fallback_used": map_lookup_fallback_used,
                    "map_lookup_fallback_reason": map_lookup_fallback_reason,
                    "create_payload": create_payload,
                    "created": create_body,
                    "created_uuid": existing_uuid,
                    "owner_uuid": "",
                    "owner_contact_sync": None,
                    "enrich_wait_seconds": 0,
                    "enrich": None,
                    "autocomplete": autocomplete_payload,
                    "address_info": address_info_payload,
                    "duplicate_existing": True,
                    "duplicate_reason": duplicate_reason or "Property address already exists!",
                    "create_status_code": create_res.status_code,
                }
        raise ValueError(f"ReiSift create failed ({create_res.status_code}): {create_body}")
    created_uuid = str(create_body.get("uuid") or create_body.get("id") or "").strip()
    owner_uuid = _reisift_find_owner_uuid(create_body)
    owner_payload = create_payload.get("owner") if isinstance(create_payload.get("owner"), dict) else {}
    owner_phones = _reisift_parse_owner_phones(owner_payload)
    owner_emails = _reisift_parse_owner_emails(owner_payload)
    owner_contact_sync = None
    if owner_uuid and (owner_phones or owner_emails):
        try:
            owner_contact_sync = reisift_upsert_owner_contacts(token, owner_uuid, owner_phones, owner_emails)
        except Exception as exc:
            owner_contact_sync = {"ok": False, "owner_uuid": owner_uuid, "error": str(exc)}

    # Wait 2-5 seconds before enrich to allow create propagation.
    enrich_result = None
    enrich_wait_seconds = random.randint(2, 5)
    if created_uuid:
        time.sleep(enrich_wait_seconds)
        try:
            enrich_result = reisift_enrich_property_uuid(token, created_uuid)
        except Exception as exc:
            enrich_result = {"ok": False, "error": str(exc)}

    return {
        "search": search,
        "map_id": map_id,
        "map_lookup_fallback_used": map_lookup_fallback_used,
        "map_lookup_fallback_reason": map_lookup_fallback_reason,
        "create_payload": create_payload,
        "created": create_body,
        "created_uuid": created_uuid,
        "owner_uuid": owner_uuid,
        "owner_contact_sync": owner_contact_sync,
        "enrich_wait_seconds": enrich_wait_seconds if created_uuid else 0,
        "enrich": enrich_result,
        "autocomplete": autocomplete_payload,
        "address_info": address_info_payload,
    }


def fetch_reisift_referrals():
    status_slug = os.getenv("REISIFT_REFERRAL_STATUS", "refer_lead").strip() or "refer_lead"
    token = reisift_get_access_token()
    rows, total = reisift_search_referral_rows(token, status_slug)

    results = []
    for row in rows:
        address = row.get("address") or {}
        owners = row.get("owners") or []
        owner_names = []
        for owner in owners:
            full = (owner.get("full_name") or "").strip()
            if full:
                owner_names.append(full)
                continue
            first = (owner.get("first_name") or "").strip()
            last = (owner.get("last_name") or "").strip()
            combined = " ".join(x for x in [first, last] if x)
            if combined:
                owner_names.append(combined)
        full_address = (
            (address.get("full_address") or "").strip()
            or ", ".join(
                x
                for x in [
                    address.get("street"),
                    address.get("city"),
                    address.get("state"),
                    address.get("zip"),
                ]
                if x
            )
        )
        results.append(
            {
                "uuid": row.get("uuid"),
                "status": row.get("status"),
                "full_address": full_address,
                "owners": owner_names,
            }
        )
    return {"count": total or len(results), "status_slug": status_slug, "results": results}


def reisift_search_properties_by_phone(token, phone_raw, limit=10):
    phone_norm = normalize_phone(phone_raw)
    if not phone_norm:
        return []
    body = {
        "limit": max(1, min(50, int(limit or 10))),
        "offset": 0,
        "ordering": "-owner_updated",
        "query": {"must": {"search": phone_norm}},
    }
    response = requests.post(
        f"{REISIFT_BASE_URL}/api/internal/property/",
        headers=reisift_auth_headers(token, {"x-http-method-override": "GET"}),
        json=body,
        timeout=30,
    )
    response.raise_for_status()
    payload = response.json() if response.headers.get("content-type", "").lower().startswith("application/json") else {}
    rows = payload.get("results") if isinstance(payload, dict) else []
    out = []
    for row in rows or []:
        if not isinstance(row, dict):
            continue
        address = row.get("address") if isinstance(row.get("address"), dict) else {}
        full_address = (
            str(address.get("full_address") or "").strip()
            or ", ".join(
                [x for x in [address.get("street"), address.get("city"), address.get("state"), address.get("zip")] if x]
            ).strip()
        )
        owners = row.get("owners") if isinstance(row.get("owners"), list) else []
        owner_names = []
        for owner in owners:
            if not isinstance(owner, dict):
                continue
            full_name = (owner.get("full_name") or "").strip()
            if full_name:
                owner_names.append(full_name)
                continue
            candidate = " ".join([x for x in [(owner.get("first_name") or "").strip(), (owner.get("last_name") or "").strip()] if x]).strip()
            if candidate:
                owner_names.append(candidate)
        out.append(
            {
                "uuid": normalize_uuid(row.get("uuid") or ""),
                "status": str(row.get("status") or "").strip(),
                "full_address": full_address,
                "created_at": str(row.get("created") or "").strip(),
                "updated_at": str(row.get("updated") or row.get("owner_updated") or "").strip(),
                "owner_names": owner_names,
            }
        )
    return out


def reisift_search_referral_rows(token, status_slug):
    headers = {
        "Authorization": f"Bearer {token}",
        "Content-Type": "application/json",
        "x-reisift-ui-version": REISIFT_UI_VERSION,
        "x-http-method-override": "GET",
    }
    body = {
        "limit": 200,
        "offset": 0,
        "ordering": "-list_count",
        "query": {"must": {"any_property_status": [status_slug]}},
    }
    response = requests.post(
        f"{REISIFT_BASE_URL}/api/internal/property/",
        headers=headers,
        json=body,
        timeout=30,
    )
    response.raise_for_status()
    payload = response.json()
    rows = payload.get("results") or []
    return rows, int(payload.get("count") or len(rows))


def reisift_search_property_rows_by_status(token, status_slug, counties=None, max_rows=1000):
    status_slug = (status_slug or "").strip()
    if not status_slug:
        return [], 0
    headers = reisift_auth_headers(token, {"x-http-method-override": "GET"})
    max_rows = max(1, min(5000, int(max_rows or 1000)))
    county_values = [
        normalize_whitespace(county)
        for county in (counties or [])
        if normalize_whitespace(county)
    ]
    offset = 0
    rows = []
    total = 0
    while offset < max_rows:
        must_query = {}
        if county_values:
            must_query["any_county"] = county_values
        must_query["any_property_status"] = [status_slug]
        body = {
            "offset": offset,
            "ordering": "-list_count",
            "query": {"must": must_query},
        }
        response = requests.post(
            f"{REISIFT_BASE_URL}/api/internal/property/",
            headers=headers,
            json=body,
            timeout=30,
        )
        response.raise_for_status()
        payload = response.json()
        page_rows = payload.get("results") or []
        total = int(payload.get("count") or total or len(page_rows))
        if not page_rows:
            break
        dict_rows = [row for row in page_rows if isinstance(row, dict)]
        rows.extend(dict_rows)
        offset += len(page_rows)
        if total and offset >= total:
            break
        if not dict_rows:
            break
    return rows[:max_rows], total or len(rows)


def fetch_reisift_property_payload(token, property_uuid):
    headers = {
        "Authorization": f"Bearer {token}",
        "Content-Type": "application/json",
        "x-reisift-ui-version": REISIFT_UI_VERSION,
    }
    response = requests.get(
        f"{REISIFT_BASE_URL}/api/internal/property/{property_uuid}/",
        headers=headers,
        timeout=30,
    )
    response.raise_for_status()
    return response.json()


def fetch_reisift_property_log_rollup(token, property_uuid, max_rows=200):
    headers = {
        "Authorization": f"Bearer {token}",
        "Content-Type": "application/json",
        "x-reisift-ui-version": REISIFT_UI_VERSION,
    }
    offset = 0
    limit = 100
    inspected = 0
    outbound_calls = 0
    inbound_calls = 0
    outbound_sms = 0
    inbound_sms = 0
    outbound_email = 0
    inbound_email = 0
    seen_call_ids = set()
    seen_sms_ids = set()
    seen_email_ids = set()
    events = []
    tasks = []
    seen_task_ids = set()
    property_created_at = None

    while inspected < max_rows:
        response = requests.get(
            f"{REISIFT_BASE_URL}/api/internal/property/{property_uuid}/logs/?offset={offset}&limit={limit}",
            headers=headers,
            timeout=30,
        )
        response.raise_for_status()
        payload = response.json() if response.headers.get("content-type", "").lower().startswith("application/json") else {}
        results = payload.get("results") if isinstance(payload, dict) else []
        if not isinstance(results, list) or not results:
            break

        for item in results:
            if not isinstance(item, dict):
                continue
            event_type = (item.get("event_type") or "").strip().lower()
            if not event_type:
                continue
            if event_type == "property.created" and not property_created_at:
                property_created_at = item.get("timestamp")
            if len(events) < 50:
                events.append(
                    {
                        "event_type": item.get("event_type"),
                        "timestamp": item.get("timestamp"),
                        "source": item.get("source"),
                        "title": (item.get("payload") or {}).get("task", {}).get("title") if isinstance(item.get("payload"), dict) else "",
                    }
                )
            if event_type.startswith("task."):
                payload = item.get("payload") if isinstance(item.get("payload"), dict) else {}
                task = payload.get("task") if isinstance(payload.get("task"), dict) else {}
                task_uuid = (task.get("uuid") or "").strip() or f"evt:{item.get('timestamp')}:{event_type}"
                if task_uuid not in seen_task_ids:
                    seen_task_ids.add(task_uuid)
                    created_by = task.get("created_by") if isinstance(task.get("created_by"), dict) else {}
                    creator_name = " ".join(
                        x
                        for x in [
                            (created_by.get("first_name") or "").strip(),
                            (created_by.get("last_name") or "").strip(),
                        ]
                        if x
                    )
                    if not creator_name:
                        author_extra = item.get("author_extra_info") if isinstance(item.get("author_extra_info"), dict) else {}
                        creator_name = " ".join(
                            x
                            for x in [
                                (author_extra.get("first_name") or "").strip(),
                                (author_extra.get("last_name") or "").strip(),
                            ]
                            if x
                        ) or (item.get("author") or "")
                    tasks.append(
                        {
                            "event_type": "task",
                            "title": (task.get("title") or "").strip() or "-",
                            "due_date": task.get("due_date"),
                            "created_by_name": creator_name or "-",
                        }
                    )
            payload = item.get("payload") if isinstance(item.get("payload"), dict) else {}

            if event_type.startswith("owner.call."):
                call = payload.get("call") if isinstance(payload.get("call"), dict) else {}
                call_id = (call.get("uuid") or "").strip() or f"evt:{item.get('timestamp')}:{event_type}"
                if call_id in seen_call_ids:
                    continue
                direction = (call.get("direction") or "").strip().lower()
                if not direction:
                    if event_type.endswith(".incoming") or event_type.endswith(".received"):
                        direction = "inbound"
                    else:
                        direction = "outbound"
                seen_call_ids.add(call_id)
                if direction == "inbound":
                    inbound_calls += 1
                else:
                    outbound_calls += 1
                continue

            if event_type.startswith("owner.sms."):
                sms = payload.get("sms") if isinstance(payload.get("sms"), dict) else {}
                sms_id = (sms.get("uuid") or "").strip() or f"evt:{item.get('timestamp')}:{event_type}"
                if sms_id in seen_sms_ids:
                    continue
                direction = (sms.get("direction") or "").strip().lower()
                if not direction:
                    if event_type.endswith(".received") or event_type.endswith(".replied"):
                        direction = "inbound"
                    else:
                        direction = "outbound"
                seen_sms_ids.add(sms_id)
                if direction == "inbound":
                    inbound_sms += 1
                else:
                    outbound_sms += 1
                continue

            if event_type.startswith("owner.email."):
                email = payload.get("email") if isinstance(payload.get("email"), dict) else {}
                email_id = (email.get("uuid") or "").strip() or f"evt:{item.get('timestamp')}:{event_type}"
                if email_id in seen_email_ids:
                    continue
                direction = (email.get("direction") or "").strip().lower()
                if not direction:
                    if event_type.endswith(".received") or event_type.endswith(".replied"):
                        direction = "inbound"
                    else:
                        direction = "outbound"
                seen_email_ids.add(email_id)
                if direction == "inbound":
                    inbound_email += 1
                else:
                    outbound_email += 1

        inspected += len(results)
        if len(results) < limit:
            break
        offset += limit

    return {
        "outbound_calls": outbound_calls,
        "outbound_sms": outbound_sms,
        "outbound_email": outbound_email,
        "inbound_calls": inbound_calls,
        "inbound_sms": inbound_sms,
        "inbound_email": inbound_email,
        "inbound_responses": inbound_calls + inbound_sms + inbound_email,
        "property_created_at": property_created_at,
        "events": events,
        "tasks": tasks,
    }


def extract_reisift_property_address(payload):
    payload = payload if isinstance(payload, dict) else {}
    address = payload.get("address") if isinstance(payload.get("address"), dict) else {}
    property_obj = payload.get("property") if isinstance(payload.get("property"), dict) else {}
    property_address = property_obj.get("address") if isinstance(property_obj.get("address"), dict) else {}
    candidates = [
        {
            "full_address": address.get("full_address"),
            "street": address.get("street") or address.get("address") or address.get("line1"),
            "city": address.get("city"),
            "state": address.get("state"),
            "postal_code": address.get("postal_code") or address.get("zip") or address.get("zipcode"),
        },
        {
            "full_address": property_address.get("full_address"),
            "street": property_address.get("street") or property_address.get("address") or property_address.get("line1"),
            "city": property_address.get("city"),
            "state": property_address.get("state"),
            "postal_code": property_address.get("postal_code") or property_address.get("zip") or property_address.get("zipcode"),
        },
        {
            "full_address": property_obj.get("full_address") or property_obj.get("property_full_address"),
            "street": property_obj.get("street") or property_obj.get("property_address") or property_obj.get("address_line_1"),
            "city": property_obj.get("city") or property_obj.get("property_city"),
            "state": property_obj.get("state") or property_obj.get("property_state"),
            "postal_code": property_obj.get("postal_code") or property_obj.get("zip") or property_obj.get("property_zip"),
        },
        {
            "full_address": payload.get("full_address") or payload.get("property_full_address"),
            "street": payload.get("street") or payload.get("property_address") or payload.get("address_line_1"),
            "city": payload.get("city") or payload.get("property_city"),
            "state": payload.get("state") or payload.get("property_state"),
            "postal_code": payload.get("postal_code") or payload.get("zip") or payload.get("property_zip"),
        },
    ]
    for candidate in candidates:
        full_address = normalize_whitespace(candidate.get("full_address") or "")
        street = normalize_whitespace(candidate.get("street") or "")
        city = normalize_whitespace(candidate.get("city") or "")
        state = normalize_state_code(candidate.get("state") or "")
        postal_code = normalize_postal_code(candidate.get("postal_code") or "")
        if full_address or street or city:
            return {
                "full_address": full_address,
                "street": street,
                "city": city,
                "state": state,
                "postal_code": postal_code,
            }
    return {"full_address": "", "street": "", "city": "", "state": "", "postal_code": ""}


def summarize_reisift_property(payload, fallback_payload=None):
    payload = payload if isinstance(payload, dict) else {}
    fallback_payload = fallback_payload if isinstance(fallback_payload, dict) else {}
    address = extract_reisift_property_address(payload)
    fallback_address = extract_reisift_property_address(fallback_payload)
    full_address = (
        address.get("full_address")
        or format_property_address_line(
            address.get("street"),
            address.get("city"),
            address.get("state"),
            address.get("postal_code"),
        )
        or fallback_address.get("full_address")
        or format_property_address_line(
            fallback_address.get("street"),
            fallback_address.get("city"),
            fallback_address.get("state"),
            fallback_address.get("postal_code"),
        )
    )
    owner_names = []
    for source_payload in [payload, fallback_payload]:
        owner = source_payload.get("owner") or {}
        if owner:
            owner_full = " ".join(
                x for x in [(owner.get("first_name") or "").strip(), (owner.get("last_name") or "").strip()] if x
            )
            if owner_full:
                owner_names.append(owner_full)
        for o in source_payload.get("owners") or []:
            if not isinstance(o, dict):
                continue
            full = (o.get("full_name") or "").strip()
            if full:
                owner_names.append(full)
                continue
            combined = " ".join(
                x for x in [(o.get("first_name") or "").strip(), (o.get("last_name") or "").strip()] if x
            )
            if combined:
                owner_names.append(combined)
    return {
        "status": payload.get("status") or fallback_payload.get("status"),
        "full_address": full_address,
        "owner_names": ", ".join(dict.fromkeys(owner_names)),
    }


def infer_county_from_reisift_payload(payload):
    if not isinstance(payload, dict):
        return ""
    address = payload.get("address") if isinstance(payload.get("address"), dict) else {}
    county = (address.get("county") or address.get("county_name") or "").strip()
    if county:
        return county
    property_obj = payload.get("property") if isinstance(payload.get("property"), dict) else {}
    property_address = property_obj.get("address") if isinstance(property_obj.get("address"), dict) else {}
    county = (
        property_address.get("county")
        or property_address.get("county_name")
        or property_obj.get("county")
        or property_obj.get("county_name")
        or ""
    ).strip()
    if county:
        return county
    metadata = payload.get("metadata") if isinstance(payload.get("metadata"), dict) else {}
    county = (metadata.get("county") or metadata.get("county_name") or "").strip()
    if county:
        return county
    return ""


def infer_on_market_status_from_payload(payload):
    if not isinstance(payload, dict):
        return "Unknown"
    for key in ("listed_on_market", "listedOnMarket", "on_market", "onMarket"):
        val = payload.get(key)
        if isinstance(val, bool):
            return "On Market" if val else "Off Market"
        if isinstance(val, str) and val.strip():
            text = val.strip().lower()
            if text in {"yes", "true", "listed", "on market", "active"}:
                return "On Market"
            if text in {"no", "false", "off market", "not listed"}:
                return "Off Market"
    notes = str(payload.get("notes") or "")
    if "Listed On Market: Yes" in notes:
        return "On Market"
    if "Listed On Market: No" in notes:
        return "Off Market"
    return "Unknown"


def _build_rentcast_listing_snapshot(listing):
    item = listing if isinstance(listing, dict) else {}
    history = item.get("history") if isinstance(item.get("history"), dict) else {}
    latest_history = None
    if history:
        try:
            latest_key = sorted(history.keys())[-1]
            latest_history = history.get(latest_key) if isinstance(history.get(latest_key), dict) else None
        except Exception:
            latest_history = None
    return {
        "id": str(item.get("id") or "").strip(),
        "formattedAddress": str(item.get("formattedAddress") or "").strip(),
        "status": str(item.get("status") or "").strip(),
        "price": item.get("price"),
        "daysOnMarket": item.get("daysOnMarket") or (latest_history or {}).get("daysOnMarket"),
        "listedDate": item.get("listedDate") or item.get("listDate") or (latest_history or {}).get("listedDate"),
        "removedDate": item.get("removedDate") or (latest_history or {}).get("removedDate"),
        "listingAgent": item.get("listingAgent") if isinstance(item.get("listingAgent"), dict) else {},
        "listingOffice": item.get("listingOffice") if isinstance(item.get("listingOffice"), dict) else {},
    }


def _rentcast_listing_matches_address(full_address, listing):
    target_variants = {
        normalize_address_match_text(v)
        for v in _normalize_listing_address_variants(full_address)
        if normalize_address_match_text(v)
    }
    if not target_variants:
        return False
    item = listing if isinstance(listing, dict) else {}
    candidates = [
        str(item.get("formattedAddress") or "").strip(),
        format_property_address_line(
            item.get("addressLine1"),
            item.get("city"),
            item.get("state"),
            item.get("zipCode"),
        ),
    ]
    for candidate in candidates:
        normalized = normalize_address_match_text(candidate)
        if normalized and normalized in target_variants:
            return True
    return False


def infer_on_market_status_from_rentcast(db, full_address, previous_lookup=None):
    checked_at = format_db_time(datetime.utcnow())
    address = normalize_whitespace(full_address)
    prior = previous_lookup if isinstance(previous_lookup, dict) else {}
    previous_address = normalize_whitespace(prior.get("address") or "")
    previous_checked_at = parse_db_time(prior.get("checked_at") or "")
    if (
        previous_address
        and previous_address == address
        and previous_checked_at is not None
        and (datetime.utcnow() - previous_checked_at) < timedelta(hours=RENTCAST_MARKET_STATUS_CACHE_HOURS)
    ):
        cached_lookup = dict(prior)
        cached_lookup["cached"] = True
        return cached_lookup

    api_key = get_rentcast_api_key(db)
    if not api_key or not address:
        return {
            "status": "Unknown",
            "address": address,
            "checked_at": checked_at,
            "cached": False,
            "skipped": "missing_api_key_or_address",
            "matched_listings": [],
            "primary_listing": {},
            "evidence": [],
        }

    response = None
    response_body = None
    try:
        response = requests.get(
            f"{RENTCAST_BASE_URL}/listings/sale",
            headers={
                "Accept": "application/json",
                "X-Api-Key": api_key,
            },
            params={
                "address": address,
                "limit": 10,
            },
            timeout=30,
        )
        try:
            response_body = response.json() if response.content else []
        except ValueError:
            response_body = {"raw_text": response.text}
        if not response.ok:
            log_app_error(
                db,
                source="rentcast_market_status",
                error_message=f"RentCast sale listings failed ({response.status_code}).",
                details=response_body,
                route="infer_on_market_status_from_rentcast",
                status_code=response.status_code,
            )
            return {
                "status": "Unknown",
                "address": address,
                "checked_at": checked_at,
                "cached": False,
                "http_status": response.status_code,
                "error": f"RentCast sale listings failed ({response.status_code})",
                "matched_listings": [],
                "primary_listing": {},
                "evidence": [],
            }
    except Exception as exc:
        return {
            "status": "Unknown",
            "address": address,
            "checked_at": checked_at,
            "cached": False,
            "error": str(exc),
            "matched_listings": [],
            "primary_listing": {},
            "evidence": [],
        }

    listings = response_body if isinstance(response_body, list) else []
    matched = [item for item in listings if _rentcast_listing_matches_address(address, item)]
    snapshots = [_build_rentcast_listing_snapshot(item) for item in matched[:5]]
    primary_listing = snapshots[0] if snapshots else {}
    resolved_status = "Unknown"
    if any(str(item.get("status") or "").strip().lower() == "active" for item in snapshots):
        resolved_status = "On Market"
        for item in snapshots:
            if str(item.get("status") or "").strip().lower() == "active":
                primary_listing = item
                break
    elif snapshots:
        resolved_status = "Off Market"

    evidence = []
    for item in snapshots[:3]:
        evidence.append(
            {
                "source": "rentcast_sale_listing",
                "listing_id": item.get("id"),
                "formatted_address": item.get("formattedAddress"),
                "status": item.get("status"),
                "days_on_market": item.get("daysOnMarket"),
                "listed_date": item.get("listedDate"),
                "listing_agent": item.get("listingAgent"),
                "listing_office": item.get("listingOffice"),
            }
        )

    return {
        "status": resolved_status,
        "address": address,
        "checked_at": checked_at,
        "cached": False,
        "matched_count": len(snapshots),
        "matched_listings": snapshots,
        "primary_listing": primary_listing,
        "evidence": evidence,
    }


def _rentcast_response_headers_map(response):
    if response is None:
        return {}
    out = {}
    for key in ["X-Total-Count", "Content-Type"]:
        value = response.headers.get(key)
        if value is not None:
            out[key] = value
    return out


def reisift_search_properties_by_text(token, search_text, limit=10):
    text = normalize_whitespace(search_text)
    if not text:
        return []
    body = {
        "limit": max(1, min(50, int(limit or 10))),
        "offset": 0,
        "ordering": "-owner_updated",
        "query": {"must": {"search": text}},
    }
    response = requests.post(
        f"{REISIFT_BASE_URL}/api/internal/property/",
        headers=reisift_auth_headers(token, {"x-http-method-override": "GET"}),
        json=body,
        timeout=30,
    )
    response.raise_for_status()
    payload = response.json() if response.headers.get("content-type", "").lower().startswith("application/json") else {}
    rows = payload.get("results") if isinstance(payload, dict) else []
    out = []
    for row in rows or []:
        if not isinstance(row, dict):
            continue
        address = row.get("address") if isinstance(row.get("address"), dict) else {}
        street = str(address.get("street") or "").strip()
        city = str(address.get("city") or "").strip()
        state = str(address.get("state") or "").strip()
        postal_code = str(address.get("zip") or address.get("postal_code") or "").strip()
        full_address = (
            str(address.get("full_address") or "").strip()
            or ", ".join([x for x in [street, city, state, postal_code] if x]).strip()
        )
        owners = row.get("owners") if isinstance(row.get("owners"), list) else []
        owner_names = []
        for owner in owners:
            if not isinstance(owner, dict):
                continue
            full_name = (owner.get("full_name") or "").strip()
            if full_name:
                owner_names.append(full_name)
                continue
            candidate = " ".join([x for x in [(owner.get("first_name") or "").strip(), (owner.get("last_name") or "").strip()] if x]).strip()
            if candidate:
                owner_names.append(candidate)
        out.append(
            {
                "uuid": normalize_uuid(row.get("uuid") or ""),
                "status": str(row.get("status") or "").strip(),
                "full_address": full_address,
                "street": street,
                "city": city,
                "state": state,
                "postal_code": postal_code,
                "created_at": str(row.get("created") or "").strip(),
                "updated_at": str(row.get("updated") or row.get("owner_updated") or "").strip(),
                "owner_names": owner_names,
            }
        )
    return out


def reisift_find_existing_property_by_address(token, street="", city="", state="", postal_code="", search_text=""):
    normalized_target = _normalize_address_components(street=street, city=city, state=state, postal_code=postal_code)
    target_street = normalize_address_match_text(normalized_target.get("street") or "")
    target_city = normalize_address_match_text(normalized_target.get("city") or "")
    target_state = normalize_state_code(normalized_target.get("state") or "")
    target_postal = normalize_postal_code(normalized_target.get("postal_code") or "")
    target_full = normalize_address_match_text(normalized_target.get("address") or format_property_address_line(street, city, state, postal_code))

    search_candidates = []
    for candidate in [
        search_text,
        normalized_target.get("address") or "",
        " ".join([x for x in [normalized_target.get("street"), normalized_target.get("city"), normalized_target.get("state"), normalized_target.get("postal_code")] if x]),
        ", ".join([x for x in [normalized_target.get("street"), normalized_target.get("city"), normalized_target.get("state")] if x]),
        normalized_target.get("street") or "",
    ]:
        clean = normalize_whitespace(candidate)
        if clean and clean.lower() not in [item.lower() for item in search_candidates]:
            search_candidates.append(clean)

    seen = set()
    best = None
    best_score = -1
    for query in search_candidates:
        for row in reisift_search_properties_by_text(token, query, limit=20):
            uuid = normalize_uuid(row.get("uuid") or "")
            if not uuid or uuid in seen:
                continue
            seen.add(uuid)
            row_street = normalize_address_match_text(row.get("street") or "")
            row_city = normalize_address_match_text(row.get("city") or "")
            row_state = normalize_state_code(row.get("state") or "")
            row_postal = normalize_postal_code(row.get("postal_code") or "")
            row_full = normalize_address_match_text(row.get("full_address") or "")

            score = 0
            if target_street and row_street == target_street:
                score += 60
            if target_city and row_city == target_city:
                score += 20
            if target_state and row_state == target_state:
                score += 10
            if target_postal and row_postal == target_postal:
                score += 15
            if target_full and row_full == target_full:
                score += 15
            if target_street and target_city and row_street == target_street and row_city == target_city and score >= best_score:
                if score > best_score:
                    best = row
                    best_score = score

    if best_score < 70:
        return {}
    return dict(best or {})


def call_rentcast_address_tool(db, action, full_address):
    action_key = normalize_whitespace(action).lower().replace("-", "_")
    address = normalize_whitespace(full_address)
    api_key = get_rentcast_api_key(db)
    if not address:
        raise ValueError("Address is required.")
    if not api_key:
        raise ValueError("RentCast API key is not configured.")

    if action_key == "sale_listing":
        endpoint_path = "/listings/sale"
        params = {"address": address, "limit": 10}
    elif action_key == "valuation":
        endpoint_path = "/avm/value"
        params = {"address": address}
    else:
        raise ValueError(f"Unsupported RentCast action: {action}")

    response = None
    response_body = None
    try:
        response = requests.get(
            f"{RENTCAST_BASE_URL}{endpoint_path}",
            headers={
                "Accept": "application/json",
                "X-Api-Key": api_key,
            },
            params=params,
            timeout=30,
        )
        try:
            response_body = response.json() if response.content else {}
        except ValueError:
            response_body = {"raw_text": response.text}
    except Exception as exc:
        raise ValueError(f"RentCast {action_key} request failed: {exc}") from exc

    payload = {
        "ok": bool(response.ok),
        "action": action_key,
        "address": address,
        "endpoint": f"{RENTCAST_BASE_URL}{endpoint_path}",
        "query": params,
        "status_code": int(response.status_code),
        "response_headers": _rentcast_response_headers_map(response),
        "data": response_body,
    }
    if not response.ok:
        log_app_error(
            db,
            source=f"rentcast_tool_{action_key}",
            error_message=f"RentCast {action_key} failed ({response.status_code}).",
            details=response_body,
            route="/api/tools/rentcast",
            status_code=response.status_code,
        )
    return payload


def _rentcast_nested_value(data, *paths):
    if not isinstance(data, dict):
        return None
    for path in paths:
        current = data
        ok = True
        for part in str(path or "").split("."):
            if isinstance(current, dict) and part in current:
                current = current.get(part)
            else:
                ok = False
                break
        if ok and current not in (None, ""):
            return current
    return None


def _rentcast_number_value(data, *paths):
    value = _rentcast_nested_value(data, *paths)
    if value in (None, ""):
        return None
    try:
        number = float(value)
    except (TypeError, ValueError):
        return None
    if not math.isfinite(number):
        return None
    return number


def _rentcast_money_text(value):
    if value in (None, ""):
        return ""
    try:
        number = float(value)
    except (TypeError, ValueError):
        return ""
    if not math.isfinite(number):
        return ""
    return f"${number:,.0f}"


def _rentcast_count_text(value):
    if value in (None, ""):
        return ""
    try:
        number = float(value)
    except (TypeError, ValueError):
        return ""
    if not math.isfinite(number):
        return ""
    if abs(number - round(number)) < 0.05:
        return f"{int(round(number))}"
    return f"{number:,.1f}"


def _rentcast_property_display_address(property_row):
    if not property_row:
        return ""
    return ", ".join(
        [
            part
            for part in [
                normalize_whitespace(property_row.get("street") or ""),
                normalize_whitespace(property_row.get("city") or ""),
                " ".join(
                    [
                        normalize_whitespace(property_row.get("state") or ""),
                        normalize_whitespace(property_row.get("postal_code") or ""),
                    ]
                ).strip(),
            ]
            if part
        ]
    ).strip()


def _summarize_rentcast_comparables(comparables):
    rows = comparables if isinstance(comparables, list) else []
    prices = []
    total_price = 0.0
    total_sqft_price = 0.0
    total_sqft = 0.0
    for item in rows:
        if not isinstance(item, dict):
            continue
        price = _rentcast_number_value(item, "price", "listPrice", "value")
        sqft = _rentcast_number_value(item, "squareFootage", "square_feet", "livingArea", "sqft")
        if price is not None:
            prices.append(price)
            total_price += price
        if price is not None and sqft is not None and sqft > 0:
            total_sqft_price += price
            total_sqft += sqft
    prices.sort()
    if not prices:
        return {"count": len(rows), "median_price": None, "average_price": None, "price_per_sqft": None}
    middle = len(prices) // 2
    if len(prices) % 2:
        median_price = prices[middle]
    else:
        median_price = (prices[middle - 1] + prices[middle]) / 2.0
    average_price = total_price / len(prices) if prices else None
    price_per_sqft = (total_sqft_price / total_sqft) if total_sqft > 0 else None
    return {
        "count": len(rows),
        "median_price": median_price,
        "average_price": average_price,
        "price_per_sqft": price_per_sqft,
    }


def _rentcast_comparable_address(item):
    item = item if isinstance(item, dict) else {}
    direct = normalize_whitespace(
        _rentcast_nested_value(item, "formattedAddress", "fullAddress", "addressLine1", "address") or ""
    )
    city = normalize_whitespace(_rentcast_nested_value(item, "city") or "")
    state = normalize_whitespace(_rentcast_nested_value(item, "state") or "")
    postal = normalize_whitespace(_rentcast_nested_value(item, "zipCode", "postalCode", "zipcode") or "")
    state_postal = " ".join([part for part in [state, postal] if part]).strip()
    suffix = ", ".join([part for part in [city, state_postal] if part]).strip()
    if direct and suffix and suffix.lower() not in direct.lower():
        return f"{direct}, {suffix}"
    return direct or suffix or "Address unavailable"


def _rentcast_comparable_date_text(value):
    text = normalize_whitespace(str(value or ""))
    if not text:
        return ""
    match = re.match(r"^(\d{4}-\d{2}-\d{2})", text)
    if match:
        return match.group(1)
    return text


def _rentcast_correlation_percent_text(value):
    if value is None:
        return ""
    percent = float(value)
    if -1 <= percent <= 1:
        percent *= 100
    if percent.is_integer():
        return f"{int(percent)}%"
    return f"{percent:.1f}".rstrip("0").rstrip(".") + "%"


def _format_rentcast_comparable_note_lines(comparables):
    rows = comparables if isinstance(comparables, list) else []
    lines = []
    for idx, item in enumerate(rows, start=1):
        if not isinstance(item, dict):
            continue
        details = []
        price = _rentcast_number_value(item, "price", "listPrice", "value")
        beds = _rentcast_number_value(item, "bedrooms", "beds")
        baths = _rentcast_number_value(item, "bathrooms", "baths")
        sqft = _rentcast_number_value(item, "squareFootage", "square_feet", "livingArea", "sqft")
        distance = _rentcast_number_value(item, "distance", "distanceMiles")
        correlation = _rentcast_number_value(item, "correlation", "score", "similarity")
        year_built = _rentcast_number_value(item, "yearBuilt", "year_built")
        property_type = normalize_whitespace(_rentcast_nested_value(item, "propertyType", "property_type") or "")
        listed_date = normalize_whitespace(_rentcast_nested_value(item, "listedDate", "lastSeenDate", "saleDate") or "")

        if price is not None:
            details.append(_rentcast_money_text(price))
        bed_bath = " / ".join(
            [
                f"{_rentcast_count_text(beds)} bd" if beds is not None else "",
                f"{_rentcast_count_text(baths)} ba" if baths is not None else "",
            ]
        ).strip(" /")
        if bed_bath:
            details.append(bed_bath)
        if sqft is not None:
            details.append(f"{_rentcast_count_text(sqft)} sqft")
        if distance is not None:
            details.append(f"{distance:.2f} mi")
        if correlation is not None:
            details.append(f"corr {_rentcast_correlation_percent_text(correlation)}")
        if property_type:
            details.append(property_type)
        if year_built is not None:
            details.append(f"built {_rentcast_count_text(year_built)}")
        if listed_date:
            details.append(f"date {_rentcast_comparable_date_text(listed_date)}")

        line = f"{idx}. {_rentcast_comparable_address(item)}"
        if details:
            line += " | " + " | ".join(details)
        lines.append(line)
    return lines


def build_rentcast_valuation_note(payload, fallback_address="", saved_at=None):
    payload = payload if isinstance(payload, dict) else {}
    data = payload.get("data") if isinstance(payload.get("data"), dict) else {}
    action = normalize_whitespace(payload.get("action") or "")
    if action.lower().replace("-", "_") != "valuation":
        raise ValueError("Only RentCast valuation results can be saved to property notes.")
    if not payload.get("ok"):
        raise ValueError("RentCast valuation did not succeed, so there is nothing to save.")

    saved_dt = saved_at or datetime.utcnow()
    saved_label = format_est_datetime(format_db_time(saved_dt))
    address = normalize_whitespace(payload.get("address") or fallback_address or "")
    if not address:
        address = normalize_whitespace(
            ", ".join(
                [
                    part
                    for part in [
                        _rentcast_nested_value(data, "formattedAddress", "fullAddress", "addressLine1", "address"),
                        _rentcast_nested_value(data, "city"),
                        " ".join(
                            [
                                str(_rentcast_nested_value(data, "state") or "").strip(),
                                str(_rentcast_nested_value(data, "zipCode", "postalCode") or "").strip(),
                            ]
                        ).strip(),
                    ]
                    if part
                ]
            )
        )

    estimate = _rentcast_number_value(
        data,
        "price",
        "value",
        "valuation",
        "estimatedValue",
        "estimate",
        "avm",
    )
    estimate_low = _rentcast_number_value(
        data,
        "priceRangeLow",
        "valueRangeLow",
        "estimatedValueRangeLow",
        "low",
        "range.low",
    )
    estimate_high = _rentcast_number_value(
        data,
        "priceRangeHigh",
        "valueRangeHigh",
        "estimatedValueRangeHigh",
        "high",
        "range.high",
    )
    rent_estimate = _rentcast_number_value(
        data,
        "rent",
        "rentEstimate",
        "estimatedRent",
        "estimated_rent",
    )
    confidence = _rentcast_nested_value(data, "confidenceScore", "confidence", "score")
    comparables = data.get("comparables") if isinstance(data.get("comparables"), list) else []
    comp_summary = _summarize_rentcast_comparables(comparables)

    lines = [f"RentCast Valuation | Saved {saved_label}"]
    if address:
        lines.append(f"Address: {address}")
    if estimate is not None:
        lines.append(f"Estimated Value: {_rentcast_money_text(estimate)}")
    if estimate_low is not None or estimate_high is not None:
        low_text = _rentcast_money_text(estimate_low) or "?"
        high_text = _rentcast_money_text(estimate_high) or "?"
        lines.append(f"Estimated Range: {low_text} - {high_text}")
    if rent_estimate is not None:
        lines.append(f"Estimated Rent: {_rentcast_money_text(rent_estimate)}/mo")
    confidence_text = _rentcast_count_text(confidence)
    if confidence_text:
        lines.append(f"Confidence: {confidence_text}")
    if comp_summary["count"]:
        lines.append(f"Comparable Count: {comp_summary['count']}")
    if comp_summary["median_price"] is not None:
        lines.append(f"Median Comp Price: {_rentcast_money_text(comp_summary['median_price'])}")
    if comp_summary["average_price"] is not None:
        lines.append(f"Average Comp Price: {_rentcast_money_text(comp_summary['average_price'])}")
    if comp_summary["price_per_sqft"] is not None:
        lines.append(f"Comp $/Sqft: {_rentcast_money_text(comp_summary['price_per_sqft'])}")
    comp_lines = _format_rentcast_comparable_note_lines(comparables)
    if comp_lines:
        lines.append("Comparable Sales:")
        lines.extend(comp_lines)
    lines.append("Source: RentCast AVM")
    return "\n".join([line for line in lines if line]).strip()


def extract_latest_rentcast_valuation_note(notes):
    text = str(notes or "").strip()
    marker = "RentCast Valuation |"
    start = text.rfind(marker)
    if start < 0:
        return ""
    latest = text[start:].strip()
    next_block = latest.find("\n\n")
    if next_block >= 0:
        latest = latest[:next_block].strip()
    return latest


def _normalize_listing_address_variants(full_address):
    address = re.sub(r"\s+", " ", str(full_address or "").strip())
    if not address:
        return []
    variants = [address]
    no_zip4 = re.sub(r"(\d{5})-\d{4}\b", r"\1", address)
    if no_zip4 not in variants:
        variants.append(no_zip4)
    no_quotes_noise = re.sub(r"\s*,\s*", ", ", no_zip4).strip(" ,")
    if no_quotes_noise not in variants:
        variants.append(no_quotes_noise)
    collapsed = re.sub(r"\s+", " ", no_zip4.replace(",", " ")).strip()
    if collapsed and collapsed not in variants:
        variants.append(collapsed)
    return [v for v in variants if v]


def _is_supported_listing_url(url):
    u = str(url or "").lower()
    return ("zillow.com" in u) or ("realtor.com" in u)


def _is_supported_listing_result(url, title, snippet):
    joined = " ".join([str(url or ""), str(title or ""), str(snippet or "")]).lower()
    return ("zillow" in joined) or ("realtor" in joined)


def _fetch_listing_page_text(url):
    target = str(url or "").strip()
    if not target:
        return ""
    headers = {"User-Agent": "Mozilla/5.0 (compatible; DeepProspectCRM/1.0)"}
    attempts = [target]
    try:
        parts = urlsplit(target)
        if parts.scheme and parts.netloc:
            path = parts.path or "/"
            query = f"?{parts.query}" if parts.query else ""
            attempts.append(f"https://r.jina.ai/http://{parts.netloc}{path}{query}")
            attempts.append(f"https://r.jina.ai/https://{parts.netloc}{path}{query}")
    except Exception:
        pass
    for attempt in attempts:
        try:
            resp = requests.get(attempt, headers=headers, timeout=20)
            if resp.status_code >= 400:
                continue
            text = re.sub(r"(?is)<[^>]+>", " ", resp.text)
            text = re.sub(r"\s+", " ", unescape(text)).strip()
            if text:
                return text.lower()
        except Exception:
            continue
    return ""


def _classify_listing_market_status(text):
    combined = f" {str(text or '').lower()} "
    checks = [
        ("Coming Soon", ["coming soon"]),
        ("For Sale by Owner", ["for sale by owner", " fsbo ", "fsbo."]),
        ("For Rent", ["for rent", "for lease"]),
        ("Sold", ["just sold", "recently sold", " sold on ", "last sold", " was sold "]),
        ("For Sale", ["for sale", " active listing ", "active status"]),
        ("Off Market", ["off market", "not currently for sale", "listing removed"]),
    ]
    for status, terms in checks:
        for term in terms:
            if term in combined:
                return status, term.strip()
    return "Unknown", ""


def _fetch_market_status_from_remote_agent(full_address):
    if not MARKET_STATUS_REMOTE_URL:
        return {"status": "Unknown", "evidence": []}
    payload = {
        "address": str(full_address or "").strip(),
        "task": "listing_status",
        "allowed_statuses": [
            "Off Market",
            "For Sale by Owner",
            "Coming Soon",
            "For Sale",
            "For Rent",
            "Sold",
            "Unknown",
        ],
    }
    headers = {"Content-Type": "application/json"}
    if MARKET_STATUS_REMOTE_TOKEN:
        headers["Authorization"] = f"Bearer {MARKET_STATUS_REMOTE_TOKEN}"
    try:
        resp = requests.post(
            MARKET_STATUS_REMOTE_URL,
            headers=headers,
            json=payload,
            timeout=30,
        )
        resp.raise_for_status()
        data = resp.json() if resp.content else {}
    except Exception:
        return {"status": "Unknown", "evidence": []}
    status = str(data.get("status") or "Unknown").strip() or "Unknown"
    evidence = data.get("evidence") if isinstance(data.get("evidence"), list) else []
    normalized = {
        "Off Market",
        "For Sale by Owner",
        "Coming Soon",
        "For Sale",
        "For Rent",
        "Sold",
        "Unknown",
    }
    if status not in normalized:
        status = "Unknown"
    return {"status": status, "evidence": evidence[:5]}


def infer_on_market_status_from_web_listing(full_address):
    address_variants = _normalize_listing_address_variants(full_address)
    if not address_variants:
        return {"status": "Unknown", "evidence": []}
    evidence = []
    snippets = []
    queries = []
    for addr in address_variants[:3]:
        queries.extend(
            [
                f'site:zillow.com "{addr}"',
                f'site:realtor.com "{addr}"',
                f"{addr} zillow",
                f"{addr} realtor",
            ]
        )

    candidates = []
    seen_urls = set()
    for q in queries:
        results = []
        try:
            results.extend(fetch_search_results_duckduckgo(q, max_results=8))
        except Exception:
            pass
        try:
            results.extend(fetch_search_results_bing(q, max_results=8))
        except Exception:
            pass
        for r in results:
            url = str(r.get("url") or "")
            title = str(r.get("title") or "")
            snippet = str(r.get("snippet") or "")
            if not _is_supported_listing_result(url, title, snippet):
                continue
            text = f"{title} {snippet}".strip()
            if not text:
                continue
            if url in seen_urls:
                continue
            seen_urls.add(url)
            snippets.append(text.lower())
            candidates.append({"url": url, "title": title, "snippet": snippet})

    # Pass 1: classify from search snippets immediately.
    combined_snippets = " \n ".join(snippets)
    snippet_status, snippet_term = _classify_listing_market_status(combined_snippets)
    if snippet_status != "Unknown":
        for c in candidates[:5]:
            evidence.append(
                {
                    "url": c["url"],
                    "title": c["title"],
                    "snippet": c["snippet"],
                    "source": "search-snippet",
                    "matched_term": snippet_term,
                }
            )
        return {"status": snippet_status, "evidence": evidence[:5]}

    # Pass 2: fetch page source and classify from page text.
    page_evidence = []
    for c in candidates[:6]:
        if not _is_supported_listing_url(c["url"]):
            continue
        page_text = _fetch_listing_page_text(c["url"])
        if not page_text:
            continue
        status, matched_term = _classify_listing_market_status(page_text)
        page_evidence.append(
            {
                "url": c["url"],
                "title": c["title"],
                "snippet": c["snippet"],
                "source": "page-source",
                "matched_term": matched_term,
            }
        )
        if status != "Unknown":
            return {"status": status, "evidence": page_evidence[:5]}

    # Pass 3: remote browser/AI fallback when local scraping is blocked.
    remote = _fetch_market_status_from_remote_agent(full_address)
    if (remote.get("status") or "Unknown") != "Unknown":
        remote_evidence = remote.get("evidence") or []
        if not remote_evidence:
            remote_evidence = [{"source": "remote-agent", "note": "Remote classifier returned a resolved status."}]
        return {"status": remote.get("status"), "evidence": remote_evidence[:5]}

    evidence.extend(page_evidence[:5])
    return {"status": "Unknown", "evidence": evidence[:5]}


def upsert_reisift_referral(db, property_uuid, payload, is_active=1, preserve_market_status=True):
    merged_payload = dict(payload or {})
    source_override = {}
    existing_market_status = "Unknown"
    existing_payload = {}
    if preserve_market_status:
        existing_row = db.execute(
            """
            SELECT
                COALESCE(on_market_status, 'Unknown') AS on_market_status,
                source_override_json,
                payload_json
            FROM reisift_referrals
            WHERE property_uuid = ?
            """,
            ((property_uuid or "").strip(),),
        ).fetchone()
        existing_market_status = str((existing_row["on_market_status"] if existing_row else "Unknown") or "Unknown").strip() or "Unknown"
        source_override = parse_json_object((existing_row["source_override_json"] if existing_row else "") or "{}")
        existing_payload = parse_json_object((existing_row["payload_json"] if existing_row else "") or "{}")
    if source_override:
        merged_payload = apply_referral_source_override(merged_payload, source_override)
    summary = summarize_reisift_property(merged_payload)
    county = infer_county_from_reisift_payload(merged_payload)
    payload_market_status = infer_on_market_status_from_payload(merged_payload)
    override_market_status = str(source_override.get("on_market_status") or "").strip() if isinstance(source_override, dict) else ""
    previous_inference = {}
    if isinstance(existing_payload, dict):
        previous_inference = existing_payload.get("market_status_inference") if isinstance(existing_payload.get("market_status_inference"), dict) else {}
    rentcast_lookup = {}
    if not override_market_status:
        rentcast_lookup = infer_on_market_status_from_rentcast(
            db,
            summary["full_address"],
            previous_lookup=previous_inference.get("rentcast_lookup"),
        )
    rentcast_status = str((rentcast_lookup or {}).get("status") or "Unknown").strip() or "Unknown"
    on_market_status = override_market_status or rentcast_status or payload_market_status or "Unknown"
    if on_market_status == "Unknown":
        on_market_status = payload_market_status or "Unknown"
    if on_market_status == "Unknown" and existing_market_status != "Unknown":
        on_market_status = existing_market_status
    merged_payload["market_status_inference"] = {
        "payload_status": payload_market_status,
        "rentcast_status": rentcast_status,
        "rentcast_lookup": rentcast_lookup,
        "web_status": None,
        "web_evidence": [],
        "previous_local_status": existing_market_status if preserve_market_status else "",
        "resolved_status": on_market_status,
        "override_status": override_market_status,
    }
    db.execute(
        """
        INSERT INTO reisift_referrals
            (property_uuid, status, full_address, owner_names, county, on_market_status, payload_json, is_active, last_synced_at)
        VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)
        ON CONFLICT(property_uuid) DO UPDATE SET
            status = excluded.status,
            full_address = excluded.full_address,
            owner_names = excluded.owner_names,
            county = excluded.county,
            on_market_status = excluded.on_market_status,
            payload_json = excluded.payload_json,
            is_active = excluded.is_active,
            last_synced_at = excluded.last_synced_at
        """,
        (
            property_uuid,
            summary["status"],
            summary["full_address"],
            summary["owner_names"],
            county,
            on_market_status,
            json.dumps(merged_payload),
            int(bool(is_active)),
            datetime.utcnow().strftime("%Y-%m-%d %H:%M:%S"),
        ),
    )


def queue_referral_auto_send_candidates(db):
    watermark_raw = (get_setting(db, "referral_auto_send_last_referral_id", "0") or "0").strip()
    try:
        watermark = int(watermark_raw)
    except (TypeError, ValueError):
        watermark = 0

    # Initialize watermark to current max to avoid backfilling historical referrals.
    if watermark <= 0:
        current_max_row = db.execute("SELECT COALESCE(MAX(id), 0) AS max_id FROM reisift_referrals").fetchone()
        current_max_id = int((current_max_row["max_id"] if current_max_row else 0) or 0)
        set_setting(db, "referral_auto_send_last_referral_id", str(current_max_id))
        return {"queued": 0, "no_realtor": 0, "initialized_watermark": current_max_id}

    rows = db.execute(
        """
        SELECT id, property_uuid, full_address, county, owner_names
        FROM reisift_referrals
        WHERE is_active = 1
          AND id > ?
          AND lower(COALESCE(referral_status, 'Untouched')) = 'untouched'
        ORDER BY id ASC
        """
        ,
        (watermark,),
    ).fetchall()
    queued = 0
    no_realtor = 0
    max_seen_id = watermark
    for row in rows:
        row_id = int((row["id"] or 0))
        if row_id > max_seen_id:
            max_seen_id = row_id
        property_uuid = (row["property_uuid"] or "").strip()
        county = (row["county"] or "").strip()
        if not property_uuid:
            continue
        existing = db.execute(
            "SELECT id FROM referral_auto_send_queue WHERE property_uuid = ? LIMIT 1",
            (property_uuid,),
        ).fetchone()
        if existing:
            continue
        if not county:
            db.execute(
                """
                INSERT INTO referral_auto_send_queue (property_uuid, realtor_id, county, queue_status, note, payload_json)
                VALUES (?, NULL, ?, 'No Realtor', ?, ?)
                """,
                (
                    property_uuid,
                    county,
                    "County missing on referral; waiting for manual routing.",
                    json.dumps({"full_address": row["full_address"], "owner_names": row["owner_names"]}),
                ),
            )
            no_realtor += 1
            continue

        realtors = db.execute(
            """
            SELECT id, first_name, last_name
            FROM referral_realtors
            WHERE lower(target_markets) LIKE ?
            ORDER BY id ASC
            """,
            (f"%{county.lower()}%",),
        ).fetchall()
        if not realtors:
            db.execute(
                """
                INSERT INTO referral_auto_send_queue (property_uuid, realtor_id, county, queue_status, note, payload_json)
                VALUES (?, NULL, ?, 'No Realtor', ?, ?)
                """,
                (
                    property_uuid,
                    county,
                    "No realtor currently tagged for this county.",
                    json.dumps({"full_address": row["full_address"], "owner_names": row["owner_names"]}),
                ),
            )
            no_realtor += 1
            continue
        for realtor in realtors:
            db.execute(
                """
                INSERT INTO referral_auto_send_queue (property_uuid, realtor_id, county, queue_status, note, payload_json)
                VALUES (?, ?, ?, 'Queued', ?, ?)
                """,
                (
                    property_uuid,
                    realtor["id"],
                    county,
                    "Queued for review before auto-send.",
                    json.dumps({"full_address": row["full_address"], "owner_names": row["owner_names"]}),
                ),
            )
            queued += 1
    if max_seen_id > watermark:
        set_setting(db, "referral_auto_send_last_referral_id", str(max_seen_id))
    return {"queued": queued, "no_realtor": no_realtor}


def refresh_reisift_referrals_cache(db):
    status_slug = os.getenv("REISIFT_REFERRAL_STATUS", "refer_lead").strip() or "refer_lead"
    token = reisift_get_access_token()
    rows, total = reisift_search_referral_rows(token, status_slug)

    db.execute("UPDATE reisift_referrals SET is_active = 0")
    synced = 0
    errors = []
    for row in rows:
        property_uuid = (row.get("uuid") or "").strip()
        if not property_uuid:
            continue
        detail_payload = row
        try:
            detail_payload = fetch_reisift_property_payload(token, property_uuid)
        except Exception as exc:
            errors.append(f"{property_uuid}: {exc}")
        try:
            upsert_reisift_referral(db, property_uuid, detail_payload, is_active=1, preserve_market_status=True)
            synced += 1
        except Exception as exc:
            errors.append(f"{property_uuid}: {exc}")
            continue

    queue_summary = queue_referral_auto_send_candidates(db)
    db.commit()
    return {
        "status_slug": status_slug,
        "total": total or len(rows),
        "synced": synced,
        "errors": errors,
        "queue_summary": queue_summary,
        "mode": "search_only",
    }


def get_cached_referrals(db):
    rows = db.execute(
        """
        SELECT r.property_uuid, r.status, r.full_address, r.owner_names, r.payload_json, r.last_synced_at,
               r.county, COALESCE(r.on_market_status, 'Unknown') AS on_market_status,
               COALESCE(r.referral_status, 'Untouched') AS referral_status,
               COALESCE(a.push_count, 0) AS push_count
        FROM reisift_referrals r
        LEFT JOIN (
            SELECT property_uuid, COUNT(*) AS push_count
            FROM referral_push_activity
            GROUP BY property_uuid
        ) a ON a.property_uuid = r.property_uuid
        WHERE r.is_active = 1
        ORDER BY r.last_synced_at DESC, r.id DESC
        """
    ).fetchall()
    return rows


def parse_iso_datetime(value):
    if not value:
        return None
    text = str(value).strip()
    if not text:
        return None
    direct = parse_db_time(text)
    if direct is not None:
        return direct
    try:
        normalized = text.replace("Z", "+00:00")
        dt = datetime.fromisoformat(normalized)
        if dt.tzinfo is not None:
            dt = dt.astimezone(timezone.utc).replace(tzinfo=None)
        return dt
    except ValueError:
        return None


def reisift_added_at_dt(search_row, detail_payload):
    candidates = []
    if isinstance(search_row, dict):
        candidates.extend([search_row.get("created"), search_row.get("created_at")])
    if isinstance(detail_payload, dict):
        candidates.extend([detail_payload.get("created"), detail_payload.get("created_at")])
    for item in candidates:
        parsed = parse_iso_datetime(item)
        if parsed is not None:
            return parsed
    return None


def find_local_property_id_for_reisift_payload(db, payload):
    address = extract_reisift_property_address(payload)
    street = (address.get("street") or "").strip().lower()
    city = (address.get("city") or "").strip().lower()
    state = (address.get("state") or "").strip().lower()
    postal = (address.get("postal_code") or "").strip().lower()
    if not street or not city:
        return None
    row = db.execute(
        """
        SELECT p.id
        FROM properties p
        JOIN addresses a ON a.id = p.property_address_id
        WHERE lower(a.street) = ?
          AND lower(a.city) = ?
          AND lower(a.state) = ?
          AND lower(a.postal_code) = ?
        ORDER BY p.id DESC
        LIMIT 1
        """,
        (street, city, state, postal),
    ).fetchone()
    return row["id"] if row else None


def get_local_property_activity_rollup(db, property_id):
    if not property_id:
        return {
            "outbound_calls": 0,
            "outbound_sms": 0,
            "outbound_email": 0,
            "inbound_responses": 0,
        }
    outbound_sms = db.execute(
        """
        SELECT COUNT(*) AS c
        FROM communications
        WHERE property_id = ?
          AND upper(channel) = 'SMS'
          AND lower(direction) = 'outbound'
        """,
        (property_id,),
    ).fetchone()["c"]
    outbound_email = db.execute(
        """
        SELECT COUNT(*) AS c
        FROM communications
        WHERE property_id = ?
          AND upper(channel) = 'EMAIL'
          AND lower(direction) = 'outbound'
        """,
        (property_id,),
    ).fetchone()["c"]
    inbound_responses = db.execute(
        """
        SELECT COUNT(*) AS c
        FROM communications
        WHERE property_id = ?
          AND lower(direction) = 'inbound'
          AND upper(channel) IN ('SMS', 'EMAIL')
        """,
        (property_id,),
    ).fetchone()["c"]
    outbound_calls = db.execute(
        """
        SELECT COUNT(*) AS c
        FROM activity_log
        WHERE property_id = ?
          AND lower(activity_type) LIKE 'call%'
        """,
        (property_id,),
    ).fetchone()["c"]
    return {
        "outbound_calls": int(outbound_calls or 0),
        "outbound_sms": int(outbound_sms or 0),
        "outbound_email": int(outbound_email or 0),
        "inbound_responses": int(inbound_responses or 0),
    }


def upsert_reisift_followup(
    db,
    property_uuid,
    payload,
    added_at,
    outbound_calls,
    outbound_sms,
    outbound_email,
    inbound_responses,
    events,
    tasks,
    is_active=1,
):
    summary = summarize_reisift_property(payload)
    execute_with_retry(
        db,
        """
        INSERT INTO reisift_followups
            (property_uuid, status, full_address, owner_names, added_at, outbound_calls, outbound_sms, outbound_email, inbound_responses, events_json, tasks_json, payload_json, is_active, last_synced_at)
        VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
        ON CONFLICT(property_uuid) DO UPDATE SET
            status = excluded.status,
            full_address = excluded.full_address,
            owner_names = excluded.owner_names,
            added_at = excluded.added_at,
            outbound_calls = excluded.outbound_calls,
            outbound_sms = excluded.outbound_sms,
            outbound_email = excluded.outbound_email,
            inbound_responses = excluded.inbound_responses,
            events_json = excluded.events_json,
            tasks_json = excluded.tasks_json,
            payload_json = excluded.payload_json,
            is_active = excluded.is_active,
            last_synced_at = excluded.last_synced_at
        """,
        (
            property_uuid,
            summary["status"],
            summary["full_address"],
            summary["owner_names"],
            format_db_time(added_at) if added_at else None,
            int(outbound_calls or 0),
            int(outbound_sms or 0),
            int(outbound_email or 0),
            int(inbound_responses or 0),
            json.dumps(events or []),
            json.dumps(tasks or []),
            json.dumps(payload),
            int(bool(is_active)),
            datetime.utcnow().strftime("%Y-%m-%d %H:%M:%S"),
        ),
    )


def build_followups_owner_updated_range(lookback_days):
    token = reisift_get_access_token()
    now_est = datetime.now(EST_TZ)
    days = max(1, min(90, int(lookback_days or 7)))
    start_local = (now_est - timedelta(days=days)).replace(hour=0, minute=0, second=0, microsecond=0)
    end_local = now_est.replace(hour=23, minute=59, second=59, microsecond=999000)
    start_utc = start_local.astimezone(timezone.utc)
    end_utc = end_local.astimezone(timezone.utc)
    owner_updated_range = [
        start_utc.isoformat(timespec="milliseconds").replace("+00:00", "Z"),
        end_utc.isoformat(timespec="milliseconds").replace("+00:00", "Z"),
    ]
    return token, days, owner_updated_range


def refresh_reisift_followups_search_cache(db, lookback_days=7):
    token, days, owner_updated_range = build_followups_owner_updated_range(lookback_days)
    headers = {
        "Authorization": f"Bearer {token}",
        "Content-Type": "application/json",
        "x-reisift-ui-version": REISIFT_UI_VERSION,
        "x-http-method-override": "GET",
    }
    offset = 0
    page_size = 200
    synced = 0
    scanned = 0
    errors = []
    # Hard reset cache first so only the current retrieve remains in the table.
    execute_with_retry(db, "DELETE FROM reisift_followups")
    commit_with_retry(db)
    while offset < 1000:
        body = {
            "limit": page_size,
            "offset": offset,
            "ordering": "-created",
            "query": {
                "must": {
                    "property_type": "clean",
                    "owner_updated": owner_updated_range,
                    "must_not": {
                        "all_tags": [REISIFT_FOLLOWUPS_EXCLUDE_TAG],
                    },
                },
            },
        }
        response = requests.post(
            f"{REISIFT_BASE_URL}/api/internal/property/",
            headers=headers,
            json=body,
            timeout=30,
        )
        response.raise_for_status()
        payload = response.json()
        rows = payload.get("results") or []
        if not rows:
            break
        for row in rows:
            scanned += 1
            property_uuid = (row.get("uuid") or "").strip()
            if not property_uuid:
                continue
            added_dt = reisift_added_at_dt(row, row)
            upsert_reisift_followup(
                db=db,
                property_uuid=property_uuid,
                payload=row,
                added_at=added_dt,
                outbound_calls=0,
                outbound_sms=0,
                outbound_email=0,
                inbound_responses=0,
                events=[],
                tasks=[],
                is_active=1,
            )
            synced += 1
        if len(rows) < page_size:
            break
        offset += page_size
    commit_with_retry(db)
    return {
        "synced": synced,
        "scanned": scanned,
        "errors": errors,
        "lookback_days": days,
        "owner_updated_range": owner_updated_range,
    }


def refresh_reisift_followups_cache(db):
    token = reisift_get_access_token()
    rows = db.execute(
        "SELECT property_uuid, added_at, payload_json FROM reisift_followups WHERE is_active = 1 ORDER BY id DESC"
    ).fetchall()
    updated = 0
    errors = []
    for row in rows:
        property_uuid = (row["property_uuid"] or "").strip()
        if not property_uuid:
            continue
        details = {}
        try:
            details = fetch_reisift_property_payload(token, property_uuid)
        except Exception as exc:
            errors.append(f"{property_uuid}: {exc}")
            try:
                details = json.loads(row["payload_json"] or "{}")
            except Exception:
                details = {}
        sift_rollup = {
            "outbound_calls": 0,
            "outbound_sms": 0,
            "outbound_email": 0,
            "inbound_responses": 0,
            "events": [],
            "tasks": [],
            "property_created_at": None,
        }
        try:
            sift_rollup = fetch_reisift_property_log_rollup(token, property_uuid)
        except Exception as exc:
            errors.append(f"{property_uuid} logs: {exc}")

        added_dt = parse_flexible_datetime(sift_rollup.get("property_created_at"))
        if added_dt is None:
            added_dt = parse_flexible_datetime(row["added_at"])
        local_property_id = find_local_property_id_for_reisift_payload(db, details)
        local_rollup = get_local_property_activity_rollup(db, local_property_id)
        outbound_calls = max(local_rollup["outbound_calls"], sift_rollup["outbound_calls"])
        outbound_sms = max(local_rollup["outbound_sms"], sift_rollup["outbound_sms"])
        outbound_email = max(local_rollup["outbound_email"], sift_rollup["outbound_email"])
        inbound_responses = max(local_rollup["inbound_responses"], sift_rollup["inbound_responses"])
        upsert_reisift_followup(
            db=db,
            property_uuid=property_uuid,
            payload=details,
            added_at=added_dt,
            outbound_calls=outbound_calls,
            outbound_sms=outbound_sms,
            outbound_email=outbound_email,
            inbound_responses=inbound_responses,
            events=sift_rollup.get("events") or [],
            tasks=sift_rollup.get("tasks") or [],
            is_active=1,
        )
        updated += 1
    commit_with_retry(db)
    return {"updated": updated, "errors": errors}


def enrich_reisift_followups_cache(db):
    return refresh_reisift_followups_cache(db)


def get_cached_followups(db, sort_dir="desc"):
    sort_sql = "DESC" if str(sort_dir).lower() != "asc" else "ASC"
    return db.execute(
        f"""
        SELECT f.*,
               CASE WHEN r.property_uuid IS NULL THEN 0 ELSE 1 END AS has_referral_cache
        FROM reisift_followups f
        LEFT JOIN reisift_referrals r ON r.property_uuid = f.property_uuid
        WHERE f.is_active = 1
        ORDER BY
            CASE WHEN f.added_at IS NULL OR trim(f.added_at) = '' THEN 1 ELSE 0 END {sort_sql},
            f.added_at {sort_sql},
            f.last_synced_at {sort_sql},
            f.id {sort_sql}
        """
    ).fetchall()


def normalize_county_name(value):
    text = normalize_whitespace(str(value or "")).lower()
    text = re.sub(r"\bcounty\b", "", text).strip()
    return re.sub(r"[^a-z0-9]+", " ", text).strip()


