def target_new_record_counties():
    return [item for item in REISIFT_NEW_RECORDS_COUNTIES if item]


def is_target_new_record_county(county):
    county_key = normalize_county_name(county)
    targets = {normalize_county_name(item) for item in target_new_record_counties()}
    return bool(county_key and county_key in targets)


def infer_untitled_new_record_county(row):
    item = row if isinstance(row, dict) else {}
    payload = parse_json_object(item.get("payload_json") or "{}")
    for key in ["county", "personal_county", "property_county", "mailing_county"]:
        county = normalize_whitespace(item.get(key) or (payload.get(key) if isinstance(payload, dict) else ""))
        if is_target_new_record_county(county):
            for configured in target_new_record_counties():
                if normalize_county_name(configured) == normalize_county_name(county):
                    return configured
            return county
    state = normalize_state_code(item.get("personal_state") or (payload.get("personal_state") if isinstance(payload, dict) else ""))
    if state != "NJ":
        return ""
    city = normalize_county_name(item.get("personal_city") or (payload.get("personal_city") if isinstance(payload, dict) else ""))
    if not city:
        return ""
    for county, cities in NEW_RECORD_COUNTY_CITY_MAP.items():
        if city in cities and is_target_new_record_county(county):
            return county
    return ""


def is_new_record_status_value(value):
    normalized = _normalize_reisift_status(value)
    return normalized in {"new record", "new records", "untouched", ""}


def sync_existing_untitled_new_record_properties(db):
    rows = db.execute(
        """
        SELECT u.*, p.status AS local_property_status
        FROM untitled_sheet_current u
        LEFT JOIN properties p ON p.id = u.local_property_id
        WHERE COALESCE(u.is_active, 1) = 1
          AND trim(COALESCE(u.skiptrace_completed_at, '')) = ''
        """
    ).fetchall()
    matched = 0
    status_updates = 0
    target_rows = 0
    now_text = format_db_time(datetime.utcnow())
    for raw_row in rows:
        row = dict(raw_row)
        county = infer_untitled_new_record_county(row)
        if not county:
            continue
        status_value = row.get("local_property_status") or row.get("reisift_status") or ""
        if not is_new_record_status_value(status_value):
            continue
        target_rows += 1
        address = _untitled_source_address(row)
        property_id = int(row.get("local_property_id") or 0)
        if property_id <= 0:
            property_id = int(find_local_property_by_address(
                db,
                address.get("street") or "",
                address.get("city") or "",
                address.get("state") or "",
                address.get("postal_code") or "",
            ) or 0)
        if property_id <= 0:
            continue
        prop = db.execute("SELECT id, status FROM properties WHERE id = ? LIMIT 1", (property_id,)).fetchone()
        if not prop:
            continue
        matched += 1
        before_status = normalize_whitespace(prop["status"] or "")
        if before_status != "New Records":
            db.execute("UPDATE properties SET status = ? WHERE id = ?", ("New Records", property_id))
            status_updates += 1
            try:
                db.execute(
                    """
                    INSERT INTO activity_log (property_id, activity_type, outcome, note)
                    VALUES (?, ?, ?, ?)
                    """,
                    (
                        property_id,
                        "Prospecting Monitor",
                        "New Records",
                        f"Marked from prospecting-monitor refresh for {county} County. Previous status: {before_status or '-'}",
                    ),
                )
            except Exception:
                pass
        _update_untitled_current_row_state(
            db,
            row.get("record_key") or "",
            local_property_id=property_id,
            reisift_status="New Records",
            last_action_error="",
        )
    set_setting(db, "reisift_new_records_last_refresh_at", now_text)
    return {"target_rows": target_rows, "matched": matched, "status_updates": status_updates}


def refresh_prospecting_new_records_once():
    snapshot_result = run_untitled_leads_snapshot_once()
    db = open_sqlite_connection()
    try:
        sync_result = sync_existing_untitled_new_record_properties(db)
        db.commit()
    finally:
        db.close()
    return {"snapshot": snapshot_result, "sync": sync_result}


def _find_local_property_for_reisift_new_record(db, property_uuid, payload):
    property_uuid = normalize_uuid(property_uuid)
    if property_uuid:
        row = db.execute(
            """
            SELECT id, status
            FROM properties
            WHERE lower(COALESCE(reisift_property_uuid, '')) = lower(?)
            ORDER BY id DESC
            LIMIT 1
            """,
            (property_uuid,),
        ).fetchone()
        if row:
            return row
    local_id = find_local_property_id_for_reisift_payload(db, payload if isinstance(payload, dict) else {})
    if not local_id:
        return None
    row = db.execute("SELECT id, status FROM properties WHERE id = ? LIMIT 1", (local_id,)).fetchone()
    if row and property_uuid:
        _set_local_property_uuid(db, int(row["id"]), property_uuid)
    return row


def sync_local_property_status_from_reisift_new_record(db, property_uuid, payload, status):
    row = _find_local_property_for_reisift_new_record(db, property_uuid, payload)
    if not row:
        return {"local_property_id": None, "before": "", "after": ""}
    local_property_id = int(row["id"])
    before = str(row["status"] or "").strip()
    after = normalize_whitespace(status or "") or before
    if after and before != after:
        db.execute("UPDATE properties SET status = ? WHERE id = ?", (after, local_property_id))
        try:
            db.execute(
                """
                INSERT INTO activity_log (property_id, activity_type, outcome, note)
                VALUES (?, ?, ?, ?)
                """,
                (
                    local_property_id,
                    "ReiSift Status Sync",
                    after,
                    f"Updated from ReiSift New Records refresh. Previous local status: {before or '-'}",
                ),
            )
        except Exception:
            pass
    return {"local_property_id": local_property_id, "before": before, "after": after}


def upsert_reisift_new_record(db, property_uuid, payload, search_row=None, is_active=1):
    payload = payload if isinstance(payload, dict) else {}
    search_row = search_row if isinstance(search_row, dict) else {}
    summary = summarize_reisift_property(payload, fallback_payload=search_row)
    county = infer_county_from_reisift_payload(payload) or infer_county_from_reisift_payload(search_row)
    added_dt = reisift_added_at_dt(search_row, payload)
    updated_at = (
        str(payload.get("updated") or payload.get("updated_at") or payload.get("owner_updated") or "").strip()
        or str(search_row.get("updated") or search_row.get("updated_at") or search_row.get("owner_updated") or "").strip()
    )
    match_payload = payload
    match_address = extract_reisift_property_address(match_payload)
    if not match_address.get("street") or not match_address.get("city"):
        match_payload = search_row
    local_sync = sync_local_property_status_from_reisift_new_record(db, property_uuid, match_payload, summary["status"])
    execute_with_retry(
        db,
        """
        INSERT INTO reisift_new_records
            (property_uuid, status, full_address, owner_names, county, added_at, reisift_updated_at,
             local_property_id, local_status_before, local_status_after, payload_json, is_active, last_synced_at)
        VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
        ON CONFLICT(property_uuid) DO UPDATE SET
            status = excluded.status,
            full_address = excluded.full_address,
            owner_names = excluded.owner_names,
            county = excluded.county,
            added_at = excluded.added_at,
            reisift_updated_at = excluded.reisift_updated_at,
            local_property_id = excluded.local_property_id,
            local_status_before = excluded.local_status_before,
            local_status_after = excluded.local_status_after,
            payload_json = excluded.payload_json,
            is_active = excluded.is_active,
            last_synced_at = excluded.last_synced_at
        """,
        (
            property_uuid,
            summary["status"],
            summary["full_address"],
            summary["owner_names"],
            county,
            format_db_time(added_dt) if added_dt else None,
            updated_at,
            local_sync["local_property_id"],
            local_sync["before"],
            local_sync["after"],
            json.dumps(payload or search_row),
            int(bool(is_active)),
            datetime.utcnow().strftime("%Y-%m-%d %H:%M:%S"),
        ),
    )
    return local_sync


def refresh_reisift_new_records_cache(db):
    token = reisift_get_access_token()
    status_slug = REISIFT_NEW_RECORDS_STATUS
    target_counties = target_new_record_counties()
    rows, total = reisift_search_property_rows_by_status(
        token,
        status_slug,
        counties=target_counties,
        max_rows=2000,
    )
    execute_with_retry(db, "UPDATE reisift_new_records SET is_active = 0")
    scanned = 0
    synced = 0
    skipped_county = 0
    local_updates = 0
    errors = []
    for row in rows:
        scanned += 1
        property_uuid = normalize_uuid(row.get("uuid") or "")
        if not property_uuid:
            continue
        details = row
        try:
            details = fetch_reisift_property_payload(token, property_uuid)
        except Exception as exc:
            errors.append(f"{property_uuid}: detail fallback used ({exc})")
        county = infer_county_from_reisift_payload(details) or infer_county_from_reisift_payload(row)
        if county and not is_target_new_record_county(county):
            skipped_county += 1
            continue
        try:
            local_sync = upsert_reisift_new_record(db, property_uuid, details, search_row=row, is_active=1)
            if local_sync.get("local_property_id") and local_sync.get("before") != local_sync.get("after"):
                local_updates += 1
            synced += 1
        except Exception as exc:
            errors.append(f"{property_uuid}: {exc}")
    set_setting(db, "reisift_new_records_last_refresh_at", datetime.utcnow().strftime("%Y-%m-%d %H:%M:%S"))
    commit_with_retry(db)
    return {
        "status_slug": status_slug,
        "target_counties": target_counties,
        "total": total,
        "scanned": scanned,
        "synced": synced,
        "skipped_county": skipped_county,
        "local_updates": local_updates,
        "errors": errors,
    }


def set_reisift_new_records_refresh_state(db, status, message="", result=None):
    payload = {
        "status": str(status or "").strip() or "unknown",
        "message": str(message or "").strip(),
        "updated_at": datetime.utcnow().strftime("%Y-%m-%d %H:%M:%S"),
        "result": result if isinstance(result, dict) else {},
    }
    set_setting(db, "reisift_new_records_refresh_state_json", json.dumps(payload))
    return payload


def get_reisift_new_records_refresh_state(db):
    raw = get_setting(db, "reisift_new_records_refresh_state_json", "")
    data = parse_json_object(raw or "{}", default={})
    if not isinstance(data, dict) or not data:
        return {"status": "idle", "message": "", "updated_at": "", "result": {}}
    return {
        "status": str(data.get("status") or "idle").strip() or "idle",
        "message": str(data.get("message") or "").strip(),
        "updated_at": str(data.get("updated_at") or "").strip(),
        "result": data.get("result") if isinstance(data.get("result"), dict) else {},
    }


def start_reisift_new_records_refresh_job(triggered_by="manual"):
    if not REISIFT_NEW_RECORDS_REFRESH_LOCK.acquire(blocking=False):
        db = open_sqlite_connection()
        try:
            state = get_reisift_new_records_refresh_state(db)
            if state.get("status") != "running":
                state = set_reisift_new_records_refresh_state(db, "running", "Refresh already in progress.")
                db.commit()
            return {"ok": True, "started": False, "running": True, "state": state}
        finally:
            db.close()

    def worker():
        db = open_sqlite_connection()
        try:
            set_reisift_new_records_refresh_state(db, "running", "Refreshing New Records from ReiSift...")
            db.commit()
            result = refresh_reisift_new_records_cache(db)
            message = (
                f"Cached {result.get('synced', 0)} row(s) from {result.get('scanned', 0)} scanned; "
                f"updated {result.get('local_updates', 0)} local status value(s)."
            )
            set_reisift_new_records_refresh_state(db, "complete", message, result=result)
            db.commit()
        except Exception as exc:
            db.rollback()
            log_app_error(
                db,
                source="reisift_new_records_refresh_job",
                error_message=str(exc),
                details=traceback.format_exc(),
                route="start_reisift_new_records_refresh_job",
                status_code=500,
            )
            state = set_reisift_new_records_refresh_state(db, "error", str(exc), result={"error": str(exc)})
            db.commit()
            return state
        finally:
            db.close()
            REISIFT_NEW_RECORDS_REFRESH_LOCK.release()

    starter_db = open_sqlite_connection()
    try:
        state = set_reisift_new_records_refresh_state(
            starter_db,
            "running",
            f"Refresh started ({triggered_by}).",
        )
        starter_db.commit()
    finally:
        starter_db.close()
    thread = threading.Thread(target=worker, daemon=True)
    thread.start()
    return {"ok": True, "started": True, "running": True, "state": state}


def _new_record_row_date(row):
    for candidate in [row.get("added_at"), row.get("reisift_updated_at"), row.get("last_synced_at")]:
        dt = parse_flexible_datetime(candidate)
        if dt is not None:
            return dt
    return datetime.min


def _new_record_matches_filters(row, filters):
    filters = filters if isinstance(filters, dict) else {}
    date_from = _parse_iso_date_only(filters.get("date_from") or "")
    date_to = _parse_iso_date_only(filters.get("date_to") or "")
    row_dt = _new_record_row_date(row)
    if (date_from or date_to) and row_dt == datetime.min:
        return False
    row_date = row_dt.date() if row_dt != datetime.min else None
    if date_from and row_date and row_date < date_from:
        return False
    if date_to and row_date and row_date > date_to:
        return False

    status_filter = normalize_whitespace(filters.get("status") or "")
    if status_filter and _normalize_reisift_status(row.get("status") or "") != _normalize_reisift_status(status_filter):
        return False

    county_filter = normalize_county_name(filters.get("county") or "")
    if county_filter and normalize_county_name(row.get("county") or "") != county_filter:
        return False

    local_match = normalize_whitespace(filters.get("local_match") or "").lower()
    has_local = bool(row.get("deep_dive_property_id"))
    if local_match == "matched" and not has_local:
        return False
    if local_match == "unmatched" and has_local:
        return False

    local_status_filter = normalize_whitespace(filters.get("local_status") or "")
    if local_status_filter:
        local_status = normalize_whitespace(row.get("deep_dive_status") or row.get("local_status_after") or "")
        if _normalize_reisift_status(local_status) != _normalize_reisift_status(local_status_filter):
            return False
    return True


def get_new_record_filter_options(db):
    rows = db.execute(
        """
        SELECT n.status,
               n.county,
               p.status AS deep_dive_status,
               n.local_status_after
        FROM reisift_new_records n
        LEFT JOIN properties p ON p.id = n.local_property_id
        WHERE n.is_active = 1
        """
    ).fetchall()
    statuses = sorted({normalize_whitespace(row["status"] or "") for row in rows if normalize_whitespace(row["status"] or "")})
    counties = sorted({normalize_whitespace(row["county"] or "") for row in rows if normalize_whitespace(row["county"] or "")})
    local_statuses = sorted({
        normalize_whitespace(row["deep_dive_status"] or row["local_status_after"] or "")
        for row in rows
        if normalize_whitespace(row["deep_dive_status"] or row["local_status_after"] or "")
    })
    return {"statuses": statuses, "counties": counties, "local_statuses": local_statuses}


def get_cached_new_records(db, sort_dir="desc", filters=None):
    sort_reverse = str(sort_dir).lower() != "asc"
    rows = db.execute(
        """
        SELECT n.*,
               p.id AS deep_dive_property_id,
               p.status AS deep_dive_status
        FROM reisift_new_records n
        LEFT JOIN properties p ON p.id = n.local_property_id
        WHERE n.is_active = 1
        """
    ).fetchall()
    out = []
    for row in rows:
        item = dict(row)
        item["sift_record_url"] = _sift_record_url(item.get("property_uuid") or "")
        item["local_status_after"] = item.get("deep_dive_status") or item.get("local_status_after") or ""
        if not _new_record_matches_filters(item, filters):
            continue
        out.append(item)

    out.sort(key=_new_record_row_date, reverse=sort_reverse)
    return out


def parse_followup_json_list(raw_value):
    if not raw_value:
        return []
    try:
        data = json.loads(raw_value)
        return data if isinstance(data, list) else []
    except Exception:
        return []


def iter_reisift_payload_owners(payload):
    if not isinstance(payload, dict):
        return []
    owners = []
    owner = payload.get("owner")
    if isinstance(owner, dict):
        owners.append(owner)
    owner_list = payload.get("owners")
    if isinstance(owner_list, list):
        for item in owner_list:
            if isinstance(item, dict):
                owners.append(item)
    return owners


def extract_owner_names_from_payload(payload):
    names = []
    seen = set()
    for owner in iter_reisift_payload_owners(payload):
        full_name = (owner.get("full_name") or owner.get("name") or "").strip()
        if not full_name:
            first = (owner.get("first_name") or "").strip()
            last = (owner.get("last_name") or "").strip()
            full_name = " ".join(x for x in [first, last] if x).strip()
        key = full_name.lower()
        if not full_name or key in seen:
            continue
        seen.add(key)
        names.append(full_name)
    return names


def extract_owner_contacts_from_payload(payload):
    phones = []
    seen_phones = set()
    emails = []
    seen_emails = set()
    for owner in iter_reisift_payload_owners(payload):
        for p in owner.get("phones") or []:
            value = ""
            p_type = "Unknown"
            p_status = "Unknown"
            if isinstance(p, dict):
                value = (p.get("number") or p.get("phone") or "").strip()
                p_type = (p.get("type") or "Unknown").strip() or "Unknown"
                p_status = (p.get("status") or "Unknown").strip() or "Unknown"
            else:
                value = str(p or "").strip()
            key = normalize_phone(value) or value
            if not value or key in seen_phones:
                continue
            seen_phones.add(key)
            phones.append({"value": value, "type": p_type, "status": p_status})

        for e in owner.get("emails") or []:
            value = ""
            status = "Unknown"
            if isinstance(e, dict):
                value = (e.get("email") or e.get("value") or "").strip()
                status = (e.get("status") or "Unknown").strip() or "Unknown"
            else:
                value = str(e or "").strip()
            key = value.lower()
            if not value or key in seen_emails:
                continue
            seen_emails.add(key)
            emails.append({"value": value, "status": status})
    return phones, emails


def _split_referral_multivalue_text(raw_text, allow_comma=True):
    text = str(raw_text or "")
    pattern = r"[\r\n,;]+" if allow_comma else r"[\r\n;]+"
    values = []
    seen = set()
    for part in re.split(pattern, text):
        value = str(part or "").strip()
        key = value.lower()
        if not value or key in seen:
            continue
        seen.add(key)
        values.append(value)
    return values


def _build_referral_source_override(form):
    return {
        "status": str(form.get("source_status") or "").strip(),
        "full_address": str(form.get("source_full_address") or "").strip(),
        "county": str(form.get("source_county") or "").strip(),
        "on_market_status": str(form.get("source_on_market_status") or "").strip() or "Unknown",
        "owner_names": _split_referral_multivalue_text(form.get("source_owner_names"), allow_comma=False),
        "phones": _split_referral_multivalue_text(form.get("source_phones"), allow_comma=True),
        "emails": _split_referral_multivalue_text(form.get("source_emails"), allow_comma=True),
    }


def _owner_dict_with_name(base_owner, full_name):
    owner = copy.deepcopy(base_owner) if isinstance(base_owner, dict) else {}
    normalized_name = " ".join(str(full_name or "").split()).strip()
    parsed = _reisift_parse_owner_name({"full_name": normalized_name})
    owner["first_name"] = parsed["first_name"]
    owner["last_name"] = parsed["last_name"]
    if normalized_name:
        owner["full_name"] = normalized_name
        owner["name"] = normalized_name
    else:
        owner.pop("full_name", None)
        owner.pop("name", None)
    return owner


def apply_referral_source_override(payload, override):
    merged = copy.deepcopy(payload) if isinstance(payload, dict) else {}
    override = override if isinstance(override, dict) else {}
    if not override:
        return merged

    status = str(override.get("status") or "").strip()
    if status:
        merged["status"] = status

    address = merged.get("address") if isinstance(merged.get("address"), dict) else {}
    address["full_address"] = str(override.get("full_address") or "").strip()
    county = str(override.get("county") or "").strip()
    if county:
        address["county"] = county
    else:
        address.pop("county", None)
    if address:
        merged["address"] = address

    owner_names = [str(x).strip() for x in (override.get("owner_names") or []) if str(x).strip()]
    phone_values = [normalize_phone(x) or str(x).strip() for x in (override.get("phones") or []) if str(x).strip()]
    email_values = [str(x).strip() for x in (override.get("emails") or []) if str(x).strip()]
    base_owner = iter_reisift_payload_owners(merged)[0] if iter_reisift_payload_owners(merged) else {}

    owners = []
    if owner_names:
        for idx, name in enumerate(owner_names):
            owner = _owner_dict_with_name(base_owner if idx == 0 else {}, name)
            if idx == 0:
                owner["phones"] = [{"number": phone, "type": "MANUAL", "tags": [], "status": "MANUAL"} for phone in phone_values]
                owner["emails"] = list(email_values)
            else:
                owner["phones"] = []
                owner["emails"] = []
            owners.append(owner)
    elif base_owner or phone_values or email_values:
        owner = _owner_dict_with_name(base_owner, "")
        owner["phones"] = [{"number": phone, "type": "MANUAL", "tags": [], "status": "MANUAL"} for phone in phone_values]
        owner["emails"] = list(email_values)
        owners.append(owner)

    if owners:
        merged["owner"] = owners[0]
        merged["owners"] = owners
    else:
        merged.pop("owner", None)
        merged["owners"] = []

    return merged


def extract_property_lists(payload):
    lists = payload.get("lists") if isinstance(payload, dict) else []
    if not isinstance(lists, list):
        return ""
    names = []
    for item in lists:
        if isinstance(item, dict):
            val = (item.get("title") or item.get("name") or "").strip()
        else:
            val = str(item or "").strip()
        if val:
            names.append(val)
    dedup = list(dict.fromkeys(names))
    return ", ".join(dedup)


def extract_payload_address(payload):
    address = payload.get("address") if isinstance(payload, dict) else {}
    if not isinstance(address, dict):
        return {"street": "", "city": "", "state": "", "postal_code": ""}
    return {
        "street": (address.get("street") or "").strip(),
        "city": (address.get("city") or "").strip(),
        "state": (address.get("state") or "").strip(),
        "postal_code": (address.get("postal_code") or address.get("zip") or "").strip(),
    }


def find_local_property_by_address(db, street, city, state, postal_code):
    if not street or not city:
        return None
    normalized_street = normalize_address_match_text(street)
    normalized_city = normalize_address_match_text(city)
    normalized_state = normalize_state_code(state)
    normalized_postal = normalize_postal_code(postal_code)

    row = db.execute(
        """
        SELECT p.id
        FROM properties p
        JOIN addresses a ON a.id = p.property_address_id
        WHERE lower(a.street) = lower(?)
          AND lower(a.city) = lower(?)
          AND lower(a.state) = lower(?)
          AND lower(a.postal_code) = lower(?)
        ORDER BY p.id DESC
        LIMIT 1
        """,
        (street, city, state, postal_code),
    ).fetchone()
    if row:
        return row["id"]

    candidate_rows = db.execute(
        """
        SELECT p.id, a.street, a.city, a.state, a.postal_code
        FROM properties p
        JOIN addresses a ON a.id = p.property_address_id
        WHERE lower(a.city) = lower(?)
          AND lower(a.state) = lower(?)
        ORDER BY p.id DESC
        """,
        (city, normalized_state or state),
    ).fetchall()
    for candidate in candidate_rows:
        if normalize_address_match_text(candidate["street"]) != normalized_street:
            continue
        if normalize_address_match_text(candidate["city"]) != normalized_city:
            continue
        if normalize_state_code(candidate["state"]) != normalized_state:
            continue
        if normalized_postal and normalize_postal_code(candidate["postal_code"]) != normalized_postal:
            continue
        return candidate["id"]
    return None


def ensure_property_in_d4d(db, address, added_by="", source="Slack command", raw_input=""):
    street = normalize_whitespace(address.get("street"))
    city = normalize_whitespace(address.get("city"))
    state = normalize_state_code(address.get("state"))
    postal_code = normalize_postal_code(address.get("postal_code"))
    if not street or not city or not state:
        raise ValueError("street, city, and state are required")

    property_id = find_local_property_by_address(db, street, city, state, postal_code)
    now_text = format_db_time(datetime.utcnow())
    actor = normalize_whitespace(added_by) or "Slack"
    note_line = f"D4D lead flagged via {source} on {now_text} by {actor}."
    payload = {
        "address": {
            "street": street,
            "city": city,
            "state": state,
            "postal_code": postal_code,
        },
        "source": source,
        "added_by": actor,
        "raw_input": raw_input,
    }

    if property_id:
        existing = db.execute(
            """
            SELECT id, owner_person_id, notes, COALESCE(is_d4d, 0) AS is_d4d
            FROM properties
            WHERE id = ?
            """,
            (property_id,),
        ).fetchone()
        was_marked = int(existing["is_d4d"] or 0) == 0
        if was_marked:
            db.execute(
                """
                UPDATE properties
                SET is_d4d = 1,
                    d4d_added_at = COALESCE(NULLIF(d4d_added_at, ''), ?),
                    d4d_added_by = COALESCE(NULLIF(d4d_added_by, ''), ?),
                    d4d_source = COALESCE(NULLIF(d4d_source, ''), ?),
                    notes = ?
                WHERE id = ?
                """,
                (
                    now_text,
                    actor,
                    source,
                    append_note_line(existing["notes"], note_line),
                    property_id,
                ),
            )
            db.execute(
                """
                INSERT INTO activity_log (property_id, person_id, activity_type, outcome, note)
                VALUES (?, ?, ?, ?, ?)
                """,
                (
                    property_id,
                    existing["owner_person_id"],
                    "D4D Intake",
                    "Existing property marked for D4D",
                    json.dumps(payload),
                ),
            )
        return {
            "property_id": property_id,
            "created": False,
            "marked_for_d4d": was_marked,
            "already_d4d": not was_marked,
            "owner_person_id": existing["owner_person_id"],
        }

    address_id = create_address(db, street, city, state, postal_code)
    property_notes = note_line
    cur = db.execute(
        """
        INSERT INTO properties (
            property_address_id,
            owner_person_id,
            resident_person_id,
            status,
            notes,
            is_d4d,
            d4d_added_at,
            d4d_added_by,
            d4d_source
        )
        VALUES (?, NULL, NULL, ?, ?, 1, ?, ?, ?)
        """,
        (
            address_id,
            "Untouched",
            property_notes,
            now_text,
            actor,
            source,
        ),
    )
    property_id = cur.lastrowid
    db.execute(
        """
        INSERT INTO activity_log (property_id, person_id, activity_type, outcome, note)
        VALUES (?, NULL, ?, ?, ?)
        """,
        (
            property_id,
            "D4D Intake",
            "New D4D property created",
            json.dumps(payload),
        ),
    )
    return {
        "property_id": property_id,
        "created": True,
        "marked_for_d4d": True,
        "already_d4d": False,
        "owner_person_id": None,
    }


def ensure_local_property_for_reisift_sync(
    db,
    property_uuid,
    owner_uuid="",
    address=None,
    source="ReiSift one-off sync",
    added_by="System",
):
    property_uuid = normalize_uuid(property_uuid or "")
    owner_uuid = normalize_uuid(owner_uuid or "")
    address = address or {}
    street = normalize_whitespace(address.get("street"))
    city = normalize_whitespace(address.get("city"))
    state = normalize_state_code(address.get("state"))
    postal_code = normalize_postal_code(address.get("postal_code"))
    if not street or not city or not state:
        raise ValueError("street, city, and state are required to create local property context")

    property_id = None
    if property_uuid and _table_has_column(db, "properties", "reisift_property_uuid"):
        row = db.execute(
            "SELECT id FROM properties WHERE reisift_property_uuid = ? ORDER BY id DESC LIMIT 1",
            (property_uuid,),
        ).fetchone()
        if row:
            property_id = int(row["id"])
    if not property_id:
        property_id = find_local_property_by_address(db, street, city, state, postal_code)

    now_text = format_db_time(datetime.utcnow())
    actor = normalize_whitespace(added_by) or "System"
    property_note = f"Local property context created via {source} on {now_text} by {actor}."
    payload = {
        "reisift_property_uuid": property_uuid,
        "reisift_owner_uuid": owner_uuid,
        "address": {
            "street": street,
            "city": city,
            "state": state,
            "postal_code": postal_code,
        },
        "source": source,
        "added_by": actor,
    }

    created = False
    if property_id:
        row = db.execute(
            "SELECT notes, owner_person_id FROM properties WHERE id = ? LIMIT 1",
            (property_id,),
        ).fetchone()
        db.execute(
            "UPDATE properties SET notes = ? WHERE id = ?",
            (append_note_line((row["notes"] if row else ""), property_note), property_id),
        )
        db.execute(
            """
            INSERT INTO activity_log (property_id, person_id, activity_type, outcome, note)
            VALUES (?, ?, ?, ?, ?)
            """,
            (
                property_id,
                row["owner_person_id"] if row else None,
                "ReiSift Sync Intake",
                "Existing property linked for one-off sync",
                json.dumps(payload),
            ),
        )
    else:
        address_id = create_address(db, street, city, state, postal_code)
        cur = db.execute(
            """
            INSERT INTO properties (property_address_id, owner_person_id, resident_person_id, status, notes)
            VALUES (?, NULL, NULL, ?, ?)
            """,
            (
                address_id,
                "Untouched",
                property_note,
            ),
        )
        property_id = int(cur.lastrowid or 0)
        created = True
        db.execute(
            """
            INSERT INTO activity_log (property_id, person_id, activity_type, outcome, note)
            VALUES (?, NULL, ?, ?, ?)
            """,
            (
                property_id,
                "ReiSift Sync Intake",
                "Local property created for one-off sync",
                json.dumps(payload),
            ),
        )

    if property_uuid:
        _set_local_property_uuid(db, property_id, property_uuid)
    if owner_uuid:
        _set_local_owner_uuid(db, property_id, owner_uuid)

    return {
        "property_id": property_id,
        "created": created,
        "address": {
            "street": street,
            "city": city,
            "state": state,
            "postal_code": postal_code,
        },
    }


def run_property_skip_trace_lookup(db, property_id):
    prop = db.execute(
        """
        SELECT p.id, a.street, a.city, a.state, a.postal_code
        FROM properties p
        JOIN addresses a ON a.id = p.property_address_id
        WHERE p.id = ?
        """,
        (property_id,),
    ).fetchone()
    if not prop:
        raise ValueError("property not found")
    lookup_pkg = call_skipsherpa_property_lookup(
        street=prop["street"],
        city=prop["city"],
        state=prop["state"],
        zipcode=prop["postal_code"],
        db=db,
    )
    summary = import_skipsherpa_property_result(db, property_id, lookup_pkg)
    return {
        "summary": summary,
        "raw": lookup_pkg.get("response") if isinstance(lookup_pkg, dict) else {},
    }


def run_reisift_uuid_skiptrace_sync(db, property_uuid, added_by="System", source="Integration one-off sync"):
    property_uuid = normalize_uuid(property_uuid or "")
    if not property_uuid:
        raise ValueError("property_uuid is required")

    token = reisift_get_access_token()
    reisift_payload = fetch_reisift_property_payload(token, property_uuid)
    owner_uuid = _reisift_find_owner_uuid(reisift_payload)
    address = extract_payload_address(reisift_payload)
    if not address.get("street") or not address.get("city"):
        address = _reisift_find_first_address_dict(reisift_payload)
    intake = ensure_local_property_for_reisift_sync(
        db,
        property_uuid,
        owner_uuid=owner_uuid,
        address=address,
        source=source,
        added_by=added_by,
    )
    property_id = int(intake["property_id"])
    if property_uuid:
        _set_local_property_uuid(db, property_id, property_uuid)
    if owner_uuid:
        _set_local_owner_uuid(db, property_id, owner_uuid)

    lookup_pkg = call_skipsherpa_property_lookup(
        street=intake["address"]["street"],
        city=intake["address"]["city"],
        state=intake["address"]["state"],
        zipcode=intake["address"]["postal_code"],
        db=db,
    )
    summary = import_skipsherpa_property_result(db, property_id, lookup_pkg)
    if owner_uuid:
        _set_local_owner_uuid(db, property_id, owner_uuid)
    return {
        "property_id": property_id,
        "local_created": bool(intake.get("created")),
        "reisift_property_uuid": property_uuid,
        "reisift_owner_uuid": owner_uuid,
        "address": intake["address"],
        "summary": summary,
        "raw": lookup_pkg.get("response") if isinstance(lookup_pkg, dict) else {},
        "reisift_record_url": _sift_record_url(property_uuid),
    }


def collect_property_owner_person_ids_for_reisift_sync(db, property_id):
    property_id = int(property_id or 0)
    if property_id <= 0:
        return []

    row = db.execute(
        "SELECT owner_person_id FROM properties WHERE id = ? LIMIT 1",
        (property_id,),
    ).fetchone()
    owner_person_id = int((row["owner_person_id"] if row else 0) or 0)
    if owner_person_id <= 0:
        return []

    person_ids = [owner_person_id]
    seen_ids = {owner_person_id}
    co_owner_rows = db.execute(
        """
        SELECT subject_person_id, related_person_id
        FROM person_relationships
        WHERE relationship_type = 'Co-Owner'
          AND (subject_person_id = ? OR related_person_id = ?)
        ORDER BY id ASC
        """,
        (owner_person_id, owner_person_id),
    ).fetchall()
    for rel in co_owner_rows:
        subject_id = int(rel["subject_person_id"] or 0)
        related_id = int(rel["related_person_id"] or 0)
        candidate_id = related_id if subject_id == owner_person_id else subject_id
        if candidate_id <= 0 or candidate_id in seen_ids:
            continue
        seen_ids.add(candidate_id)
        person_ids.append(candidate_id)
    return person_ids


def sync_d4d_property_to_reisift(db, property_id, added_by="", source="Slack D4D"):
    property_id = int(property_id or 0)
    if property_id <= 0:
        raise ValueError("property_id is required")

    prop = db.execute(
        """
        SELECT p.id,
               p.owner_person_id,
               p.reisift_property_uuid,
               p.reisift_owner_uuid,
               a.street,
               a.city,
               a.state,
               a.postal_code
        FROM properties p
        JOIN addresses a ON a.id = p.property_address_id
        WHERE p.id = ?
        LIMIT 1
        """,
        (property_id,),
    ).fetchone()
    if not prop:
        raise ValueError("property not found")

    owner_person_id = int(prop["owner_person_id"] or 0)
    owner_person_ids = collect_property_owner_person_ids_for_reisift_sync(db, property_id)
    phone_items, email_items = collect_person_contact_items_for_reisift_sync(db, owner_person_ids)

    owner_first = "Unknown"
    owner_last = "Owner"
    if owner_person_id > 0:
        owner_row = db.execute(
            "SELECT first_name, last_name FROM people WHERE id = ? LIMIT 1",
            (owner_person_id,),
        ).fetchone()
        if owner_row:
            owner_first = normalize_whitespace(owner_row["first_name"] or "") or owner_first
            owner_last = normalize_whitespace(owner_row["last_name"] or "") or owner_last

    property_uuid = normalize_uuid(prop["reisift_property_uuid"] or "")
    owner_uuid = normalize_uuid(prop["reisift_owner_uuid"] or "")
    had_local_uuid_before = bool(property_uuid)
    actor = normalize_whitespace(added_by) or "Slack"
    now_text = format_db_time(datetime.utcnow())
    address_line = format_property_address_line(prop["street"], prop["city"], prop["state"], prop["postal_code"])
    notes = f"D4D lead synced from {source} on {now_text} by {actor}. Local property #{property_id}."
    out = {
        "ok": False,
        "property_id": property_id,
        "property_uuid": property_uuid,
        "owner_uuid": owner_uuid,
        "created": False,
        "duplicate_existing": False,
        "contact_sync": None,
        "phones_count": len(phone_items),
        "emails_count": len(email_items),
        "owner_person_ids": owner_person_ids,
        "sift_record_url": _sift_record_url(property_uuid),
        "create_result": None,
        "status_result": None,
        "list_sync": None,
        "tag_sync": None,
        "note_sync": None,
        "task_result": None,
        "warnings": [],
    }

    token = None
    create_result = None

    if not property_uuid:
        token = reisift_get_access_token()
        existing_match = reisift_find_existing_property_by_address(
            token,
            street=prop["street"],
            city=prop["city"],
            state=prop["state"],
            postal_code=prop["postal_code"],
            search_text=address_line,
        )
        if existing_match:
            property_uuid = normalize_uuid(existing_match.get("uuid") or "")
            out["duplicate_existing"] = bool(property_uuid)
            out["property_uuid"] = property_uuid
            out["sift_record_url"] = _sift_record_url(property_uuid)
        if not property_uuid:
            create_payload = {
                "search": address_line,
                "street": prop["street"],
                "city": prop["city"],
                "state": prop["state"],
                "postal_code": prop["postal_code"],
                "status": "new_lead",
                "lists": "Driving For Dollars",
                "tags": "Driving For Dollars,D4D",
                "notes": notes,
                "owner": {
                    "first_name": owner_first,
                    "last_name": owner_last,
                    "address_street": prop["street"],
                    "address_city": prop["city"],
                    "address_state": prop["state"],
                    "address_postal_code": prop["postal_code"],
                    "emails": email_items,
                    "phones": phone_items,
                },
            }
            try:
                create_result = create_reisift_property_from_search(create_payload)
                property_uuid = normalize_uuid(create_result.get("created_uuid") or "")
                owner_uuid = normalize_uuid(create_result.get("owner_uuid") or "")
                out["created"] = bool(property_uuid) and not bool(create_result.get("duplicate_existing"))
                out["duplicate_existing"] = bool(create_result.get("duplicate_existing"))
                out["create_result"] = create_result
            except Exception as exc:
                out["warnings"].append(f"ReiSift create failed: {exc}")
                existing_match = reisift_find_existing_property_by_address(
                    token,
                    street=prop["street"],
                    city=prop["city"],
                    state=prop["state"],
                    postal_code=prop["postal_code"],
                    search_text=address_line,
                )
                if not existing_match:
                    raise
                property_uuid = normalize_uuid(existing_match.get("uuid") or "")
                out["duplicate_existing"] = bool(property_uuid)
                out["warnings"].append("Recovered by linking to an existing ReiSift property.")

            out["property_uuid"] = property_uuid
            out["owner_uuid"] = owner_uuid
            if property_uuid:
                _set_local_property_uuid(db, property_id, property_uuid)
                out["sift_record_url"] = _sift_record_url(property_uuid)

    if property_uuid:
        token = token or reisift_get_access_token()
        _set_local_property_uuid(db, property_id, property_uuid)
        if not owner_uuid:
            details = fetch_reisift_property_payload(token, property_uuid)
            owner_uuid = normalize_uuid(_reisift_find_owner_uuid(details) or "")
            out["owner_uuid"] = owner_uuid
        if owner_uuid:
            _set_local_owner_uuid(db, property_id, owner_uuid)
        try:
            out["status_result"] = reisift_update_property_status(token, property_uuid, "new_lead")
        except Exception as exc:
            out["warnings"].append(f"ReiSift status update failed: {exc}")
        try:
            out["list_sync"] = reisift_sync_property_lists(token, property_uuid, ["Driving For Dollars"])
        except Exception as exc:
            out["warnings"].append(f"ReiSift list sync failed: {exc}")
        try:
            d4d_tags = ["D4D", "Driving For Dollars"]
            if phone_items or email_items:
                d4d_tags.extend(build_reisift_skiptrace_tags())
            out["tag_sync"] = reisift_append_property_tags(token, property_uuid, d4d_tags)
        except Exception as exc:
            out["warnings"].append(f"ReiSift tag sync failed: {exc}")
        try:
            out["note_sync"] = reisift_append_property_note(token, property_uuid, notes)
        except Exception as exc:
            out["warnings"].append(f"ReiSift note sync failed: {exc}")
        if owner_uuid and (phone_items or email_items):
            out["contact_sync"] = sync_skiptrace_contacts_to_reisift_owner(
                db,
                property_id,
                phone_items=phone_items,
                email_items=email_items,
            )
        if not had_local_uuid_before and reisift_task_writes_enabled():
            try:
                out["task_result"] = reisift_create_task(
                    token,
                    title="Call New D4D Lead",
                    address=address_line,
                    assigned_to_property=property_uuid,
                    assigned_to_user=REISIFT_UNTITLED_TASK_ASSIGNED_TO_USER,
                    due_date=_reisift_due_tomorrow_noon_utc_text(),
                    all_day=True,
                    notes=f"D4D lead synced from {source}. Review local property #{property_id}.",
                )
            except Exception as exc:
                out["warnings"].append(f"ReiSift task create failed: {exc}")
    out["ok"] = bool(property_uuid)

    activity_note = {
        "source": source,
        "added_by": actor,
        "address": {
            "street": prop["street"],
            "city": prop["city"],
            "state": prop["state"],
            "postal_code": prop["postal_code"],
        },
        "property_uuid": property_uuid,
        "owner_uuid": owner_uuid,
        "created": out["created"],
        "duplicate_existing": out["duplicate_existing"],
        "phones_count": out["phones_count"],
        "emails_count": out["emails_count"],
        "contact_sync": out["contact_sync"],
    }
    db.execute(
        """
        INSERT INTO activity_log (property_id, person_id, activity_type, outcome, note)
        VALUES (?, ?, ?, ?, ?)
        """,
        (
            property_id,
            owner_person_id or None,
            "D4D Intake",
            "Property synced to ReiSift" if out["ok"] else "Property sync to ReiSift pending",
            json.dumps(activity_note, default=str),
        ),
    )
    return out


def build_d4d_property_url(base_url, property_id):
    root = (base_url or "").strip().rstrip("/")
    return f"{root}/property/{int(property_id)}" if root else f"/property/{int(property_id)}"


def build_d4d_dashboard_url(base_url):
    root = (base_url or "").strip().rstrip("/")
    return f"{root}/d4d" if root else "/d4d"


def build_d4d_completion_lines(
    db,
    property_id,
    intake,
    parsed,
    skip_trace_result=None,
    skip_trace_error="",
    reisift_sync_result=None,
    reisift_sync_error="",
    base_url="",
):
    prop_row = db.execute(
        """
        SELECT p.id,
               p.status,
               p.owner_person_id,
               p.reisift_property_uuid,
               a.street,
               a.city,
               a.state,
               a.postal_code,
               op.first_name AS owner_first,
               op.middle_name AS owner_middle,
               op.last_name AS owner_last
        FROM properties p
        JOIN addresses a ON a.id = p.property_address_id
        LEFT JOIN people op ON op.id = p.owner_person_id
        WHERE p.id = ?
        """,
        (property_id,),
    ).fetchone()

    owner_name = ""
    owner_phone_numbers = []
    if prop_row and prop_row["owner_person_id"]:
        owner_name = " ".join(
            [
                x
                for x in [
                    (prop_row["owner_first"] or "").strip(),
                    (prop_row["owner_middle"] or "").strip(),
                    (prop_row["owner_last"] or "").strip(),
                ]
                if x
            ]
        ).strip()
        owner_phone_numbers = [
            format_phone_display(number)
            for number in get_display_phone_numbers_for_person(db, prop_row["owner_person_id"])
        ]

    address_line = format_property_address_line(
        parsed.get("street"),
        parsed.get("city"),
        parsed.get("state"),
        parsed.get("postal_code"),
    )
    property_url = build_d4d_property_url(base_url, property_id)
    d4d_url = build_d4d_dashboard_url(base_url)

    if intake.get("created"):
        headline = f"New D4D lead created in SIFT as property #{property_id}."
    elif intake.get("marked_for_d4d"):
        headline = f"Existing property #{property_id} found in SIFT and added to D4D."
    else:
        headline = f"Property #{property_id} already exists in SIFT and is already tracked in D4D."

    lines = [
        headline,
        f"Address: {address_line}",
        f"Status: {(prop_row['status'] if prop_row else 'Untouched') or 'Untouched'}",
    ]
    if skip_trace_result and owner_name:
        lines.append(f"Retrieve complete. Owner: {owner_name}")
    elif skip_trace_result:
        lines.append("Retrieve complete.")
    elif skip_trace_error:
        lines.append(f"Retrieve failed: {skip_trace_error}")
    elif owner_name:
        lines.append(f"Owner already on file: {owner_name}")
    if owner_phone_numbers:
        lines.append(f"Phones: {', '.join(owner_phone_numbers[:5])}")
    elif owner_name:
        lines.append("Phones: none on file yet.")
    property_uuid = normalize_uuid((prop_row["reisift_property_uuid"] if prop_row else "") or "")
    if reisift_sync_result and reisift_sync_result.get("ok") and (reisift_sync_result.get("property_uuid") or property_uuid):
        effective_uuid = normalize_uuid(reisift_sync_result.get("property_uuid") or property_uuid)
        sift_url = _sift_record_url(effective_uuid)
        if reisift_sync_result.get("created"):
            lines.append(f"ReiSift: created <{sift_url}|Open Sift record>.")
        elif reisift_sync_result.get("duplicate_existing"):
            lines.append(f"ReiSift: linked to existing record <{sift_url}|Open Sift record>.")
        else:
            lines.append(f"ReiSift: synced <{sift_url}|Open Sift record>.")
    elif reisift_sync_error:
        lines.append(f"ReiSift sync failed: {reisift_sync_error}")
    elif property_uuid:
        lines.append(f"ReiSift: <{_sift_record_url(property_uuid)}|Open Sift record>.")
    lines.append(f"SIFT record: <{property_url}|Open property #{property_id}>")
    lines.append(f"D4D queue: <{d4d_url}|Open D4D queue>")
    return lines


def process_d4d_slack_intake(response_url, address_text, raw_text="", added_by="", base_url=""):
    db = open_sqlite_connection()
    try:
        parsed = parse_freeform_property_address(address_text)
        intake = ensure_property_in_d4d(
            db,
            parsed,
            added_by=added_by,
            source="Slack D4D",
            raw_input=raw_text,
        )
        commit_with_retry(db)

        skip_trace_result = None
        skip_trace_error = ""
        reisift_sync_result = None
        reisift_sync_error = ""
        should_skip_trace = bool(intake.get("created")) or not intake.get("owner_person_id")
        if should_skip_trace:
            try:
                skip_trace_result = run_property_skip_trace_lookup(db, intake["property_id"])
                commit_with_retry(db)
            except Exception as exc:
                db.rollback()
                skip_trace_error = str(exc)
                existing = db.execute("SELECT notes, owner_person_id FROM properties WHERE id = ?", (intake["property_id"],)).fetchone()
                db.execute(
                    "UPDATE properties SET notes = ? WHERE id = ?",
                    (
                        append_note_line(
                            existing["notes"] if existing else "",
                            f"D4D auto skip trace failed: {skip_trace_error}",
                        ),
                        intake["property_id"],
                    ),
                )
                db.execute(
                    """
                    INSERT INTO activity_log (property_id, person_id, activity_type, outcome, note)
                    VALUES (?, ?, ?, ?, ?)
                    """,
                    (
                        intake["property_id"],
                        existing["owner_person_id"] if existing else None,
                        "D4D Intake",
                        "Property auto skip trace failed",
                        json.dumps({"error": skip_trace_error, "address": parsed, "raw_input": raw_text}),
                    ),
                )
                commit_with_retry(db)

        try:
            reisift_sync_result = sync_d4d_property_to_reisift(
                db,
                intake["property_id"],
                added_by=added_by,
                source="Slack D4D",
            )
            commit_with_retry(db)
        except Exception as exc:
            db.rollback()
            reisift_sync_error = str(exc)
            existing = db.execute(
                "SELECT notes, owner_person_id FROM properties WHERE id = ?",
                (intake["property_id"],),
            ).fetchone()
            db.execute(
                "UPDATE properties SET notes = ? WHERE id = ?",
                (
                    append_note_line(
                        existing["notes"] if existing else "",
                        f"D4D ReiSift sync failed: {reisift_sync_error}",
                    ),
                    intake["property_id"],
                ),
            )
            db.execute(
                """
                INSERT INTO activity_log (property_id, person_id, activity_type, outcome, note)
                VALUES (?, ?, ?, ?, ?)
                """,
                (
                    intake["property_id"],
                    existing["owner_person_id"] if existing else None,
                    "D4D Intake",
                    "Property sync to ReiSift failed",
                    json.dumps({"error": reisift_sync_error, "address": parsed, "raw_input": raw_text}),
                ),
            )
            commit_with_retry(db)

        lines = build_d4d_completion_lines(
            db,
            intake["property_id"],
            intake,
            parsed,
            skip_trace_result=skip_trace_result,
            skip_trace_error=skip_trace_error,
            reisift_sync_result=reisift_sync_result,
            reisift_sync_error=reisift_sync_error,
            base_url=base_url,
        )
        if response_url:
            send_slack_response_url(response_url, "\n".join(lines), response_type="in_channel", replace_original=True)
        return {
            "ok": True,
            "property_id": intake["property_id"],
            "lines": lines,
            "reisift_sync_result": reisift_sync_result,
            "reisift_sync_error": reisift_sync_error,
        }
    except Exception as exc:
        db.rollback()
        message = (
            f"Could not add D4D lead: {exc}\n"
            "Use `d4d 123 Main St, Newark, NJ 07102` or `d4d 123 Main St Newark NJ`."
        )
        if response_url:
            try:
                send_slack_response_url(response_url, message, response_type="in_channel", replace_original=True)
            except Exception:
                pass
        return {"ok": False, "error": str(exc), "message": message}
    finally:
        db.close()


def launch_d4d_slack_intake(response_url, address_text, raw_text="", added_by="", base_url=""):
    worker = threading.Thread(
        target=process_d4d_slack_intake,
        kwargs={
            "response_url": response_url,
            "address_text": address_text,
            "raw_text": raw_text,
            "added_by": added_by,
            "base_url": base_url,
        },
        daemon=True,
    )
    worker.start()
    return worker


def _normalize_counties_csv(values):
    county_map = {str(option).strip().lower(): str(option).strip() for option in (NJ_COUNTIES or []) if str(option).strip()}
    cleaned = []
    raw_values = split_markets(values) if isinstance(values, str) else list(values or [])
    for value in raw_values:
        raw = str(value or "").strip()
        if not raw:
            continue
        lookup = re.sub(r"\s+county$", "", raw, flags=re.IGNORECASE).strip().lower()
        canonical = county_map.get(lookup)
        if canonical and canonical not in cleaned:
            cleaned.append(canonical)
    return join_markets(cleaned)


def _extract_wrapped_slack_arg(text, label):
    pattern = re.compile(rf"(?i)\b{re.escape(label)}\s*\((.*?)\)")
    match = pattern.search(text or "")
    if not match:
        return "", (text or "")
    value = (match.group(1) or "").strip()
    remaining = ((text or "")[: match.start()] + " " + (text or "")[match.end() :]).strip()
    remaining = re.sub(r"\s{2,}", " ", remaining).strip()
    return value, remaining


def _extract_first_phone_like(text):
    candidates = re.findall(r"(?:\+?1[\s\-.()]*)?(?:\(?\d{3}\)?[\s\-.()]*)\d{3}[\s\-.()]*\d{4}", text or "")
    for candidate in candidates:
        norm = normalize_phone(candidate)
        if len(norm) == 10:
            return candidate.strip(), norm
    return "", ""


def _extract_first_email_like(text):
    match = EMAIL_RE.search(text or "")
    if not match:
        return "", ""
    raw = match.group(0).strip()
    return raw, normalize_email(raw)


def _slack_command_remaining_text_without_value(text, value):
    if not text or not value:
        return text or ""
    pattern = re.compile(re.escape(value), re.IGNORECASE)
    remaining = pattern.sub(" ", text, count=1)
    remaining = re.sub(r"\s{2,}", " ", remaining).strip()
    return remaining


def _parse_slack_buyer_name(remaining_text):
    text = normalize_whitespace(remaining_text or "")
    if not text:
        return "", "", ""
    tokens = [re.sub(r"^[^\w]+|[^\w'.-]+$", "", token) for token in text.split()]
    tokens = [token for token in tokens if token]
    if len(tokens) >= 2:
        return tokens[0], tokens[1], " ".join(tokens[2:]).strip()
    if len(tokens) == 1:
        return tokens[0], "Buyer", ""
    return "", "", ""


def parse_slack_buyer_command(raw_text):
    original = normalize_whitespace(raw_text or "")
    text = original
    if text.lower().startswith("buyer "):
        text = text[6:].strip()
    elif text.lower() == "buyer":
        text = ""

    extracted = {}
    for label in ["county", "category", "type", "email", "business", "notes", "name"]:
        value, text = _extract_wrapped_slack_arg(text, label)
        extracted[label] = value

    phone_raw, phone_norm = _extract_first_phone_like(text)
    text = _slack_command_remaining_text_without_value(text, phone_raw)

    inferred_email_raw, inferred_email = _extract_first_email_like(text)
    if not extracted.get("email"):
        extracted["email"] = inferred_email_raw
    text = _slack_command_remaining_text_without_value(text, inferred_email_raw)

    explicit_name = normalize_whitespace(extracted.get("name") or "")
    if explicit_name:
        first_name, last_name, leftover_name = _parse_slack_buyer_name(explicit_name)
    else:
        first_name, last_name, leftover_name = _parse_slack_buyer_name(text)
        text = leftover_name

    normalized_email = normalize_email(extracted.get("email") or inferred_email or "")
    business_name = normalize_whitespace(extracted.get("business") or "")
    notes_value = normalize_whitespace(extracted.get("notes") or "")
    leftover_notes = normalize_whitespace(text or "")
    notes_parts = []
    if notes_value:
        notes_parts.append(notes_value)
    if leftover_notes:
        notes_parts.append(f"Unparsed Slack text: {leftover_notes}")
    notes_parts.append(f"Slack intake: {original}")
    counties = _normalize_counties_csv(extracted.get("county") or "")
    buyer_categories = normalize_option_csv(
        split_markets(extracted.get("category") or ""),
        BUYER_ROLE_OPTIONS,
        BUYER_ROLE_ALIASES,
    )
    property_types = normalize_option_csv(
        split_markets(extracted.get("type") or ""),
        BUYER_PROPERTY_TYPE_OPTIONS,
        BUYER_PROPERTY_TYPE_ALIASES,
    )

    if not first_name and business_name:
        first_name = business_name
        last_name = "Buyer"
    elif not first_name:
        first_name = "Unknown"
        last_name = "Buyer"
    elif not last_name:
        last_name = "Buyer"

    return {
        "ok": bool(phone_norm),
        "phone_raw": phone_raw.strip(),
        "phone_norm": phone_norm,
        "phone_display": phone_raw.strip() or phone_norm,
        "email": normalized_email,
        "first_name": first_name,
        "last_name": last_name,
        "business_name": business_name,
        "target_counties": counties,
        "buyer_categories": buyer_categories,
        "property_types": property_types,
        "notes": "\n".join([part for part in notes_parts if part]).strip(),
        "raw_text": original,
        "error": "" if phone_norm else "A phone number is required. Example: buyer 9735551212 John Smith county(Essex) category(Wholesaler) type(SFR)",
    }


def _find_existing_buyer_row(db, phone_norm="", email=""):
    phone_norm = normalize_phone(phone_norm or "")
    email_norm = normalize_email(email or "")
    rows = db.execute(
        """
        SELECT *
        FROM buyers
        ORDER BY id DESC
        """
    ).fetchall()
    email_match = None
    for row in rows or []:
        row_phone = normalize_phone(row["phone"] or "")
        row_email = normalize_email(row["email"] or "")
        if phone_norm and row_phone == phone_norm:
            return row
        if email_norm and row_email == email_norm and email_match is None:
            email_match = row
    return email_match


def upsert_buyer_from_slack_command(db, parsed, added_by=""):
    phone_norm = normalize_phone(parsed.get("phone_norm") or parsed.get("phone_raw") or "")
    if not phone_norm:
        raise ValueError("A phone number is required for buyer intake.")

    existing = _find_existing_buyer_row(db, phone_norm=phone_norm, email=parsed.get("email") or "")
    now_text = format_est_datetime(datetime.utcnow().strftime("%Y-%m-%d %H:%M:%S"))
    actor = normalize_whitespace(added_by or "") or "Slack"
    intake_note = f"Slack buyer intake on {now_text} by {actor}."
    combined_notes = "\n".join([x for x in [parsed.get("notes") or "", intake_note] if x]).strip()

    if existing:
        first_name = (parsed.get("first_name") or existing["first_name"] or "").strip() or "Unknown"
        last_name = (parsed.get("last_name") or existing["last_name"] or "").strip() or "Buyer"
        business_name = (parsed.get("business_name") or existing["business_name"] or "").strip()
        email_value = normalize_email(parsed.get("email") or existing["email"] or "")
        phone_value = (parsed.get("phone_display") or existing["phone"] or phone_norm).strip()
        target_counties = _normalize_counties_csv(
            split_markets(existing["target_counties"] or "") + split_markets(parsed.get("target_counties") or "")
        )
        buyer_categories = normalize_option_csv(
            split_markets(existing["buyer_categories"] or "") + split_markets(parsed.get("buyer_categories") or ""),
            BUYER_ROLE_OPTIONS,
            BUYER_ROLE_ALIASES,
        )
        property_types = normalize_option_csv(
            split_markets(existing["property_types"] or "") + split_markets(parsed.get("property_types") or ""),
            BUYER_PROPERTY_TYPE_OPTIONS,
            BUYER_PROPERTY_TYPE_ALIASES,
        )
        existing_notes = (existing["notes"] or "").strip()
        notes = "\n\n".join([x for x in [existing_notes, combined_notes] if x]).strip()
        db.execute(
            """
            UPDATE buyers
            SET first_name = ?, last_name = ?, business_name = ?, email = ?, phone = ?, notes = ?,
                target_counties = ?, buyer_categories = ?, property_types = ?
            WHERE id = ?
            """,
            (
                first_name,
                last_name,
                business_name,
                email_value,
                phone_value,
                notes,
                target_counties,
                buyer_categories,
                property_types,
                int(existing["id"]),
            ),
        )
        buyer_id = int(existing["id"])
        action = "updated"
    else:
        cur = db.execute(
            """
            INSERT INTO buyers
            (first_name, last_name, business_name, email, phone, notes, target_counties, buyer_categories, property_types)
            VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)
            """,
            (
                (parsed.get("first_name") or "Unknown").strip(),
                (parsed.get("last_name") or "Buyer").strip(),
                (parsed.get("business_name") or "").strip(),
                normalize_email(parsed.get("email") or ""),
                (parsed.get("phone_display") or phone_norm).strip(),
                combined_notes,
                parsed.get("target_counties") or "",
                parsed.get("buyer_categories") or "",
                parsed.get("property_types") or "",
            ),
        )
        buyer_id = int(cur.lastrowid or 0)
        action = "created"

    upsert_cached_contact_context(
        db,
        phone_norm,
        classification="buyer",
        source="slack_buyer_intake",
        confidence=0.95,
        notes=f"Buyer {action} from Slack command (buyer_id={buyer_id}).",
        last_reisift_lookup_at=format_db_time(datetime.utcnow()),
    )

    row = db.execute("SELECT * FROM buyers WHERE id = ?", (buyer_id,)).fetchone()
    return {"buyer_id": buyer_id, "action": action, "buyer": dict(row) if row else {}}


def build_market_status_helper(address_text):
    address = " ".join((address_text or "").strip().split())
    if not address:
        return {"query": "", "links": []}
    encoded = quote_plus(address)
    return {
        "query": address,
        "links": [
            {
                "label": "Zillow Search",
                "url": f"https://www.google.com/search?q=site%3Azillow.com+{encoded}",
            },
            {
                "label": "Realtor.com Search",
                "url": f"https://www.google.com/search?q=site%3Arealtor.com+{encoded}",
            },
            {
                "label": "Redfin Search",
                "url": f"https://www.google.com/search?q=site%3Aredfin.com+{encoded}",
            },
            {
                "label": "General Search",
                "url": f"https://www.google.com/search?q={encoded}",
            },
        ],
    }


def _authority_clean_text(value, max_len=420):
    text = unescape(str(value or ""))
    if "<" in text and ">" in text:
        if BeautifulSoup:
            try:
                text = BeautifulSoup(text, "html.parser").get_text(" ")
            except Exception:
                text = re.sub(r"<[^>]+>", " ", text)
        else:
            text = re.sub(r"<[^>]+>", " ", text)
    text = re.sub(r"\s+", " ", text).strip()
    if max_len and len(text) > max_len:
        return text[: max_len - 3].rstrip() + "..."
    return text


def _authority_tag_name(tag):
    raw = str(tag or "")
    if "}" in raw:
        return raw.split("}", 1)[1].lower()
    return raw.lower()


def _authority_direct_child_text(node, accepted_names):
    accepted = {str(x).strip().lower() for x in (accepted_names or []) if str(x).strip()}
    for child in list(node or []):
        if _authority_tag_name(child.tag) in accepted:
            return _authority_clean_text(" ".join(child.itertext()), max_len=800)
    return ""


def _authority_direct_child_link(node):
    for child in list(node or []):
        if _authority_tag_name(child.tag) != "link":
            continue
        href = str(child.attrib.get("href") or "").strip()
        if href.startswith("http://") or href.startswith("https://"):
            return href
        text_value = _authority_clean_text(" ".join(child.itertext()), max_len=800)
        if text_value.startswith("http://") or text_value.startswith("https://"):
            return text_value
    return ""


def _authority_parse_xml_entries(xml_root, max_items=10):
    entries = []
    max_items = max(1, int(max_items or 10))
    root_name = _authority_tag_name(xml_root.tag)
    if root_name == "rss":
        channel = None
        for child in list(xml_root):
            if _authority_tag_name(child.tag) == "channel":
                channel = child
                break
        if channel is None:
            channel = xml_root
        for item in list(channel):
            if _authority_tag_name(item.tag) != "item":
                continue
            title = _authority_direct_child_text(item, ["title"])
            url = _authority_direct_child_text(item, ["link"])
            summary = _authority_direct_child_text(item, ["description", "content", "content:encoded"])
            published_at = _authority_direct_child_text(item, ["pubdate", "published", "updated", "dc:date"])
            if title or url:
                entries.append(
                    {
                        "title": title or "Untitled update",
                        "url": url,
                        "summary": summary,
                        "published_at": published_at,
                    }
                )
            if len(entries) >= max_items:
                break
        return entries

    # Atom-style feeds (and mixed XML payloads with <entry>).
    for node in list(xml_root):
        if _authority_tag_name(node.tag) != "entry":
            continue
        title = _authority_direct_child_text(node, ["title"])
        url = _authority_direct_child_link(node)
        summary = _authority_direct_child_text(node, ["summary", "content"])
        published_at = _authority_direct_child_text(node, ["published", "updated"])
        if title or url:
            entries.append(
                {
                    "title": title or "Untitled update",
                    "url": url,
                    "summary": summary,
                    "published_at": published_at,
                }
            )
        if len(entries) >= max_items:
            break
    return entries


def _authority_fetch_feed_entries(feed_url, max_items=10):
    if not str(feed_url or "").strip():
        raise ValueError("Feed URL is required.")
    headers = {"User-Agent": "DeepSift Authority Researcher/1.0"}
    response = requests.get(str(feed_url).strip(), headers=headers, timeout=25)
    response.raise_for_status()
    body = response.content or b""
    entries = []
    parse_error = ""
    if body:
        try:
            root = ET.fromstring(body)
            entries = _authority_parse_xml_entries(root, max_items=max_items)
        except Exception as exc:
            parse_error = str(exc)
    if not entries and body:
        html_title = ""
        html_summary = ""
        decoded = body.decode("utf-8", errors="ignore")
        if BeautifulSoup:
            try:
                soup = BeautifulSoup(decoded, "html.parser")
                html_title = _authority_clean_text((soup.title.string or "") if soup.title else "", max_len=220)
                desc = soup.find("meta", attrs={"name": "description"}) or soup.find("meta", attrs={"property": "og:description"})
                html_summary = _authority_clean_text(desc.get("content") if desc else "", max_len=320)
            except Exception:
                html_title = ""
                html_summary = ""
        if not html_title:
            match = re.search(r"<title[^>]*>(.*?)</title>", decoded, flags=re.IGNORECASE | re.DOTALL)
            if match:
                html_title = _authority_clean_text(match.group(1), max_len=220)
        if html_title:
            entries = [
                {
                    "title": html_title,
                    "url": str(feed_url).strip(),
                    "summary": html_summary,
                    "published_at": "",
                }
            ]
    if not entries:
        if parse_error:
            raise ValueError(f"No feed entries parsed: {parse_error}")
        raise ValueError("No feed entries parsed from response.")
    cleaned = []
    seen = set()
    for entry in entries:
        title = _authority_clean_text(entry.get("title") or "", max_len=220)
        url = str(entry.get("url") or "").strip()
        summary = _authority_clean_text(entry.get("summary") or "", max_len=420)
        published_at = _authority_clean_text(entry.get("published_at") or "", max_len=80)
        key = (title.lower(), url.lower())
        if key in seen:
            continue
        seen.add(key)
        cleaned.append(
            {
                "title": title or "Untitled update",
                "url": url,
                "summary": summary,
                "published_at": published_at,
            }
        )
        if len(cleaned) >= max(1, int(max_items or 10)):
            break
    if not cleaned:
        raise ValueError("Parsed feed was empty after cleanup.")
    return cleaned


def _authority_extract_keywords(*parts, max_keywords=8):
    words = []
    for part in parts:
        for token in re.findall(r"[A-Za-z0-9\-]{4,}", str(part or "").lower()):
            if token not in words:
                words.append(token)
    return words[: max(1, int(max_keywords or 8))]


def _authority_normalize_idea(raw, default_audience="", default_channel=""):
    item = raw if isinstance(raw, dict) else {}
    title = _authority_clean_text(item.get("title") or "", max_len=220)
    if not title:
        return None
    outline = item.get("outline")
    if not isinstance(outline, list):
        outline = []
    outline = [_authority_clean_text(x, max_len=200) for x in outline if _authority_clean_text(x, max_len=200)]
    keywords = item.get("seo_keywords")
    if not isinstance(keywords, list):
        keywords = []
    keywords = [_authority_clean_text(x, max_len=45).lower() for x in keywords if _authority_clean_text(x, max_len=45)]
    sources = item.get("sources")
    if not isinstance(sources, list):
        sources = []
    normalized_sources = []
    for src in sources:
        if isinstance(src, dict):
            source_title = _authority_clean_text(src.get("title") or src.get("name") or "", max_len=180)
            source_url = str(src.get("url") or "").strip()
            if source_title or source_url:
                normalized_sources.append({"title": source_title, "url": source_url})
        else:
            source_text = _authority_clean_text(src, max_len=220)
            if source_text:
                normalized_sources.append({"title": source_text, "url": ""})
    try:
        confidence = float(item.get("confidence") or 0.0)
    except Exception:
        confidence = 0.0
    confidence = min(max(confidence, 0.0), 1.0)
    return {
        "title": title,
        "angle": _authority_clean_text(item.get("angle") or "", max_len=320),
        "target_audience": _authority_clean_text(item.get("target_audience") or default_audience, max_len=90),
        "platform_primary": _authority_clean_text(item.get("platform_primary") or default_channel, max_len=70),
        "hook": _authority_clean_text(item.get("hook") or "", max_len=320),
        "thesis": _authority_clean_text(item.get("thesis") or "", max_len=500),
        "outline": outline,
        "cta": _authority_clean_text(item.get("cta") or "", max_len=220),
        "seo_keywords": keywords[:10],
        "sources": normalized_sources[:8],
        "confidence": confidence,
    }


def _authority_generate_fallback_ideas(feed_items, focus_topic="", target_audience="", channel_focus="", idea_count=8):
    count = max(1, min(int(idea_count or 8), 25))
    items = list(feed_items or [])
    ideas = []
    if not items:
        seed_topic = _authority_clean_text(focus_topic or "Real estate strategy", max_len=120)
        for idx in range(count):
            base = f"{seed_topic} insight #{idx + 1}"
            ideas.append(
                {
                    "title": base.title(),
                    "angle": f"Translate {seed_topic.lower()} into practical talking points for serious investors.",
                    "target_audience": target_audience or "General Investors",
                    "platform_primary": channel_focus or "LinkedIn Long-Form",
                    "hook": f"What the market is signaling about {seed_topic.lower()} right now.",
                    "thesis": "Frame the opportunity with evidence, risk controls, and an execution perspective from active operators.",
                    "outline": [
                        "Market context and why this matters now",
                        "One decision framework readers can apply immediately",
                        "Risk factors and how experienced operators mitigate them",
                        "Call to discuss strategy with other serious investors",
                    ],
                    "cta": "Invite conversation with other operators and accredited investors.",
                    "seo_keywords": _authority_extract_keywords(seed_topic, target_audience, channel_focus),
                    "sources": [],
                    "confidence": 0.45,
                }
            )
        return ideas

    used = set()
    for item in items:
        title = _authority_clean_text(item.get("title") or "", max_len=220)
        if not title:
            continue
        key = title.lower()
        if key in used:
            continue
        used.add(key)
        url = str(item.get("url") or "").strip()
        summary = _authority_clean_text(item.get("summary") or "", max_len=320)
        feed_name = _authority_clean_text(item.get("feed_name") or "Source", max_len=80)
        angle = f"Use this update to explain second-order implications for acquisition and asset management decisions."
        thesis = summary or "Explain what changed, why it matters, and how disciplined investors should respond."
        ideas.append(
            {
                "title": title,
                "angle": angle,
                "target_audience": target_audience or "General Investors",
                "platform_primary": channel_focus or "LinkedIn Long-Form",
                "hook": f"Signal from {feed_name}: {title}",
                "thesis": thesis,
                "outline": [
                    "What happened and why sophisticated investors should care",
                    "How this changes underwriting, financing, or execution assumptions",
                    "Risks, caveats, and where people usually overreact",
                    "Actionable next step for operators and capital partners",
                ],
                "cta": "Invite peers to compare assumptions and decision rules.",
                "seo_keywords": _authority_extract_keywords(title, summary, focus_topic, target_audience, channel_focus),
                "sources": [{"title": title, "url": url}],
                "confidence": 0.58,
            }
        )
        if len(ideas) >= count:
            break
    while len(ideas) < count:
        ideas.append(
            {
                "title": f"Market pulse idea #{len(ideas) + 1}",
                "angle": "Synthesize multiple market signals into a clear operator playbook.",
                "target_audience": target_audience or "General Investors",
                "platform_primary": channel_focus or "LinkedIn Long-Form",
                "hook": "Where conviction should increase or decrease this week.",
                "thesis": "Discuss practical decision filters instead of broad predictions.",
                "outline": [
                    "Current market context",
                    "What is noise vs signal",
                    "Operator response framework",
                    "Discussion prompt",
                ],
                "cta": "Ask network members how they are adjusting strategy this week.",
                "seo_keywords": _authority_extract_keywords(focus_topic, target_audience, channel_focus),
                "sources": [],
                "confidence": 0.42,
            }
        )
    return ideas[:count]


def _authority_generate_ideas_with_openai(feed_items, focus_topic="", target_audience="", channel_focus="", idea_count=8):
    api_key = os.getenv("OPENAI_API_KEY", "").strip()
    if not api_key:
        raise ValueError("OPENAI_API_KEY is not set")
    model = os.getenv("OPENAI_MODEL", "gpt-4.1-mini").strip() or "gpt-4.1-mini"
    count = max(1, min(int(idea_count or 8), 25))
    corpus = []
    for idx, item in enumerate(list(feed_items or [])[:45], start=1):
        corpus.append(
            (
                f"{idx}. [{_authority_clean_text(item.get('feed_name') or 'Source', max_len=80)}] "
                f"{_authority_clean_text(item.get('title') or '', max_len=200)} | "
                f"{_authority_clean_text(item.get('published_at') or '-', max_len=50)} | "
                f"{_authority_clean_text(item.get('summary') or '', max_len=260)} | "
                f"{str(item.get('url') or '').strip()}"
            )
        )
    corpus_text = "\n".join(corpus)[:14000]
    schema = {
        "name": "authority_research_ideas",
        "schema": {
            "type": "object",
            "additionalProperties": False,
            "properties": {
                "ideas": {
                    "type": "array",
                    "minItems": 1,
                    "maxItems": count,
                    "items": {
                        "type": "object",
                        "additionalProperties": False,
                        "properties": {
                            "title": {"type": "string"},
                            "angle": {"type": "string"},
                            "target_audience": {"type": "string"},
                            "platform_primary": {"type": "string"},
                            "hook": {"type": "string"},
                            "thesis": {"type": "string"},
                            "outline": {"type": "array", "items": {"type": "string"}},
                            "cta": {"type": "string"},
                            "seo_keywords": {"type": "array", "items": {"type": "string"}},
                            "sources": {
                                "type": "array",
                                "items": {
                                    "type": "object",
                                    "additionalProperties": False,
                                    "properties": {
                                        "title": {"type": "string"},
                                        "url": {"type": "string"},
                                    },
                                    "required": ["title", "url"],
                                },
                            },
                            "confidence": {"type": "number"},
                        },
                        "required": [
                            "title",
                            "angle",
                            "target_audience",
                            "platform_primary",
                            "hook",
                            "thesis",
                            "outline",
                            "cta",
                            "seo_keywords",
                            "sources",
                            "confidence",
                        ],
                    },
                }
            },
            "required": ["ideas"],
        },
        "strict": True,
    }
    prompt = (
        "You are the Researcher agent for a real-estate authority content pipeline.\n"
        "Goal: produce high-quality article/post ideas for investors and accredited investors.\n"
        "Audience should never be homeowners.\n"
        "Never promise returns and never make guaranteed-income claims.\n"
        "Use source-backed angles and mention concrete third-party sources.\n"
        f"Generate exactly {count} ideas.\n"
        f"Focus topic: {_authority_clean_text(focus_topic, max_len=120) or '-'}\n"
        f"Target audience: {_authority_clean_text(target_audience, max_len=80) or 'General Investors'}\n"
        f"Primary channel: {_authority_clean_text(channel_focus, max_len=60) or 'LinkedIn Long-Form'}\n\n"
        f"Source corpus:\n{corpus_text}"
    )
    response = requests.post(
        "https://api.openai.com/v1/responses",
        headers={"Authorization": f"Bearer {api_key}", "Content-Type": "application/json"},
        json={
            "model": model,
            "input": [
                {"role": "system", "content": [{"type": "input_text", "text": "You are a strategic research analyst for real estate content."}]},
                {"role": "user", "content": [{"type": "input_text", "text": prompt}]},
            ],
            "text": {"format": {"type": "json_schema", "name": schema["name"], "schema": schema["schema"], "strict": True}},
        },
        timeout=90,
    )
    response.raise_for_status()
    data = response.json()
    output_text = (data.get("output_text") or "").strip()
    payload = {}
    if output_text:
        payload = json.loads(output_text)
    else:
        for item in data.get("output", []):
            for part in item.get("content", []):
                if part.get("type") in {"output_text", "text"} and part.get("text"):
                    payload = json.loads(part["text"])
                    break
            if payload:
                break
    if not isinstance(payload, dict):
        raise ValueError("Authority researcher did not return JSON object output.")
    raw_ideas = payload.get("ideas")
    if not isinstance(raw_ideas, list) or not raw_ideas:
        raise ValueError("Authority researcher returned no ideas.")
    ideas = []
    for raw in raw_ideas[:count]:
        normalized = _authority_normalize_idea(raw, default_audience=target_audience, default_channel=channel_focus)
        if normalized:
            ideas.append(normalized)
    if not ideas:
        raise ValueError("Authority researcher ideas could not be normalized.")
    return ideas[:count], {"model": model}


def run_authority_research_once(
    db,
    *,
    focus_topic="",
    target_audience="",
    channel_focus="",
    requested_idea_count=8,
    selected_feed_ids=None,
):
    idea_count = max(1, min(int(requested_idea_count or 8), 25))
    selected_ids = []
    for raw in selected_feed_ids or []:
        try:
            val = int(raw)
        except Exception:
            continue
        if val > 0 and val not in selected_ids:
            selected_ids.append(val)
    if selected_ids:
        placeholders = ",".join(["?"] * len(selected_ids))
        feed_rows = db.execute(
            f"""
            SELECT id, name, url, feed_type, notes, is_active
            FROM authority_feeds
            WHERE id IN ({placeholders})
            ORDER BY is_active DESC, id DESC
            """,
            tuple(selected_ids),
        ).fetchall()
    else:
        feed_rows = db.execute(
            """
            SELECT id, name, url, feed_type, notes, is_active
            FROM authority_feeds
            WHERE is_active = 1
            ORDER BY id DESC
            """
        ).fetchall()
    if not feed_rows:
        raise ValueError("No feeds selected. Add at least one feed or enable an existing feed.")

    prompt_payload = {
        "focus_topic": (focus_topic or "").strip(),
        "target_audience": (target_audience or "").strip(),
        "channel_focus": (channel_focus or "").strip(),
        "requested_idea_count": idea_count,
        "selected_feed_ids": selected_ids,
    }
    run_cur = db.execute(
        """
        INSERT INTO authority_research_runs
        (status, focus_topic, target_audience, channel_focus, requested_idea_count, selected_feed_ids_json, prompt_json, started_at, updated_at)
        VALUES ('Running', ?, ?, ?, ?, ?, ?, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP)
        """,
        (
            prompt_payload["focus_topic"],
            prompt_payload["target_audience"],
            prompt_payload["channel_focus"],
            idea_count,
            json.dumps(selected_ids),
            json.dumps(prompt_payload),
        ),
    )
    run_id = int(run_cur.lastrowid or 0)
    fetched_items = []
    feed_errors = []
    for feed in feed_rows:
        feed_id = int(feed["id"])
        feed_name = str(feed["name"] or "").strip() or f"Feed {feed_id}"
        feed_url = str(feed["url"] or "").strip()
        try:
            entries = _authority_fetch_feed_entries(feed_url, max_items=8)
            db.execute(
                """
                UPDATE authority_feeds
                SET last_fetched_at = CURRENT_TIMESTAMP,
                    last_fetch_status = 'ok',
                    last_fetch_error = '',
                    updated_at = CURRENT_TIMESTAMP
                WHERE id = ?
                """,
                (feed_id,),
            )
            for entry in entries:
                fetched_items.append(
                    {
                        "feed_id": feed_id,
                        "feed_name": feed_name,
                        "title": entry.get("title") or "",
                        "url": entry.get("url") or "",
                        "summary": entry.get("summary") or "",
                        "published_at": entry.get("published_at") or "",
                    }
                )
        except Exception as exc:
            feed_errors.append(f"{feed_name}: {exc}")
            db.execute(
                """
                UPDATE authority_feeds
                SET last_fetched_at = CURRENT_TIMESTAMP,
                    last_fetch_status = 'error',
                    last_fetch_error = ?,
                    updated_at = CURRENT_TIMESTAMP
                WHERE id = ?
                """,
                (str(exc)[:600], feed_id),
            )

    generation_mode = "fallback"
    generation_meta = {}
    try:
        ideas = []
        if os.getenv("OPENAI_API_KEY", "").strip():
            ideas, generation_meta = _authority_generate_ideas_with_openai(
                fetched_items,
                focus_topic=focus_topic,
                target_audience=target_audience,
                channel_focus=channel_focus,
                idea_count=idea_count,
            )
            generation_mode = "openai"
        else:
            ideas = _authority_generate_fallback_ideas(
                fetched_items,
                focus_topic=focus_topic,
                target_audience=target_audience,
                channel_focus=channel_focus,
                idea_count=idea_count,
            )
    except Exception as exc:
        feed_errors.append(f"Idea generation fallback used: {exc}")
        ideas = _authority_generate_fallback_ideas(
            fetched_items,
            focus_topic=focus_topic,
            target_audience=target_audience,
            channel_focus=channel_focus,
            idea_count=idea_count,
        )
        generation_mode = "fallback"

    inserted_ideas = 0
    for raw in ideas:
        normalized = _authority_normalize_idea(
            raw,
            default_audience=target_audience or "General Investors",
            default_channel=channel_focus or "LinkedIn Long-Form",
        )
        if not normalized:
            continue
        db.execute(
            """
            INSERT INTO authority_research_ideas
            (run_id, title, angle, target_audience, platform_primary, hook, thesis, outline_json, cta, seo_keywords_json, sources_json, confidence, status, editor_notes, updated_at)
            VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 'Draft', '', CURRENT_TIMESTAMP)
            """,
            (
                run_id,
                normalized["title"],
                normalized["angle"],
                normalized["target_audience"],
                normalized["platform_primary"],
                normalized["hook"],
                normalized["thesis"],
                json.dumps(normalized["outline"]),
                normalized["cta"],
                json.dumps(normalized["seo_keywords"]),
                json.dumps(normalized["sources"]),
                float(normalized["confidence"] or 0.0),
            ),
        )
        inserted_ideas += 1

    run_status = "Completed" if inserted_ideas > 0 else "Failed"
    summary = {
        "run_id": run_id,
        "feeds_considered": len(feed_rows),
        "feed_items_collected": len(fetched_items),
        "ideas_inserted": inserted_ideas,
        "generation_mode": generation_mode,
        "generation_meta": generation_meta,
        "errors": feed_errors,
    }
    db.execute(
        """
        UPDATE authority_research_runs
        SET status = ?, summary_json = ?, completed_at = CURRENT_TIMESTAMP, updated_at = CURRENT_TIMESTAMP
        WHERE id = ?
        """,
        (run_status, json.dumps(summary), run_id),
    )
    return summary


@app.route("/healthz")
def healthz():
    return jsonify({"ok": True}), 200


@app.route("/favicon.ico")
def favicon():
    return send_from_directory(app.static_folder, "favicon.ico", mimetype="image/x-icon")


@app.route("/login", methods=["GET", "POST"])
def login():
    if not APP_AUTH_ENABLED:
        return redirect(url_for("dashboard"))
    next_target = (request.args.get("next") or request.form.get("next") or "").strip()
    error = ""
    if request.method == "POST":
        username = (request.form.get("username") or "").strip()
        password = request.form.get("password") or ""
        if verify_app_login(username, password):
            session["auth_ok"] = True
            session["auth_user"] = username
            if is_safe_next_path(next_target):
                return redirect(next_target)
            return redirect(url_for("dashboard"))
        error = "Invalid username or password."
    config_warning = ""
    if not app_auth_is_configured():
        config_warning = (
            "APP_AUTH is enabled, but credentials are not configured. "
            "Set APP_AUTH_USERNAME and APP_AUTH_PASSWORD or APP_AUTH_PASSWORD_HASH."
        )
    return render_template("login.html", error=error, next_target=next_target, config_warning=config_warning)


@app.route("/logout", methods=["POST"])
def logout():
    session.clear()
    if APP_AUTH_ENABLED:
        return redirect(url_for("login"))
    return redirect(url_for("dashboard"))


def communication_counts_for_people(db, person_ids, property_id=None):
    clean_ids = []
    seen = set()
    for pid in person_ids or []:
        try:
            val = int(pid)
        except Exception:
            continue
        if val <= 0 or val in seen:
            continue
        seen.add(val)
        clean_ids.append(val)
    if not clean_ids:
        return {}
    placeholders = ",".join(["?"] * len(clean_ids))
    where = [f"person_id IN ({placeholders})"]
    params = list(clean_ids)
    if property_id is not None:
        where.append("property_id = ?")
        params.append(int(property_id))
    rows = db.execute(
        f"""
        SELECT person_id,
               SUM(CASE WHEN upper(channel)='SMS' AND lower(direction)='outbound' THEN 1 ELSE 0 END) AS sms_outbound,
               SUM(CASE WHEN upper(channel)='SMS' AND lower(direction)='inbound' THEN 1 ELSE 0 END) AS sms_inbound,
               SUM(CASE WHEN upper(channel)='EMAIL' AND lower(direction)='outbound' THEN 1 ELSE 0 END) AS email_outbound,
               SUM(CASE WHEN upper(channel)='EMAIL' AND lower(direction)='inbound' THEN 1 ELSE 0 END) AS email_inbound,
               SUM(CASE WHEN upper(channel)='EMAIL' AND lower(direction)='outbound' AND COALESCE(open_count, 0) > 0 THEN 1 ELSE 0 END) AS email_opened
        FROM communications
        WHERE {' AND '.join(where)}
        GROUP BY person_id
        """,
        tuple(params),
    ).fetchall()
    mail_where = [f"person_id IN ({placeholders})"]
    mail_params = list(clean_ids)
    if property_id is not None:
        mail_where.append("property_id = ?")
        mail_params.append(int(property_id))
    mail_rows = db.execute(
        f"""
        SELECT person_id,
               COUNT(*) AS mail_outbound
        FROM mail_orders
        WHERE {' AND '.join(mail_where)}
        GROUP BY person_id
        """,
        tuple(mail_params),
    ).fetchall()
    out = {}
    for r in rows:
        out[int(r["person_id"])] = {
            "sms_outbound": int(r["sms_outbound"] or 0),
            "sms_inbound": int(r["sms_inbound"] or 0),
            "email_outbound": int(r["email_outbound"] or 0),
            "email_inbound": int(r["email_inbound"] or 0),
            "email_opened": int(r["email_opened"] or 0),
            "mail_outbound": 0,
        }
    for r in mail_rows:
        person_id = int(r["person_id"])
        bucket = out.setdefault(
            person_id,
            {
                "sms_outbound": 0,
                "sms_inbound": 0,
                "email_outbound": 0,
                "email_inbound": 0,
                "email_opened": 0,
                "mail_outbound": 0,
            },
        )
        bucket["mail_outbound"] = int(r["mail_outbound"] or 0)
    return out


def _upsert_lead_action(
    db,
    property_id,
    person_id,
    action_type,
    priority,
    reason,
    payload,
    dedupe_key_override=None,
    due_at=None,
    contact_classification="",
):
    property_val = int(property_id or 0)
    dedupe_key = (dedupe_key_override or f"{property_val}:{int(person_id or 0)}:{action_type}").strip()
    existing = db.execute(
        "SELECT id, status, contact_classification FROM lead_management_actions WHERE dedupe_key = ?",
        (dedupe_key,),
    ).fetchone()
    payload_json = json.dumps(payload or {})
    normalized_class = normalize_lead_contact_classification(contact_classification)
    if existing:
        next_class = normalized_class or normalize_lead_contact_classification(existing["contact_classification"] or "")
        db.execute(
            """
            UPDATE lead_management_actions
            SET action_type = ?,
                priority = ?,
                status = CASE WHEN status IN ('Completed', 'Dismissed') THEN 'Pending' ELSE status END,
                reason = ?,
                payload_json = ?,
                due_at = ?,
                contact_classification = ?,
                updated_at = CURRENT_TIMESTAMP
            WHERE id = ?
            """,
            (action_type, priority, reason, payload_json, (due_at or ""), next_class, existing["id"]),
        )
        return False
    db.execute(
        """
        INSERT INTO lead_management_actions
        (dedupe_key, property_id, person_id, action_type, priority, status, reason, payload_json, due_at, contact_classification)
        VALUES (?, ?, ?, ?, ?, 'Pending', ?, ?, ?, ?)
        """,
        (dedupe_key, property_val, person_id, action_type, priority, reason, payload_json, (due_at or ""), normalized_class),
    )
    return True


def _close_unmapped_actions_for_source_key(db, source_key, property_id):
    src = (source_key or "").strip()
    if not src:
        return 0
    pattern = f'%\"source_key\": \"{src}\"%'
    row = db.execute(
        """
        UPDATE lead_management_actions
        SET status = CASE WHEN status = 'Pending' THEN 'Completed' ELSE status END,
            reason = CASE
                WHEN COALESCE(reason, '') LIKE '%Auto-clustered to property %' THEN reason
                ELSE TRIM(COALESCE(reason, '') || ' [Auto-clustered to property ' || ? || ']')
            END,
            updated_at = CURRENT_TIMESTAMP
        WHERE property_id = 0
          AND payload_json LIKE ?
        """,
        (int(property_id or 0), pattern),
    )
    return int(row.rowcount or 0)


def _retarget_unmapped_signals_for_lead_key(db, lead_key, approved_property_id):
    property_id = int(approved_property_id or 0)
    if property_id <= 0:
        return {"retargeted_signals": 0, "closed_actions": 0}
    lead_key = (lead_key or "").strip().lower()
    phones = set()
    if lead_key.startswith("phone:"):
        num = normalize_phone(lead_key.split("phone:", 1)[1])
        if num:
            phones.add(num)
    matched_source_keys = set()
    rows = db.execute(
        """
        SELECT id, source_key, payload_json
        FROM agent_signals
        WHERE COALESCE(property_id, 0) = 0
        ORDER BY id DESC
        LIMIT 1000
        """
    ).fetchall()
    retargeted = 0
    for r in rows:
        src = str(r["source_key"] or "")
        payload_json = str(r["payload_json"] or "")
        is_match = False
        for p in phones:
            if p and (p in src or p in payload_json):
                is_match = True
                break
        if not is_match:
            continue
        db.execute(
            """
            UPDATE agent_signals
            SET property_id = ?, routing_status = 'new', updated_at = CURRENT_TIMESTAMP
            WHERE id = ?
            """,
            (property_id, int(r["id"])),
        )
        retargeted += 1
        if src:
            matched_source_keys.add(src)
    closed = 0
    for src in matched_source_keys:
        closed += _close_unmapped_actions_for_source_key(db, src, property_id)
    return {"retargeted_signals": retargeted, "closed_actions": closed}


def _property_comm_snapshot(db, property_id):
    row = db.execute(
        """
        SELECT
            SUM(CASE WHEN lower(direction) = 'outbound' THEN 1 ELSE 0 END) AS outbound_total,
            SUM(CASE WHEN lower(direction) = 'inbound' THEN 1 ELSE 0 END) AS inbound_total,
            SUM(CASE WHEN upper(channel) = 'SMS' AND lower(direction) = 'outbound' THEN 1 ELSE 0 END) AS sms_outbound,
            SUM(CASE WHEN upper(channel) = 'SMS' AND lower(direction) = 'inbound' THEN 1 ELSE 0 END) AS sms_inbound,
            SUM(CASE WHEN upper(channel) = 'EMAIL' AND lower(direction) = 'outbound' THEN 1 ELSE 0 END) AS email_outbound,
            SUM(CASE WHEN upper(channel) = 'EMAIL' AND lower(direction) = 'inbound' THEN 1 ELSE 0 END) AS email_inbound,
            MAX(CASE WHEN lower(direction) = 'outbound' THEN COALESCE(sent_at, created_at) END) AS last_outbound_at,
            MAX(CASE WHEN lower(direction) = 'inbound' THEN COALESCE(sent_at, created_at) END) AS last_inbound_at
        FROM communications
        WHERE property_id = ?
        """,
        (property_id,),
    ).fetchone()
    latest_inbound = db.execute(
        """
        SELECT lower(COALESCE(body, '')) AS body
        FROM communications
        WHERE property_id = ? AND lower(direction) = 'inbound'
        ORDER BY COALESCE(sent_at, created_at) DESC, id DESC
        LIMIT 1
        """,
        (property_id,),
    ).fetchone()
    return {
        "outbound_total": int((row["outbound_total"] if row else 0) or 0),
        "inbound_total": int((row["inbound_total"] if row else 0) or 0),
        "sms_outbound": int((row["sms_outbound"] if row else 0) or 0),
        "sms_inbound": int((row["sms_inbound"] if row else 0) or 0),
        "email_outbound": int((row["email_outbound"] if row else 0) or 0),
        "email_inbound": int((row["email_inbound"] if row else 0) or 0),
        "last_outbound_at": (row["last_outbound_at"] if row else "") or "",
        "last_inbound_at": (row["last_inbound_at"] if row else "") or "",
        "latest_inbound_body": (latest_inbound["body"] if latest_inbound else "") or "",
    }


def _owner_relative_contact_count(db, owner_person_id):
    if not owner_person_id:
        return 0
    row = db.execute(
        """
        SELECT COUNT(*) AS c
        FROM person_relationships pr
        JOIN touchpoints t ON t.person_id = pr.related_person_id
        WHERE pr.subject_person_id = ?
          AND pr.related_person_id != pr.subject_person_id
          AND lower(COALESCE(t.channel_type, '')) IN ('phone', 'email')
          AND trim(COALESCE(t.value, '')) != ''
        """,
        (owner_person_id,),
    ).fetchone()
    return int((row["c"] if row else 0) or 0)


def _latest_inbound_text_for_lead_watch_item(db, item):
    texts = _collect_recent_lead_text_entries(db, item, limit=40)
    for t in texts:
        if (t.get("direction") or "").lower() == "inbound":
            return str(t.get("text") or "").strip().lower()
    return ""


def _lead_phone_match_clause(max_phones):
    conds = []
    for _ in range(max_phones):
        conds.append(
            """
            (
                replace(replace(replace(replace(replace(COALESCE(from_number,''),'+',''),'(',''),')',''),'-',''),' ','') LIKE ?
                OR replace(replace(replace(replace(replace(COALESCE(to_number,''),'+',''),'(',''),')',''),'-',''),' ','') LIKE ?
            )
            """
        )
    return " OR ".join(conds)


def _collect_recent_lead_text_entries(db, item, limit=40):
    property_id = int(item.get("property_id") or 0)
    phones = [normalize_phone(x) for x in (item.get("phones") or []) if normalize_phone(x)]
    phones = list(dict.fromkeys([p for p in phones if p]))[:5]
    entries = []

    def _add_entry(text, ts, direction, source):
        clean = re.sub(r"\s+", " ", str(text or "").strip())
        if not clean:
            return
        key = (clean.lower(), str(ts or "").strip(), (direction or "").lower(), source)
        if key in seen:
            return
        seen.add(key)
        entries.append(
            {
                "text": clean,
                "ts": str(ts or ""),
                "direction": (direction or "").strip().lower(),
                "source": source,
            }
        )

    seen = set()
    if property_id > 0:
        comm_rows = db.execute(
            """
            SELECT body, direction, COALESCE(sent_at, created_at) AS ts
            FROM communications
            WHERE property_id = ?
            ORDER BY COALESCE(sent_at, created_at) DESC, id DESC
            LIMIT 120
            """,
            (property_id,),
        ).fetchall()
        for r in comm_rows:
            _add_entry(r["body"], r["ts"], r["direction"], "communications")
        call_rows = db.execute(
            """
            SELECT summary_text, transcript_text, created_at
            FROM call_recording_jobs
            WHERE property_id = ?
            ORDER BY datetime(created_at) DESC, id DESC
            LIMIT 120
            """,
            (property_id,),
        ).fetchall()
        for r in call_rows:
            _add_entry(r["summary_text"], r["created_at"], "", "call_summary")
            _add_entry(r["transcript_text"], r["created_at"], "", "call_transcript")

    if phones:
        phone_clause = _lead_phone_match_clause(len(phones))
        args = []
        for p in phones:
            like = f"%{p}%"
            args.extend([like, like])
        comm_rows = db.execute(
            f"""
            SELECT body, direction, COALESCE(sent_at, created_at) AS ts
            FROM communications
            WHERE {phone_clause}
            ORDER BY COALESCE(sent_at, created_at) DESC, id DESC
            LIMIT 120
            """,
            tuple(args),
        ).fetchall()
        for r in comm_rows:
            _add_entry(r["body"], r["ts"], r["direction"], "communications")

        call_rows = db.execute(
            f"""
            SELECT summary_text, transcript_text, created_at
            FROM call_recording_jobs
            WHERE {phone_clause}
            ORDER BY datetime(created_at) DESC, id DESC
            LIMIT 120
            """,
            tuple(args),
        ).fetchall()
        for r in call_rows:
            _add_entry(r["summary_text"], r["created_at"], "", "call_summary")
            _add_entry(r["transcript_text"], r["created_at"], "", "call_transcript")

    entries.sort(key=lambda x: x.get("ts") or "", reverse=True)
    return entries[: max(1, int(limit or 40))]


def _parse_explicit_timeline_from_text(text, now_est):
    low = str(text or "").lower()
    if not low:
        return None
    if not any(term in low for term in TIMELINE_TRIGGER_TERMS):
        return None

    intent = "callback"
    if "appointment" in low or "meet" in low or "showing" in low:
        intent = "appointment"

    target_date = None
    weekdays = {
        "monday": 0,
        "tuesday": 1,
        "wednesday": 2,
        "thursday": 3,
        "friday": 4,
        "saturday": 5,
        "sunday": 6,
    }
    for name, idx in weekdays.items():
        if re.search(rf"\b(next\s+)?{name}\b", low):
            days_ahead = (idx - now_est.weekday()) % 7
            if days_ahead == 0:
                days_ahead = 7
            target_date = (now_est + timedelta(days=days_ahead)).date()
            break
    if target_date is None and "tomorrow" in low:
        target_date = (now_est + timedelta(days=1)).date()
    if target_date is None and "today" in low:
        target_date = now_est.date()
    if target_date is None:
        rel = re.search(r"\bin\s+(\d{1,2})\s+(day|days|week|weeks)\b", low)
        if rel:
            n = int(rel.group(1))
            unit = rel.group(2)
            if "week" in unit:
                target_date = (now_est + timedelta(days=n * 7)).date()
            else:
                target_date = (now_est + timedelta(days=n)).date()

    hm = re.search(r"\b(?:after|at|around)\s+(\d{1,2})(?::(\d{2}))?\s*(am|pm)?\b", low)
    hour = 10
    minute = 0
    if hm:
        hour = int(hm.group(1))
        minute = int(hm.group(2) or 0)
        meridiem = (hm.group(3) or "").lower()
        if meridiem == "pm" and hour < 12:
            hour += 12
        if meridiem == "am" and hour == 12:
            hour = 0
        if "after" in hm.group(0).lower() and minute == 0:
            minute = 15

    if target_date is None:
        return None
    due_est = datetime(
        year=target_date.year,
        month=target_date.month,
        day=target_date.day,
        hour=max(0, min(23, hour)),
        minute=max(0, min(59, minute)),
        second=0,
        tzinfo=EST_TZ,
    )
    return {
        "due_est": due_est,
        "intent": intent,
        "confidence": 0.92 if hm else 0.84,
        "phrase": _short_text(text, 180),
    }


def _extract_timeline_override_for_lead(db, item):
    now_est = datetime.now(EST_TZ)
    entries = _collect_recent_lead_text_entries(db, item, limit=50)
    for ent in entries:
        parsed = _parse_explicit_timeline_from_text(ent.get("text"), now_est)
        if parsed:
            due_utc = parsed["due_est"].astimezone(timezone.utc).replace(tzinfo=None)
            return {
                "due_at": format_db_time(due_utc),
                "intent": parsed["intent"],
                "confidence": float(parsed["confidence"]),
                "phrase": parsed["phrase"],
                "source": ent.get("source") or "",
            }
    return {}


def _dismiss_open_leadwatch_actions(db, lead_key, reason):
    if not lead_key:
        return 0
    rollup = str(lead_key or "").strip()
    patterns = []
    if rollup:
        patterns.append(f"leadwatch:{rollup}%")
    lk = str(lead_key or "").strip()
    if lk and not lk.startswith("lead:"):
        patterns.append(f"leadwatch:lead:{lk}%")
        patterns.append(f"leadwatch:{lk}:%")
    patterns = list(dict.fromkeys([p for p in patterns if p]))
    if not patterns:
        return 0
    where_clause = " OR ".join(["dedupe_key LIKE ?"] * len(patterns))
    params = [(reason or "").strip()[:120], *patterns]
    cur = db.execute(
        f"""
        UPDATE lead_management_actions
        SET status = CASE WHEN status = 'Pending' THEN 'Dismissed' ELSE status END,
            reason = TRIM(COALESCE(reason, '') || ' [Auto-dismissed: ' || ? || ']'),
            updated_at = CURRENT_TIMESTAMP
        WHERE ({where_clause})
          AND status = 'Pending'
        """,
        tuple(params),
    )
    return int(cur.rowcount or 0)


def _close_other_pending_leadwatch_actions(db, lead_key, keep_dedupe_key, phone_tokens=None):
    if not lead_key and not keep_dedupe_key:
        return 0
    rollup = str(lead_key or "").strip()
    patterns = []
    if rollup:
        patterns.append(f"leadwatch:{rollup}%")
    lk = str(lead_key or "").strip()
    if lk and not lk.startswith("lead:"):
        patterns.append(f"leadwatch:lead:{lk}%")
        patterns.append(f"leadwatch:{lk}:%")
    patterns = list(dict.fromkeys([p for p in patterns if p]))
    if not patterns:
        return 0
    where_clause = " OR ".join(["dedupe_key LIKE ?"] * len(patterns))
    params = [*patterns, str(keep_dedupe_key or "").strip()]
    cur = db.execute(
        f"""
        UPDATE lead_management_actions
        SET status = 'Completed',
            reason = TRIM(COALESCE(reason, '') || ' [Superseded by Agent 2]'),
            updated_at = CURRENT_TIMESTAMP
        WHERE ({where_clause})
          AND status = 'Pending'
          AND dedupe_key <> ?
        """,
        tuple(params),
    )
    closed = int(cur.rowcount or 0)
    phone_norms = []
    for p in phone_tokens or []:
        n = normalize_phone(p)
        if n and n not in phone_norms:
            phone_norms.append(n)
    if phone_norms:
        payload_clause = " OR ".join(["payload_json LIKE ?"] * len(phone_norms))
        key_clause = " OR ".join(["dedupe_key LIKE ?"] * len(phone_norms))
        payload_args = [f"%{p}%" for p in phone_norms]
        key_args = [f"%{p}%" for p in phone_norms]
        cur_phone = db.execute(
            f"""
            UPDATE lead_management_actions
            SET status = 'Completed',
                reason = TRIM(COALESCE(reason, '') || ' [Superseded by Agent 2 phone roll-up]'),
                updated_at = CURRENT_TIMESTAMP
            WHERE status = 'Pending'
              AND property_id = 0
              AND dedupe_key <> ?
              AND (({payload_clause}) OR ({key_clause}))
            """,
            tuple([str(keep_dedupe_key or "").strip(), *payload_args, *key_args]),
        )
        closed += int(cur_phone.rowcount or 0)
    return closed


def _extract_phone_from_lead_key(lead_key):
    lk = str(lead_key or "").strip().lower()
    if lk.startswith("phone:"):
        return normalize_phone(lk.split("phone:", 1)[1])
    return ""


def _rollup_phone_candidates_for_item(db, item, lead_key=""):
    system_numbers = _known_system_numbers(db, refresh_seconds=300)
    all_norm = []
    for raw in list(item.get("phones") or []):
        n = normalize_phone(raw)
        if n and n not in all_norm:
            all_norm.append(n)
    from_key = _extract_phone_from_lead_key(lead_key)
    if from_key and from_key not in all_norm:
        all_norm.append(from_key)
    preferred = [n for n in all_norm if n not in system_numbers]
    chosen = preferred if preferred else all_norm
    return sorted(chosen)


def _rollup_address_key_for_item(item):
    hints = list(item.get("address_hints") or [])
    for h in hints:
        nk = normalize_address_key(h)
        if nk:
            return nk
    lbl = str(item.get("label") or "").strip()
    low = lbl.lower()
    if (
        lbl
        and not low.startswith("phone:")
        and not low.startswith("phone ")
        and not low.startswith("uuid:")
        and not low.startswith("property:")
        and not normalize_phone(lbl)
    ):
        nk = normalize_address_key(lbl)
        if nk:
            return nk
    return ""


def _canonical_rollup_key_for_item(db, item, lead_key=""):
    rollup_uuid = normalize_uuid(item.get("reisift_property_uuid") or "")
    if not rollup_uuid:
        property_id = int(item.get("property_id") or 0)
        if property_id > 0:
            rollup_uuid = _get_local_property_uuid(db, property_id)
    if rollup_uuid:
        return f"uuid:{rollup_uuid}", []
    phones = _rollup_phone_candidates_for_item(db, item, lead_key=lead_key)
    if phones:
        return f"phone:{phones[0]}", phones
    return f"lead:{str(lead_key or '').strip()}", []


def _canonical_rollup_key_for_action_row(db, action_row):
    row = dict(action_row or {})
    payload = parse_json_object(row.get("payload_json") or "{}")
    snapshot = payload.get("snapshot") if isinstance(payload.get("snapshot"), dict) else {}
    lead_key = str(snapshot.get("lead_key") or payload.get("lead_key") or "").strip()
    if lead_key.startswith("uuid:") or lead_key.startswith("phone:"):
        return lead_key
    rollup_uuid = normalize_uuid(snapshot.get("reisift_property_uuid") or "")
    if not rollup_uuid:
        rollup_uuid = normalize_uuid(payload.get("reisift_property_uuid") or "")
    if not rollup_uuid:
        property_id = int(row.get("property_id") or 0)
        if property_id > 0:
            rollup_uuid = _get_local_property_uuid(db, property_id)
    if rollup_uuid:
        return f"uuid:{rollup_uuid}"
    system_numbers = _known_system_numbers(db, refresh_seconds=300)
    phones = []
    for raw in list(snapshot.get("phones") or []):
        n = normalize_phone(raw)
        if n and n not in phones:
            phones.append(n)
    signal = payload.get("signal") if isinstance(payload.get("signal"), dict) else {}
    for raw in [
        payload.get("counterpart"),
        payload.get("phone"),
        payload.get("counterpart_number"),
        payload.get("from"),
        payload.get("to"),
        signal.get("counterpart"),
        signal.get("phone"),
        signal.get("counterpart_number"),
        signal.get("from"),
        signal.get("to"),
        signal.get("from_number"),
        signal.get("to_number"),
    ]:
        n = normalize_phone(raw)
        if n and n not in phones:
            phones.append(n)
    dk = str(row.get("dedupe_key") or "")
    phone_match = re.search(r"(?:^|:)phone:([0-9]{10,15})(?:$|:)", dk)
    if phone_match:
        n = normalize_phone(phone_match.group(1))
        if n and n not in phones:
            phones.append(n)
    if not phones and dk.startswith("unmapped:sms-unresolved:"):
        # Legacy key format can still include numbers in the tail.
        for found in re.findall(r"([0-9]{10,15})", dk):
            n = normalize_phone(found)
            if n and n not in phones:
                phones.append(n)
    lk_phone = _extract_phone_from_lead_key(lead_key)
    if lk_phone and lk_phone not in phones:
        phones.append(lk_phone)
    preferred = sorted([n for n in phones if n not in system_numbers])
    if preferred:
        return f"phone:{preferred[0]}"
    if phones:
        return f"phone:{sorted(phones)[0]}"
    if lead_key:
        return lead_key
    if dk.startswith("leadwatch:"):
        tail = dk[len("leadwatch:") :].strip()
        return tail or dk
    return dk or f"row:{int(row.get('id') or 0)}"


def dedupe_pending_lead_actions_by_rollup(db):
    rows = db.execute(
        """
        SELECT id, dedupe_key, property_id, payload_json, updated_at, created_at, reason
        FROM lead_management_actions
        WHERE status = 'Pending'
        ORDER BY COALESCE(updated_at, created_at) DESC, id DESC
        """
    ).fetchall()
    seen = {}
    closed = 0
    for r in rows:
        row = dict(r)
        rollup = _canonical_rollup_key_for_action_row(db, row)
        keep_id = seen.get(rollup)
        if keep_id is None:
            seen[rollup] = int(row["id"])
            continue
        db.execute(
            """
            UPDATE lead_management_actions
            SET status = 'Completed',
                reason = TRIM(COALESCE(reason, '') || ' [Auto-merged duplicate roll-up]'),
                updated_at = CURRENT_TIMESTAMP
            WHERE id = ?
              AND status = 'Pending'
            """,
            (int(row["id"]),),
        )
        closed += 1
    return {"kept_rollups": len(seen), "closed_duplicates": closed}


def _determine_agent2_action(item, snapshot, timeline_override, latest_inbound_text):
    classification = str(snapshot.get("classification") or "unknown").strip().lower()
    reisift_status = _normalize_reisift_status(snapshot.get("reisift_status") or "")
    on_market_status = str(snapshot.get("on_market_status") or "").strip().lower()
    outbound_total = int(snapshot.get("outbound_total") or 0)
    inbound_total = int(snapshot.get("inbound_total") or 0)
    last_activity_at = str(item.get("last_activity_at") or "")
    now_utc = datetime.utcnow()
    last_dt = parse_db_time(last_activity_at) or now_utc
    days_since_touch = max(0.0, (now_utc - last_dt).total_seconds() / 86400.0)
    cadence_days = int(LEAD_STATUS_CADENCE_DAYS.get(reisift_status, 1))
    due_by_cadence = last_dt + timedelta(days=max(0, cadence_days))

    if classification in {"spam", "solicitor"}:
        return {"skip": True, "skip_reason": "classification_suppressed"}
    if reisift_status in {"opt-out", "opt out", "dead", "dead lead", "dnc"}:
        return {"skip": True, "skip_reason": "reisift_stop_status"}
    if reisift_status == "not interested":
        return {
            "action_type": "HumanReviewDisposition",
            "priority": "Medium",
            "due_at": format_db_time(now_utc),
            "reason": "Not Interested requires Agent 3 recommendation and human confirmation before status transition.",
        }
    if on_market_status in ON_MARKET_STATUSES:
        return {
            "action_type": "ReviewInboundAndNextBestAction",
            "priority": "Medium",
            "due_at": format_db_time(due_by_cadence),
            "reason": "Lead appears listed/on-market; monitor referral side while preserving cash-offer lane.",
        }
    if any(token in (latest_inbound_text or "") for token in LEAD_NEGATIVE_INTENT_TOKENS):
        return {
            "action_type": "HumanReviewDisposition",
            "priority": "High",
            "due_at": format_db_time(now_utc),
            "reason": "Latest inbound message indicates negative/disposition risk requiring human review.",
        }
    if timeline_override and timeline_override.get("due_at"):
        intent = str(timeline_override.get("intent") or "callback")
        act = "ScheduleAppointment" if intent in {"appointment", "callback"} else "FollowUpTouchDue"
        return {
            "action_type": act,
            "priority": _playbook_priority_for_action(reisift_status, act, "High"),
            "due_at": str(timeline_override.get("due_at") or ""),
            "reason": (
                "Agent 1 extracted explicit timeline from communication: "
                f"\"{timeline_override.get('phrase') or ''}\""
            ),
            "timeline_override": True,
        }

    if inbound_total > 0:
        return {
            "action_type": "ReviewInboundAndNextBestAction",
            "priority": _playbook_priority_for_action(reisift_status, "ReviewInboundAndNextBestAction", "Medium"),
            "due_at": format_db_time(now_utc),
            "reason": "Inbound activity detected; confirm intent and choose next touchpoint.",
        }

    # Status-specific cadence behavior.
    if reisift_status == "no contact new lead":
        if outbound_total >= 1 and days_since_touch >= 1.0:
            return {
                "action_type": "EscalateToDeepDiveResearch",
                "priority": "High",
                "due_at": format_db_time(now_utc),
                "reason": "No Contact New Lead day-2 escalation: no reply after initial outreach.",
            }
        return {
            "action_type": "FollowUpTouchDue",
            "priority": "High",
            "due_at": format_db_time(due_by_cadence),
            "reason": "No Contact New Lead day-1 follow-up is due.",
        }
    if reisift_status == "ghosting lead":
        if outbound_total >= 2 and days_since_touch >= 5.0:
            return {
                "action_type": "EscalateToDeepDiveResearch",
                "priority": "High",
                "due_at": format_db_time(now_utc),
                "reason": "Ghosting lead with repeated no-response; escalate to Deep Dive.",
            }
        return {
            "action_type": "FollowUpTouchDue",
            "priority": "Medium",
            "due_at": format_db_time(due_by_cadence),
            "reason": "Ghosting lead follow-up cadence reached.",
        }
    if reisift_status in {"new lead", "hot lead"} and outbound_total == 0:
        return {
            "action_type": "ScheduleAppointment",
            "priority": "High",
            "due_at": format_db_time(now_utc),
            "reason": "High-priority lead with no outbound touch yet; initiate call scheduling now.",
        }
    if now_utc >= due_by_cadence:
        return {
            "action_type": "FollowUpTouchDue",
            "priority": _playbook_priority_for_action(reisift_status, "FollowUpTouchDue", "Medium"),
            "due_at": format_db_time(due_by_cadence),
            "reason": f"Cadence reached for status '{reisift_status or 'unknown'}' after {max(0, int(days_since_touch))} day(s).",
        }
    return {"skip": True, "skip_reason": "not_due"}


def evaluate_lead_watch_item_lead_management(db, item):
    lead_key = str(item.get("lead_key") or "").strip()
    if not lead_key:
        return {"lead_key": "", "skipped": True, "created_actions": 0, "snapshot": {}}

    property_id = int(item.get("property_id") or 0)
    person_id = int(item.get("person_id") or 0) or None
    classification = str(item.get("classification") or "unknown").strip().lower()
    ignore_agent2 = int(item.get("ignore_agent2") or 0) == 1
    sms_outbound = int(item.get("sms_outbound") or 0)
    sms_inbound = int(item.get("sms_inbound") or 0)
    calls = int(item.get("calls") or 0)
    outbound_total = sms_outbound + calls
    inbound_total = sms_inbound
    referral = item.get("referral") if isinstance(item.get("referral"), dict) else {}
    reisift_status = _normalize_reisift_status(str(referral.get("status") or "") or str(item.get("reisift_property_status") or ""))
    on_market_status = str(referral.get("on_market_status") or "").strip().lower()

    snapshot = {
        "outbound_total": outbound_total,
        "inbound_total": inbound_total,
        "sms_outbound": sms_outbound,
        "sms_inbound": sms_inbound,
        "calls": calls,
        "classification": classification,
        "reisift_status": reisift_status,
        "on_market_status": on_market_status,
        "lead_key": lead_key,
        "label": str(item.get("label") or ""),
        "reisift_property_uuid": str(item.get("reisift_property_uuid") or ""),
        "phones": list(item.get("phones") or []),
    }
    rollup_key, rollup_phone_norms = _canonical_rollup_key_for_item(db, item, lead_key=lead_key)
    snapshot["rollup_key"] = rollup_key
    if ignore_agent2:
        _dismiss_open_leadwatch_actions(db, rollup_key, "manual_ignore_agent2")
        return {"lead_key": lead_key, "skipped": True, "created_actions": 0, "snapshot": snapshot}

    timeline_override = _extract_timeline_override_for_lead(db, item)
    latest_inbound = _latest_inbound_text_for_lead_watch_item(db, item)
    decision = _determine_agent2_action(item, snapshot, timeline_override, latest_inbound)

    if decision.get("skip"):
        if decision.get("skip_reason") in {"classification_suppressed", "reisift_stop_status"}:
            _dismiss_open_leadwatch_actions(db, rollup_key, decision.get("skip_reason"))
        return {"lead_key": lead_key, "skipped": True, "created_actions": 0, "snapshot": snapshot}

    action_type = str(decision.get("action_type") or "ReviewInboundAndNextBestAction")
    priority = str(decision.get("priority") or "Medium").title()
    due_at = str(decision.get("due_at") or "")
    reason = str(decision.get("reason") or "Agent 2 generated next best action.").strip()
    payload = {
        "snapshot": snapshot,
        "source": "agent2_lead_watch_v2",
        "timeline_override": timeline_override,
        "latest_inbound": latest_inbound[:800],
    }
    dedupe_key = f"leadwatch:{rollup_key}"
    created = int(
        _upsert_lead_action(
            db,
            property_id,
            person_id,
            action_type,
            priority,
            reason,
            payload,
            dedupe_key_override=dedupe_key,
            due_at=due_at,
            contact_classification=classification,
        )
    )
    _close_other_pending_leadwatch_actions(db, rollup_key, dedupe_key, phone_tokens=rollup_phone_norms)
    return {
        "lead_key": lead_key,
        "skipped": False,
        "created_actions": created,
        "snapshot": snapshot,
        "action_type": action_type,
        "priority": priority,
        "due_at": due_at,
    }


def evaluate_property_lead_management(db, property_row):
    property_id = int(property_row["id"])
    owner_person_id = property_row["owner_person_id"]
    prop_status = str(property_row["status"] or "").strip().lower()
    snapshot = _property_comm_snapshot(db, property_id)
    relative_contact_count = _owner_relative_contact_count(db, owner_person_id)
    created_actions = 0
    skipped = False

    if prop_status in LEAD_STOP_STATUSES:
        return {"property_id": property_id, "skipped": True, "created_actions": 0, "snapshot": snapshot}

    latest_inbound = snapshot["latest_inbound_body"]
    has_negative_intent = any(token in latest_inbound for token in LEAD_NEGATIVE_INTENT_TOKENS)
    if has_negative_intent:
        created_actions += int(
            _upsert_lead_action(
                db,
                property_id,
                owner_person_id,
                "HumanReviewDisposition",
                "High",
                "Inbound response appears negative and requires a human decision before additional outreach.",
                {"snapshot": snapshot, "reason": "negative_intent_detected"},
            )
        )
        return {"property_id": property_id, "skipped": skipped, "created_actions": created_actions, "snapshot": snapshot}

    if snapshot["outbound_total"] >= 3 and snapshot["inbound_total"] == 0:
        if relative_contact_count > 0:
            created_actions += int(
                _upsert_lead_action(
                    db,
                    property_id,
                    owner_person_id,
                    "EscalateToRelativeOutreach",
                    "High",
                    "No inbound responses after 3+ touches. Escalate outreach to known relatives/associates.",
                    {"snapshot": snapshot, "relative_contact_count": relative_contact_count},
                )
            )
        else:
            created_actions += int(
                _upsert_lead_action(
                    db,
                    property_id,
                    owner_person_id,
                    "EscalateToDeepDiveResearch",
                    "High",
                    "No inbound responses after 3+ touches and no relative contact channels on file.",
                    {"snapshot": snapshot, "relative_contact_count": relative_contact_count},
                )
            )
    elif snapshot["outbound_total"] >= 1 and snapshot["inbound_total"] == 0:
        created_actions += int(
            _upsert_lead_action(
                db,
                property_id,
                owner_person_id,
                "FollowUpTouchDue",
                "Medium",
                "Lead has outreach activity but no inbound response yet. Schedule next compliant touchpoint.",
                {"snapshot": snapshot},
            )
        )

    if snapshot["inbound_total"] > 0 and snapshot["outbound_total"] > 0:
        created_actions += int(
            _upsert_lead_action(
                db,
                property_id,
                owner_person_id,
                "ReviewInboundAndNextBestAction",
                "Medium",
                "Inbound activity exists. Confirm sentiment and set next best action manually.",
                {"snapshot": snapshot},
            )
        )

    return {"property_id": property_id, "skipped": skipped, "created_actions": created_actions, "snapshot": snapshot}


def backfill_reisift_context_for_recent_phones(db, cutoff=None, limit=20):
    cutoff_value = (cutoff or "").strip() or format_db_time(est_yesterday_start_utc())
    max_attempts = max(1, min(200, int(limit or 20)))
    system_numbers = _known_system_numbers(db, refresh_seconds=300)
    ordered_phones = []

    def _add_phone(raw):
        n = normalize_phone(raw)
        if not n or n in system_numbers or n in ordered_phones:
            return
        ordered_phones.append(n)

    try:
        comm_rows = db.execute(
            """
            SELECT from_number, to_number
            FROM communications
            WHERE sent_at >= ?
              AND upper(channel) = 'SMS'
            ORDER BY id DESC
            LIMIT 2000
            """,
            (cutoff_value,),
        ).fetchall()
        for r in comm_rows:
            _add_phone(r["from_number"])
            _add_phone(r["to_number"])
    except Exception:
        pass
    try:
        event_rows = db.execute(
            """
            SELECT from_number, to_number
            FROM smrtphone_webhook_events
            WHERE received_at >= ?
              AND event_type IN ('inbound', 'outbound', 'call_completed')
            ORDER BY id DESC
            LIMIT 2000
            """,
            (cutoff_value,),
        ).fetchall()
        for r in event_rows:
            _add_phone(r["from_number"])
            _add_phone(r["to_number"])
    except Exception:
        pass
    try:
        call_rows = db.execute(
            """
            SELECT from_number, to_number
            FROM call_recording_jobs
            WHERE created_at >= ?
            ORDER BY id DESC
            LIMIT 1200
            """,
            (cutoff_value,),
        ).fetchall()
        for r in call_rows:
            _add_phone(r["from_number"])
            _add_phone(r["to_number"])
    except Exception:
        pass

    attempted = 0
    resolved = 0
    skipped_recent = 0
    skipped_already = 0
    sampled = []
    now_utc = datetime.utcnow()
    for phone in ordered_phones:
        if attempted >= max_attempts:
            break
        ctx = get_cached_contact_context(db, phone)
        if ctx:
            cached_uuid = normalize_uuid(ctx["reisift_property_uuid"] or "")
            cached_pid = int(ctx["property_id"] or 0)
            if cached_uuid or cached_pid:
                skipped_already += 1
                continue
            last_lookup = parse_db_time(ctx["last_reisift_lookup_at"])
            if last_lookup and (now_utc - last_lookup) < timedelta(hours=6):
                skipped_recent += 1
                continue
        attempted += 1
        resolved_ctx = resolve_property_context_by_phone(db, phone, search_reisift=True) or {}
        has_resolution = bool(normalize_uuid(resolved_ctx.get("reisift_property_uuid") or "")) or bool(
            int(resolved_ctx.get("property_id") or 0)
        )
        if has_resolution:
            resolved += 1
        if len(sampled) < 10:
            sampled.append(
                {
                    "phone": phone,
                    "resolved": bool(has_resolution),
                    "uuid": normalize_uuid(resolved_ctx.get("reisift_property_uuid") or ""),
                    "property_id": int(resolved_ctx.get("property_id") or 0),
                    "source": str(resolved_ctx.get("source") or ""),
                }
            )
    return {
        "checked_candidates": len(ordered_phones),
        "attempted": attempted,
        "resolved": resolved,
        "skipped_already": skipped_already,
        "skipped_recent": skipped_recent,
        "sample": sampled,
    }


def run_uuid_backfill_once(db, snapshot_limit=300, phone_limit=200):
    snapshot = build_today_lead_watch_snapshot(db, limit=max(1, min(500, int(snapshot_limit or 300))))
    items = snapshot.get("items") or []
    targets = []
    for x in items:
        uuid_missing = not normalize_uuid(x.get("reisift_property_uuid") or "")
        has_phone_or_property = bool(int(x.get("property_id") or 0)) or bool(x.get("phones") or []) or str(x.get("lead_key") or "").startswith("phone:")
        if int(x.get("unresolved") or 0) == 1 or (uuid_missing and has_phone_or_property):
            targets.append(x)
    system_numbers = _known_system_numbers(db, refresh_seconds=300)
    seen = set()
    candidates = []
    no_phone_rows = 0
    for row in targets:
        row_phones = list(row.get("phones") or [])
        if not row_phones and str(row.get("lead_key") or "").startswith("phone:"):
            row_phones = [str(row.get("lead_key") or "").split(":", 1)[1]]
        picked_any = False
        for raw in row_phones:
            n = normalize_phone(raw)
            if not n or n in system_numbers:
                continue
            picked_any = True
            if n not in seen:
                seen.add(n)
                candidates.append(n)
        if not picked_any:
            no_phone_rows += 1
    max_phones = max(1, min(500, int(phone_limit or 200)))
    candidates = candidates[:max_phones]

    local_hits_cached_uuid = 0
    local_hits_property_uuid = 0
    sift_attempted = 0
    resolved_from_sift = 0
    unresolved_after_lookup = 0
    errors = []
    processed = []
    for phone in candidates:
        item = {"phone": phone, "result": "", "uuid": "", "source": "", "error": ""}
        ctx = get_cached_contact_context(db, phone)
        cached_uuid = normalize_uuid((ctx["reisift_property_uuid"] if ctx else "") or "")
        if cached_uuid:
            local_hits_cached_uuid += 1
            item["result"] = "local_cached_uuid"
            item["uuid"] = cached_uuid
            item["source"] = "cache"
            processed.append(item)
            continue
        property_id = int((ctx["property_id"] if ctx else 0) or 0)
        local_uuid = _get_local_property_uuid(db, property_id)
        if local_uuid:
            local_hits_property_uuid += 1
            item["result"] = "local_property_uuid"
            item["uuid"] = local_uuid
            item["source"] = "local_property"
            upsert_cached_contact_context(
                db,
                phone,
                property_id=property_id,
                person_id=(ctx["person_id"] if ctx else None),
                classification=(ctx["classification"] if ctx else "potential_seller"),
                source="uuid_backfill_local_property",
                confidence=0.95,
                notes="Filled UUID from local property link.",
                reisift_property_uuid=local_uuid,
                reisift_full_address=(ctx["reisift_full_address"] if ctx else ""),
                reisift_owner_name=(ctx["reisift_owner_name"] if ctx else ""),
                reisift_property_status=(ctx["reisift_property_status"] if ctx else ""),
                last_reisift_lookup_at=format_db_time(datetime.utcnow()),
            )
            processed.append(item)
            continue

        sift_attempted += 1
        resolved = resolve_property_context_by_phone(db, phone, search_reisift=True, force_reisift=True) or {}
        resolved_uuid = normalize_uuid(resolved.get("reisift_property_uuid") or "")
        item["uuid"] = resolved_uuid
        item["source"] = str(resolved.get("source") or "")
        item["error"] = str(resolved.get("error") or "")
        if resolved_uuid:
            resolved_from_sift += 1
            item["result"] = "resolved_from_sift"
        else:
            unresolved_after_lookup += 1
            if item["error"]:
                item["result"] = "reisift_error"
                err_payload = {
                    "phone": phone,
                    "source": item["source"],
                    "error": item["error"],
                }
                errors.append(err_payload)
                log_app_error(
                    db,
                    source="uuid_backfill_once",
                    error_message=item["error"][:500],
                    details=json.dumps(err_payload),
                    route="/api/integrations/agents/uuid-backfill-once",
                    status_code=500,
                )
            else:
                # Acceptable unresolved reason if ReiSift has no linked property/address payload for this phone.
                item["result"] = "no_uuid_found_for_phone"
        processed.append(item)

    return {
        "cutoff_utc": snapshot.get("cutoff_utc"),
        "snapshot_count": int(snapshot.get("count") or 0),
        "target_rows": len(targets),
        "unresolved_before": sum(1 for x in items if int(x.get("unresolved") or 0) == 1),
        "rows_without_phone": int(no_phone_rows),
        "candidate_phones": len(candidates),
        "local_hits_cached_uuid": local_hits_cached_uuid,
        "local_hits_property_uuid": local_hits_property_uuid,
        "sift_lookups_attempted": sift_attempted,
        "resolved_from_sift": resolved_from_sift,
        "unresolved_after_lookup": unresolved_after_lookup,
        "errors": errors[:100],
        "processed_sample": processed[:120],
    }


def repair_unresolved_call_context_once(db, limit=80, max_reisift_lookups=12):
    max_rows = max(1, min(500, int(limit or 80)))
    lookup_budget = max(0, min(200, int(max_reisift_lookups or 12)))
    rows = db.execute(
        """
        SELECT id, call_sid, from_number, to_number, property_id, person_id, payload_json
        FROM call_recording_jobs
        WHERE COALESCE(property_id, 0) = 0
        ORDER BY id DESC
        LIMIT ?
        """,
        (max_rows,),
    ).fetchall()
    processed = 0
    repaired = 0
    unresolved = 0
    reisift_lookups = 0
    phone_lookup_cache = {}
    sample = []

    def _pick_best_resolution(base_ctx, candidate_ctx):
        result = dict(base_ctx or {})
        cand = dict(candidate_ctx or {})
        for key in ["phone_norm", "source", "reisift_full_address", "reisift_owner_name", "reisift_property_status"]:
            if (not result.get(key)) and cand.get(key):
                result[key] = cand.get(key)
        if int(cand.get("property_id") or 0) and not int(result.get("property_id") or 0):
            result["property_id"] = int(cand.get("property_id") or 0)
        if int(cand.get("person_id") or 0) and not int(result.get("person_id") or 0):
            result["person_id"] = int(cand.get("person_id") or 0)
        cand_uuid = normalize_uuid(cand.get("reisift_property_uuid") or "")
        base_uuid = normalize_uuid(result.get("reisift_property_uuid") or "")
        if cand_uuid and not base_uuid:
            result["reisift_property_uuid"] = cand_uuid
        return result

    for row in rows:
        processed += 1
        candidates = _counterparty_candidates(db, row["from_number"], row["to_number"])
        resolved = resolve_shared_contact_context_by_numbers(
            db,
            candidates,
            fallback_property_id=None,
            force_reisift=False,
            search_reisift=False,
        ) or {}
        resolved_uuid = normalize_uuid(resolved.get("reisift_property_uuid") or "")
        if not (int(resolved.get("property_id") or 0) or resolved_uuid):
            for phone in candidates:
                n = normalize_phone(phone)
                if not n:
                    continue
                ctx = phone_lookup_cache.get(n)
                if ctx is None:
                    if reisift_lookups >= lookup_budget:
                        continue
                    ctx = resolve_property_context_by_phone(
                        db,
                        n,
                        search_reisift=True,
                        force_reisift=True,
                    ) or {}
                    phone_lookup_cache[n] = ctx
                    reisift_lookups += 1
                resolved = _pick_best_resolution(resolved, ctx)
                resolved_uuid = normalize_uuid(resolved.get("reisift_property_uuid") or "")
                if int(resolved.get("property_id") or 0) or resolved_uuid:
                    break

        resolved_pid = int(resolved.get("property_id") or 0) or None
        resolved_person_id = int(resolved.get("person_id") or 0) or None
        resolved_uuid = normalize_uuid(resolved.get("reisift_property_uuid") or "")
        if resolved_pid or resolved_uuid:
            payload_obj = parse_json_object(row["payload_json"] or "{}")
            payload_obj["context_repair"] = {
                "repaired_at": format_db_time(datetime.utcnow()),
                "from_number": row["from_number"],
                "to_number": row["to_number"],
                "resolved_property_id": resolved_pid,
                "resolved_person_id": resolved_person_id,
                "reisift_property_uuid": resolved_uuid,
                "source": str(resolved.get("source") or ""),
            }
            db.execute(
                """
                UPDATE call_recording_jobs
                SET property_id = COALESCE(?, property_id),
                    person_id = COALESCE(?, person_id),
                    payload_json = ?,
                    updated_at = CURRENT_TIMESTAMP
                WHERE id = ?
                """,
                (
                    resolved_pid,
                    resolved_person_id,
                    json.dumps(payload_obj),
                    int(row["id"]),
                ),
            )
            if resolved_pid and resolved_uuid:
                _set_local_property_uuid(db, int(resolved_pid), resolved_uuid)
            primary_phone = normalize_phone(candidates[0] if candidates else "")
            if primary_phone:
                upsert_cached_contact_context(
                    db,
                    primary_phone,
                    property_id=resolved_pid,
                    person_id=resolved_person_id,
                    classification="potential_seller",
                    source="call_context_repair",
                    confidence=0.9 if resolved_uuid else 0.8,
                    notes=f"repair call_sid={row['call_sid']}",
                    reisift_property_uuid=resolved_uuid,
                    reisift_full_address=str(resolved.get("reisift_full_address") or "").strip(),
                    reisift_owner_name=str(resolved.get("reisift_owner_name") or "").strip(),
                    reisift_property_status=str(resolved.get("reisift_property_status") or "").strip(),
                    last_reisift_lookup_at=format_db_time(datetime.utcnow()),
                )
            repaired += 1
            status_value = "repaired"
        else:
            unresolved += 1
            status_value = "unresolved"
        if len(sample) < 120:
            sample.append(
                {
                    "call_job_id": int(row["id"]),
                    "call_sid": str(row["call_sid"] or ""),
                    "status": status_value,
                    "from_number": str(row["from_number"] or ""),
                    "to_number": str(row["to_number"] or ""),
                    "resolved_property_id": int(resolved_pid or 0),
                    "resolved_person_id": int(resolved_person_id or 0),
                    "reisift_property_uuid": resolved_uuid,
                    "resolver_source": str(resolved.get("source") or ""),
                }
            )
    return {
        "processed": processed,
        "repaired": repaired,
        "unresolved": unresolved,
        "reisift_lookups": reisift_lookups,
        "lookup_budget": lookup_budget,
        "sample": sample,
    }


def run_lead_monitor_once(db, source="manual", property_id=None):
    run_cur = db.execute(
        """
        INSERT INTO lead_monitor_runs (source, property_id, status, summary_json)
        VALUES (?, ?, 'Running', ?)
        """,
        ((source or "manual")[:40], property_id, "{}"),
    )
    run_id = run_cur.lastrowid
    backfill_stats = backfill_reisift_context_for_recent_phones(db, cutoff=format_db_time(est_yesterday_start_utc()), limit=20)
    snapshot = build_today_lead_watch_snapshot(db, limit=300)
    rows = snapshot.get("items") or []
    if property_id:
        rows = [r for r in rows if int(r.get("property_id") or 0) == int(property_id)]
    inspected = 0
    skipped = 0
    created_actions = 0
    details = []

    def _append_agent3_kick_log(run_id_value, item_row, result_row):
        lead_key_val = str(item_row.get("lead_key") or "").strip()
        if not lead_key_val:
            return
        db.execute(
            """
            INSERT INTO agent3_kick_logs
            (run_id, lead_key, property_id, reisift_property_uuid, payload_json)
            VALUES (?, ?, ?, ?, ?)
            """,
            (
                int(run_id_value or 0) or None,
                lead_key_val,
                int(item_row.get("property_id") or 0),
                normalize_uuid(item_row.get("reisift_property_uuid") or ""),
                json.dumps({"item": item_row, "result": result_row}),
            ),
        )

    for row in rows:
        inspected += 1
        result = evaluate_lead_watch_item_lead_management(db, row)
        _append_agent3_kick_log(run_id, row, result)
        created_actions += int(result.get("created_actions") or 0)
        if result.get("skipped"):
            skipped += 1
        if len(details) < 25:
            details.append(
                {
                    "lead_key": result.get("lead_key") or "",
                    "property_id": int(row.get("property_id") or 0),
                    "label": str(row.get("label") or ""),
                    "created_actions": result["created_actions"],
                    "skipped": bool(result.get("skipped")),
                    "action_type": str(result.get("action_type") or ""),
                    "priority": str(result.get("priority") or ""),
                    "due_at": str(result.get("due_at") or ""),
                    "outbound_total": (result.get("snapshot") or {}).get("outbound_total", 0),
                    "inbound_total": (result.get("snapshot") or {}).get("inbound_total", 0),
                }
            )
    dedupe_stats = dedupe_pending_lead_actions_by_rollup(db)
    summary = {
        "inspected": inspected,
        "skipped": skipped,
        "created_actions": created_actions,
        "dedupe": dedupe_stats,
        "uuid_backfill": backfill_stats,
        "details": details,
    }
    db.execute(
        """
        UPDATE lead_monitor_runs
        SET status = 'Completed',
            summary_json = ?,
            completed_at = CURRENT_TIMESTAMP
        WHERE id = ?
        """,
        (json.dumps(summary), run_id),
    )
    return {"run_id": run_id, **summary}


def trigger_agent_pipeline_refresh(db, property_id=None, reason=""):
    result = {"lead_monitor": {}, "reconcile": {}, "reason": (reason or "").strip()}
    try:
        result["lead_monitor"] = run_lead_monitor_once(
            db,
            source="agent1_event",
            property_id=(int(property_id) if int(property_id or 0) > 0 else None),
        )
    except Exception as exc:
        result["lead_monitor"] = {"error": str(exc)}
        log_app_error(
            db,
            source="agent_pipeline_refresh",
            error_message=str(exc),
            details=traceback.format_exc(),
            route="trigger_agent_pipeline_refresh.lead_monitor",
            status_code=500,
        )
    try:
        result["reconcile"] = run_agent3_lead_watch_reconcile(db, limit=120)
    except Exception as exc:
        result["reconcile"] = {"error": str(exc)}
        log_app_error(
            db,
            source="agent_pipeline_refresh",
            error_message=str(exc),
            details=traceback.format_exc(),
            route="trigger_agent_pipeline_refresh.reconcile",
            status_code=500,
        )
    return result


def build_agent3_lead_watch_snapshot_from_logs(db, limit=80):
    rows = db.execute(
        """
        SELECT l.id, l.run_id, l.lead_key, l.property_id, l.reisift_property_uuid, l.payload_json, l.created_at
        FROM agent3_kick_logs l
        JOIN (
            SELECT lead_key, MAX(id) AS max_id
            FROM agent3_kick_logs
            GROUP BY lead_key
        ) latest ON latest.max_id = l.id
        ORDER BY l.id DESC
        LIMIT ?
        """,
        (max(1, min(500, int(limit or 80))),),
    ).fetchall()
    items = []
    unresolved_count = 0
    unresolved_active_count = 0
    for r in rows:
        payload = parse_json_object(r["payload_json"] or "{}")
        item = payload.get("item") if isinstance(payload.get("item"), dict) else {}
        if not item:
            item = {"lead_key": str(r["lead_key"] or "").strip()}
        row = dict(item)
        row["lead_key"] = str(row.get("lead_key") or r["lead_key"] or "").strip()
        row["property_id"] = int(row.get("property_id") or r["property_id"] or 0)
        row["reisift_property_uuid"] = normalize_uuid(row.get("reisift_property_uuid") or r["reisift_property_uuid"] or "")
        row["open_record_url"] = _sift_record_url(row.get("reisift_property_uuid") or "")
        row["phones"] = list(row.get("phones") or [])
        row["address_hints"] = list(row.get("address_hints") or [])
        row["sources"] = list(row.get("sources") or [])
        row["sms_inbound"] = int(row.get("sms_inbound") or 0)
        row["sms_outbound"] = int(row.get("sms_outbound") or 0)
        row["calls"] = int(row.get("calls") or 0)
        row["events"] = int(row.get("events") or 0)
        row["classification"] = str(row.get("classification") or "unknown").strip().lower()
        row["unresolved"] = int(row.get("unresolved") or 0)
        row["ignore_agent2"] = int(row.get("ignore_agent2") or 0)
        row["agent_summary"] = str(row.get("agent_summary") or "").strip()
        row["recommended"] = str(row.get("recommended") or "").strip()
        row["last_activity_at"] = str(row.get("last_activity_at") or r["created_at"] or "")
        row["referral"] = row.get("referral") if isinstance(row.get("referral"), dict) else {}
        row["referral_pushes"] = row.get("referral_pushes") if isinstance(row.get("referral_pushes"), list) else []
        row["agent2_resolution"] = row.get("agent2_resolution") if isinstance(row.get("agent2_resolution"), dict) else {}
        row["resolution_status"] = str(row.get("resolution_status") or "")
        row["resolution_notes"] = str(row.get("resolution_notes") or "")
        row["resolution_updated_at"] = str(row.get("resolution_updated_at") or "")
        row["suggested_property_id"] = int(row.get("suggested_property_id") or 0)
        row["suggested_property_uuid"] = normalize_uuid(row.get("suggested_property_uuid") or "")
        items.append(row)
        if row["unresolved"]:
            unresolved_count += 1
            if (not row["ignore_agent2"]) and row["classification"] not in {"spam", "solicitor"}:
                unresolved_active_count += 1
    return {
        "cutoff_utc": "",
        "count": len(items),
        "unresolved_count": unresolved_count,
        "unresolved_active_count": unresolved_active_count,
        "items": items,
    }


def enqueue_agent_refresh(db, property_id, reason="", delay_seconds=0):
    pid = int(property_id or 0)
    if pid <= 0:
        return None
    # Debounce repeated events for the same property by resetting to latest run_after.
    db.execute(
        """
        DELETE FROM agent_refresh_queue
        WHERE property_id = ?
          AND status = 'Queued'
        """,
        (pid,),
    )
    run_after_dt = datetime.utcnow() + timedelta(seconds=max(0, int(delay_seconds or 0)))
    cur = db.execute(
        """
        INSERT INTO agent_refresh_queue (property_id, reason, run_after, status, summary_json, updated_at)
        VALUES (?, ?, ?, 'Queued', '{}', CURRENT_TIMESTAMP)
        """,
        (pid, (reason or "").strip()[:120], format_db_time(run_after_dt)),
    )
    return int(cur.lastrowid or 0)


def run_agent_refresh_queue_once(limit=25):
    ensure_db()
    db = open_sqlite_connection()
    lock_acquired = False
    try:
        lock_acquired = AGENT_PIPELINE_LOCK.acquire(timeout=20)
        if not lock_acquired:
            return {"ok": True, "skipped": "agent_pipeline_busy"}
        now_utc = format_db_time(datetime.utcnow())
        rows = db.execute(
            """
            SELECT id, property_id, reason
            FROM agent_refresh_queue
            WHERE status = 'Queued'
              AND run_after <= ?
            ORDER BY run_after ASC, id ASC
            LIMIT ?
            """,
            (now_utc, max(1, int(limit))),
        ).fetchall()
        processed = 0
        for row in rows:
            qid = int(row["id"])
            pid = int(row["property_id"] or 0)
            db.execute(
                "UPDATE agent_refresh_queue SET status = 'Running', updated_at = CURRENT_TIMESTAMP WHERE id = ?",
                (qid,),
            )
            try:
                result = trigger_agent_pipeline_refresh(db, property_id=pid, reason=str(row["reason"] or "queued_refresh"))
                db.execute(
                    """
                    UPDATE agent_refresh_queue
                    SET status = 'Completed', summary_json = ?, updated_at = CURRENT_TIMESTAMP
                    WHERE id = ?
                    """,
                    (json.dumps(result), qid),
                )
            except Exception as exc:
                db.execute(
                    """
                    UPDATE agent_refresh_queue
                    SET status = 'Error', summary_json = ?, updated_at = CURRENT_TIMESTAMP
                    WHERE id = ?
                    """,
                    (json.dumps({"error": str(exc)}), qid),
                )
            processed += 1
        db.commit()
        return {"ok": True, "processed": processed}
    except Exception as exc:
        db.rollback()
        log_app_error(
            db,
            source="agent_refresh_queue",
            error_message=str(exc),
            details=traceback.format_exc(),
            route="run_agent_refresh_queue_once",
            status_code=500,
        )
        db.commit()
        return {"ok": False, "error": str(exc)}
    finally:
        if lock_acquired:
            AGENT_PIPELINE_LOCK.release()
        db.close()


def start_agent_refresh_worker():
    global AGENT_REFRESH_WORKER_STARTED
    if AGENT_REFRESH_WORKER_STARTED or not AGENT_REFRESH_WORKER_ENABLED:
        return
    AGENT_REFRESH_WORKER_STARTED = True

    def worker():
        while True:
            try:
                run_agent_refresh_queue_once(limit=30)
            except Exception:
                pass
            time.sleep(AGENT_REFRESH_POLL_SECONDS)

    thread = threading.Thread(target=worker, daemon=True)
    thread.start()


