@app.route("/authority", methods=["GET", "POST"])
def authority_page():
    ensure_db()
    db = get_db()
    notice = (request.args.get("notice") or "").strip()
    error_notice = (request.args.get("error") or "").strip()
    if request.method == "POST":
        action = (request.form.get("authority_action") or "").strip().lower()
        try:
            if action == "add_feed":
                name = (request.form.get("feed_name") or "").strip()
                url = (request.form.get("feed_url") or "").strip()
                feed_type = (request.form.get("feed_type") or "rss").strip().lower()[:20] or "rss"
                notes = (request.form.get("feed_notes") or "").strip()
                is_active = 1 if (request.form.get("feed_is_active") or "").strip().lower() in {"1", "true", "yes", "on"} else 0
                if not name:
                    raise ValueError("Feed name is required.")
                if not (url.startswith("http://") or url.startswith("https://")):
                    raise ValueError("Feed URL must start with http:// or https://")
                try:
                    db.execute(
                        """
                        INSERT INTO authority_feeds (name, url, feed_type, notes, is_active, updated_at)
                        VALUES (?, ?, ?, ?, ?, CURRENT_TIMESTAMP)
                        """,
                        (name[:120], url[:700], feed_type, notes[:1200], is_active),
                    )
                    notice = "Feed added."
                except sqlite3.IntegrityError:
                    db.execute(
                        """
                        UPDATE authority_feeds
                        SET name = ?, feed_type = ?, notes = ?, is_active = ?, updated_at = CURRENT_TIMESTAMP
                        WHERE url = ?
                        """,
                        (name[:120], feed_type, notes[:1200], is_active, url[:700]),
                    )
                    notice = "Feed already existed. Existing feed updated."
            elif action == "toggle_feed":
                feed_id_raw = (request.form.get("feed_id") or "").strip()
                next_state_raw = (request.form.get("next_state") or "").strip().lower()
                if not feed_id_raw.isdigit():
                    raise ValueError("Feed id is required.")
                next_state = 1 if next_state_raw in {"1", "true", "yes", "on"} else 0
                db.execute(
                    """
                    UPDATE authority_feeds
                    SET is_active = ?, updated_at = CURRENT_TIMESTAMP
                    WHERE id = ?
                    """,
                    (next_state, int(feed_id_raw)),
                )
                notice = "Feed status updated."
            elif action == "delete_feed":
                feed_id_raw = (request.form.get("feed_id") or "").strip()
                if not feed_id_raw.isdigit():
                    raise ValueError("Feed id is required.")
                db.execute("DELETE FROM authority_feeds WHERE id = ?", (int(feed_id_raw),))
                notice = "Feed removed."
            elif action == "run_research":
                focus_topic = (request.form.get("focus_topic") or "").strip()
                target_audience = (request.form.get("target_audience") or "").strip()
                channel_focus = (request.form.get("channel_focus") or "").strip()
                idea_count_raw = (request.form.get("idea_count") or "").strip()
                selected_feed_ids = request.form.getlist("selected_feed_ids")
                try:
                    idea_count = int(idea_count_raw or "8")
                except Exception:
                    idea_count = 8
                result = run_authority_research_once(
                    db,
                    focus_topic=focus_topic,
                    target_audience=target_audience,
                    channel_focus=channel_focus,
                    requested_idea_count=idea_count,
                    selected_feed_ids=selected_feed_ids,
                )
                notice = (
                    f"Research run #{result.get('run_id')} completed. "
                    f"Ideas: {result.get('ideas_inserted', 0)}, mode: {result.get('generation_mode', 'fallback')}."
                )
                if result.get("errors"):
                    notice += f" Warnings: {len(result.get('errors') or [])}."
            elif action == "update_idea":
                idea_id_raw = (request.form.get("idea_id") or "").strip()
                idea_status = (request.form.get("idea_status") or "").strip()
                editor_notes = (request.form.get("editor_notes") or "").strip()
                if not idea_id_raw.isdigit():
                    raise ValueError("Idea id is required.")
                if idea_status not in AUTHORITY_IDEA_STATUSES:
                    raise ValueError("Invalid idea status.")
                db.execute(
                    """
                    UPDATE authority_research_ideas
                    SET status = ?, editor_notes = ?, updated_at = CURRENT_TIMESTAMP
                    WHERE id = ?
                    """,
                    (idea_status, editor_notes[:4000], int(idea_id_raw)),
                )
                notice = "Idea updated."
            else:
                raise ValueError("Unknown authority action.")
            db.commit()
            return redirect(url_for("authority_page", notice=notice))
        except Exception as exc:
            db.rollback()
            log_app_error(
                db,
                source="authority_page",
                error_message=str(exc),
                details=traceback.format_exc(),
                route="/authority",
                status_code=500,
            )
            db.commit()
            return redirect(url_for("authority_page", error=str(exc)))

    feeds = db.execute(
        """
        SELECT id, name, url, feed_type, notes, is_active, last_fetched_at, last_fetch_status, last_fetch_error, created_at, updated_at
        FROM authority_feeds
        ORDER BY is_active DESC, id DESC
        """
    ).fetchall()
    feed_rows = []
    for row in feeds:
        item = dict(row)
        item["is_active"] = bool(item.get("is_active"))
        feed_rows.append(item)

    runs = db.execute(
        """
        SELECT r.id, r.status, r.focus_topic, r.target_audience, r.channel_focus, r.requested_idea_count,
               r.prompt_json, r.summary_json, r.started_at, r.completed_at, r.created_at, r.updated_at,
               (SELECT COUNT(*) FROM authority_research_ideas i WHERE i.run_id = r.id) AS ideas_count
        FROM authority_research_runs r
        ORDER BY r.id DESC
        LIMIT 40
        """
    ).fetchall()
    run_rows = []
    for row in runs:
        item = dict(row)
        item["prompt_obj"] = parse_json_object(item.get("prompt_json") or "{}")
        item["summary_obj"] = parse_json_object(item.get("summary_json") or "{}")
        run_rows.append(item)

    ideas = db.execute(
        """
        SELECT i.id, i.run_id, i.title, i.angle, i.target_audience, i.platform_primary, i.hook, i.thesis,
               i.outline_json, i.cta, i.seo_keywords_json, i.sources_json, i.confidence, i.status, i.editor_notes, i.created_at, i.updated_at,
               r.focus_topic, r.status AS run_status, r.created_at AS run_created_at
        FROM authority_research_ideas i
        LEFT JOIN authority_research_runs r ON r.id = i.run_id
        ORDER BY i.id DESC
        LIMIT 180
        """
    ).fetchall()
    idea_rows = []
    for row in ideas:
        item = dict(row)
        try:
            outline = json.loads(item.get("outline_json") or "[]")
        except Exception:
            outline = []
        try:
            keywords = json.loads(item.get("seo_keywords_json") or "[]")
        except Exception:
            keywords = []
        try:
            sources = json.loads(item.get("sources_json") or "[]")
        except Exception:
            sources = []
        item["outline_items"] = [str(x).strip() for x in outline if str(x).strip()]
        item["seo_keywords"] = [str(x).strip() for x in keywords if str(x).strip()]
        normalized_sources = []
        for src in sources if isinstance(sources, list) else []:
            if isinstance(src, dict):
                source_title = str(src.get("title") or src.get("name") or "").strip()
                source_url = str(src.get("url") or "").strip()
            else:
                source_title = str(src).strip()
                source_url = ""
            if source_title or source_url:
                normalized_sources.append({"title": source_title, "url": source_url})
        item["sources_list"] = normalized_sources
        idea_rows.append(item)

    return render_template(
        "authority.html",
        notice=notice,
        error_notice=error_notice,
        feeds=feed_rows,
        runs=run_rows,
        ideas=idea_rows,
        audiences=AUTHORITY_AUDIENCES,
        channels=AUTHORITY_CHANNELS,
        idea_statuses=AUTHORITY_IDEA_STATUSES,
    )


def run_agent3_lead_watch_reconcile(db, limit=80):
    snapshot = build_agent3_lead_watch_snapshot_from_logs(db, limit=limit)
    suggested = 0
    touched = 0
    for item in snapshot.get("items", []):
        lead_key = (item.get("lead_key") or "").strip()
        if not lead_key:
            continue
        if int(item.get("property_id") or 0):
            continue
        hints = item.get("address_hints") or []
        if not hints:
            continue
        hint = str(hints[0]).strip()
        if not hint:
            continue
        hinted_uuid = normalize_uuid(item.get("reisift_property_uuid") or "")
        if hinted_uuid:
            touched += 1
            db.execute(
                """
                INSERT INTO agent3_lead_resolutions
                (lead_key, suggested_property_uuid, status, notes, updated_at)
                VALUES (?, ?, 'Pending', ?, CURRENT_TIMESTAMP)
                ON CONFLICT(lead_key) DO UPDATE SET
                    suggested_property_uuid = excluded.suggested_property_uuid,
                    status = CASE
                        WHEN agent3_lead_resolutions.status IN ('Approved', 'Rejected') THEN agent3_lead_resolutions.status
                        ELSE 'Pending'
                    END,
                    notes = excluded.notes,
                    updated_at = CURRENT_TIMESTAMP
                """,
                (
                    lead_key,
                    hinted_uuid,
                    f"Agent 3 suggested ReiSIFT UUID from referral match: {hinted_uuid}",
                ),
            )
            suggested += 1
            continue
        like = f"%{hint.lower()}%"
        match = db.execute(
            """
            SELECT p.id
            FROM properties p
            JOIN addresses a ON a.id = p.property_address_id
            WHERE lower(a.street || ' ' || a.city || ' ' || a.state || ' ' || a.postal_code) LIKE ?
            ORDER BY p.id DESC
            LIMIT 1
            """,
            (like,),
        ).fetchone()
        if not match:
            continue
        touched += 1
        db.execute(
            """
            INSERT INTO agent3_lead_resolutions
            (lead_key, suggested_property_id, suggested_property_uuid, status, notes, updated_at)
            VALUES (?, ?, NULL, 'Pending', ?, CURRENT_TIMESTAMP)
            ON CONFLICT(lead_key) DO UPDATE SET
                suggested_property_id = excluded.suggested_property_id,
                suggested_property_uuid = NULL,
                status = CASE
                    WHEN agent3_lead_resolutions.status IN ('Approved', 'Rejected') THEN agent3_lead_resolutions.status
                    ELSE 'Pending'
                END,
                notes = excluded.notes,
                updated_at = CURRENT_TIMESTAMP
            """,
            (
                lead_key,
                int(match["id"]),
                f"Agent 3 suggested property match from address hint: {hint}",
            ),
        )
        suggested += 1
    return {"inspected": int(snapshot.get("count") or 0), "suggested": suggested, "touched": touched}


@app.route("/agents")
def agents_page():
    ensure_db()
    db = get_db()
    try:
        maybe_run_agent3_end_of_day_refresh(db)
    except Exception:
        # Never block the agents page if nightly closeout generation fails.
        pass
    notice = (request.args.get("notice") or "").strip()
    queue_counts = db.execute(
        """
        SELECT
            SUM(CASE WHEN queue_status = 'Queued' THEN 1 ELSE 0 END) AS queued_count,
            SUM(CASE WHEN queue_status = 'No Realtor' THEN 1 ELSE 0 END) AS no_realtor_count
        FROM referral_auto_send_queue
        """
    ).fetchone()
    summary = {
        "queued_count": int((queue_counts["queued_count"] or 0) if queue_counts else 0),
        "no_realtor_count": int((queue_counts["no_realtor_count"] or 0) if queue_counts else 0),
    }
    dedupe_stats = dedupe_pending_lead_actions_by_rollup(db)
    if int(dedupe_stats.get("closed_duplicates") or 0) > 0:
        db.commit()
    lead_counts = db.execute(
        """
        SELECT
            SUM(CASE WHEN status = 'Pending' THEN 1 ELSE 0 END) AS pending_count,
            SUM(CASE WHEN status = 'Pending' AND priority = 'High' THEN 1 ELSE 0 END) AS high_count,
            SUM(CASE WHEN status = 'Pending' AND action_type IN ('EscalateToRelativeOutreach', 'EscalateToDeepDiveResearch') THEN 1 ELSE 0 END) AS escalation_count
        FROM lead_management_actions
        """
    ).fetchone()
    lead_summary = {
        "pending_count": int((lead_counts["pending_count"] if lead_counts else 0) or 0),
        "high_count": int((lead_counts["high_count"] if lead_counts else 0) or 0),
        "escalation_count": int((lead_counts["escalation_count"] if lead_counts else 0) or 0),
    }
    lead_actions = db.execute(
        """
        SELECT a.id, a.property_id, a.person_id, a.action_type, a.priority, a.status, a.reason, a.payload_json, a.due_at, a.created_at, a.updated_at, a.contact_classification,
               adr.street, adr.city, adr.state, adr.postal_code,
               pe.first_name, pe.middle_name, pe.last_name
        FROM lead_management_actions a
        LEFT JOIN properties p ON p.id = a.property_id
        LEFT JOIN addresses adr ON adr.id = p.property_address_id
        LEFT JOIN people pe ON pe.id = a.person_id
        WHERE a.status = 'Pending'
        ORDER BY
            CASE a.status WHEN 'Pending' THEN 0 WHEN 'Approved' THEN 1 WHEN 'Completed' THEN 2 ELSE 3 END,
            CASE a.priority WHEN 'High' THEN 0 WHEN 'Medium' THEN 1 ELSE 2 END,
            a.updated_at DESC,
            a.id DESC
        LIMIT 200
        """
    ).fetchall()
    lead_actions_enriched = []
    system_numbers_for_page = _known_system_numbers(db, refresh_seconds=300)
    for row in lead_actions:
        item = dict(row)
        item["contact_classification"] = normalize_lead_contact_classification(item.get("contact_classification") or "")
        address_parts = [str(item.get("street") or "").strip(), str(item.get("city") or "").strip()]
        state_zip = " ".join(
            p for p in [str(item.get("state") or "").strip(), str(item.get("postal_code") or "").strip()] if p
        ).strip()
        if state_zip:
            address_parts.append(state_zip)
        address_label = ", ".join([p for p in address_parts if p]).strip()

        payload_obj = parse_json_object(item.get("payload_json") or "{}")
        snapshot = payload_obj.get("snapshot") if isinstance(payload_obj.get("snapshot"), dict) else {}
        signal_obj = payload_obj.get("signal") if isinstance(payload_obj.get("signal"), dict) else {}
        signal_event = (
            extract_first_string_by_keys(signal_obj, ["event", "eventType"])
            or extract_first_string_by_keys(payload_obj, ["event", "eventType"])
        ).lower()
        signal_from = normalize_phone(
            extract_first_string_by_keys(signal_obj, ["from", "from_number"])
            or extract_first_string_by_keys(payload_obj, ["from", "from_number"])
        )
        signal_to = normalize_phone(
            extract_first_string_by_keys(signal_obj, ["to", "to_number"])
            or extract_first_string_by_keys(payload_obj, ["to", "to_number"])
        )
        signal_message = (
            extract_first_string_by_keys(signal_obj, ["message", "body", "text"])
            or extract_first_string_by_keys(payload_obj, ["message", "body", "text"])
        ).strip()
        signal_classification = str(
            signal_obj.get("classification") if isinstance(signal_obj, dict) else payload_obj.get("classification") or ""
        ).strip().lower()
        signal_is_inbound = "incoming" in signal_event
        signal_is_outbound = "outgoing" in signal_event
        item["lead_key"] = str(snapshot.get("lead_key") or payload_obj.get("lead_key") or "").strip()
        item["latest_inbound_text"] = str(payload_obj.get("latest_inbound") or snapshot.get("latest_inbound") or "").strip()
        item["timeline_override"] = payload_obj.get("timeline_override") if isinstance(payload_obj.get("timeline_override"), dict) else {}
        if not snapshot and (signal_is_inbound or signal_is_outbound or signal_message):
            snapshot = {
                "sms_outbound": 1 if signal_is_outbound else 0,
                "sms_inbound": 1 if signal_is_inbound else 0,
                "calls": 0,
                "classification": signal_classification or "unknown",
                "reisift_status": "-",
            }
        elif snapshot and (signal_is_inbound or signal_is_outbound):
            # For unresolved signal payloads that still have sparse snapshots, populate visible counts.
            snapshot.setdefault("sms_outbound", 1 if signal_is_outbound else 0)
            snapshot.setdefault("sms_inbound", 1 if signal_is_inbound else 0)
            snapshot.setdefault("calls", 0)
            snapshot.setdefault("classification", signal_classification or "unknown")
            snapshot.setdefault("reisift_status", "-")
        item["snapshot_obj"] = snapshot
        phone_candidates = []
        for n in (snapshot.get("phones") if isinstance(snapshot.get("phones"), list) else []):
            norm = normalize_phone(n)
            if norm and norm not in phone_candidates:
                phone_candidates.append(norm)
        for key in ["counterpart", "phone", "counterpart_number"]:
            val = extract_first_string_by_keys(payload_obj, [key])
            norm = normalize_phone(val)
            if norm and norm not in phone_candidates:
                phone_candidates.append(norm)
        for n in [signal_from, signal_to]:
            if n and n not in phone_candidates:
                phone_candidates.append(n)
        if not phone_candidates and str(item["lead_key"]).lower().startswith("phone:"):
            lead_phone = normalize_phone(str(item["lead_key"]).split(":", 1)[1])
            if lead_phone:
                phone_candidates.append(lead_phone)
        phone_label = ", ".join(format_phone_display(n) for n in phone_candidates if n)
        item["phone_candidates"] = phone_candidates
        item["phone_candidates_display"] = ", ".join(format_phone_display(n) for n in phone_candidates if n)

        item["target_label"] = address_label or (phone_label if phone_label else "-")
        item["target_kind"] = "address" if address_label else ("phone" if phone_label else "none")
        snapshot_uuid = normalize_uuid(snapshot.get("reisift_property_uuid") or payload_obj.get("reisift_property_uuid") or "")
        item["reisift_property_uuid"] = snapshot_uuid
        item["open_record_url"] = _sift_record_url(snapshot_uuid) if snapshot_uuid else ""
        item["resolver_source"] = "snapshot" if snapshot_uuid else ""
        item["resolver_phone"] = ""
        item["last_call_summary"] = ""
        item["last_call_at"] = ""
        item["last_sms_summary"] = ""
        item["last_sms_at"] = ""
        if signal_message:
            from_disp = format_phone_display(signal_from) if signal_from else "-"
            to_disp = format_phone_display(signal_to) if signal_to else "-"
            if signal_is_inbound:
                dir_label = "Inbound SMS"
            elif signal_is_outbound:
                dir_label = "Outbound SMS"
            else:
                dir_label = "SMS"
            item["last_sms_summary"] = f"{dir_label} from {from_disp} to {to_disp}. Message: {signal_message}"
            item["last_sms_at"] = str(item.get("updated_at") or item.get("created_at") or "").strip()
            if signal_is_inbound and not item["latest_inbound_text"]:
                item["latest_inbound_text"] = signal_message
        if not item["resolver_phone"]:
            counterparty = ""
            if signal_is_inbound:
                if signal_from and signal_from not in system_numbers_for_page:
                    counterparty = signal_from
            elif signal_is_outbound:
                if signal_to and signal_to not in system_numbers_for_page:
                    counterparty = signal_to
            else:
                for n in [signal_from, signal_to]:
                    if n and n not in system_numbers_for_page:
                        counterparty = n
                        break
            if counterparty:
                item["resolver_phone"] = format_phone_display(counterparty)
        lead_actions_enriched.append(item)
    lead_actions = lead_actions_enriched
    latest_run = db.execute(
        """
        SELECT id, source, property_id, status, summary_json, created_at, completed_at
        FROM lead_monitor_runs
        ORDER BY id DESC
        LIMIT 1
        """
    ).fetchone()
    latest_run_summary = {}
    if latest_run and latest_run["summary_json"]:
        latest_run_summary = parse_json_object(latest_run["summary_json"])
    call_job_counts = db.execute(
        """
        SELECT
            SUM(CASE WHEN analysis_status IN ('Pending', 'Retry') THEN 1 ELSE 0 END) AS pending_count,
            SUM(CASE WHEN analysis_status = 'Completed' THEN 1 ELSE 0 END) AS completed_count
        FROM call_recording_jobs
        """
    ).fetchone()
    call_job_summary = {
        "pending_count": int((call_job_counts["pending_count"] if call_job_counts else 0) or 0),
        "completed_count": int((call_job_counts["completed_count"] if call_job_counts else 0) or 0),
    }
    call_jobs = db.execute(
        """
        SELECT id, call_sid, property_id, person_id, from_number, to_number, recording_url, fetch_status, analysis_status, transcript_text, summary_text, analysis_json, payload_json, created_at, updated_at
        FROM call_recording_jobs
        ORDER BY id DESC
        LIMIT 100
        """
    ).fetchall()
    signal_counts = db.execute(
        """
        SELECT
            SUM(CASE WHEN routing_status = 'new' THEN 1 ELSE 0 END) AS new_count,
            SUM(CASE WHEN routing_status = 'routed' THEN 1 ELSE 0 END) AS routed_count,
            SUM(CASE WHEN source_type = 'sms' THEN 1 ELSE 0 END) AS sms_count,
            SUM(CASE WHEN source_type = 'call' THEN 1 ELSE 0 END) AS call_count
        FROM agent_signals
        """
    ).fetchone()
    signal_summary = {
        "new_count": int((signal_counts["new_count"] if signal_counts else 0) or 0),
        "routed_count": int((signal_counts["routed_count"] if signal_counts else 0) or 0),
        "sms_count": int((signal_counts["sms_count"] if signal_counts else 0) or 0),
        "call_count": int((signal_counts["call_count"] if signal_counts else 0) or 0),
    }
    signals = db.execute(
        """
        SELECT id, source_type, source_key, property_id, person_id, intent, sentiment, confidence, recommended_next_step, routing_status, summary_text, payload_json, updated_at
        FROM agent_signals
        WHERE lower(COALESCE(source_type, '')) = 'sms'
        ORDER BY id DESC
        LIMIT 100
        """
    ).fetchall()

    def _property_uuid_map(ids):
        out = {}
        clean_ids = [int(x) for x in ids if int(x or 0) > 0]
        if not clean_ids:
            return out
        placeholders = ",".join(["?"] * len(clean_ids))
        try:
            rows = db.execute(
                f"SELECT id, reisift_property_uuid FROM properties WHERE id IN ({placeholders})",
                tuple(clean_ids),
            ).fetchall()
            for r in rows:
                out[int(r["id"])] = normalize_uuid(r["reisift_property_uuid"] or "")
        except Exception:
            return {}
        return out

    def _resolve_uuid_from_numbers(numbers, fallback_property_id=None):
        resolved = resolve_shared_contact_context_by_numbers(
            db,
            numbers,
            fallback_property_id=fallback_property_id,
            force_reisift=False,
            search_reisift=False,
        ) or {}
        uuid_value = normalize_uuid(resolved.get("reisift_property_uuid") or "")
        resolver_source = str(resolved.get("source") or "").strip()
        resolver_phone = normalize_phone(resolved.get("phone_norm") or "")
        if uuid_value:
            return {
                "uuid": uuid_value,
                "source": resolver_source or "cache",
                "phone_norm": resolver_phone,
            }
        pid = int(resolved.get("property_id") or 0)
        if pid and property_uuid_by_id.get(pid, ""):
            return {
                "uuid": property_uuid_by_id.get(pid, ""),
                "source": resolver_source or "local_property",
                "phone_norm": resolver_phone,
            }
        if int(fallback_property_id or 0) > 0 and property_uuid_by_id.get(int(fallback_property_id), ""):
            return {
                "uuid": property_uuid_by_id.get(int(fallback_property_id), ""),
                "source": "local_property",
                "phone_norm": resolver_phone,
            }
        return {"uuid": "", "source": resolver_source or "", "phone_norm": resolver_phone}

    all_property_ids = set()
    for r in lead_actions:
        if int(r.get("property_id") or 0):
            all_property_ids.add(int(r.get("property_id") or 0))
    for r in call_jobs:
        if int(r["property_id"] or 0):
            all_property_ids.add(int(r["property_id"]))
    for r in signals:
        if int(r["property_id"] or 0):
            all_property_ids.add(int(r["property_id"]))
    property_uuid_by_id = _property_uuid_map(sorted(list(all_property_ids)))
    latest_inbound_by_property = {}
    lead_property_ids = sorted({int(r.get("property_id") or 0) for r in lead_actions if int(r.get("property_id") or 0) > 0})
    if lead_property_ids:
        placeholders = ",".join(["?"] * len(lead_property_ids))
        inbound_rows = db.execute(
            f"""
            SELECT property_id, body, COALESCE(sent_at, created_at) AS when_at, id
            FROM communications
            WHERE lower(direction) = 'inbound'
              AND property_id IN ({placeholders})
            ORDER BY property_id ASC, COALESCE(sent_at, created_at) DESC, id DESC
            """,
            tuple(lead_property_ids),
        ).fetchall()
        for r in inbound_rows:
            pid = int(r["property_id"] or 0)
            if pid <= 0 or pid in latest_inbound_by_property:
                continue
            latest_inbound_by_property[pid] = {
                "body": str(r["body"] or "").strip(),
                "when": str(r["when_at"] or "").strip(),
            }

    call_jobs_enriched = []
    for row in call_jobs:
        item = dict(row)
        phone_candidates = [item.get("from_number"), item.get("to_number")]
        resolved_link = _resolve_uuid_from_numbers(phone_candidates, fallback_property_id=item.get("property_id"))
        uuid = normalize_uuid(resolved_link.get("uuid") or "")
        item["reisift_property_uuid"] = uuid
        item["open_record_url"] = _sift_record_url(uuid)
        item["resolver_source"] = str(resolved_link.get("source") or "").strip()
        item["resolver_phone"] = format_phone_display(resolved_link.get("phone_norm") or "")
        payload_obj = parse_json_object(item.get("payload_json") or "{}")
        analysis_obj = parse_json_object(item.get("analysis_json") or "{}")
        context = payload_obj.get("analysis_context") if isinstance(payload_obj.get("analysis_context"), dict) else {}
        detail = compose_call_summary(context, analysis_obj, str(item.get("transcript_text") or ""))
        if not detail:
            detail = str(item.get("summary_text") or "").strip()
        item["detail_summary"] = detail
        call_jobs_enriched.append(item)

    signals_enriched = []
    for row in signals:
        item = dict(row)
        payload_obj = parse_json_object(item.get("payload_json") or "{}")
        phone_candidates = []
        for key in ["from", "to", "counterpart", "phone", "counterpart_number"]:
            val = extract_first_string_by_keys(payload_obj, [key])
            if val:
                phone_candidates.append(val)
        # Fallback parse from source key (e.g., sms_thread:0:0:9734492338)
        source_key = str(item.get("source_key") or "")
        source_tail = source_key.rsplit(":", 1)[-1] if ":" in source_key else ""
        if normalize_phone(source_tail):
            phone_candidates.append(source_tail)
        resolved_link = _resolve_uuid_from_numbers(phone_candidates, fallback_property_id=item.get("property_id"))
        uuid = normalize_uuid(resolved_link.get("uuid") or "")
        item["reisift_property_uuid"] = uuid
        item["open_record_url"] = _sift_record_url(uuid)
        item["resolver_source"] = str(resolved_link.get("source") or "").strip()
        item["resolver_phone"] = format_phone_display(resolved_link.get("phone_norm") or "")
        item["detail_summary"] = compose_sms_signal_detail(item) if str(item.get("source_type") or "").lower() == "sms" else str(item.get("summary_text") or "").strip()
        item["phone_candidates"] = [normalize_phone(x) for x in phone_candidates if normalize_phone(x)]
        signals_enriched.append(item)

    latest_call_by_phone = {}
    latest_call_by_property = {}
    latest_call_by_uuid = {}
    for row in call_jobs_enriched:
        detail = str(row.get("detail_summary") or row.get("summary_text") or "").strip()
        if not detail:
            continue
        when = str(row.get("updated_at") or row.get("created_at") or "").strip()
        for raw in [row.get("from_number"), row.get("to_number"), row.get("resolver_phone")]:
            n = normalize_phone(raw)
            if n and n not in latest_call_by_phone:
                latest_call_by_phone[n] = {"summary": detail, "when": when}
        pid = int(row.get("property_id") or 0)
        if pid > 0 and pid not in latest_call_by_property:
            latest_call_by_property[pid] = {"summary": detail, "when": when}
        uuid_key = normalize_uuid(row.get("reisift_property_uuid") or "")
        if uuid_key and uuid_key not in latest_call_by_uuid:
            latest_call_by_uuid[uuid_key] = {"summary": detail, "when": when}

    latest_sms_by_phone = {}
    latest_sms_by_property = {}
    latest_sms_by_uuid = {}
    for row in signals_enriched:
        detail = str(row.get("detail_summary") or row.get("summary_text") or "").strip()
        if not detail:
            continue
        when = str(row.get("updated_at") or "").strip()
        for raw in list(row.get("phone_candidates") or []) + [row.get("resolver_phone")]:
            n = normalize_phone(raw)
            if n and n not in latest_sms_by_phone:
                latest_sms_by_phone[n] = {"summary": detail, "when": when}
        pid = int(row.get("property_id") or 0)
        if pid > 0 and pid not in latest_sms_by_property:
            latest_sms_by_property[pid] = {"summary": detail, "when": when}
        uuid_key = normalize_uuid(row.get("reisift_property_uuid") or "")
        if uuid_key and uuid_key not in latest_sms_by_uuid:
            latest_sms_by_uuid[uuid_key] = {"summary": detail, "when": when}

    lead_actions_with_context = []
    for item in lead_actions:
        resolved_link = _resolve_uuid_from_numbers(item.get("phone_candidates") or [], fallback_property_id=item.get("property_id"))
        uuid = normalize_uuid(resolved_link.get("uuid") or "")
        if uuid:
            item["reisift_property_uuid"] = uuid
            item["open_record_url"] = _sift_record_url(uuid)
            item["resolver_source"] = str(resolved_link.get("source") or "").strip() or item.get("resolver_source") or ""
        elif not item.get("reisift_property_uuid"):
            item["reisift_property_uuid"] = ""
            item["open_record_url"] = ""
        item["resolver_phone"] = format_phone_display(resolved_link.get("phone_norm") or "") or item.get("resolver_phone") or ""
        for n in item.get("phone_candidates") or []:
            if n in latest_call_by_phone and not item["last_call_summary"]:
                item["last_call_summary"] = latest_call_by_phone[n]["summary"]
                item["last_call_at"] = latest_call_by_phone[n]["when"]
            if n in latest_sms_by_phone and not item["last_sms_summary"]:
                item["last_sms_summary"] = latest_sms_by_phone[n]["summary"]
                item["last_sms_at"] = latest_sms_by_phone[n]["when"]
        property_id = int(item.get("property_id") or 0)
        if property_id > 0:
            if not item["last_call_summary"] and property_id in latest_call_by_property:
                item["last_call_summary"] = latest_call_by_property[property_id]["summary"]
                item["last_call_at"] = latest_call_by_property[property_id]["when"]
            if not item["last_sms_summary"] and property_id in latest_sms_by_property:
                item["last_sms_summary"] = latest_sms_by_property[property_id]["summary"]
                item["last_sms_at"] = latest_sms_by_property[property_id]["when"]
            if not item["latest_inbound_text"] and property_id in latest_inbound_by_property:
                item["latest_inbound_text"] = latest_inbound_by_property[property_id]["body"]
        uuid_key = normalize_uuid(item.get("reisift_property_uuid") or "")
        if uuid_key:
            if not item["last_call_summary"] and uuid_key in latest_call_by_uuid:
                item["last_call_summary"] = latest_call_by_uuid[uuid_key]["summary"]
                item["last_call_at"] = latest_call_by_uuid[uuid_key]["when"]
            if not item["last_sms_summary"] and uuid_key in latest_sms_by_uuid:
                item["last_sms_summary"] = latest_sms_by_uuid[uuid_key]["summary"]
                item["last_sms_at"] = latest_sms_by_uuid[uuid_key]["when"]
        if not item["latest_inbound_text"] and item["last_sms_summary"]:
            item["latest_inbound_text"] = item["last_sms_summary"]
        if not item["last_sms_summary"]:
            item["last_sms_summary"] = str(item.get("reason") or "").strip()
        if not item["last_call_summary"] and item["last_sms_summary"]:
            item["last_call_summary"] = item["last_sms_summary"]
        lead_actions_with_context.append(item)
    lead_actions = lead_actions_with_context

    advisor_snapshot = build_agent_advisor_snapshot(db, window_hours=72)
    advisor_recommendations = build_agent_advisor_recommendations(advisor_snapshot)
    advisor_summary_row = db.execute(
        """
        SELECT id, response_text, response_json, snapshot_json, created_at
        FROM agent_advisor_logs
        WHERE log_type = 'summary'
        ORDER BY id DESC
        LIMIT 1
        """
    ).fetchone()
    advisor_qa_rows = db.execute(
        """
        SELECT id, question, response_text, created_at
        FROM agent_advisor_logs
        WHERE log_type = 'qa'
        ORDER BY id DESC
        LIMIT 12
        """
    ).fetchall()
    return render_template(
        "agents.html",
        agents=AGENT_DEFINITIONS,
        summary=summary,
        lead_summary=lead_summary,
        lead_actions=lead_actions,
        lead_action_statuses=LEAD_ACTION_STATUSES,
        lead_action_types=LEAD_ACTION_TYPES,
        lead_action_priorities=LEAD_ACTION_PRIORITIES,
        lead_contact_classifications=LEAD_CONTACT_CLASSIFICATIONS,
        latest_run=latest_run,
        latest_run_summary=latest_run_summary,
        call_job_summary=call_job_summary,
        call_jobs=call_jobs_enriched,
        signal_summary=signal_summary,
        signals=signals_enriched,
        advisor_snapshot=advisor_snapshot,
        advisor_recommendations=advisor_recommendations,
        advisor_summary_row=advisor_summary_row,
        advisor_qa_rows=advisor_qa_rows,
        notice=notice,
    )


def _is_ajax_request(req):
    xr = (req.headers.get("X-Requested-With") or "").strip().lower()
    accept = (req.headers.get("Accept") or "").strip().lower()
    return xr == "xmlhttprequest" or "application/json" in accept


def _lead_key_from_action_row(action_row):
    row = dict(action_row or {})
    payload = parse_json_object(row.get("payload_json") or "{}")
    snapshot = payload.get("snapshot") if isinstance(payload.get("snapshot"), dict) else {}
    lead_key = str(snapshot.get("lead_key") or payload.get("lead_key") or "").strip()
    if not lead_key:
        dedupe = str(row.get("dedupe_key") or "").strip()
        if dedupe.startswith("leadwatch:"):
            lead_key = dedupe.split(":", 1)[1].strip()
    return lead_key


def _upsert_agent3_classification_from_action(db, action_row, contact_classification):
    classification = normalize_lead_contact_classification(contact_classification)
    lead_key = _lead_key_from_action_row(action_row)
    if not lead_key:
        return False
    db.execute(
        """
        INSERT INTO agent3_lead_resolutions
        (lead_key, classification_override, status, notes, updated_at)
        VALUES (?, ?, 'Pending', ?, CURRENT_TIMESTAMP)
        ON CONFLICT(lead_key) DO UPDATE SET
            classification_override = excluded.classification_override,
            updated_at = CURRENT_TIMESTAMP
        """,
        (
            lead_key,
            classification,
            "Classification set from Agent 2 action queue.",
        ),
    )
    return True


def _record_agent2_learning_feedback(
    db,
    action_row,
    *,
    user_action_type="",
    user_priority="",
    user_reason="",
    user_status="",
    change_source="manual",
):
    row = dict(action_row or {})
    db.execute(
        """
        INSERT INTO agent2_learning_feedback
        (
            action_id, dedupe_key, property_id, person_id,
            model_action_type, model_priority, model_reason, model_status,
            user_action_type, user_priority, user_reason, user_status, change_source
        )
        VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
        """,
        (
            int(row.get("id") or 0) or None,
            str(row.get("dedupe_key") or "").strip(),
            int(row.get("property_id") or 0),
            int(row.get("person_id") or 0) or None,
            str(row.get("action_type") or "").strip(),
            str(row.get("priority") or "").strip(),
            str(row.get("reason") or "").strip(),
            str(row.get("status") or "").strip(),
            str(user_action_type or "").strip(),
            str(user_priority or "").strip(),
            str(user_reason or "").strip(),
            str(user_status or "").strip(),
            str(change_source or "manual")[:50],
        ),
    )


@app.route("/agents/lead-monitor/run", methods=["POST"])
def run_lead_monitor_route():
    ensure_db()
    db = get_db()
    property_raw = (request.form.get("property_id") or "").strip()
    property_id = int(property_raw) if property_raw.isdigit() else None
    try:
        data = run_lead_monitor_once(db, source="manual", property_id=property_id)
        db.commit()
        notice = (
            f"Lead monitor run #{data['run_id']} completed. "
            f"Inspected {data['inspected']} properties, created {data['created_actions']} action(s), skipped {data['skipped']}."
        )
        return redirect(url_for("agents_page", notice=notice))
    except Exception as exc:
        db.rollback()
        return redirect(url_for("agents_page", notice=f"Lead monitor failed: {exc}"))


@app.route("/agents/logs/clear", methods=["POST"])
def clear_agent_logs_route():
    ensure_db()
    db = get_db()
    ajax = _is_ajax_request(request)
    try:
        c1 = db.execute("DELETE FROM lead_management_actions")
        c2 = db.execute("DELETE FROM lead_monitor_runs")
        c3 = db.execute("DELETE FROM agent_advisor_logs")
        c4 = db.execute("DELETE FROM agent3_lead_resolutions")
        c5 = db.execute("DELETE FROM agent2_learning_feedback")
        c6 = db.execute("DELETE FROM agent3_kick_logs")
        db.commit()
        msg = (
            "Cleared Agent 2/3 tables. "
            f"lead_management_actions={int(c1.rowcount or 0)}, "
            f"lead_monitor_runs={int(c2.rowcount or 0)}, "
            f"agent_advisor_logs={int(c3.rowcount or 0)}, "
            f"agent3_lead_resolutions={int(c4.rowcount or 0)}, "
            f"agent2_learning_feedback={int(c5.rowcount or 0)}, "
            f"agent3_kick_logs={int(c6.rowcount or 0)}."
        )
        if ajax:
            return jsonify(
                {
                    "ok": True,
                    "message": msg,
                    "counts": {
                        "lead_management_actions": int(c1.rowcount or 0),
                        "lead_monitor_runs": int(c2.rowcount or 0),
                        "agent_advisor_logs": int(c3.rowcount or 0),
                        "agent3_lead_resolutions": int(c4.rowcount or 0),
                        "agent2_learning_feedback": int(c5.rowcount or 0),
                        "agent3_kick_logs": int(c6.rowcount or 0),
                    },
                }
            )
        return redirect(url_for("agents_page", notice=msg))
    except Exception as exc:
        db.rollback()
        if ajax:
            return jsonify({"ok": False, "error": str(exc)}), 500
        return redirect(url_for("agents_page", notice=f"Failed to clear Agent 2/3 logs: {exc}"))


@app.route("/agents/lead-actions/<int:action_id>/status", methods=["POST"])
def update_lead_action_status_route(action_id):
    ensure_db()
    db = get_db()
    ajax = _is_ajax_request(request)
    status = (request.form.get("status") or "").strip()
    if status not in LEAD_ACTION_STATUSES:
        if ajax:
            return jsonify({"ok": False, "error": "Invalid lead action status."}), 400
        return redirect(url_for("agents_page", notice="Invalid lead action status."))
    row = db.execute(
        """
        SELECT id, dedupe_key, property_id, person_id, action_type, priority, status, reason, due_at, updated_at, payload_json, contact_classification
        FROM lead_management_actions
        WHERE id = ?
        """,
        (action_id,),
    ).fetchone()
    if not row:
        if ajax:
            return jsonify({"ok": False, "error": "Lead action not found."}), 404
        return redirect(url_for("agents_page", notice="Lead action not found."))
    _record_agent2_learning_feedback(
        db,
        row,
        user_action_type=row["action_type"],
        user_priority=row["priority"],
        user_reason=row["reason"],
        user_status=status,
        change_source="status_update",
    )
    db.execute(
        "UPDATE lead_management_actions SET status = ?, updated_at = CURRENT_TIMESTAMP WHERE id = ?",
        (status, action_id),
    )
    updated = db.execute(
        """
        SELECT id, action_type, priority, status, reason, due_at, updated_at, contact_classification
        FROM lead_management_actions
        WHERE id = ?
        """,
        (action_id,),
    ).fetchone()
    db.commit()
    if ajax:
        out = dict(updated or {})
        out["contact_classification"] = normalize_lead_contact_classification(out.get("contact_classification") or "")
        out["updated_at_est"] = format_est_datetime(out.get("updated_at") or "")
        out["due_at_est"] = format_est_datetime(out.get("due_at") or "") if str(out.get("due_at") or "").strip() else "-"
        return jsonify({"ok": True, "row": out, "message": f"Lead action #{action_id} updated to {status}."})
    return redirect(url_for("agents_page", notice=f"Lead action #{action_id} updated to {status}."))


@app.route("/agents/lead-actions/<int:action_id>/override", methods=["POST"])
def update_lead_action_override_route(action_id):
    ensure_db()
    db = get_db()
    ajax = _is_ajax_request(request)
    row = db.execute(
        """
        SELECT id, dedupe_key, property_id, person_id, payload_json, action_type, priority, reason, status, due_at, updated_at, contact_classification
        FROM lead_management_actions
        WHERE id = ?
        """,
        (action_id,),
    ).fetchone()
    if not row:
        if ajax:
            return jsonify({"ok": False, "error": "Lead action not found."}), 404
        return redirect(url_for("agents_page", notice="Lead action not found."))
    action_type = (request.form.get("action_type") or "").strip()
    priority = (request.form.get("priority") or "").strip().title()
    reason = (request.form.get("reason") or "").strip()
    if action_type not in LEAD_ACTION_TYPES:
        action_type = row["action_type"]
    if priority not in LEAD_ACTION_PRIORITIES:
        priority = row["priority"]
    if not reason:
        reason = row["reason"]
    contact_classification = normalize_lead_contact_classification(
        request.form.get("contact_classification") or row["contact_classification"] or ""
    )
    payload = parse_json_object(row["payload_json"] or "{}")
    payload["manual_override"] = {
        "at": format_db_time(datetime.utcnow()),
        "action_type": action_type,
        "priority": priority,
        "contact_classification": contact_classification,
    }
    _record_agent2_learning_feedback(
        db,
        row,
        user_action_type=action_type,
        user_priority=priority,
        user_reason=reason,
        user_status=row["status"],
        change_source="recommendation_override",
    )
    db.execute(
        """
        UPDATE lead_management_actions
        SET action_type = ?, priority = ?, reason = ?, payload_json = ?, contact_classification = ?, updated_at = CURRENT_TIMESTAMP
        WHERE id = ?
        """,
        (action_type, priority, reason, json.dumps(payload), contact_classification, action_id),
    )
    _upsert_agent3_classification_from_action(db, row, contact_classification)
    updated = db.execute(
        """
        SELECT id, action_type, priority, status, reason, due_at, updated_at, contact_classification
        FROM lead_management_actions
        WHERE id = ?
        """,
        (action_id,),
    ).fetchone()
    db.commit()
    if ajax:
        out = dict(updated or {})
        out["contact_classification"] = normalize_lead_contact_classification(out.get("contact_classification") or "")
        out["updated_at_est"] = format_est_datetime(out.get("updated_at") or "")
        out["due_at_est"] = format_est_datetime(out.get("due_at") or "") if str(out.get("due_at") or "").strip() else "-"
        return jsonify({"ok": True, "row": out, "message": f"Lead action #{action_id} recommendation updated."})
    return redirect(url_for("agents_page", notice=f"Lead action #{action_id} recommendation updated."))


@app.route("/agents/call-recordings/run", methods=["POST"])
def run_call_recordings_route():
    limit_raw = (request.form.get("limit") or "").strip()
    limit = int(limit_raw) if limit_raw.isdigit() else 2
    result = run_call_recording_analysis_once(limit=max(1, min(10, limit)))
    if result.get("ok"):
        return redirect(
            url_for(
                "agents_page",
                notice=(
                    f"Call analysis run complete. Processed {result.get('processed', 0)}, "
                    f"completed {result.get('completed', 0)}, failed {result.get('failed', 0)}."
                ),
            )
        )
    return redirect(url_for("agents_page", notice=f"Call analysis run failed: {result.get('error', 'Unknown error')}"))


@app.route("/agents/sms-analysis/run", methods=["POST"])
def run_sms_analysis_route():
    lookback_raw = (request.form.get("lookback_days") or "").strip()
    limit_raw = (request.form.get("limit_threads") or "").strip()
