@app.route("/agents/advisor/lead-watch/resolve", methods=["POST"])
def run_agent3_lead_watch_resolve_route():
    ensure_db()
    db = get_db()
    lead_key = (request.form.get("lead_key") or "").strip()
    if not lead_key:
        return redirect(url_for("agents_page", notice="Lead key is required for resolution."))
    classification = (request.form.get("classification_override") or "").strip().lower()
    status = (request.form.get("status") or "Pending").strip().title()
    approved_property_raw = (request.form.get("approved_property_id") or "").strip()
    approved_property_uuid_raw = (request.form.get("approved_property_uuid") or "").strip()
    suggested_property_raw = (request.form.get("suggested_property_id") or "").strip()
    suggested_property_uuid_raw = (request.form.get("suggested_property_uuid") or "").strip()
    ignore_agent2 = 1 if (request.form.get("ignore_agent2") or "").strip().lower() in {"1", "true", "on", "yes"} else 0
    notes = (request.form.get("notes") or "").strip()
    approved_property_id = int(approved_property_raw) if approved_property_raw.isdigit() else None
    approved_property_uuid = normalize_uuid(approved_property_uuid_raw)
    suggested_property_id = int(suggested_property_raw) if suggested_property_raw.isdigit() else None
    suggested_property_uuid = normalize_uuid(suggested_property_uuid_raw)
    if status not in {"Pending", "Approved", "Rejected"}:
        status = "Pending"
    db.execute(
        """
        INSERT INTO agent3_lead_resolutions
        (lead_key, classification_override, ignore_agent2,
         suggested_property_id, suggested_property_uuid,
         approved_property_id, approved_property_uuid,
         status, notes, updated_at)
        VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, CURRENT_TIMESTAMP)
        ON CONFLICT(lead_key) DO UPDATE SET
            classification_override = excluded.classification_override,
            ignore_agent2 = excluded.ignore_agent2,
            suggested_property_id = excluded.suggested_property_id,
            suggested_property_uuid = excluded.suggested_property_uuid,
            approved_property_id = excluded.approved_property_id,
            approved_property_uuid = excluded.approved_property_uuid,
            status = excluded.status,
            notes = excluded.notes,
            updated_at = CURRENT_TIMESTAMP
        """,
        (
            lead_key,
            classification,
            ignore_agent2,
            suggested_property_id,
            suggested_property_uuid,
            approved_property_id,
            approved_property_uuid,
            status,
            notes,
        ),
    )
    # If user approved a property, persist phone->property context from current lead-watch window events.
    if approved_property_id:
        cutoff = format_db_time(est_yesterday_start_utc())
        rows = db.execute(
            """
            SELECT from_number, to_number, payload_json
            FROM smrtphone_webhook_events
            WHERE received_at >= ?
            ORDER BY id DESC
            LIMIT 500
            """,
            (cutoff,),
        ).fetchall()
        for r in rows:
            payload = parse_json_object(r["payload_json"])
            msg = extract_first_string_by_keys(payload, ["message", "body", "text"])
            candidates = extract_address_candidates(msg)
            joined = " | ".join(candidates).lower()
            if lead_key.startswith("address:"):
                target = lead_key.split("address:", 1)[1]
                if target and target not in re.sub(r"[^a-z0-9]+", " ", joined):
                    continue
            for num in [r["from_number"], r["to_number"]]:
                upsert_cached_contact_context(
                    db,
                    num,
                    property_id=approved_property_id,
                    person_id=None,
                    classification=classification or "potential_seller",
                    source="agent3_manual_resolution",
                    confidence=0.95,
                    notes=f"lead_key={lead_key}",
                    reisift_property_uuid=approved_property_uuid,
                    last_reisift_lookup_at=format_db_time(datetime.utcnow()),
                )
        remap = _retarget_unmapped_signals_for_lead_key(db, lead_key, approved_property_id)
        route_new_agent_signals_once(db, limit=100)
        trigger_agent_pipeline_refresh(db, property_id=int(approved_property_id), reason="agent3_manual_resolution")
    db.commit()
    return redirect(url_for("agents_page", notice=f"Lead resolution saved for {lead_key}."))


@app.route("/referral")
def referral_dashboard():
    ensure_db()
    db = get_db()
    def _to_int(value):
        try:
            return int(value or 0)
        except (TypeError, ValueError):
            try:
                return int(float(value or 0))
            except (TypeError, ValueError):
                return 0

    raw_referrals = get_cached_referrals(db)
    referrals = []
    for row in raw_referrals:
        item = dict(row)
        payload = parse_json_object(item.get("payload_json") or "{}")
        phones, emails = extract_owner_contacts_from_payload(payload)
        item["phones"] = phones
        item["emails"] = emails
        referrals.append(item)
    total_count = len(referrals)
    error = ""
    notice = request.args.get("notice", "").strip()
    status_slug = os.getenv("REISIFT_REFERRAL_STATUS", "refer_lead").strip() or "refer_lead"
    if not referrals:
        try:
            data = refresh_reisift_referrals_cache(db)
            status_slug = data["status_slug"]
            raw_referrals = get_cached_referrals(db)
            referrals = []
            for row in raw_referrals:
                item = dict(row)
                payload = parse_json_object(item.get("payload_json") or "{}")
                phones, emails = extract_owner_contacts_from_payload(payload)
                item["phones"] = phones
                item["emails"] = emails
                referrals.append(item)
            total_count = len(referrals)
            notice = f"Referral cache initialized ({data['synced']} synced)."
        except Exception as exc:
            error = str(exc)
    referral_summary = {
        "lead_count": total_count,
        "untouched_count": 0,
        "referred_count": 0,
        "on_market_count": 0,
    }
    referred_statuses = {"referred", "on market", "appointment set", "under contract", "closed"}
    on_market_statuses = {"on market", "listed", "active", "coming soon"}
    for item in referrals:
        referral_status = str(item.get("referral_status") or "").strip() or "Untouched"
        referral_status_key = referral_status.lower()
        push_count = _to_int(item.get("push_count"))
        winning_realtor_id = item.get("winning_realtor_id")
        on_market_status = str(item.get("on_market_status") or "").strip().lower()
        if referral_status == "Untouched":
            referral_summary["untouched_count"] += 1
        if push_count > 0 or referral_status_key in referred_statuses or winning_realtor_id:
            referral_summary["referred_count"] += 1
        if on_market_status in on_market_statuses:
            referral_summary["on_market_count"] += 1
    queue_filter = (request.args.get("queue_filter") or "all").strip().lower()
    valid_queue_filters = {"all", "queued", "no_realtor"}
    if queue_filter not in valid_queue_filters:
        queue_filter = "all"
    queue_sql = """
        SELECT q.*, r.first_name, r.last_name, rr.full_address
        FROM referral_auto_send_queue q
        LEFT JOIN referral_realtors r ON r.id = q.realtor_id
        LEFT JOIN reisift_referrals rr ON rr.property_uuid = q.property_uuid
    """
    if queue_filter == "queued":
        queue_sql += " WHERE q.queue_status = 'Queued'"
    elif queue_filter == "no_realtor":
        queue_sql += " WHERE q.queue_status = 'No Realtor'"
    queue_sql += " ORDER BY q.id DESC LIMIT 200"
    queue_rows = db.execute(
        queue_sql,
    ).fetchall()
    realtor_push_rows = db.execute(
        """
        SELECT
            rr.id AS realtor_id,
            rr.first_name,
            rr.last_name,
            rr.brokerage,
            rpa.property_uuid,
            rpa.status AS push_status,
            rpa.created_at AS push_created_at,
            COALESCE(rf.full_address, rpa.property_uuid) AS full_address,
            COALESCE(rf.referral_status, 'Untouched') AS referral_status,
            rf.winning_realtor_id
        FROM referral_realtors rr
        LEFT JOIN referral_push_activity rpa ON rpa.realtor_id = rr.id
        LEFT JOIN reisift_referrals rf ON rf.property_uuid = rpa.property_uuid
        ORDER BY lower(rr.last_name), lower(rr.first_name), datetime(rpa.created_at) DESC, rpa.id DESC
        """
    ).fetchall()
    realtor_activity = []
    activity_by_realtor = {}
    for row in realtor_push_rows:
        realtor_id = int(row["realtor_id"])
        bucket = activity_by_realtor.get(realtor_id)
        if not bucket:
            name = " ".join(
                x for x in [str(row["first_name"] or "").strip(), str(row["last_name"] or "").strip()] if x
            ).strip() or f"Realtor #{realtor_id}"
            bucket = {
                "realtor_id": realtor_id,
                "name": name,
                "brokerage": str(row["brokerage"] or "").strip(),
                "total_sent": 0,
                "unique_properties": 0,
                "last_sent_at": "",
                "properties": [],
                "_seen_props": set(),
            }
            activity_by_realtor[realtor_id] = bucket
            realtor_activity.append(bucket)
        if not row["property_uuid"]:
            continue
        prop_uuid = str(row["property_uuid"] or "").strip()
        bucket["total_sent"] += 1
        if not bucket["last_sent_at"]:
            bucket["last_sent_at"] = str(row["push_created_at"] or "")
        if prop_uuid not in bucket["_seen_props"]:
            bucket["_seen_props"].add(prop_uuid)
            row_status = str(row["referral_status"] or "").strip() or "Untouched"
            winner_id = int(row["winning_realtor_id"]) if str(row["winning_realtor_id"] or "").isdigit() else None
            show_status = winner_id == realtor_id and row_status in {"On Market", "Appointment Set", "Under Contract", "Closed"}
            bucket["properties"].append(
                {
                    "property_uuid": prop_uuid,
                    "full_address": str(row["full_address"] or prop_uuid).strip(),
                    "last_push_status": str(row["push_status"] or "").strip() or "unknown",
                    "last_sent_at": str(row["push_created_at"] or "").strip(),
                    "referral_management_status": row_status if show_status else "",
                }
            )
    for bucket in realtor_activity:
        bucket["unique_properties"] = len(bucket["_seen_props"])
        del bucket["_seen_props"]
    return render_template(
        "referral.html",
        referrals=referrals,
        queue_rows=queue_rows,
        realtor_activity=realtor_activity,
        queue_filter=queue_filter,
        total_count=total_count,
        referral_summary=referral_summary,
        status_slug=status_slug,
        error=error,
        notice=notice,
        referral_statuses=REFERRAL_STATUSES,
    )


