@app.route("/follow-ups")
def follow_ups_page():
    ensure_db()
    db = get_db()
    def _to_int(value):
        try:
            return int(value or 0)
        except (TypeError, ValueError):
            try:
                return int(float(value or 0))
            except (TypeError, ValueError):
                return 0

    lookback_days_raw = (request.args.get("days") or "7").strip()
    sort_order = (request.args.get("sort") or "desc").strip().lower()
    if sort_order not in {"asc", "desc"}:
        sort_order = "desc"
    try:
        lookback_days = max(1, min(90, int(lookback_days_raw)))
    except ValueError:
        lookback_days = 7

    raw_rows = get_cached_followups(db, sort_dir=sort_order)
    rows = []
    for row in raw_rows:
        payload = {}
        if row["payload_json"]:
            try:
                payload = json.loads(row["payload_json"])
            except Exception:
                payload = {}
        phones, emails = extract_owner_contacts_from_payload(payload)
        property_lists = extract_property_lists(payload)
        addr = extract_payload_address(payload)
        deep_dive_property_id = find_local_property_by_address(
            db, addr["street"], addr["city"], addr["state"], addr["postal_code"]
        )
        rows.append(
            {
                **dict(row),
                "phones": phones,
                "emails": emails,
                "property_lists": property_lists,
                "deep_dive_property_id": deep_dive_property_id,
                "events": parse_followup_json_list(row["events_json"]),
                "tasks": parse_followup_json_list(row["tasks_json"]),
            }
        )
    notice = (request.args.get("notice") or "").strip()
    error = (request.args.get("error") or "").strip()
    outbound_calls_total = sum(_to_int(row.get("outbound_calls")) for row in rows)
    outbound_sms_total = sum(_to_int(row.get("outbound_sms")) for row in rows)
    outbound_email_total = sum(_to_int(row.get("outbound_email")) for row in rows)
    inbound_responses_total = sum(_to_int(row.get("inbound_responses")) for row in rows)
    return render_template(
        "follow_ups.html",
        rows=rows,
        notice=notice,
        error=error,
        lookback_days=lookback_days,
        sort_order=sort_order,
        auto_refresh=(request.args.get("refresh") or request.args.get("enrich") or "0") == "1",
        followup_summary={
            "lead_count": len(rows),
            "outbound_calls": outbound_calls_total,
            "outbound_messages": outbound_sms_total + outbound_email_total,
            "outbound_sms": outbound_sms_total,
            "outbound_email": outbound_email_total,
            "inbound_responses": inbound_responses_total,
        },
    )


