@app.route("/api/integrations/website/lead", methods=["POST", "GET", "OPTIONS"])
def integrations_website_lead_api():
    ensure_db()
    db = get_db()
    if request.method == "OPTIONS":
        return jsonify({"ok": True, "method": "OPTIONS"}), 200
    if request.method == "GET":
        return jsonify(
            {
                "ok": True,
                "endpoint": "/api/integrations/website/lead",
                "method": "POST",
                "auth": "X-Integration-Key or Authorization: Bearer <key>",
                "status": "ready",
            }
        ), 200
    if not integration_auth_ok(db, request):
        return jsonify({"ok": False, "error": "Unauthorized"}), 401
    payload = request.get_json(silent=True)
    if not isinstance(payload, dict):
        payload = dict(request.form or {})
    result = process_website_lead_payload(db, payload, source_label="webhook")
    if not result.get("ok"):
        try:
            ek = (
                _payload_value_by_keys(payload, ["event_key", "submission_id", "event_id"])
                or f"validation:{int(time.time())}"
            )
            lk = (
                _derive_website_lead_key(
                    payload,
                    address=_payload_value_by_keys(payload, ["address", "property_address", "street_address"]),
                    phone=_payload_value_by_keys(payload, ["phone", "phone_number", "mobile"]),
                    email=_payload_value_by_keys(payload, ["email", "email_address"]),
                )
                or "unknown"
            )
            add_website_webhook_note(
                db,
                f"website:{ek}",
                lk,
                f"Website lead processing validation/server failure\nError: {result.get('error') or 'Unknown'}",
                {"payload": payload, "result": result},
            )
            db.commit()
        except Exception:
            pass
        if not result.get("slack_sent"):
            try:
                fields = _extract_website_lead_fields(payload if isinstance(payload, dict) else {})
                sift_link = _sift_record_url(result.get("created_uuid") or "")
                send_slack_notification(
                    db,
                    "\n".join(
                        [
                            "Website Lead SIFT Handling",
                            f"Stage: {fields.get('stage') or '-'}",
                            f"Mode: failed",
                            f"Address: {fields.get('address') or '-'}",
                            f"Name: {fields.get('seller_name') or '-'}",
                            f"Phone: {fields.get('phone') or '-'}",
                            f"Email: {fields.get('email') or '-'}",
                            f"SIFT Record: {sift_link or '-'}",
                            f"Error: {result.get('error') or 'Unknown'}",
                        ]
                    ),
                )
            except Exception:
                pass
    if result.get("ok"):
        mode = str(result.get("mode") or "").strip().lower()
        suppress_fallback_slack = bool(result.get("duplicate")) or mode in {"queued_waiting_for_step2"}
        if (not result.get("slack_sent")) and (not suppress_fallback_slack):
            try:
                fields = _extract_website_lead_fields(payload if isinstance(payload, dict) else {})
                sift_link = _sift_record_url(result.get("created_uuid") or "")
                send_slack_notification(
                    db,
                    "\n".join(
                        [
                            "Website Lead SIFT Handling",
                            f"Stage: {fields.get('stage') or '-'}",
                            f"Mode: {result.get('mode') or ('duplicate' if result.get('duplicate') else 'success')}",
                            f"Address: {fields.get('address') or '-'}",
                            f"Name: {fields.get('seller_name') or '-'}",
                            f"Phone: {fields.get('phone') or '-'}",
                            f"Email: {fields.get('email') or '-'}",
                            f"SIFT Record: {sift_link or '-'}",
                        ]
                    ),
                )
            except Exception:
                pass
        status_code = 200
    else:
        err_type = str(result.get("error_type") or "").strip().lower()
        status_code = 400 if err_type == "validation" else 500
    return jsonify(result), status_code


@app.route("/api/integrations/website/lead/logs", methods=["GET"])
def integrations_website_lead_logs_api():
    ensure_db()
    db = get_db()
    if not integration_auth_ok(db, request):
        return jsonify({"ok": False, "error": "Unauthorized"}), 401
    limit_raw = (request.args.get("limit") or "20").strip()
    limit = int(limit_raw) if limit_raw.isdigit() else 20
    limit = max(1, min(100, limit))
    rows = db.execute(
        """
        SELECT id, event_key, lead_key, note_body, payload_json, created_at
        FROM website_lead_webhook_notes
        ORDER BY id DESC
        LIMIT ?
        """,
        (limit,),
    ).fetchall()
    items = []
    for r in rows:
        payload = parse_json_object(r["payload_json"] or "{}")
        items.append(
            {
                "id": int(r["id"]),
                "event_key": r["event_key"],
                "lead_key": r["lead_key"],
                "note_body": r["note_body"],
                "payload": payload,
                "created_at": r["created_at"],
            }
        )
    return jsonify({"ok": True, "count": len(items), "items": items})


@app.route("/api/integrations/website/lead/latest", methods=["GET"])
def integrations_website_lead_latest_api():
    ensure_db()
    db = get_db()
    if not integration_auth_ok(db, request):
        return jsonify({"ok": False, "error": "Unauthorized"}), 401
    row = db.execute(
        """
        SELECT id, event_key, lead_key, note_body, payload_json, created_at
        FROM website_lead_webhook_notes
        ORDER BY id DESC
        LIMIT 1
        """
    ).fetchone()
    if not row:
        return jsonify({"ok": True, "item": None})
    return jsonify(
        {
            "ok": True,
            "item": {
                "id": int(row["id"]),
                "event_key": row["event_key"],
                "lead_key": row["lead_key"],
                "note_body": row["note_body"],
                "payload_json_raw": row["payload_json"] or "{}",
                "created_at": row["created_at"],
            },
        }
    )


@app.route("/api/admin/import-referral-bundle", methods=["POST"])
def import_referral_bundle_api():
    ensure_db()
    db = get_db()
    try:
        payload = request.get_json(silent=True) or {}
        realtor_rows = payload.get("referral_realtors")
        referral_rows = payload.get("reisift_referrals")
        push_rows = payload.get("referral_push_activity")
        realtor_rows = realtor_rows if isinstance(realtor_rows, list) else []
        referral_rows = referral_rows if isinstance(referral_rows, list) else []
        push_rows = push_rows if isinstance(push_rows, list) else []
        if not (realtor_rows or referral_rows or push_rows):
            return jsonify({"ok": False, "error": "No import rows provided."}), 400
        counts = import_referral_bundle_rows(db, realtor_rows, referral_rows, push_rows)
        db.commit()
        return jsonify({"ok": True, "imported": counts})
    except Exception as exc:
        db.rollback()
        log_app_error(
            db,
            source="import_referral_bundle_api",
            error_message=str(exc),
            details=traceback.format_exc(),
            route="/api/admin/import-referral-bundle",
            status_code=500,
        )
        db.commit()
        return jsonify({"ok": False, "error": str(exc)}), 500


