@app.route("/oauth/meta/test", methods=["GET"])
def meta_oauth_test():
    ensure_db()
    db = get_db()
    settings = get_ads_dashboard_settings(db)
    access_token = settings.get("meta_access_token", "")
    if not access_token:
        return redirect(url_for("settings_page", tab="ads", error="Save a Meta access token first."))
    try:
        accounts = _fetch_meta_accessible_accounts(access_token)
        account_ids = []
        for account in accounts:
            if not isinstance(account, dict):
                continue
            normalized = _normalize_meta_account_id(account.get("account_id") or account.get("id"))
            if normalized:
                account_ids.append(normalized)
        account_ids = list(dict.fromkeys(account_ids))
        configured = list(dict.fromkeys(settings.get("meta_account_ids") or []))
        if not configured and account_ids:
            set_setting(db, "ads_meta_account_ids", ", ".join(account_ids))
            db.commit()
        matched = sorted(set(configured).intersection(account_ids)) if configured else account_ids
        notice_parts = [
            "Meta connection OK.",
            f"Detected {len(account_ids)} accessible ad account(s).",
        ]
        if configured:
            notice_parts.append(f"Configured account matches: {len(matched)}/{len(configured)}.")
            if matched:
                notice_parts.append("Matched IDs: " + ", ".join(matched) + ".")
        elif account_ids:
            notice_parts.append("Saved detected Meta ad account IDs into Ad Platforms.")
        return redirect(url_for("settings_page", tab="ads", notice=" ".join(notice_parts)))
    except Exception as exc:
        db.rollback()
        log_app_error(
            db,
            source="meta_oauth_test",
            error_message=str(exc),
            details=traceback.format_exc(),
            route="/oauth/meta/test",
            status_code=500,
        )
        db.commit()
        return redirect(url_for("settings_page", tab="ads", error=f"Meta test failed: {exc}"))


@app.route("/oauth/meta/exchange", methods=["POST"])
def meta_oauth_exchange():
    ensure_db()
    db = get_db()
    settings = get_ads_dashboard_settings(db)
    app_id = settings.get("meta_app_id", "")
    app_secret = settings.get("meta_app_secret", "")
    user_access_token = normalize_whitespace(request.form.get("meta_user_access_token"))
    if not app_id or not app_secret:
        return redirect(url_for("settings_page", tab="ads", error="Save Meta app ID and app secret first."))
    if not user_access_token:
        return redirect(url_for("settings_page", tab="ads", error="Paste a fresh Meta user access token first."))
    try:
        payload = _exchange_meta_long_lived_access_token(app_id, app_secret, user_access_token)
        access_token = normalize_whitespace(payload.get("access_token"))
        expires_in = payload.get("expires_in")
        if not access_token:
            raise RuntimeError("Meta exchange did not return an access token.")
        set_setting(db, "ads_meta_access_token", access_token)
        notice_parts = ["Meta long-lived token saved."]
        if expires_in:
            try:
                days = max(int(round(float(expires_in) / 86400.0)), 1)
                notice_parts.append(f"Token lifetime: about {days} day(s).")
            except Exception:
                pass
        try:
            accounts = _fetch_meta_accessible_accounts(access_token)
            account_ids = []
            for account in accounts:
                if not isinstance(account, dict):
                    continue
                normalized = _normalize_meta_account_id(account.get("account_id") or account.get("id"))
                if normalized:
                    account_ids.append(normalized)
            account_ids = list(dict.fromkeys(account_ids))
            if account_ids:
                set_setting(db, "ads_meta_account_ids", ", ".join(account_ids))
                notice_parts.append(f"Saved {len(account_ids)} Meta ad account ID(s).")
        except Exception as account_exc:
            notice_parts.append(f"Account lookup did not complete: {account_exc}")
        db.commit()
        return redirect(url_for("settings_page", tab="ads", notice=" ".join(notice_parts)))
    except Exception as exc:
        db.rollback()
        log_app_error(
            db,
            source="meta_oauth_exchange",
            error_message=str(exc),
            details=traceback.format_exc(),
            route="/oauth/meta/exchange",
            status_code=500,
        )
        db.commit()
        return redirect(url_for("settings_page", tab="ads", error=f"Meta token exchange failed: {exc}"))


@app.route("/oauth/amazon/callback", methods=["GET"])
def amazon_oauth_callback():
    ensure_db()
    db = get_db()
    settings = get_ads_dashboard_settings(db)
    callback_url = request.base_url
    error_value = normalize_whitespace(request.args.get("error"))
    error_description = normalize_whitespace(request.args.get("error_description"))
    code = normalize_whitespace(request.args.get("code"))
    state = normalize_whitespace(request.args.get("state"))
    expected_state = normalize_whitespace(session.get("amazon_oauth_state"))
    result = {
        "ok": False,
        "notice": "",
        "error": "",
        "callback_url": callback_url,
        "state": state,
        "refresh_token": "",
        "access_token_preview": "",
        "expires_in": "",
        "profiles": [],
        "saved_to_settings": False,
    }
    if state and expected_state and state != expected_state:
        result["error"] = "Amazon OAuth state mismatch. Start the flow again from Ad Platforms."
        session.pop("amazon_oauth_state", None)
        return render_template("amazon_oauth_callback.html", result=result)
    if error_value:
        result["error"] = error_description or error_value
        return render_template("amazon_oauth_callback.html", result=result)
    if not code:
        result["notice"] = "Amazon callback is ready. Register this exact URL as the redirect URI, then start the OAuth flow from Amazon."
        return render_template("amazon_oauth_callback.html", result=result)
    client_id = settings.get("amazon_client_id", "")
    client_secret = settings.get("amazon_client_secret", "")
    if not client_id or not client_secret:
        result["error"] = "Amazon Ads client ID and client secret must be saved in Ad Platforms before exchanging the authorization code."
        return render_template("amazon_oauth_callback.html", result=result)
    try:
        token_payload = _exchange_amazon_authorization_code(client_id, client_secret, code, callback_url)
        session.pop("amazon_oauth_state", None)
        refresh_token = normalize_whitespace(token_payload.get("refresh_token"))
        access_token = normalize_whitespace(token_payload.get("access_token"))
        expires_in = token_payload.get("expires_in")
        profiles = []
        profile_error = ""
        if access_token:
            try:
                profiles = _fetch_amazon_ads_profiles(client_id, access_token, settings.get("amazon_region") or "na")
            except Exception as exc:
                profile_error = str(exc)
        if refresh_token and session.get("auth_ok"):
            set_setting(db, "ads_amazon_refresh_token", refresh_token)
            profile_ids = _amazon_profile_ids_from_profiles(profiles)
            account_ids = _amazon_account_ids_from_profiles(profiles)
            if len(account_ids) == 1:
                set_setting(db, "ads_amazon_account_id", account_ids[0])
            if profile_ids:
                set_setting(db, "ads_amazon_profile_ids", ", ".join(profile_ids))
            db.commit()
            result["saved_to_settings"] = True
        result["ok"] = bool(refresh_token)
        result["refresh_token"] = refresh_token
        result["access_token_preview"] = f"{access_token[:18]}..." if access_token else ""
        result["expires_in"] = str(expires_in or "")
        result["profiles"] = profiles if isinstance(profiles, list) else []
        if profile_error:
            result["notice"] = f"Amazon authorization succeeded, but profile lookup did not complete: {profile_error}"
        elif refresh_token and result["profiles"]:
            result["notice"] = (
                "Amazon authorization succeeded. "
                + (
                    "Refresh token and detected profile IDs were saved into Ad Platforms."
                    if result["saved_to_settings"]
                    else "Use the profile IDs below in Ad Platforms."
                )
            )
        elif refresh_token:
            result["notice"] = "Amazon authorization succeeded."
    except Exception as exc:
        result["error"] = str(exc)
        log_app_error(
            db,
            source="amazon_oauth_callback",
            error_message=str(exc),
            details=traceback.format_exc(),
            route="/oauth/amazon/callback",
            status_code=500,
        )
        db.commit()
    return render_template("amazon_oauth_callback.html", result=result)


@app.route("/oauth/amazon/start", methods=["GET"])
def amazon_oauth_start():
    ensure_db()
    db = get_db()
    settings = get_ads_dashboard_settings(db)
    client_id = settings.get("amazon_client_id", "")
    client_secret = settings.get("amazon_client_secret", "")
    if not client_id or not client_secret:
        return redirect(url_for("settings_page", tab="ads", notice="Save Amazon client ID and secret first."))
    state = secrets.token_urlsafe(24)
    session["amazon_oauth_state"] = state
    authorize_url = _build_amazon_authorize_url(
        client_id=client_id,
        redirect_uri=url_for("amazon_oauth_callback", _external=True),
        state=state,
    )
    return redirect(authorize_url)


@app.route("/oauth/amazon/test", methods=["GET"])
def amazon_oauth_test():
    ensure_db()
    db = get_db()
    settings = get_ads_dashboard_settings(db)
    missing = []
    if not settings.get("amazon_client_id"):
        missing.append("client ID")
    if not settings.get("amazon_client_secret"):
        missing.append("client secret")
    if not settings.get("amazon_refresh_token"):
        missing.append("refresh token")
    if missing:
        return redirect(
            url_for(
                "settings_page",
                tab="ads",
                error="Save Amazon " + ", ".join(missing) + " first.",
            )
        )
    try:
        access_token = _exchange_amazon_refresh_token(
            settings.get("amazon_client_id", ""),
            settings.get("amazon_client_secret", ""),
            settings.get("amazon_refresh_token", ""),
        )
        profiles = _fetch_amazon_ads_profiles(
            settings.get("amazon_client_id", ""),
            access_token,
            settings.get("amazon_region") or "na",
        )
        profile_ids = _amazon_profile_ids_from_profiles(profiles)
        account_ids = _amazon_account_ids_from_profiles(profiles)
        configured_account_id = normalize_whitespace(settings.get("amazon_account_id"))
        configured_profile_ids = list(dict.fromkeys(settings.get("amazon_profile_ids") or []))
        if configured_account_id:
            matched_profile_ids = _amazon_profile_ids_from_profiles(
                [profile for profile in profiles if _amazon_profile_matches_account(profile, configured_account_id)]
            )
        elif configured_profile_ids:
            matched_profile_ids = sorted(set(configured_profile_ids).intersection(profile_ids))
        else:
            matched_profile_ids = profile_ids
        campaign_count = 0
        for profile_id in matched_profile_ids[:4]:
            campaign_count += len(_fetch_amazon_campaign_snapshots(settings, access_token, profile_id))
        notice_parts = [
            "Amazon connection OK.",
            "Refreshed access token successfully.",
            f"Detected {len(profile_ids)} Amazon profile(s).",
            f"Sponsored TV campaign endpoint returned {campaign_count} campaign(s).",
        ]
        if configured_account_id:
            matched_account = configured_account_id in account_ids
            notice_parts.append(f"Configured account match: {'yes' if matched_account else 'no'}.")
            if not matched_account and account_ids:
                notice_parts.append("Accessible account IDs: " + ", ".join(account_ids) + ".")
        if configured_profile_ids:
            notice_parts.append(f"Configured profile matches: {len(matched_profile_ids)}/{len(configured_profile_ids)}.")
            if matched_profile_ids:
                notice_parts.append("Matched IDs: " + ", ".join(matched_profile_ids) + ".")
        elif profile_ids:
            set_setting(db, "ads_amazon_profile_ids", ", ".join(profile_ids))
            if len(account_ids) == 1:
                set_setting(db, "ads_amazon_account_id", account_ids[0])
            db.commit()
            if len(account_ids) == 1:
                notice_parts.append("Saved detected Amazon account ID and profile IDs into Ad Platforms.")
            else:
                notice_parts.append("Saved detected Amazon profile IDs into Ad Platforms.")
        return redirect(url_for("settings_page", tab="ads", notice=" ".join(notice_parts)))
    except Exception as exc:
        db.rollback()
        log_app_error(
            db,
            source="amazon_oauth_test",
            error_message=str(exc),
            details=traceback.format_exc(),
            route="/oauth/amazon/test",
            status_code=500,
        )
        db.commit()
        return redirect(url_for("settings_page", tab="ads", error=f"Amazon test failed: {exc}"))


@app.route("/oauth/roku/callback", methods=["GET"])
def roku_oauth_callback():
    ensure_db()
    db = get_db()
    settings = get_ads_dashboard_settings(db)
    callback_url = request.base_url
    error_value = normalize_whitespace(request.args.get("error"))
    error_description = normalize_whitespace(request.args.get("error_description"))
    code = normalize_whitespace(request.args.get("code"))
    state = normalize_whitespace(request.args.get("state"))
    result = {
        "ok": False,
        "notice": "",
        "error": "",
        "callback_url": callback_url,
        "state": state,
        "code": code,
        "refresh_token": "",
        "access_token_preview": "",
        "expires_in": "",
        "accounts": [],
        "saved_to_settings": False,
        "params": [],
    }
    for key in sorted(request.args.keys()):
        if key in {"code", "state", "error", "error_description"}:
            continue
        result["params"].append({"key": key, "value": normalize_whitespace(request.args.get(key))})
    if error_value:
        result["error"] = error_description or error_value
        return render_template("roku_oauth_callback.html", result=result)
    if not code:
        result["notice"] = "Roku callback is ready. Register this exact URL as the redirect URI, then start the OAuth flow from Roku."
        return render_template("roku_oauth_callback.html", result=result)
    client_id = settings.get("roku_client_id", "")
    client_secret = settings.get("roku_client_secret", "")
    if not client_id or not client_secret:
        result["error"] = "Roku client ID and client secret must be saved in Ad Platforms before exchanging the authorization code."
        return render_template("roku_oauth_callback.html", result=result)
    try:
        token_payload = _exchange_roku_authorization_code(client_id, client_secret, code, callback_url)
        refresh_token = normalize_whitespace(token_payload.get("refresh_token"))
        access_token = normalize_whitespace(token_payload.get("access_token"))
        expires_in = token_payload.get("expires_in")
        accounts = []
        account_error = ""
        if access_token:
            try:
                accounts = _fetch_roku_accounts(access_token)
            except Exception as exc:
                account_error = str(exc)
        if refresh_token and session.get("auth_ok"):
            set_setting(db, "ads_roku_refresh_token", refresh_token)
            if accounts:
                set_setting(
                    db,
                    "ads_roku_account_ids",
                    ", ".join(
                        account_id
                        for account_id in (
                            _normalize_roku_account_id((account.get("uid") if isinstance(account, dict) else ""))
                            for account in accounts
                        )
                        if account_id
                    ),
                )
            db.commit()
            result["saved_to_settings"] = True
        result["ok"] = bool(refresh_token)
        result["refresh_token"] = refresh_token
        result["access_token_preview"] = f"{access_token[:18]}..." if access_token else ""
        result["expires_in"] = str(expires_in or "")
        result["accounts"] = accounts if isinstance(accounts, list) else []
        if account_error:
            result["notice"] = f"Roku authorization succeeded, but account lookup did not complete: {account_error}"
        elif refresh_token and result["accounts"]:
            result["notice"] = "Roku authorization succeeded. Use the account IDs below in Ad Platforms."
        elif refresh_token:
            result["notice"] = "Roku authorization succeeded."
    except Exception as exc:
        result["error"] = str(exc)
        log_app_error(
            db,
            source="roku_oauth_callback",
            error_message=str(exc),
            details=traceback.format_exc(),
            route="/oauth/roku/callback",
            status_code=500,
        )
        db.commit()
    return render_template("roku_oauth_callback.html", result=result)


