@app.route("/oauth/roku/exchange", methods=["POST"])
def roku_oauth_exchange_code():
    ensure_db()
    db = get_db()
    settings = get_ads_dashboard_settings(db)
    client_id = settings.get("roku_client_id", "")
    client_secret = settings.get("roku_client_secret", "")
    code = normalize_whitespace(request.form.get("roku_authorization_code"))
    if not client_id or not client_secret:
        return redirect(
            url_for(
                "settings_page",
                tab="ads",
                error="Save Roku client ID and client secret first.",
            )
        )
    if not code:
        return redirect(url_for("settings_page", tab="ads", error="Paste a Roku authorization code first."))
    try:
        token_payload = _exchange_roku_authorization_code(
            client_id,
            client_secret,
            code,
            url_for("roku_oauth_callback", _external=True),
        )
        refresh_token = normalize_whitespace(token_payload.get("refresh_token"))
        access_token = normalize_whitespace(token_payload.get("access_token"))
        if not refresh_token:
            raise RuntimeError("Roku token exchange did not return a refresh token.")
        set_setting(db, "ads_roku_refresh_token", refresh_token)
        notice_parts = ["Roku authorization code exchanged successfully. Refresh token saved."]
        if access_token:
            try:
                accounts = _fetch_roku_accounts(access_token)
                account_ids = [
                    _normalize_roku_account_id((account.get("uid") if isinstance(account, dict) else ""))
                    for account in accounts
                ]
                account_ids = [value for value in account_ids if value]
                if account_ids:
                    set_setting(db, "ads_roku_account_ids", ", ".join(account_ids))
                    notice_parts.append(f"Saved {len(account_ids)} Roku ad account ID(s).")
            except Exception as account_exc:
                notice_parts.append(f"Account lookup did not complete: {account_exc}")
        db.commit()
        return redirect(url_for("settings_page", tab="ads", notice=" ".join(notice_parts)))
    except Exception as exc:
        db.rollback()
        log_app_error(
            db,
            source="roku_oauth_exchange_code",
            error_message=str(exc),
            details=traceback.format_exc(),
            route="/oauth/roku/exchange",
            status_code=500,
        )
        db.commit()
        return redirect(url_for("settings_page", tab="ads", error=f"Roku code exchange failed: {exc}"))


@app.route("/property/<int:property_id>/upload-contacts", methods=["POST"])
def upload_owner_contacts(property_id):
    ensure_db()
    db = get_db()

    prop = db.execute("SELECT owner_person_id FROM properties WHERE id = ?", (property_id,)).fetchone()
    owner_id = prop["owner_person_id"] if prop else None
    if not owner_id:
        return redirect(url_for("property_detail", property_id=property_id))

    file = request.files.get("contacts_file")
    if not file:
        return redirect(url_for("property_detail", property_id=property_id))

    content = file.stream.read().decode("utf-8-sig")
    reader = csv.DictReader(io.StringIO(content))

    for row in reader:
        channel_type = (row.get("channel_type") or "").strip()
        value = (row.get("value") or "").strip()
        if channel_type not in {"Phone", "Email"} or not value:
            continue

        db.execute(
            """
            INSERT INTO touchpoints (person_id, channel_type, channel_label, value, status, note, last_attempted)
            VALUES (?, ?, ?, ?, ?, ?, ?)
            """,
            (
                owner_id,
                channel_type,
                (row.get("channel_label") or "").strip(),
                value,
                (row.get("status") or "Correct").strip(),
                (row.get("note") or "").strip(),
                "",
            ),
        )

    db.commit()
    return redirect(url_for("property_detail", property_id=property_id))

@app.route("/property/<int:property_id>")
def property_detail(property_id):
    ensure_db()
    db = get_db()
    ads_settings = get_ads_dashboard_settings(db)

    prop = db.execute(
        """
        SELECT p.*,
               a.street,
               a.city,
               a.state,
               a.postal_code,
               op.first_name AS owner_first,
               op.last_name AS owner_last
        FROM properties p
        JOIN addresses a ON a.id = p.property_address_id
        LEFT JOIN people op ON op.id = p.owner_person_id
        WHERE p.id = ?
        """,
        (property_id,),
    ).fetchone()

    if prop is None:
        return "Property not found", 404

    owner = None
    owner_touchpoints = []
    owner_relationships = []
    owner_primary_phone = ""
    owner_phone_options = []
    owner_email_options = []

    if prop["owner_person_id"]:
        owner = db.execute("SELECT * FROM people WHERE id = ?", (prop["owner_person_id"],)).fetchone()
        owner_touchpoints = db.execute(
            """
            SELECT * FROM touchpoints
            WHERE person_id = ? AND lower(channel_type) IN ('phone', 'email')
            ORDER BY
                CASE
                    WHEN lower(channel_type) = 'phone' THEN 0
                    ELSE 1
                END,
                CASE
                    WHEN lower(channel_type) = 'phone' AND lower(channel_label) = 'mobile' THEN 0
                    WHEN lower(channel_type) = 'phone' AND lower(channel_label) = 'landline' THEN 1
                    WHEN lower(channel_type) = 'phone' AND lower(channel_label) = 'voip' THEN 2
                    WHEN lower(channel_type) = 'phone' AND lower(channel_label) = 'fax' THEN 3
                    ELSE 4
                END,
                created_at DESC,
                id DESC
            """,
            (prop["owner_person_id"],),
        ).fetchall()
        owner_touchpoints = _decorate_touchpoint_rows_for_display(owner_touchpoints)
        owner_relationships = db.execute(
            """
            SELECT r.id AS relationship_id, r.relationship_type, r.note, r.relationship_order,
                   p.id AS person_id, p.first_name, p.middle_name, p.last_name, p.outreach_status, p.deceased,
                   CASE WHEN EXISTS (SELECT 1 FROM skiptrace_runs sr WHERE sr.person_id = p.id) THEN 1 ELSE 0 END AS skip_traced
            FROM person_relationships r
            JOIN people p ON p.id = r.related_person_id
            WHERE r.subject_person_id = ?
            ORDER BY
                CASE WHEN COALESCE(p.deceased, 0) = 1 THEN 1 ELSE 0 END,
                CASE WHEN COALESCE(r.relationship_order, 0) <= 0 THEN 1 ELSE 0 END,
                r.relationship_order ASC,
                p.last_name ASC,
                p.first_name ASC,
                r.id ASC
            """,
            (prop["owner_person_id"],),
        ).fetchall()
        owner_phone_options = get_manual_sms_targets_for_person(db, prop["owner_person_id"])
        owner_email_options = get_manual_email_targets_for_person(db, prop["owner_person_id"])
        if owner_phone_options:
            owner_primary_phone = owner_phone_options[0]

    network_ids, _ = build_property_network(db, prop)

    touchpoints = []
    socials = []
    if network_ids:
        placeholders = ",".join(["?"] * len(network_ids))
        touchpoints = db.execute(
            f"SELECT * FROM touchpoints WHERE person_id IN ({placeholders}) ORDER BY created_at DESC",
            tuple(network_ids),
        ).fetchall()
        socials = db.execute(
            f"SELECT * FROM social_accounts WHERE person_id IN ({placeholders}) ORDER BY created_at DESC",
            tuple(network_ids),
        ).fetchall()

    activities = db.execute(
        "SELECT * FROM activity_log WHERE property_id = ? ORDER BY created_at DESC",
        (property_id,),
    ).fetchall()

    obituary_imports = db.execute(
        """
        SELECT o.*, p.first_name, p.last_name
        FROM obituary_sources o
        JOIN people p ON p.id = o.subject_person_id
        WHERE o.property_id = ?
        ORDER BY o.created_at DESC
        """,
        (property_id,),
    ).fetchall()

    communications = db.execute(
        """
        SELECT c.*
        FROM communications c
        WHERE c.property_id = ?
          AND (? IS NULL OR c.person_id = ?)
        ORDER BY c.sent_at ASC, c.id ASC
        """,
        (property_id, prop["owner_person_id"], prop["owner_person_id"]),
    ).fetchall()

    all_people = db.execute("SELECT * FROM people ORDER BY last_name, first_name").fetchall()
    related_people_options = db.execute(
        "SELECT * FROM people WHERE id != ? ORDER BY last_name, first_name",
        (prop["owner_person_id"] or -1,),
    ).fetchall()

    sms_rollup = {"sent": 0, "received": 0}
    verified_contacts = []
    property_comm_summary_rows = []
    if network_ids:
        placeholders = ",".join(["?"] * len(network_ids))
        sent = db.execute(
            f"""
            SELECT COUNT(*) AS c
            FROM communications
            WHERE property_id = ?
              AND upper(channel) = 'SMS'
              AND lower(direction) = 'outbound'
              AND person_id IN ({placeholders})
            """,
            tuple([property_id] + network_ids),
        ).fetchone()["c"]
        received = db.execute(
            f"""
            SELECT COUNT(*) AS c
            FROM communications
            WHERE property_id = ?
              AND upper(channel) = 'SMS'
              AND lower(direction) = 'inbound'
              AND person_id IN ({placeholders})
            """,
            tuple([property_id] + network_ids),
        ).fetchone()["c"]
        sms_rollup = {"sent": sent, "received": received}

        people_rows = db.execute(
            f"SELECT id, first_name, last_name FROM people WHERE id IN ({placeholders}) ORDER BY last_name, first_name",
            tuple(network_ids),
        ).fetchall()
        for p in people_rows:
            correct_phone = db.execute(
                """
                SELECT COUNT(*) AS c
                FROM touchpoints
                WHERE person_id = ? AND lower(channel_type) = 'phone' AND lower(status) = 'correct'
                """,
                (p["id"],),
            ).fetchone()["c"]
            verified_social = db.execute(
                """
                SELECT COUNT(*) AS c
                FROM social_accounts
                WHERE person_id = ? AND lower(status) = 'verified'
                """,
                (p["id"],),
            ).fetchone()["c"]
            if correct_phone > 0 or verified_social > 0:
                verified_contacts.append(
                    {
                        "person_id": p["id"],
                        "full_name": f"{p['first_name']} {p['last_name']}".strip(),
                        "confirmed_phone_count": correct_phone,
                        "verified_social_count": verified_social,
                    }
                )
    property_mail_summary = _summarize_property_mail_orders(db, property_id)
    property_skiptrace_summary = _summarize_property_skiptrace_runs(db, property_id)
    related_website_lead = None
    related_website_lead_updated = False
    property_address_text = f"{prop['street']}, {prop['city']}, {prop['state']} {prop['postal_code']}".strip()
    prop_reisift_uuid = normalize_uuid((prop["reisift_property_uuid"] if "reisift_property_uuid" in prop.keys() else "") or "")
    candidate_lead_rows = db.execute(
        """
        SELECT id,
               lead_key,
               reisift_property_uuid,
               reisift_owner_uuid,
               latest_address,
               latest_phone,
               latest_email,
               latest_name,
               latest_stage,
               status,
               first_received_at,
               last_received_at,
               hold_expires_at,
               processed_at,
               processing_result_json,
               local_property_id,
               step1_payload_json,
               step2_payload_json,
               google_ads_qualified_at,
               google_ads_qualified_result_json,
               google_ads_converted_at,
               google_ads_converted_result_json
        FROM website_lead_submissions
        WHERE COALESCE(local_property_id, 0) = ?
           OR (? <> '' AND lower(COALESCE(reisift_property_uuid, '')) = lower(?))
           OR lower(COALESCE(latest_address, '')) = lower(?)
        ORDER BY COALESCE(last_received_at, first_received_at) DESC, id DESC
        LIMIT 10
        """,
        (property_id, prop_reisift_uuid, prop_reisift_uuid, property_address_text),
    ).fetchall()
    for candidate in candidate_lead_rows:
        candidate_lead = _build_ads_website_lead_detail(db, candidate, settings=ads_settings, include_notes=False, backfill_local=False)
        candidate_property_id = int(candidate_lead.get("local_property_id") or 0)
        if candidate_property_id not in {0, property_id}:
            continue
        if candidate_property_id == 0:
            db.execute("UPDATE website_lead_submissions SET local_property_id = ? WHERE id = ?", (property_id, int(candidate["id"])))
            candidate_lead["local_property_id"] = property_id
            related_website_lead_updated = True
        related_website_lead = candidate_lead
        break
    if related_website_lead_updated:
        db.commit()
    summary_people = []
    if owner:
        summary_people.append(
            {
                "person_id": int(owner["id"]),
                "full_name": person_name(owner),
                "relationship_type": "Owner",
            }
        )
    for rel in owner_relationships:
        summary_people.append(
            {
                "person_id": int(rel["person_id"]),
                "full_name": person_name(rel),
                "relationship_type": (rel["relationship_type"] or "Unknown"),
            }
        )
    dedup_summary_people = []
    seen_summary_ids = set()
    for row in summary_people:
        pid = int(row["person_id"])
        if pid in seen_summary_ids:
            continue
        seen_summary_ids.add(pid)
        dedup_summary_people.append(row)
    counts_map = communication_counts_for_people(db, [r["person_id"] for r in dedup_summary_people], property_id=property_id)
    for row in dedup_summary_people:
        c = counts_map.get(int(row["person_id"]), {})
        property_comm_summary_rows.append(
            {
                **row,
                "mail_outbound": int(c.get("mail_outbound", 0)),
                "sms_outbound": int(c.get("sms_outbound", 0)),
                "sms_inbound": int(c.get("sms_inbound", 0)),
                "email_outbound": int(c.get("email_outbound", 0)),
                "email_inbound": int(c.get("email_inbound", 0)),
                "email_opened": int(c.get("email_opened", 0)),
            }
        )
    sequence_campaigns = get_sequence_campaigns(db, only_active=True)
    mail_sequence_campaigns = get_mail_only_sequence_campaigns(db, only_active=True)
    target_ids = _property_sequence_targets(db, property_id)
    sequence_targets = []
    if target_ids:
        placeholders = ",".join(["?"] * len(target_ids))
        sequence_targets = db.execute(
            f"SELECT id, first_name, last_name FROM people WHERE id IN ({placeholders}) ORDER BY last_name, first_name",
            tuple(target_ids),
        ).fetchall()
    sequence_enrollments = db.execute(
        """
        SELECT e.*, c.name AS campaign_name, p.first_name, p.last_name
        FROM sequence_enrollments e
        JOIN sequence_campaigns c ON c.id = e.campaign_id
        JOIN people p ON p.id = e.person_id
        WHERE e.property_id = ?
        ORDER BY e.created_at DESC, e.id DESC
        LIMIT 100
        """,
        (property_id,),
    ).fetchall()
    mail_sequence_campaign_ids = {int(c["id"]) for c in mail_sequence_campaigns}
    mail_sequence_enrollments = [
        row for row in sequence_enrollments if int(row["campaign_id"] or 0) in mail_sequence_campaign_ids
    ]
    agent_trace = _agent_trace_for_property(db, property_id, limit=25) or {}

    return render_template(
        "property_detail.html",
        prop=prop,
        sift_record_url=_sift_record_url,
        owner=owner,
        owner_touchpoints=owner_touchpoints,
        owner_primary_phone=owner_primary_phone,
        owner_phone_options=owner_phone_options,
        owner_email_options=owner_email_options,
        owner_relationships=owner_relationships,
        all_people=all_people,
        related_people_options=related_people_options,
        sms_rollup=sms_rollup,
        property_comm_summary_rows=property_comm_summary_rows,
        verified_contacts=verified_contacts,
        property_mail_summary=property_mail_summary,
        property_skiptrace_summary=property_skiptrace_summary,
        touchpoints=touchpoints,
        socials=socials,
        activities=activities,
        obituary_imports=obituary_imports,
        communications=communications,
        smrt_from_number=get_deep_dive_sms_number(db),
        social_url=normalize_social_profile_url,
        person_name=person_name,
        sequence_campaigns=sequence_campaigns,
        mail_sequence_campaigns=mail_sequence_campaigns,
        sequence_targets=sequence_targets,
        sequence_enrollments=sequence_enrollments,
        mail_sequence_enrollments=mail_sequence_enrollments,
        agent_trace=agent_trace,
        related_website_lead=related_website_lead,
        fema_search_url=build_fema_msc_search_url(
            prop["street"],
            prop["city"],
            prop["state"],
            prop["postal_code"],
        ),
        page_notice=(request.args.get("notice") or request.args.get("seq_notice") or "").strip(),
        page_error=(request.args.get("error") or "").strip(),
    )


@app.route("/property/<int:property_id>/nj-map")
def open_property_nj_map(property_id):
    ensure_db()
    db = get_db()

    prop = db.execute(
        """
        SELECT p.id,
               a.street,
               a.city,
               a.state,
               a.postal_code
        FROM properties p
        JOIN addresses a ON a.id = p.property_address_id
        WHERE p.id = ?
        LIMIT 1
        """,
        (property_id,),
    ).fetchone()
    if prop is None:
        return "Property not found", 404

    try:
        geocode = geocode_address_via_census(
            prop["street"],
            prop["city"],
            prop["state"],
            prop["postal_code"],
        )
        return redirect(
            build_nj_map_parcel_url(
                geocode["latitude"],
                geocode["longitude"],
            )
        )
    except Exception as exc:
        log_app_error(
            db,
            source="nj_map_geocoder",
            error_message=str(exc),
            details=json.dumps(
                {
                    "property_id": property_id,
                    "street": prop["street"],
                    "city": prop["city"],
                    "state": prop["state"],
                    "postal_code": prop["postal_code"],
                }
            ),
            route=f"/property/{property_id}/nj-map",
            status_code=500,
        )
        db.commit()
        return redirect(
            url_for(
                "property_detail",
                property_id=property_id,
                error=f"NJ MAP lookup failed: {exc}",
            )
        )


@app.route("/property/<int:property_id>/reisift-link", methods=["POST"])
def update_property_reisift_link(property_id):
    ensure_db()
    db = get_db()

    property_row = db.execute(
        """
        SELECT id, owner_person_id, reisift_property_uuid, reisift_owner_uuid
        FROM properties
        WHERE id = ?
        LIMIT 1
        """,
        (property_id,),
    ).fetchone()
    if property_row is None:
        return "Property not found", 404

    raw_input = (request.form.get("reisift_record") or "").strip()
    property_uuid = extract_reisift_uuid_from_input(raw_input)
    if not property_uuid:
        return redirect(url_for("property_detail", property_id=property_id, error="Enter a valid REISift record URL or UUID."))

    owner_uuid = normalize_uuid(property_row["reisift_owner_uuid"] or "")
    notice = "REISift link updated."
    try:
        token = reisift_get_access_token()
        details = fetch_reisift_property_payload(token, property_uuid)
        owner_uuid = normalize_uuid(_reisift_find_owner_uuid(details) or owner_uuid)
    except Exception as exc:
        notice = f"REISift UUID saved. Owner details could not be verified: {exc}"

    db.execute(
        """
        UPDATE properties
        SET reisift_property_uuid = ?,
            reisift_owner_uuid = ?
        WHERE id = ?
        """,
        (property_uuid, owner_uuid, property_id),
    )
    db.execute(
        """
        INSERT INTO activity_log (property_id, person_id, activity_type, outcome, note)
        VALUES (?, ?, ?, ?, ?)
        """,
        (
            property_id,
            property_row["owner_person_id"],
            "ReiSift Link",
            "Updated",
            json.dumps({"property_uuid": property_uuid, "owner_uuid": owner_uuid, "raw_input": raw_input}),
        ),
    )
    db.commit()
    return redirect(url_for("property_detail", property_id=property_id, notice=notice))


@app.route("/property/<int:property_id>/reisift-note", methods=["POST"])
def add_property_reisift_note(property_id):
    ensure_db()
    db = get_db()

    property_row = db.execute(
        """
        SELECT id, owner_person_id, reisift_property_uuid
        FROM properties
        WHERE id = ?
        LIMIT 1
        """,
        (property_id,),
    ).fetchone()
    if property_row is None:
        return "Property not found", 404

    property_uuid = normalize_uuid(property_row["reisift_property_uuid"] or "")
    note_text = (request.form.get("note_text") or "").strip()
    if not note_text:
        return redirect(url_for("property_detail", property_id=property_id, error="Enter a note before sending it to REISift."))
    if not property_uuid:
        return redirect(url_for("property_detail", property_id=property_id, error="No REISift record is linked to this property yet."))

    try:
        token = reisift_get_access_token()
        note_result = reisift_append_property_note(token, property_uuid, note_text)
    except Exception as exc:
        log_app_error(
            db,
            source=f"{PROVIDER_ALERT_SOURCE_PREFIX}reisift",
            route=f"/property/{property_id}/reisift-note",
            status_code=500,
            error_message=f"ReiSift note sync failed: {exc}",
            details=json.dumps({"property_id": property_id, "property_uuid": property_uuid, "note_text": note_text[:1000]}),
        )
        db.commit()
        return redirect(url_for("property_detail", property_id=property_id, error=f"REISift note failed: {exc}"))

    outcome = "Skipped"
    notice = "REISift note already present."
    if note_result.get("ok") and not note_result.get("skipped"):
        outcome = "Appended"
        notice = "REISift note added."
    elif not note_result.get("ok"):
        outcome = "Failed"
        notice = "REISift note could not be added."

    db.execute(
        """
        INSERT INTO activity_log (property_id, person_id, activity_type, outcome, note)
        VALUES (?, ?, ?, ?, ?)
        """,
        (
            property_id,
            property_row["owner_person_id"],
            "ReiSift Note",
            outcome,
            note_text,
        ),
    )
    db.commit()
    return redirect(url_for("property_detail", property_id=property_id, notice=notice))

@app.route("/people", methods=["POST"])
def create_person_route():
    ensure_db()
    db = get_db()
    person_id = create_person(
        db,
        request.form.get("first_name", "Unknown"),
        request.form.get("last_name", "Person"),
        middle_name=request.form.get("middle_name", ""),
        phone=request.form.get("phone", ""),
        email=request.form.get("email", ""),
        notes=request.form.get("notes", ""),
    )
    db.commit()

    redirect_property = request.form.get("property_id")
    if redirect_property:
        return redirect(url_for("property_detail", property_id=redirect_property))
    return redirect(url_for("person_detail", person_id=person_id))


@app.route("/person/<int:person_id>")
def person_detail(person_id):
    ensure_db()
    db = get_db()

    person = db.execute("SELECT * FROM people WHERE id = ?", (person_id,)).fetchone()
    if person is None:
        return "Person not found", 404

    touchpoints = db.execute(
        """
        SELECT *
        FROM touchpoints
        WHERE person_id = ?
        ORDER BY
            CASE
                WHEN lower(channel_type) = 'phone' THEN 0
                ELSE 1
            END,
            CASE
                WHEN lower(channel_type) = 'phone' AND lower(channel_label) = 'mobile' THEN 0
                WHEN lower(channel_type) = 'phone' AND lower(channel_label) = 'landline' THEN 1
                WHEN lower(channel_type) = 'phone' AND lower(channel_label) = 'voip' THEN 2
                WHEN lower(channel_type) = 'phone' AND lower(channel_label) = 'fax' THEN 3
                ELSE 4
            END,
            created_at DESC,
            id DESC
        """,
        (person_id,),
    ).fetchall()
    touchpoints = _decorate_touchpoint_rows_for_display(touchpoints)
    socials = db.execute(
        "SELECT * FROM social_accounts WHERE person_id = ? ORDER BY created_at DESC", (person_id,)
    ).fetchall()
    person_primary_phone = ""
    person_phone_options = []
    person_email_options = []
    person_phone_options = get_manual_sms_targets_for_person(db, person_id)
    person_email_options = get_manual_email_targets_for_person(db, person_id)
    if person_phone_options:
        person_primary_phone = person_phone_options[0]

    relationship_rows = db.execute(
        """
        SELECT r.id AS relationship_id, r.relationship_type, r.note, r.relationship_order,
               p.id AS person_id, p.first_name, p.middle_name, p.last_name, p.outreach_status, p.deceased,
               CASE WHEN EXISTS (SELECT 1 FROM skiptrace_runs sr WHERE sr.person_id = p.id) THEN 1 ELSE 0 END AS skip_traced
        FROM person_relationships r
        JOIN people p ON p.id = r.related_person_id
        WHERE r.subject_person_id = ?
        ORDER BY
            CASE WHEN COALESCE(p.deceased, 0) = 1 THEN 1 ELSE 0 END,
            CASE WHEN COALESCE(r.relationship_order, 0) <= 0 THEN 1 ELSE 0 END,
            r.relationship_order ASC,
            p.last_name ASC,
            p.first_name ASC,
            r.id ASC
        """,
        (person_id,),
    ).fetchall()

    addresses = db.execute(
        """
        SELECT pa.id AS person_address_id, pa.address_id, pa.label, pa.created_at, pa.is_default_mailing,
               a.street, a.city, a.state, a.postal_code,
               a.is_verified_deliverable, a.is_vacant, a.attom_last_sold_date, a.attom_last_sold_price
        FROM person_addresses pa
        JOIN addresses a ON a.id = pa.address_id
        WHERE pa.person_id = ?
        ORDER BY COALESCE(pa.is_default_mailing, 0) DESC, pa.created_at DESC, pa.id DESC
        """,
        (person_id,),
    ).fetchall()
    addresses = _decorate_person_address_rows(addresses)
    current_mail_address_row = get_default_person_address_row(db, person_id)
    current_mail_person_address_id = int(current_mail_address_row["person_address_id"] or 0) if current_mail_address_row else 0


    property_context = None
    property_id = request.args.get("property_id", "").strip()
    if property_id.isdigit():
        ctx = db.execute(
            """
            SELECT p.id, a.street, a.city, a.state, a.postal_code,
                   op.first_name AS owner_first, op.middle_name AS owner_middle, op.last_name AS owner_last
            FROM properties p
            JOIN addresses a ON a.id = p.property_address_id
            LEFT JOIN people op ON op.id = p.owner_person_id
            WHERE p.id = ?
            """,
            (int(property_id),),
        ).fetchone()
        if ctx:
            property_context = ctx
    default_property_id = property_context["id"] if property_context else None
    default_property_context = property_context
    if default_property_id is None:
        direct_prop = db.execute(
            "SELECT id FROM properties WHERE owner_person_id = ? OR resident_person_id = ? ORDER BY created_at DESC LIMIT 1",
            (person_id, person_id),
        ).fetchone()
        if direct_prop:
            default_property_id = direct_prop["id"]
            default_property_context = db.execute(
                """
                SELECT p.id, a.street, a.city, a.state, a.postal_code,
                       op.first_name AS owner_first, op.middle_name AS owner_middle, op.last_name AS owner_last
                FROM properties p
                JOIN addresses a ON a.id = p.property_address_id
                LEFT JOIN people op ON op.id = p.owner_person_id
                WHERE p.id = ?
                """,
                (default_property_id,),
            ).fetchone()

    context_relationship = None
    if default_property_context and default_property_context["id"]:
        owner_row = db.execute("SELECT owner_person_id FROM properties WHERE id = ?", (default_property_context["id"],)).fetchone()
        owner_pid = owner_row["owner_person_id"] if owner_row else None
        if owner_pid and int(owner_pid) != int(person_id):
            context_relationship = db.execute(
                """
                SELECT id, relationship_type
                FROM person_relationships
                WHERE subject_person_id = ? AND related_person_id = ?
                ORDER BY id DESC
                LIMIT 1
                """,
                (owner_pid, person_id),
            ).fetchone()

    communications = db.execute(
        """
        SELECT c.*
        FROM communications c
        WHERE c.person_id = ?
        ORDER BY c.sent_at ASC, c.id ASC
        """,
        (person_id,),
    ).fetchall()
    person_notes = db.execute(
        "SELECT * FROM person_notes WHERE person_id = ? ORDER BY created_at DESC, id DESC",
        (person_id,),
    ).fetchall()
    sequence_campaigns = get_sequence_campaigns(db, only_active=True)
    mail_sequence_campaigns = get_mail_only_sequence_campaigns(db, only_active=True)
    person_enrollments = db.execute(
        """
        SELECT e.*, c.name AS campaign_name, a.street, a.city, a.state, a.postal_code
        FROM sequence_enrollments e
        JOIN sequence_campaigns c ON c.id = e.campaign_id
        JOIN properties pr ON pr.id = e.property_id
        JOIN addresses a ON a.id = pr.property_address_id
        WHERE e.person_id = ?
        ORDER BY e.created_at DESC, e.id DESC
        LIMIT 100
        """,
        (person_id,),
    ).fetchall()
    mail_sequence_campaign_ids = {int(c["id"]) for c in mail_sequence_campaigns}
    mail_person_enrollments = [
        row for row in person_enrollments if int(row["campaign_id"] or 0) in mail_sequence_campaign_ids
    ]
    skiptrace_origin = db.execute(
        """
        SELECT r.subject_person_id,
               sp.first_name AS source_first_name,
               sp.middle_name AS source_middle_name,
               sp.last_name AS source_last_name
        FROM person_relationships r
        JOIN people sp ON sp.id = r.subject_person_id
        WHERE r.related_person_id = ?
          AND r.note LIKE '%source:skiptrace-person-import%'
        ORDER BY r.id DESC
        LIMIT 1
        """,
        (person_id,),
    ).fetchone()

    dedup_person_summary = [
        {
            "person_id": int(person["id"]),
            "full_name": person_name(person),
            "relationship_type": "Self",
        }
    ]
    person_counts_map = communication_counts_for_people(
        db,
        [r["person_id"] for r in dedup_person_summary],
        property_id=(default_property_id if default_property_id else None),
    )
    person_comm_summary_rows = []
    for row in dedup_person_summary:
        c = person_counts_map.get(int(row["person_id"]), {})
        person_comm_summary_rows.append(
            {
                **row,
                "mail_outbound": int(c.get("mail_outbound", 0)),
                "sms_outbound": int(c.get("sms_outbound", 0)),
                "sms_inbound": int(c.get("sms_inbound", 0)),
                "email_outbound": int(c.get("email_outbound", 0)),
                "email_inbound": int(c.get("email_inbound", 0)),
                "email_opened": int(c.get("email_opened", 0)),
            }
        )

    return render_template(
        "person_detail.html",
        person=person,
        touchpoints=touchpoints,
        person_primary_phone=person_primary_phone,
        person_phone_options=person_phone_options,
        person_email_options=person_email_options,
        socials=socials,
        relationship_rows=relationship_rows,
        addresses=addresses,
        current_mail_person_address_id=current_mail_person_address_id,
        person_notes=person_notes,
        communications=communications,
        property_context=property_context,
        default_property_context=default_property_context,
        default_property_id=default_property_id,
        context_relationship=context_relationship,
        skiptrace_origin=skiptrace_origin,
        smrt_from_number=get_deep_dive_sms_number(db),
        social_url=normalize_social_profile_url,
        sequence_campaigns=sequence_campaigns,
        mail_sequence_campaigns=mail_sequence_campaigns,
        person_enrollments=person_enrollments,
        mail_person_enrollments=mail_person_enrollments,
        person_comm_summary_rows=person_comm_summary_rows,
        seq_notice=(request.args.get("seq_notice") or "").strip(),
    )


@app.route("/api/people/<int:person_id>/notes", methods=["POST"])
def create_person_note_api(person_id):
    ensure_db()
    db = get_db()
