@app.route("/api/properties/<int:property_id>/mail/preview/relative/<int:person_id>/address/<int:person_address_id>", methods=["GET"])
def mail_preview_single_relative_address_route(property_id, person_id, person_address_id):
    ensure_db()
    db = get_db()
    template_id = direct_mail_template_id_from_request(db)
    prop = db.execute(
        """
        SELECT p.id, p.owner_person_id, a.street, a.city, a.state, a.postal_code
        FROM properties p
        JOIN addresses a ON a.id = p.property_address_id
        WHERE p.id = ?
        """,
        (property_id,),
    ).fetchone()
    if not prop:
        return jsonify({"error": "property not found"}), 404

    person = db.execute("SELECT deceased FROM people WHERE id = ?", (person_id,)).fetchone()
    if not person:
        return jsonify({"error": "person not found"}), 404
    if int(person["deceased"] or 0) == 1:
        return jsonify({"error": "Mailer is not available for deceased individuals"}), 400

    contact = _format_person_contact_for_mail(db, prop, person_id, person_address_id=person_address_id)
    if not contact:
        return jsonify({"error": "No mailing address available for this person at the selected address"}), 400

    built = build_openletterconnect_order_payload(
        db,
        [contact],
        prop,
        template_id=template_id,
        mode="mail-individual-address-override",
    )
    template_data = built.get("template") or {}
    include_proofs = request.args.get("include_proofs", "0").strip().lower() in ("1", "true", "yes")
    proofs = view_openletterconnect_proofs(built["payload"]) if include_proofs else []
    return jsonify(
        {
            "ok": True,
            "mode": "individual_address_override",
            "selected_template_id": template_id,
            "available_templates": get_direct_mail_available_templates(template_id),
            "recipient_count": 1,
            "payload": built["payload"],
            "proofs": proofs,
            "template_meta": build_openletterconnect_template_meta(template_data),
        }
    )


@app.route("/api/properties/<int:property_id>/mail/relatives", methods=["POST"])
def mail_all_relatives_route(property_id):
    ensure_db()
    db = get_db()
    template_id = direct_mail_template_id_from_request(db)
    prop = db.execute(
        """
        SELECT p.id, p.owner_person_id, a.street, a.city, a.state, a.postal_code
        FROM properties p
        JOIN addresses a ON a.id = p.property_address_id
        WHERE p.id = ?
        """,
        (property_id,),
    ).fetchone()
    if not prop or not prop["owner_person_id"]:
        return jsonify({"error": "property owner not found"}), 404

    rel_rows = db.execute(
        """
        SELECT DISTINCT p.id AS person_id
        FROM person_relationships r
        JOIN people p ON p.id = r.related_person_id
        WHERE r.subject_person_id = ? AND COALESCE(p.deceased, 0) = 0
        """,
        (prop["owner_person_id"],),
    ).fetchall()

    person_ids = []
    if prop["owner_person_id"]:
        owner_row = db.execute(
            "SELECT id FROM people WHERE id = ? AND COALESCE(deceased, 0) = 0",
            (prop["owner_person_id"],),
        ).fetchone()
        if owner_row:
            person_ids.append(owner_row["id"])
    person_ids.extend(r["person_id"] for r in rel_rows)

    contacts = []
    seen = set()
    for person_id in person_ids:
        contact = _format_person_contact_for_mail(db, prop, person_id)
        if not contact:
            continue
        key = (
            (contact.get("firstName") or "").strip().lower(),
            (contact.get("lastName") or "").strip().lower(),
            (contact.get("address1") or "").strip().lower(),
            (contact.get("city") or "").strip().lower(),
            (contact.get("state") or "").strip().lower(),
            (contact.get("zip") or "").strip(),
        )
        if key in seen:
            continue
        seen.add(key)
        contacts.append(contact)

    if not contacts:
        return jsonify({"error": "No mailable relatives with addresses found"}), 400

    try:
        result = place_openletterconnect_order(db, contacts, prop, template_id=template_id, mode="mail-all-relatives")
        res = result["response"] if isinstance(result, dict) else {}
        order_fields = extract_openletterconnect_order_fields(res)
        external_order_id = order_fields["order_id"]
        status = order_fields["status"]
        cost = order_fields["cost"]
        db.execute(
            """
            INSERT INTO mail_orders (
                property_id, person_id, mode, template_id, external_order_id, status, cost,
                recipient_count, request_json, response_json, status_updated_at, last_event_type
            )
            VALUES (?, NULL, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
            """,
            (
                property_id,
                "all_relatives",
                template_id,
                external_order_id,
                status,
                cost,
                len(contacts),
                json.dumps(result.get("request")),
                json.dumps(res),
                format_db_time(datetime.utcnow()),
                "order_submitted",
            ),
        )
        db.execute(
            """
            INSERT INTO activity_log (property_id, person_id, activity_type, outcome, note)
            VALUES (?, ?, ?, ?, ?)
            """,
            (
                property_id,
                prop["owner_person_id"],
                "Direct Mail",
                f"Submitted all-relatives mailer order {external_order_id or '(no id)'}",
                json.dumps(res),
            ),
        )
        db.commit()
        return jsonify({"ok": True, "recipient_count": len(contacts), "order": res}), 200
    except Exception as exc:
        db.rollback()
        return jsonify({"error": str(exc)}), 400


