@app.route("/webhooks/slack/command", methods=["POST"])
def slack_command_webhook():
    ensure_db()
    db = get_db()
    s = get_slack_settings(db)
    secret = (s.get("signing_secret") or "").strip()
    if secret:
        ok, reason = verify_slack_signature(request, secret)
        if not ok:
            return jsonify({"ok": False, "error": reason}), 401
    text = (request.form.get("text") or "").strip()
    cmd = (request.form.get("command") or "").strip()
    user_name = (request.form.get("user_name") or "").strip()
    user_id = (request.form.get("user_id") or "").strip()
    response_url = (request.form.get("response_url") or "").strip()
    channel_id = (request.form.get("channel_id") or "").strip()
    base_url = (request.url_root or "").strip().rstrip("/")
    low = text.lower()
    tokens = [t for t in re.split(r"\s+", low) if t]
    cmd_name = cmd.lower().lstrip("/")
    dedicated_comp_command = cmd_name in {"comp", "comps", "siftcomp", "findcomps", "find-comps"}
    sub = "comp" if dedicated_comp_command else (tokens[0] if tokens else "help")
    if sub in {"help", "?"}:
        return jsonify(
            {
                "response_type": "ephemeral",
                "text": (
                    "Agent Ops commands:\n"
                    "• `status` - agent pipeline snapshot\n"
                    "• `queue` - pending Agent 2 actions\n"
                    "• `unresolved` - unresolved lead-watch items\n"
                    "• `d4d <address>` - add or flag a Driving For Dollars lead\n"
                    "• `comp <address>` or `comp property #128` - run the manual SIFT comping worker and return XLSX\n"
                    "• `buyer <phone> [name] county(x,y) category(x,y) type(x,y)` - add or update a buyer\n"
                    "• `ads [30d] [platform(google,meta,...)]` - cached ad snapshot and spend\n"
                    "• `health` - agent endpoint health\n"
                    "• `help` - command list"
                ),
            }
        )
    if sub in {"comp", "comps", "findcomp", "find-comps"}:
        comp_text = text if dedicated_comp_command else text.partition(" ")[2].strip()
        target = _slack_comp_target(comp_text)
        if not target.get("ok"):
            return jsonify({"response_type": "ephemeral", "text": target.get("error") or "Use `comp <address>` or `comp property #128`."})
        try:
            request_id = enqueue_slack_comp_request(
                db,
                target,
                raw_text=text,
                channel_id=channel_id,
                user_id=user_id,
                user_name=user_name,
                response_url=response_url,
            )
            db.commit()
        except Exception as exc:
            db.rollback()
            log_app_error(
                db,
                source="slack_comp_enqueue",
                error_message=str(exc),
                details=json.dumps({"text": text, "user": user_name or user_id}),
                route="/webhooks/slack/command",
                status_code=500,
            )
            db.commit()
            return jsonify({"response_type": "ephemeral", "text": f"Could not queue comp report: {exc}"})
        label = f"property #{target.get('property_id')}" if int(target.get("property_id") or 0) else target.get("address")
        return jsonify(
            {
                "response_type": "in_channel",
                "text": (
                    f"SIFT Codex comp request #{request_id} queued for {label}.\n"
                    "Codex will run the uploaded real-estate-comping skill and upload the XLSX here when it finishes."
                ),
            }
        )
    if sub == "d4d":
        address_text = text.partition(" ")[2].strip()
        if not address_text:
            return jsonify(
                {
                    "response_type": "in_channel",
                    "text": "Use `d4d 123 Main St, Newark, NJ 07102` or `d4d 123 Main St Newark NJ`.",
                }
            )
        if response_url:
            launch_d4d_slack_intake(
                response_url=response_url,
                address_text=address_text,
                raw_text=text,
                added_by=user_name or user_id,
                base_url=base_url,
            )
            return jsonify(
                {
                    "response_type": "in_channel",
                    "text": (
                        "D4D intake started.\n"
                        f"Address received: {address_text}\n"
                        "Checking SIFT, retrieving owner details if needed, and I’ll update this message when it finishes."
                    ),
                }
            )
        result = process_d4d_slack_intake(
            response_url="",
            address_text=address_text,
            raw_text=text,
            added_by=user_name or user_id,
            base_url=base_url,
        )
        return jsonify(
            {
                "response_type": "in_channel",
                "text": "\n".join(result.get("lines") or [result.get("message") or "D4D intake finished."]),
            }
        )
    if sub == "buyer":
        parsed = parse_slack_buyer_command(text)
        if not parsed.get("ok"):
            return jsonify({"response_type": "ephemeral", "text": parsed.get("error") or "Could not parse buyer command."})
        try:
            result = upsert_buyer_from_slack_command(db, parsed, added_by=user_name or user_id)
            db.commit()
        except Exception as exc:
            db.rollback()
            log_app_error(
                db,
                source="slack_buyer_intake",
                error_message=str(exc),
                details=json.dumps({"text": text, "user": user_name or user_id}),
                route="/webhooks/slack/command",
                status_code=500,
            )
            db.commit()
            return jsonify(
                {
                    "response_type": "ephemeral",
                    "text": f"Could not create buyer: {exc}",
                }
            )
        buyer = result.get("buyer") or {}
        buyer_name = " ".join([x for x in [buyer.get("first_name"), buyer.get("last_name")] if str(x or "").strip()]).strip() or "Unknown Buyer"
        msg_lines = [
            f"Buyer {result.get('action') or 'saved'}: {buyer_name}",
            f"Phone: {buyer.get('phone') or parsed.get('phone_display') or parsed.get('phone_norm')}",
        ]
        if buyer.get("email"):
            msg_lines.append(f"Email: {buyer.get('email')}")
        if buyer.get("business_name"):
            msg_lines.append(f"Business: {buyer.get('business_name')}")
        if buyer.get("target_counties"):
            msg_lines.append(f"Counties: {buyer.get('target_counties')}")
        if buyer.get("buyer_categories"):
            msg_lines.append(f"Buyer Categories: {buyer.get('buyer_categories')}")
        if buyer.get("property_types"):
            msg_lines.append(f"Property Types: {buyer.get('property_types')}")
        msg_lines.append(f"Buyer ID: {result.get('buyer_id')}")
        return jsonify({"response_type": "in_channel", "text": "\n".join(msg_lines)})
    if sub == "ads":
        parsed = parse_slack_ads_command(text)
        if not parsed.get("ok"):
            return jsonify({"response_type": "ephemeral", "text": parsed.get("error") or "Could not parse ads command."})
        summary = summarize_ad_campaign_cache(db, days=parsed.get("days") or ADS_DEFAULT_LOOKBACK_DAYS, platform=parsed.get("platform") or "")
        rows = summary.get("rows") or []
        if not rows:
            return jsonify(
                {
                    "response_type": "ephemeral",
                    "text": "No ad data is cached yet. Open the Ads page and run Refresh first.",
                }
            )
        platform_rollup = {}
        for row in rows:
            key = row.get("platform") or "unknown"
            bucket = platform_rollup.setdefault(key, {"label": _ad_platform_label(key), "spend": 0.0, "live": 0})
            bucket["spend"] += _normalize_metric_float(row.get("spend"))
            if _ad_status_is_live(row.get("campaign_status")):
                bucket["live"] += 1
        lines = [
            f"Ads snapshot for @{user_name or 'user'}",
            f"Range: {summary.get('start_date')} to {summary.get('end_date')}",
            f"Spend: ${summary.get('spend', 0):,.2f}",
            f"Impressions: {summary.get('impressions', 0):,}",
            f"Clicks: {summary.get('clicks', 0):,}",
            f"Reach: {summary.get('reach', 0):,}",
            f"Conversions: {_normalize_metric_int(summary.get('conversions', 0)):,}",
            f"Live campaigns: {len(summary.get('live_rows') or [])}",
        ]
        if platform_rollup:
            lines.append("By platform:")
            for item in sorted(platform_rollup.values(), key=lambda x: x["spend"], reverse=True):
                lines.append(f"• {item['label']}: spend ${item['spend']:,.2f}, live {item['live']}")
        live_rows = sorted(summary.get("live_rows") or [], key=lambda row: _normalize_metric_float(row.get("spend")), reverse=True)
        if live_rows:
            lines.append("Top live campaigns:")
            for row in live_rows[:5]:
                lines.append(
                    f"• {_ad_platform_label(row.get('platform'))} | {row.get('campaign_name')} | ${_normalize_metric_float(row.get('spend')):,.2f}"
                )
        return jsonify({"response_type": "in_channel", "text": "\n".join(lines)})
    if sub in {"status", "overview"}:
        snap = build_agent_advisor_snapshot(db, window_hours=72)
        signals = snap.get("signals", {})
        actions = snap.get("actions", {})
        calls = snap.get("calls", {})
        lw = snap.get("lead_watch_today", {})
        latest_run = snap.get("latest_run", {})
        msg = (
            f"DeepSift Agent Ops status for @{user_name or 'user'}:\n"
            f"Signals: new={signals.get('new_total', 0)}, routed={signals.get('routed_total', 0)}, "
            f"sms={signals.get('sms_total', 0)}, calls={signals.get('call_total', 0)}\n"
            f"Agent 2 queue: pending={actions.get('pending_total', 0)}, "
            f"high={actions.get('high_pending_total', 0)}, stale_2d={actions.get('stale_pending_2d', 0)}\n"
            f"Call analysis: pending={calls.get('pending_total', 0)}, failed={calls.get('failed_total', 0)}\n"
            f"Lead watch: total={lw.get('count', 0)}, unresolved={lw.get('unresolved_count', 0)}, "
            f"actionable_unresolved={lw.get('unresolved_active_count', 0)}\n"
            f"Latest lead monitor run: #{latest_run.get('id', 0)} ({latest_run.get('status', '-')})"
        )
        return jsonify({"response_type": "ephemeral", "text": msg})
    if sub in {"queue", "pending"}:
        rows = db.execute(
            """
            SELECT id, action_type, priority, status, due_at, reason, property_id
            FROM lead_management_actions
            WHERE status = 'Pending'
            ORDER BY
                CASE priority WHEN 'High' THEN 0 WHEN 'Medium' THEN 1 ELSE 2 END,
                datetime(COALESCE(due_at, updated_at, created_at)) ASC,
                id ASC
            LIMIT 8
            """
        ).fetchall()
        if not rows:
            return jsonify({"response_type": "ephemeral", "text": "Agent 2 queue is clear (no pending actions)."})
        lines = ["Top Agent 2 pending actions:"]
        for r in rows:
            due = format_est_datetime(str(r["due_at"] or "")) if str(r["due_at"] or "").strip() else "-"
            lines.append(
                f"• #{int(r['id'])} [{r['priority']}] {r['action_type']} | due {due} | "
                f"lead property_id={int(r['property_id'] or 0)}"
            )
        return jsonify({"response_type": "ephemeral", "text": "\n".join(lines)})
    if sub in {"unresolved", "watch"}:
        lw = build_today_lead_watch_snapshot(db, limit=50)
        unresolved = [
            x
            for x in (lw.get("items") or [])
            if int(x.get("unresolved") or 0) == 1
            and int(x.get("ignore_agent2") or 0) == 0
            and str(x.get("classification") or "").strip().lower() not in {"spam", "solicitor"}
        ]
        if not unresolved:
            return jsonify({"response_type": "ephemeral", "text": "No actionable unresolved lead-watch items right now."})
        lines = [f"Actionable unresolved lead-watch items: {len(unresolved)}"]
        for row in unresolved[:8]:
            lines.append(
                f"• {row.get('label') or row.get('lead_key')}: "
                f"sms_out={int(row.get('sms_outbound') or 0)}, sms_in={int(row.get('sms_inbound') or 0)}, calls={int(row.get('calls') or 0)}"
            )
        return jsonify({"response_type": "ephemeral", "text": "\n".join(lines)})
    if sub in {"health", "ping"}:
        return jsonify({"response_type": "ephemeral", "text": "DeepSift Agent Ops is online."})
    return jsonify({"response_type": "ephemeral", "text": f"Unknown agent-ops command `{text or cmd}`. Try `help`."})


