@app.route("/webhooks/slack/events", methods=["POST"])
def slack_events_webhook():
    ensure_db()
    db = get_db()
    s = get_slack_settings(db)
    secret = (s.get("signing_secret") or "").strip()
    if secret:
        ok, reason = verify_slack_signature(request, secret)
        if not ok:
            return jsonify({"ok": False, "error": reason}), 401
    payload = request.get_json(force=True, silent=True) or {}
    if payload.get("type") == "url_verification":
        return jsonify({"challenge": payload.get("challenge", "")})
    event = payload.get("event") if isinstance(payload.get("event"), dict) else {}
    event_id = (payload.get("event_id") or "").strip() or f"slack_event_{int(time.time())}"
    is_new = upsert_integration_event(db, "slack_event", event_id, payload)
    db.commit()
    if not is_new:
        return jsonify({"ok": True, "duplicate": True})
    try:
        if event.get("type") == "app_mention":
            text = (event.get("text") or "").strip()
            send_agent_ops_notification(db, f"Slack mention received: {text}")
    except Exception:
        pass
    return jsonify({"ok": True})


def _smrtphone_request_payload(payload=None):
    if isinstance(payload, dict):
        return payload
    return request.get_json(silent=True) or request.form.to_dict() or {}


def _verify_smrtphone_webhook_request(db):
    expected = get_smrtphone_webhook_token(db)
    if not expected:
        return True, ""
    provided = (
        (request.args.get("token") or "").strip()
        or (request.headers.get("X-SmrtPhone-Token") or "").strip()
        or (request.headers.get("X-Webhook-Token") or "").strip()
        or str((request.get_json(silent=True) or {}).get("token") or "").strip()
        or (request.form.get("token") or "").strip()
    )
    if not provided or not hmac.compare_digest(provided, expected):
        return False, "Invalid SmrtPhone webhook token."
    return True, ""


def _is_smrtagent_call_ended_event(payload, webhook, event_name=""):
    payload = payload if isinstance(payload, dict) else {}
    webhook = webhook if isinstance(webhook, dict) else {}
    candidates = [
        event_name,
        extract_first_string_by_keys(payload, ["event", "eventType", "type", "name", "webhookType", "webhook_type"]),
        extract_first_string_by_keys(webhook, ["event", "eventType", "type", "name", "webhookType", "webhook_type"]),
    ]
    for raw in candidates:
        normalized = re.sub(r"[^a-z0-9]+", "", str(raw or "").strip().lower())
        if not normalized:
            continue
        if ("smrtagent" in normalized or "smartagent" in normalized) and (
            "callended" in normalized
            or "callcomplete" in normalized
            or "endedcall" in normalized
            or "completedcall" in normalized
        ):
            return True
    return False


def _dispatch_smrtphone_events_webhook(db, payload):
    payload = payload if isinstance(payload, dict) else {}
    webhook = payload.get("webhook") if isinstance(payload.get("webhook"), dict) else {}
    event_name = (
        extract_first_string_by_keys(payload, ["event", "eventType", "type", "name"])
        or extract_first_string_by_keys(webhook, ["event", "eventType", "type", "name"])
    ).strip().lower()
    has_sms_content = any(
        str(payload.get(key) or "").strip()
        for key in ("message", "body", "text")
    )
    has_call_sid = bool(
        extract_first_string_by_keys(
            payload,
            ["call_sid", "callSid", "CallSid", "callsid", "sid", "call_id", "callId", "callID"],
        )
        or extract_first_string_by_keys(
            webhook,
            ["call_sid", "callSid", "CallSid", "callsid", "sid", "call_id", "callId", "callID"],
        )
    )
    if _is_smrtagent_call_ended_event(payload, webhook, event_name):
        return smrtphone_agent_call_ended_webhook(payload=payload, db=db)
    if "delivery" in event_name or "callback" in event_name or (
        str(payload.get("smsId") or payload.get("sms_id") or payload.get("id") or "").strip()
        and str(payload.get("status") or "").strip()
        and not has_sms_content
        and not has_call_sid
    ):
        return smrtphone_status_webhook(payload=payload, db=db)
    if has_call_sid or "call" in event_name:
        return smrtphone_call_completed_webhook(payload=payload, db=db)
    if has_sms_content or str(payload.get("smsId") or payload.get("sms_id") or "").strip():
        return smrtphone_inbound_webhook(payload=payload, db=db)
    log_smrtphone_webhook_event(
        db,
        "events_unknown",
        payload,
        processing_status="ignored",
        error_text=f"Unrecognized unified SmrtPhone payload (event={event_name or 'unknown'})",
    )
    db.commit()
    return jsonify({"ok": True, "ignored": True, "reason": "unrecognized event"}), 200


@app.route("/webhooks/smrtphone/events", methods=["POST"])
def smrtphone_events_webhook():
    ensure_db()
    db = get_db()
    ok, reason = _verify_smrtphone_webhook_request(db)
    if not ok:
        return jsonify({"ok": False, "error": reason}), 401
    payload = _smrtphone_request_payload()
    return _dispatch_smrtphone_events_webhook(db, payload)


@app.route("/webhooks/smrtphone/inbound", methods=["POST"])
def smrtphone_inbound_webhook(payload=None, db=None):
    ensure_db()
    db = db or get_db()

    payload = _smrtphone_request_payload(payload)
    sms_id = str(payload.get("smsId") or payload.get("sms_id") or payload.get("id") or "").strip()
    from_number = str(payload.get("from") or payload.get("from_number") or "").strip()
    to_number = str(payload.get("to") or payload.get("to_number") or "").strip()
    message = str(payload.get("message") or payload.get("body") or payload.get("text") or "").strip()
    status = str(payload.get("status") or "Received").strip().title()
    event_name = str(payload.get("event") or payload.get("eventType") or "").strip().lower()

    if "incoming" in event_name:
        direction = "Inbound"
    elif "outgoing" in event_name:
        direction = "Outbound"
    else:
        # When event is missing, infer from known SMS flow defaults.
        direction = "Inbound"
    event_type = "outbound" if direction == "Outbound" else "inbound"

    if not message:
        log_smrtphone_webhook_event(
            db,
            event_type,
            payload,
            processing_status="ignored",
            sms_id=sms_id,
            from_number=from_number,
            to_number=to_number,
            error_text="message/body/text is required",
        )
        db.commit()
        return jsonify({"ok": True, "ignored": True, "reason": "message/body/text is required"}), 200

    counterparty_number = from_number if direction == "Inbound" else to_number
    person_id = find_person_id_by_phone(db, counterparty_number)
    property_id = None
    reisift_context = {}
    if str(payload.get("property_id", "")).isdigit():
        property_id = int(payload["property_id"])
    elif person_id:
        property_id = find_property_id_for_person(db, person_id)
    if not property_id and counterparty_number:
        reisift_context = resolve_property_context_by_phone(db, counterparty_number, search_reisift=True)
        if int(reisift_context.get("property_id") or 0):
            property_id = int(reisift_context.get("property_id") or 0)
            if not person_id and int(reisift_context.get("person_id") or 0):
                person_id = int(reisift_context.get("person_id") or 0)
    resolved_reisift_uuid = normalize_uuid(reisift_context.get("reisift_property_uuid") or "")
    has_local_property = bool(int(property_id or 0))
    if not has_local_property:
        signal = classify_unknown_contact_text(message)
        source_key_basis = sms_id or hashlib.sha1(
            f"{event_type}|{from_number}|{to_number}|{message}|{event_name}".encode("utf-8", errors="ignore")
        ).hexdigest()[:20]
        source_key = f"sms-unresolved:{source_key_basis}"
        reisift_only_context = bool(resolved_reisift_uuid)
        unresolved_classification = "potential_seller" if reisift_only_context else signal["classification"]
        unresolved_source = "smrtphone_webhook_reisift_only" if reisift_only_context else "smrtphone_webhook_unresolved"
        unresolved_confidence = 0.78 if reisift_only_context else 0.55
        unresolved_note = f"direction={direction}; event={event_name or event_type}"
        if reisift_only_context:
            unresolved_note += "; no_local_property=1"
        upsert_cached_contact_context(
            db,
            counterparty_number,
            property_id=None,
            person_id=person_id,
            classification=unresolved_classification,
            source=unresolved_source,
            confidence=unresolved_confidence,
            notes=unresolved_note,
            reisift_property_uuid=resolved_reisift_uuid,
            reisift_full_address=str(reisift_context.get("reisift_full_address") or "").strip(),
            reisift_owner_name=str(reisift_context.get("reisift_owner_name") or "").strip(),
            reisift_property_status=str(reisift_context.get("reisift_property_status") or "").strip(),
            last_reisift_lookup_at=format_db_time(datetime.utcnow()) if reisift_only_context else None,
        )
        summary_prefix = "REISift-only" if reisift_only_context else "Unresolved"
        upsert_agent_signal(
            db,
            source_type="sms",
            source_key=source_key,
            property_id=None,
            person_id=person_id,
            channel="SMS",
            intent=signal["intent"],
            sentiment="Unknown",
            confidence=unresolved_confidence,
            recommended_next_step=signal["recommended"],
            summary_text=f"{summary_prefix} {direction.lower()} SMS: {message[:240]}",
            is_spam=(signal["classification"] in {"spam", "solicitor"}),
            do_not_contact=(signal["classification"] in {"spam", "solicitor"}),
            payload={
                "event": event_name,
                "from": from_number,
                "to": to_number,
                "message": message,
                "classification": signal["classification"],
                "reisift_property_uuid": resolved_reisift_uuid,
                "reisift_full_address": str(reisift_context.get("reisift_full_address") or "").strip(),
            },
        )
        route_new_agent_signals_once(db, limit=10)
        unresolved_error = (
            f"REISift context found without local property for {direction.lower()} message (event={event_name or 'unknown'}); uuid={resolved_reisift_uuid or '-'}"
            if reisift_only_context
            else f"Context unresolved for {direction.lower()} message (event={event_name or 'unknown'}); classified={signal['classification']}"
        )
        log_smrtphone_webhook_event(
            db,
            event_type,
            payload,
            processing_status="stored_unresolved",
            sms_id=sms_id,
            from_number=from_number,
            to_number=to_number,
            error_text=unresolved_error,
        )
        db.commit()
        return jsonify(
            {
                "ok": True,
                "stored_unresolved": True,
                "classification": signal["classification"],
                "reisift_only_context": reisift_only_context,
            }
        ), 200
    if not person_id:
        if property_id:
            person_id = find_person_id_by_recent_outbound_to_number(db, property_id, counterparty_number)
        if not person_id:
            person_id = find_person_id_by_phone(db, counterparty_number)
    upsert_cached_contact_context(
        db,
        counterparty_number,
        property_id=property_id,
        person_id=person_id,
        classification="potential_seller",
        source="smrtphone_webhook_resolved",
        confidence=0.9,
        notes=f"direction={direction}; event={event_name or event_type}",
        reisift_property_uuid=resolved_reisift_uuid,
        reisift_full_address=str(reisift_context.get("reisift_full_address") or "").strip(),
        reisift_owner_name=str(reisift_context.get("reisift_owner_name") or "").strip(),
        reisift_property_status=str(reisift_context.get("reisift_property_status") or "").strip(),
        last_reisift_lookup_at=format_db_time(datetime.utcnow()),
    )

    existing = None
    if sms_id:
        existing = db.execute("SELECT id FROM communications WHERE external_id = ?", (sms_id,)).fetchone()
    if existing:
        if direction == "Inbound":
            update_person_outreach_status_for_sms(db, person_id, "inbound_received")
        else:
            update_person_outreach_status_for_sms(db, person_id, "outbound_success")
        log_smrtphone_webhook_event(
            db,
            event_type,
            payload,
            processing_status="deduped",
            sms_id=sms_id,
            from_number=from_number,
            to_number=to_number,
            communication_id=existing["id"],
        )
        db.commit()
        return jsonify({"ok": True, "deduped": True, "communication_id": existing["id"]})

    # Handle provider behavior where one callback arrives without smsId and a second with smsId,
    # and dedupe provider outbound callbacks against locally-sent outbound rows.
    if direction == "Inbound":
        recent = find_recent_inbound_match(
            db, property_id, person_id, from_number, to_number, message, seconds=150
        )
    else:
        recent = db.execute(
            """
            SELECT id, external_id
            FROM communications
            WHERE property_id = ?
              AND upper(channel) = 'SMS'
              AND lower(direction) = 'outbound'
              AND COALESCE(to_number, '') = COALESCE(?, '')
              AND COALESCE(body, '') = COALESCE(?, '')
              AND sent_at >= ?
            ORDER BY id DESC
            LIMIT 1
            """,
            (property_id, to_number, message, format_db_time(datetime.utcnow() - timedelta(minutes=30))),
        ).fetchone()
    if recent:
        if direction == "Inbound":
            update_person_outreach_status_for_sms(db, person_id, "inbound_received")
        else:
            update_person_outreach_status_for_sms(db, person_id, "outbound_success")
        if sms_id and not (recent["external_id"] or "").strip():
            db.execute(
                "UPDATE communications SET external_id = ?, status = ? WHERE id = ?",
                (sms_id, status, recent["id"]),
            )
        log_smrtphone_webhook_event(
            db,
            event_type,
            payload,
            processing_status="deduped",
            sms_id=sms_id,
            from_number=from_number,
            to_number=to_number,
            communication_id=recent["id"],
        )
        db.commit()
        return jsonify({"ok": True, "deduped": True, "communication_id": recent["id"]})

    cur = db.execute(
        """
        INSERT INTO communications (property_id, person_id, channel, direction, from_number, to_number, body, status, is_read, sent_at, external_id)
        VALUES (?, ?, 'SMS', ?, ?, ?, ?, ?, ?, ?, ?)
        """,
        (
            property_id,
            person_id,
            direction,
            from_number,
            to_number,
            message,
            status,
            0 if direction == "Inbound" else 1,
            datetime.utcnow().strftime("%Y-%m-%d %H:%M:%S"),
            sms_id,
        ),
    )
    if direction == "Inbound":
        update_person_outreach_status_for_sms(db, person_id, "inbound_received")
    else:
        update_person_outreach_status_for_sms(db, person_id, "outbound_success")
    log_smrtphone_webhook_event(
        db,
        event_type,
        payload,
        processing_status="stored",
        sms_id=sms_id,
        from_number=from_number,
        to_number=to_number,
        communication_id=cur.lastrowid,
    )
    db.commit()
    return jsonify({"ok": True, "communication_id": cur.lastrowid}), 201


@app.route("/webhooks/smrtphone/status", methods=["POST"])
def smrtphone_status_webhook(payload=None, db=None):
    ensure_db()
    db = db or get_db()

    payload = _smrtphone_request_payload(payload)
    sms_id = str(payload.get("smsId") or payload.get("sms_id") or payload.get("id") or "").strip()
    status = str(payload.get("status") or "").strip().title()
    to_number = str(payload.get("to") or payload.get("to_number") or "").strip()
    from_number = str(payload.get("from") or payload.get("from_number") or "").strip()
    status_detail_text = " ".join(
        [
            str(payload.get("status") or ""),
            str(payload.get("status_text") or ""),
            str(payload.get("statusMessage") or ""),
            str(payload.get("status_message") or ""),
            str(payload.get("message") or ""),
            str(payload.get("error") or ""),
            str(payload.get("error_message") or ""),
            str(payload.get("reason") or ""),
            str(payload.get("description") or ""),
        ]
    ).strip()

    if not sms_id:
        log_smrtphone_webhook_event(
            db,
            "status",
            payload,
            processing_status="error",
            error_text="smsId is required",
            from_number=from_number,
            to_number=to_number,
        )
        db.commit()
        return jsonify({"ok": True, "ignored": True, "reason": "missing smsId"}), 200
    if not status:
        log_smrtphone_webhook_event(
            db,
            "status",
            payload,
            processing_status="error",
            sms_id=sms_id,
            from_number=from_number,
            to_number=to_number,
            error_text="status is required",
        )
        db.commit()
        return jsonify({"ok": True, "ignored": True, "reason": "missing status"}), 200

    row = db.execute("SELECT id FROM communications WHERE external_id = ?", (sms_id,)).fetchone()
    if row:
        db.execute(
            "UPDATE communications SET status = ?, to_number = COALESCE(NULLIF(?, ''), to_number), from_number = COALESCE(NULLIF(?, ''), from_number) WHERE id = ?",
            (status, to_number, from_number, row["id"]),
        )
        if to_number:
            apply_touchpoint_status_inference(db, to_number, status_detail_text or status)
        log_smrtphone_webhook_event(
            db,
            "status",
            payload,
            processing_status="updated",
            sms_id=sms_id,
            from_number=from_number,
            to_number=to_number,
            communication_id=row["id"],
        )
        db.commit()
        return jsonify({"ok": True, "communication_id": row["id"]})

    # Backfill case: sent row exists without external_id, then provider status arrives with smsId.
    body = str(payload.get("message") or payload.get("body") or "").strip()
    recent_outbound = db.execute(
        """
        SELECT id
        FROM communications
        WHERE upper(channel) = 'SMS'
          AND lower(direction) = 'outbound'
          AND COALESCE(external_id, '') = ''
          AND COALESCE(to_number, '') = COALESCE(?, '')
          AND (? = '' OR COALESCE(body, '') = ?)
          AND sent_at >= ?
        ORDER BY id DESC
        LIMIT 1
        """,
        (to_number, body, body, format_db_time(datetime.utcnow() - timedelta(minutes=30))),
    ).fetchone()
    if recent_outbound:
        db.execute(
            """
            UPDATE communications
            SET external_id = ?, status = ?, to_number = COALESCE(NULLIF(?, ''), to_number), from_number = COALESCE(NULLIF(?, ''), from_number)
            WHERE id = ?
            """,
            (sms_id, status, to_number, from_number, recent_outbound["id"]),
        )
        if to_number:
            apply_touchpoint_status_inference(db, to_number, status_detail_text or status)
        log_smrtphone_webhook_event(
            db,
            "status",
            payload,
            processing_status="backfilled",
            sms_id=sms_id,
            from_number=from_number,
            to_number=to_number,
            communication_id=recent_outbound["id"],
        )
        db.commit()
        return jsonify({"ok": True, "communication_id": recent_outbound["id"], "backfilled": True})

    cached_ctx = get_cached_contact_context(db, to_number) or get_cached_contact_context(db, from_number)
    if str(payload.get("property_id", "")).isdigit():
        property_id = int(payload["property_id"])
    elif cached_ctx and cached_ctx["property_id"]:
        property_id = int(cached_ctx["property_id"])
    else:
        log_smrtphone_webhook_event(
            db,
            "status",
            payload,
            processing_status="orphan",
            sms_id=sms_id,
            from_number=from_number,
            to_number=to_number,
            error_text="Unknown smsId; property_id required to create status record",
        )
        db.commit()
        return jsonify({"ok": True, "ignored": True, "reason": "unknown smsId"}), 200
    person_id = None
    if str(payload.get("person_id", "")).isdigit():
        person_id = int(payload["person_id"])
    elif cached_ctx and cached_ctx["person_id"]:
        person_id = int(cached_ctx["person_id"])
    elif to_number:
        person_id = find_person_id_by_phone(db, to_number)
    upsert_cached_contact_context(
        db,
        to_number or from_number,
        property_id=property_id,
        person_id=person_id,
        classification="potential_seller",
        source="smrtphone_status",
        confidence=0.8,
        notes=f"sms_status={status}",
    )

    cur = db.execute(
        """
        INSERT INTO communications (property_id, person_id, channel, direction, from_number, to_number, body, status, is_read, sent_at, external_id)
        VALUES (?, ?, 'SMS', 'Outbound', ?, ?, ?, ?, ?, ?, ?)
        """,
        (
            property_id,
            person_id,
            from_number,
            to_number,
            body,
            status,
            1,
            datetime.utcnow().strftime("%Y-%m-%d %H:%M:%S"),
            sms_id,
        ),
    )
    if to_number:
        apply_touchpoint_status_inference(db, to_number, status_detail_text or status)
    log_smrtphone_webhook_event(
        db,
        "status",
        payload,
        processing_status="stored",
        sms_id=sms_id,
        from_number=from_number,
        to_number=to_number,
        communication_id=cur.lastrowid,
    )
    db.commit()
    return jsonify({"ok": True, "communication_id": cur.lastrowid}), 201


@app.route("/webhooks/smrtphone/call-completed", methods=["POST"])
def smrtphone_call_completed_webhook(payload=None, db=None):
    ensure_db()
    db = db or get_db()
    payload = _smrtphone_request_payload(payload)
    call_sid = extract_first_string_by_keys(
        payload,
        ["call_sid", "callSid", "CallSid", "callsid", "sid", "call_id", "callId", "callID", "id"],
    )
    from_number = extract_first_string_by_keys(payload, ["from", "from_number", "fromNumber", "caller", "source", "ani"])
    to_number = extract_first_string_by_keys(payload, ["to", "to_number", "toNumber", "callee", "destination", "dnis"])
    call_outcome = extract_first_string_by_keys(payload, ["callOutcome", "call_outcome", "outcome", "status"])
    direct_recording_url = extract_first_string_by_keys(payload, ["recordingUrl", "recording_url", "recording", "url"])
    normalized_outcome = (call_outcome or "").strip().lower()
    resolved_reisift_context = {}

    def _resolve_property_person():
        _person_id = find_person_id_by_phone(db, from_number) or find_person_id_by_phone(db, to_number)
        _property_id = None
        if str(payload.get("property_id") or "").isdigit():
            _property_id = int(payload.get("property_id"))
        elif _person_id:
            _property_id = find_property_id_for_person(db, _person_id)
        ctx = resolve_shared_event_context(
            db,
            from_number,
            to_number,
            fallback_property_id=_property_id,
            force_reisift=True,
            search_reisift=True,
        ) or {}
        if int(ctx.get("property_id") or 0):
            _property_id = int(ctx.get("property_id") or 0)
        if not _person_id and int(ctx.get("person_id") or 0):
            _person_id = int(ctx.get("person_id") or 0)
        if ctx and not resolved_reisift_context:
            resolved_reisift_context.update(ctx)
        return _property_id, _person_id

    if not call_sid:
        property_id, person_id = _resolve_property_person()
        if property_id:
            _create_agent_diagnosis_review_action(
                db,
                property_id=int(property_id),
                person_id=person_id,
                call_sid="(missing)",
                diagnosis="Call webhook missing call SID",
                attempted_fix="Tried resolving context by from/to numbers and recent outbound thread",
                proposed_resolution="Validate provider webhook payload includes callId/call_sid and resend failed event if possible.",
                priority="High",
                extra={"payload": payload},
            )
        log_smrtphone_webhook_event(
            db,
            "call_completed",
            payload,
            processing_status="error",
            from_number=from_number,
            to_number=to_number,
            error_text="call_sid is required",
        )
        db.commit()
        return jsonify({"ok": True, "ignored": True, "reason": "missing call_sid"}), 200

    existing = db.execute("SELECT id FROM call_recording_jobs WHERE call_sid = ?", (call_sid,)).fetchone()
    if existing:
        log_smrtphone_webhook_event(
            db,
            "call_completed",
            payload,
            processing_status="deduped",
            from_number=from_number,
            to_number=to_number,
            error_text="duplicate call_sid",
        )
        db.commit()
        return jsonify({"ok": True, "deduped": True, "job_id": existing["id"]}), 200

    property_id, person_id = _resolve_property_person()
    phone_candidates = _counterparty_candidates(db, from_number, to_number)
    counterparty_number = phone_candidates[0] if phone_candidates else (from_number or to_number)
    if property_id or normalize_uuid(resolved_reisift_context.get("reisift_property_uuid") or ""):
        upsert_cached_contact_context(
            db,
            counterparty_number,
            property_id=property_id,
            person_id=person_id,
            classification="potential_seller",
            source="smrtphone_call_completed",
            confidence=0.9,
            notes=f"call_sid={call_sid}",
            reisift_property_uuid=normalize_uuid(resolved_reisift_context.get("reisift_property_uuid") or ""),
            reisift_full_address=str(resolved_reisift_context.get("reisift_full_address") or "").strip(),
            reisift_owner_name=str(resolved_reisift_context.get("reisift_owner_name") or "").strip(),
            reisift_property_status=str(resolved_reisift_context.get("reisift_property_status") or "").strip(),
            last_reisift_lookup_at=format_db_time(datetime.utcnow()),
        )

    recording_url = (direct_recording_url or "").strip()
    fetch_status = "Queued"
    fetch_raw = {}
    if recording_url:
        fetch_status = "Fetched"
        fetch_raw = {"source": "webhook_payload"}
    elif (call_outcome or "").strip().lower() in {"missed", "no_answer", "failed"}:
        fetch_status = "No Recording URL"
        fetch_raw = {"source": "webhook_payload", "reason": f"call_outcome={call_outcome}"}
    else:
        try:
            lookup = fetch_smrtphone_recording_url(call_sid)
            recording_url = (lookup.get("recording_url") or "").strip()
            fetch_raw = lookup.get("raw") or {}
            fetch_status = "Fetched" if recording_url else "No Recording URL"
        except Exception as exc:
            fetch_status = "Error"
            fetch_raw = {"error": str(exc)}

    cur = db.execute(
        """
        INSERT INTO call_recording_jobs
        (call_sid, from_number, to_number, property_id, person_id, recording_url, fetch_status, analysis_status, payload_json)
        VALUES (?, ?, ?, ?, ?, ?, ?, 'Pending', ?)
        """,
        (
            call_sid,
            from_number,
            to_number,
            property_id,
            person_id,
            recording_url,
            fetch_status,
            json.dumps({"webhook": payload, "recording_lookup": fetch_raw, "call_outcome": call_outcome}),
        ),
    )

    if property_id and normalized_outcome in NO_ANSWER_OUTCOMES:
        recommended_step, reason = _recommend_no_answer_next_step(db, int(property_id), person_id)
        upsert_agent_signal(
            db,
            source_type="call",
            source_key=f"call-no-answer:{call_sid}",
            property_id=property_id,
            person_id=person_id,
            channel="CALL",
            intent="No Answer",
            sentiment="Unknown",
            confidence=0.85,
            recommended_next_step=recommended_step,
            summary_text=f"No-answer call outcome. {reason}",
            is_spam=False,
            do_not_contact=False,
            payload={"call_sid": call_sid, "call_outcome": normalized_outcome, "reason": reason},
        )
        route_new_agent_signals_once(db, limit=25)
        trigger_agent_pipeline_refresh(db, property_id=int(property_id), reason="call_completed_no_answer")

    log_smrtphone_webhook_event(
        db,
        "call_completed",
        payload,
        processing_status="stored",
        from_number=from_number,
        to_number=to_number,
    )
    db.commit()
    return jsonify({"ok": True, "job_id": cur.lastrowid, "call_sid": call_sid, "recording_url": recording_url, "fetch_status": fetch_status})


@app.route("/webhooks/smrtphone/agent-call-ended", methods=["POST"])
def smrtphone_agent_call_ended_webhook(payload=None, db=None):
    ensure_db()
    db = db or get_db()

    payload = _smrtphone_request_payload(payload)
    webhook = payload.get("webhook") if isinstance(payload.get("webhook"), dict) else {}
    event_name = (
        extract_first_string_by_keys(payload, ["event", "eventType", "type", "name"])
        or extract_first_string_by_keys(webhook, ["event", "eventType", "type", "name"])
        or "smrtAgent Call Ended"
    ).strip()
    call_sid = (
        extract_first_string_by_keys(payload, ["call_sid", "callSid", "CallSid", "callsid", "sid", "call_id", "callId", "callID", "id"])
        or extract_first_string_by_keys(webhook, ["call_sid", "callSid", "CallSid", "callsid", "sid", "call_id", "callId", "callID", "id"])
    )
    caller_number = normalize_phone(
        extract_first_string_by_keys(payload, ["phone_number_caller"])
        or extract_first_string_by_keys(webhook, ["phone_number_caller"])
    )
    agent_number = normalize_phone(
        extract_first_string_by_keys(payload, ["phone_number_agent"])
        or extract_first_string_by_keys(webhook, ["phone_number_agent"])
    )
    from_number = normalize_phone(
        caller_number
        or extract_first_string_by_keys(payload, ["from", "from_number", "fromNumber", "caller", "source", "ani"])
        or extract_first_string_by_keys(webhook, ["from", "from_number", "fromNumber", "caller", "source", "ani"])
    )
    to_number = normalize_phone(
        agent_number
        or extract_first_string_by_keys(payload, ["to", "to_number", "toNumber", "callee", "destination", "dnis"])
        or extract_first_string_by_keys(webhook, ["to", "to_number", "toNumber", "callee", "destination", "dnis"])
    )
    agent_name = (
        extract_first_string_by_keys(payload, ["agentName", "agent_name", "userName", "user_name", "aiAgent", "agent"])
        or extract_first_string_by_keys(webhook, ["agentName", "agent_name", "userName", "user_name", "aiAgent", "agent"])
        or "AI Agent"
    ).strip()
    contact_name = (
        extract_first_string_by_keys(payload, ["contactName", "contact_name", "leadName", "lead_name", "callerName", "caller_name"])
        or extract_first_string_by_keys(webhook, ["contactName", "contact_name", "leadName", "lead_name", "callerName", "caller_name"])
    ).strip()
    outcome = (
        extract_first_string_by_keys(payload, ["callOutcome", "call_outcome", "outcome", "status", "disposition"])
        or extract_first_string_by_keys(webhook, ["callOutcome", "call_outcome", "outcome", "status", "disposition"])
    ).strip()
    duration = (
        extract_first_string_by_keys(payload, ["duration", "callDuration", "call_duration", "durationSeconds", "duration_seconds"])
        or extract_first_string_by_keys(webhook, ["duration", "callDuration", "call_duration", "durationSeconds", "duration_seconds"])
    ).strip()
    summary = (
        extract_first_string_by_keys(payload, ["summary", "notes", "callSummary", "call_summary", "dispositionNotes", "disposition_notes"])
        or extract_first_string_by_keys(webhook, ["summary", "notes", "callSummary", "call_summary", "dispositionNotes", "disposition_notes"])
    ).strip()
    timestamp_text = (
        extract_first_string_by_keys(payload, ["timestamp", "completed_at", "endedAt", "ended_at", "date"])
        or extract_first_string_by_keys(webhook, ["timestamp", "completed_at", "endedAt", "ended_at", "date"])
    ).strip()
    follow_up_number_display = format_phone_display(caller_number)

    if call_sid:
        existing_agent_event = db.execute(
            """
            SELECT id, processing_status
            FROM smrtphone_webhook_events
            WHERE event_type = 'agent_call_ended'
              AND sms_id = ?
              AND processing_status IN ('slack_sent', 'slack_disabled')
            ORDER BY id DESC
            LIMIT 1
            """,
            (call_sid,),
        ).fetchone()
        if existing_agent_event:
            log_smrtphone_webhook_event(
                db,
                "agent_call_ended",
                payload,
                processing_status="deduped",
                sms_id=call_sid,
                from_number=from_number,
                to_number=to_number,
                error_text=f"duplicate call_sid; previous status={existing_agent_event['processing_status']}",
            )
            db.commit()
            return jsonify(
                {
                    "ok": True,
                    "deduped": True,
                    "event": event_name or "smrtAgent Call Ended",
                    "call_sid": call_sid,
                    "slack_status": "deduped",
                }
            ), 200

    slack_title = "SmartAgent just completed a call"
    text_lines = [slack_title]
    if call_sid:
        text_lines.append(f"callid: {call_sid}")
    if follow_up_number_display:
        text_lines.append(f"Lead Number: {follow_up_number_display}")
    if summary:
        text_lines.append(f"Summary: {summary}")

    blocks = [{"type": "section", "text": {"type": "mrkdwn", "text": f"*{slack_title}*"}}]
    detail_lines = []
    if call_sid:
        detail_lines.append(f"*callid:* {call_sid}")
    if follow_up_number_display:
        detail_lines.append(f"*Lead Number:* {follow_up_number_display}")
    if summary:
        detail_lines.append(f"*Summary:* {summary}")
    if detail_lines:
        blocks.append({"type": "section", "text": {"type": "mrkdwn", "text": "\n".join(detail_lines)[:2900]}})

    automation_settings = get_automation_settings(db)
    if not automation_settings.get("smrtagent_slack_enabled"):
        processing_status = "slack_disabled"
        error_text = ""
    else:
        try:
            send_slack_notification(db, "\n".join(text_lines), blocks=blocks, channel="#acquisitions")
            processing_status = "slack_sent"
            error_text = ""
        except Exception as exc:
            processing_status = "slack_error"
            error_text = str(exc)

    log_smrtphone_webhook_event(
        db,
        "agent_call_ended",
        payload,
        processing_status=processing_status,
        sms_id=call_sid,
        from_number=from_number,
        to_number=to_number,
        error_text=error_text,
    )
    db.commit()
    return jsonify(
        {
            "ok": True,
            "event": event_name or "smrtAgent Call Ended",
            "call_sid": call_sid,
            "slack_status": processing_status,
        }
    ), 200


@app.route("/api/notifications/sms-unread", methods=["GET"])
def unread_sms_notifications():
    return unread_notifications()


@app.route("/api/notifications/unread", methods=["GET"])
def unread_notifications():
    ensure_db()
    db = get_db()
    rows = db.execute(
        """
        SELECT id,
               property_id,
               person_id,
               channel,
               direction,
               from_number,
               to_number,
               status,
               body,
               sent_at,
               opened_at,
               open_count
        FROM communications
        WHERE COALESCE(is_read, 1) = 0
          AND (
              lower(direction) = 'inbound'
              OR (
                  upper(channel) = 'EMAIL'
                  AND lower(direction) = 'outbound'
                  AND lower(COALESCE(status, '')) = 'opened'
              )
          )
        ORDER BY COALESCE(opened_at, sent_at) DESC, id DESC
        LIMIT 50
        """
    ).fetchall()
    items = []
    for r in rows:
        item = dict(r)
        if str(item.get("channel", "")).upper() == "SMS":
            inbound_from = (item.get("from_number") or "").strip()
            norm = normalize_phone(inbound_from)
            linked_person_id = item.get("person_id")
            linked_property_id = item.get("property_id")
            if norm:
                outbound = db.execute(
                    """
                    SELECT property_id, person_id
                    FROM communications
                    WHERE upper(channel) = 'SMS'
                      AND lower(direction) = 'outbound'
                    ORDER BY
                      CASE
                        WHEN replace(replace(replace(replace(replace(COALESCE(to_number,''),'+',''),'(',''),')',''),'-',''),' ','') LIKE ? THEN 0
                        ELSE 1
                      END,
                      sent_at DESC,
                      id DESC
                    LIMIT 1
                    """,
                    (f"%{norm}%",),
                ).fetchone()
                if outbound:
                    linked_property_id = outbound["property_id"] or linked_property_id
                    linked_person_id = outbound["person_id"] or linked_person_id
                if not linked_person_id:
                    linked_person_id = find_person_id_by_phone(db, inbound_from)
            item["link_person_id"] = linked_person_id
            item["link_property_id"] = linked_property_id
            if linked_person_id:
                p = db.execute(
                    "SELECT first_name, last_name FROM people WHERE id = ?",
                    (linked_person_id,),
                ).fetchone()
                if p:
                    item["link_person_name"] = f"{p['first_name']} {p['last_name']}".strip()
        elif str(item.get("channel", "")).upper() == "EMAIL":
            linked_person_id = item.get("person_id")
            linked_property_id = item.get("property_id")
            if str(item.get("direction", "")).lower() == "outbound" and str(item.get("status", "")).lower() == "opened":
                item["sent_at"] = item.get("opened_at") or item.get("sent_at")
            item["link_person_id"] = linked_person_id
            item["link_property_id"] = linked_property_id
            if linked_person_id:
                p = db.execute(
                    "SELECT first_name, last_name FROM people WHERE id = ?",
                    (linked_person_id,),
                ).fetchone()
                if p:
                    item["link_person_name"] = f"{p['first_name']} {p['last_name']}".strip()
        items.append(item)
    return jsonify({"count": len(items), "items": items})


def _mail_order_person_ids(order_row):
    ids = set()
    if order_row and order_row["person_id"]:
        ids.add(int(order_row["person_id"]))
    try:
        req = json.loads(order_row["request_json"] or "{}") if order_row else {}
    except Exception:
        req = {}
    contacts = req.get("contacts") if isinstance(req, dict) else []
    if isinstance(contacts, list):
        for c in contacts:
            if not isinstance(c, dict):
                continue
            meta = c.get("meta_data") if isinstance(c.get("meta_data"), dict) else {}
            pid = meta.get("person_id")
            if str(pid).isdigit():
                ids.add(int(pid))
    return sorted(ids)


def _openletterconnect_safe_header_map(req):
    safe_keys = {
        "Content-Type",
        "User-Agent",
        "X-Forwarded-For",
        "X-Forwarded-Proto",
        "X-Forwarded-Host",
        "X-Real-Ip",
    }
    out = {}
    for key in safe_keys:
        value = (req.headers.get(key) or "").strip()
        if value:
            out[key] = value
    return out


def _openletterconnect_payload_hash(payload):
    try:
        blob = json.dumps(payload or {}, sort_keys=True, separators=(",", ":"), default=str)
    except Exception:
        blob = str(payload or "")
    return hashlib.sha256(blob.encode("utf-8")).hexdigest()


def _parse_openletterconnect_event_time(value):
    dt = parse_flexible_datetime(value)
    if dt is not None:
        return format_db_time(dt)
    text = str(value or "").strip()
    if not text:
        return ""
    cleaned = re.sub(r"\s+[A-Z]{2,4}$", "", text).strip()
    for fmt in ("%m/%d/%Y %I:%M%p", "%m/%d/%Y %I:%M %p"):
        try:
            parsed = datetime.strptime(cleaned, fmt).replace(tzinfo=EST_TZ)
            return format_db_time(parsed.astimezone(timezone.utc).replace(tzinfo=None))
        except ValueError:
            continue
    return ""


def _normalize_openletterconnect_status(raw_status, event_type=""):
    raw_text = str(raw_status or "").strip()
    event_text = str(event_type or "").strip().lower()
    if "qr_code_scanned" in event_text:
        return "QR Scanned"
    lower = raw_text.lower()
    if not lower:
        return "Pending"
    if "delivered" in lower:
        return "Delivered"
    if "in transit" in lower or "re-routed" in lower or "rerouted" in lower:
        return "In Transit"
    if "returned" in lower or "failed" in lower or "bad address" in lower or "undeliverable" in lower or "canceled" in lower:
        return "Bad Address"
    if "processing" in lower or "not mailed" in lower or "pending" in lower or "created" in lower or "submitted" in lower or "queued" in lower:
        return "Pending"
    if "mailed" in lower:
        return "Mailed"
    return raw_text.title()


def _openletterconnect_event_status_update(display_status):
    normalized = str(display_status or "").strip().lower()
    if normalized == "qr scanned":
        return ""
    return str(display_status or "").strip()


def _openletterconnect_status_label(value):
    return str(value or "").strip().lower()


def _openletterconnect_status_changed(previous_status, new_status):
    previous_label = _openletterconnect_status_label(_normalize_openletterconnect_status(previous_status))
    new_label = _openletterconnect_status_label(new_status)
    return bool(new_label) and previous_label != new_label


def _openletterconnect_timestamp_column_for_status(status_label):
    normalized = _openletterconnect_status_label(status_label)
    return {
        "mailed": "mailed_at",
        "in transit": "in_transit_at",
        "delivered": "delivered_at",
        "bad address": "bad_address_at",
        "qr scanned": "qr_scanned_at",
    }.get(normalized, "")


def _openletterconnect_local_day_key(value):
    dt = parse_db_time(value)
    if not isinstance(dt, datetime):
        return ""
    if dt.tzinfo is None:
        dt = dt.replace(tzinfo=EST_TZ)
    else:
        dt = dt.astimezone(EST_TZ)
    return dt.strftime("%Y-%m-%d")


def _should_emit_reisift_mail_status(status_label):
    return _openletterconnect_status_label(status_label) in {"mailed", "delivered", "bad address"}


def _property_has_mail_status_on_day(db, property_id, status_label, event_at, exclude_mail_order_id=0):
    try:
        property_id_int = int(property_id or 0)
    except (TypeError, ValueError):
        property_id_int = 0
    try:
        exclude_id_int = int(exclude_mail_order_id or 0)
    except (TypeError, ValueError):
        exclude_id_int = 0
    if property_id_int <= 0:
        return False
    timestamp_col = _openletterconnect_timestamp_column_for_status(status_label)
    if not timestamp_col:
        return False
    target_day = _openletterconnect_local_day_key(event_at)
    if not target_day:
        return False
    rows = db.execute(
        f"""
        SELECT id, {timestamp_col} AS status_at
        FROM mail_orders
        WHERE property_id = ? AND {timestamp_col} IS NOT NULL
        """,
        (property_id_int,),
    ).fetchall()
    for row in rows:
        try:
            row_id = int(row["id"] or 0)
        except (TypeError, ValueError):
            row_id = 0
        if exclude_id_int > 0 and row_id == exclude_id_int:
            continue
        if _openletterconnect_local_day_key(row["status_at"]) == target_day:
            return True
    return False


def _openletterconnect_build_note_text(record):
    lines = [f"OpenLetterConnect: {record.get('display_status') or 'Update'}"]
    contexts = record.get("mail_contexts") if isinstance(record.get("mail_contexts"), list) else []
    primary_context = contexts[0] if contexts and isinstance(contexts[0], dict) else {}
    if primary_context.get("property_address"):
        lines.append(f"Property: {primary_context.get('property_address')}")
    if primary_context.get("mailing_address"):
        lines.append(f"Mailing Address: {primary_context.get('mailing_address')}")
    if primary_context.get("person_name"):
        lines.append(f"Matched Person: {primary_context.get('person_name')}")
    if record.get("event_type"):
        lines.append(f"Event: {record['event_type']}")
    if record.get("order_id"):
        lines.append(f"Order ID: {record['order_id']}")
    if record.get("order_item_id"):
        lines.append(f"Mail Piece ID: {record['order_item_id']}")
    if record.get("contact_name"):
        lines.append(f"Contact: {record['contact_name']}")
    if record.get("event_at"):
        lines.append(f"At: {record['event_at']}")
    if record.get("scan_count"):
        lines.append(f"Scan Count: {record['scan_count']}")
    utm_details = record.get("utm_details") if isinstance(record.get("utm_details"), dict) else {}
    if utm_details:
        if utm_details.get("utm_source"):
            lines.append(f"UTM Source: {utm_details.get('utm_source')}")
        if utm_details.get("utm_campaign"):
            lines.append(f"UTM Campaign: {utm_details.get('utm_campaign')}")
        if utm_details.get("utm_property_address"):
            lines.append(f"UTM Property Address: {utm_details.get('utm_property_address')}")
    return "\n".join(lines)


def _openletterconnect_build_reisift_note_text(record):
    lines = [f"OpenLetterConnect: {record.get('display_status') or 'Update'}"]
