def _openletterconnect_property_link(db, property_id):
    try:
        property_id_int = int(property_id or 0)
    except (TypeError, ValueError):
        property_id_int = 0
    if property_id_int <= 0:
        return ""
    base_url = get_public_app_base_url(db)
    if not base_url:
        return ""
    return f"{base_url.rstrip('/')}/property/{property_id_int}"


def _openletterconnect_row_property_address(db, mail_order_row, record):
    property_id = int(mail_order_row["property_id"] or 0) if mail_order_row and mail_order_row["property_id"] else 0
    if property_id:
        from_property = _property_address_string(db, property_id)
        if from_property:
            return from_property
    if isinstance(record.get("utm_details"), dict):
        from_utm = str(record["utm_details"].get("utm_property_address") or "").strip()
        if from_utm:
            return from_utm
    request_payload = {}
    try:
        request_payload = json.loads(mail_order_row["request_json"] or "{}") if mail_order_row else {}
    except Exception:
        request_payload = {}
    property_block = request_payload.get("property") if isinstance(request_payload, dict) and isinstance(request_payload.get("property"), dict) else {}
    if property_block:
        formatted = format_property_address_line(
            property_block.get("street"),
            property_block.get("city"),
            property_block.get("state"),
            property_block.get("postal_code") or property_block.get("zip"),
        )
        if formatted:
            return formatted
    return ""


def _openletterconnect_address_from_contact(contact):
    contact = contact if isinstance(contact, dict) else {}
    return format_property_address_line(
        contact.get("address1") or contact.get("street"),
        contact.get("city"),
        contact.get("state"),
        contact.get("zip") or contact.get("postal_code"),
    )


def _openletterconnect_property_from_contact(contact):
    contact = contact if isinstance(contact, dict) else {}
    property_address = contact.get("propertyAddress")
    if isinstance(property_address, dict):
        return format_property_address_line(
            property_address.get("address") or property_address.get("street"),
            property_address.get("city"),
            property_address.get("state"),
            property_address.get("zip") or property_address.get("postal_code"),
        )
    return format_property_address_line(
        property_address,
        contact.get("propertyCity"),
        contact.get("propertyState"),
        contact.get("propertyZip") or contact.get("propertyPostalCode"),
    )


def _openletterconnect_contact_name_from_contact(contact):
    contact = contact if isinstance(contact, dict) else {}
    return " ".join(
        [
            str(contact.get("firstName") or contact.get("first_name") or "").strip(),
            str(contact.get("lastName") or contact.get("last_name") or "").strip(),
        ]
    ).strip()


def _openletterconnect_request_contacts(mail_order_row):
    try:
        request_payload = json.loads(mail_order_row["request_json"] or "{}") if mail_order_row else {}
    except Exception:
        request_payload = {}
    contacts = request_payload.get("contacts") if isinstance(request_payload, dict) else []
    return contacts if isinstance(contacts, list) else []


def _openletterconnect_match_request_contact(mail_order_row, record):
    contacts = [c for c in _openletterconnect_request_contacts(mail_order_row) if isinstance(c, dict)]
    if not contacts:
        return {}
    if len(contacts) == 1:
        return contacts[0]

    row_person_id = str(mail_order_row["person_id"] or "").strip() if mail_order_row and mail_order_row["person_id"] else ""
    if row_person_id:
        for contact in contacts:
            meta = contact.get("meta_data") if isinstance(contact.get("meta_data"), dict) else {}
            if str(meta.get("person_id") or "").strip() == row_person_id:
                return contact

    record_contact_name = re.sub(r"\s+", " ", str(record.get("contact_name") or "").strip()).lower()
    if record_contact_name:
        for contact in contacts:
            if _openletterconnect_contact_name_from_contact(contact).lower() == record_contact_name:
                return contact

    return {}


def _openletterconnect_resolve_mail_context(db, mail_order_row, record):
    contact = _openletterconnect_match_request_contact(mail_order_row, record)
    meta = contact.get("meta_data") if isinstance(contact.get("meta_data"), dict) else {}
    property_id = int(mail_order_row["property_id"] or 0) if mail_order_row and mail_order_row["property_id"] else 0
    person_id = int(mail_order_row["person_id"] or 0) if mail_order_row and mail_order_row["person_id"] else 0
    if not person_id and str(meta.get("person_id") or "").isdigit():
        person_id = int(meta.get("person_id"))

    person_name = ""
    if person_id:
        person = db.execute("SELECT first_name, last_name FROM people WHERE id = ?", (person_id,)).fetchone()
        if person:
            person_name = " ".join([str(person["first_name"] or "").strip(), str(person["last_name"] or "").strip()]).strip()
    if not person_name:
        person_name = _openletterconnect_contact_name_from_contact(contact)

    property_address = _openletterconnect_row_property_address(db, mail_order_row, record)
    if not property_address:
        property_address = _openletterconnect_property_from_contact(contact)

    mailing_address = _openletterconnect_address_from_contact(contact)
    context = {
        "mail_order_id": int(mail_order_row["id"]) if mail_order_row and mail_order_row["id"] else None,
        "property_id": property_id or None,
        "property_address": property_address,
        "person_id": person_id or None,
        "person_name": person_name,
        "mailing_address": mailing_address,
        "person_address_id": meta.get("person_address_id"),
        "address_id": meta.get("address_id"),
    }
    return {k: v for k, v in context.items() if v not in ("", None)}


def _notify_openletterconnect_bad_address(db, rows, record, route):
    display_status = str(record.get("display_status") or "").strip().lower()
    if display_status != "bad address":
        return []
    emitted = []
    seen = set()
    for row in rows or []:
        property_id = int(row["property_id"] or 0) if row["property_id"] else 0
        order_id = str(record.get("order_id") or row["external_order_id"] or "").strip()
        order_item_id = str(record.get("order_item_id") or "").strip()
        dedupe_key = (property_id, order_id, order_item_id)
        if dedupe_key in seen:
            continue
        seen.add(dedupe_key)
        property_address = _openletterconnect_row_property_address(db, row, record)
        property_link = _openletterconnect_property_link(db, property_id)
        contact_name = str(record.get("contact_name") or "").strip()
        if not contact_name and row["person_id"]:
            person = db.execute("SELECT first_name, last_name FROM people WHERE id = ?", (int(row["person_id"]),)).fetchone()
            if person:
                contact_name = " ".join([str(person["first_name"] or "").strip(), str(person["last_name"] or "").strip()]).strip()
        alert_subject = property_address or f"order {order_id or 'unknown'}"
        if order_id:
            error_message = f"Bad Address: {alert_subject} (order {order_id})"
        else:
            error_message = f"Bad Address: {alert_subject}"
        detail_lines = []
        if property_address:
            detail_lines.append(f"Property: {property_address}")
        if property_link:
            detail_lines.append(f"DeepSift: {property_link}")
        if contact_name:
            detail_lines.append(f"Contact: {contact_name}")
        if order_id:
            detail_lines.append(f"Order ID: {order_id}")
        if order_item_id:
            detail_lines.append(f"Mail Piece ID: {order_item_id}")
        raw_status = str(record.get("raw_status") or "").strip()
        if raw_status:
            detail_lines.append(f"Provider Status: {raw_status}")
        event_type = str(record.get("event_type") or "").strip()
        if event_type:
            detail_lines.append(f"Event: {event_type}")
        event_at = str(record.get("event_at") or "").strip()
        if event_at:
            detail_lines.append(f"At: {event_at}")
        detail_text = "\n".join(detail_lines)
        emitted.append(
            emit_provider_alert(
                f"{PROVIDER_ALERT_SOURCE_PREFIX}openletterconnect",
                error_message,
                details=detail_text,
                route=route,
                status_code=422,
                db=db,
            )
        )
    return emitted


def _extract_openletterconnect_contact_name(contact_obj):
    if not isinstance(contact_obj, dict):
        return ""
    first = str(contact_obj.get("contact_first") or contact_obj.get("firstName") or contact_obj.get("first_name") or "").strip()
    last = str(contact_obj.get("contact_last") or contact_obj.get("lastName") or contact_obj.get("last_name") or "").strip()
    company = str(contact_obj.get("contact_company") or contact_obj.get("companyName") or "").strip()
    full_name = " ".join([part for part in [first, last] if part]).strip()
    return full_name or company


def _extract_openletterconnect_events(payload):
    payload = payload if isinstance(payload, dict) else {}
    event_type = str(payload.get("event") or payload.get("type") or payload.get("event_type") or "").strip()
    data = payload.get("data")
    payload_hash = _openletterconnect_payload_hash(payload)
    default_at = format_db_time(datetime.utcnow())
    events = []

    def build_record(index, order_id="", order_item_id="", raw_status="", event_at="", contact_name="", scan_count="", utm_details=None):
        display_status = _normalize_openletterconnect_status(raw_status, event_type=event_type)
        return {
            "event_key": f"{payload_hash}:{index}",
            "event_type": event_type or "openletterconnect.event",
            "order_id": str(order_id or "").strip(),
            "order_item_id": str(order_item_id or "").strip(),
            "raw_status": str(raw_status or "").strip(),
            "display_status": display_status,
            "status_update": _openletterconnect_event_status_update(display_status),
            "event_at": event_at or default_at,
            "contact_name": contact_name,
            "scan_count": str(scan_count or "").strip(),
            "utm_details": utm_details if isinstance(utm_details, dict) else {},
        }

    event_type_lower = event_type.lower()
    if event_type_lower in {"order_items.updated", "order_item.updated"}:
        items = data if isinstance(data, list) else ([data] if isinstance(data, dict) else [])
        for idx, item in enumerate(items):
            if not isinstance(item, dict):
                continue
            order_block = item.get("order") if isinstance(item.get("order"), dict) else {}
            order_item_block = item.get("orderItem") if isinstance(item.get("orderItem"), dict) else {}
            if not order_item_block and isinstance(item.get("order_item"), dict):
                order_item_block = item.get("order_item")
            contact_block = item.get("contact") if isinstance(item.get("contact"), dict) else {}
            order_id = (
                order_block.get("id")
                or item.get("orderId")
                or item.get("order_id")
                or order_item_block.get("orderId")
                or order_item_block.get("order_id")
                or ""
            )
            order_item_id = (
                order_item_block.get("id")
                or item.get("orderItemId")
                or item.get("order_item_id")
                or item.get("id")
                or ""
            )
            raw_status = order_item_block.get("status") or item.get("status") or order_block.get("status") or ""
            event_at = _parse_openletterconnect_event_time(
                order_item_block.get("updated_at")
                or order_item_block.get("updatedAt")
                or item.get("updated_at")
                or item.get("updatedAt")
                or order_block.get("updated_at")
                or order_block.get("updatedAt")
                or payload.get("updated_at")
            )
            events.append(
                build_record(
                    idx,
                    order_id=order_id,
                    order_item_id=order_item_id,
                    raw_status=raw_status,
                    event_at=event_at,
                    contact_name=_extract_openletterconnect_contact_name(contact_block),
                )
            )
    elif "qr_code_scanned" in event_type_lower:
        data_dict = data if isinstance(data, dict) else {}
        order_details = data_dict.get("order_details") if isinstance(data_dict.get("order_details"), dict) else {}
        order_item_details = data_dict.get("order_item_details") if isinstance(data_dict.get("order_item_details"), dict) else {}
        events.append(
            build_record(
                0,
                order_id=order_details.get("order_id") or data_dict.get("order_id") or payload.get("order_id") or "",
                order_item_id=order_item_details.get("order_item_id") or data_dict.get("order_item_id") or payload.get("order_item_id") or "",
                raw_status="QR Scanned",
                event_at=_parse_openletterconnect_event_time(data_dict.get("scan_timestamp") or payload.get("created_at")),
                contact_name=_extract_openletterconnect_contact_name(data_dict.get("scanned_by")),
                scan_count=data_dict.get("number_of_scans") or "",
                utm_details=data_dict.get("utm_details"),
            )
        )
    else:
        data_dict = data if isinstance(data, dict) else payload
        events.append(
            build_record(
                0,
                order_id=data_dict.get("id") or data_dict.get("order_id") or data_dict.get("orderId") or payload.get("order_id") or "",
                raw_status=data_dict.get("status") or data_dict.get("order_status") or data_dict.get("state") or payload.get("status") or "",
                event_at=_parse_openletterconnect_event_time(
                    data_dict.get("updated_at")
                    or data_dict.get("updatedAt")
                    or data_dict.get("created_at")
                    or data_dict.get("createdAt")
                    or payload.get("updated_at")
                    or payload.get("created_at")
                ),
            )
        )
    return [event for event in events if event.get("order_id")]


def _apply_openletterconnect_event_to_mail_order(db, mail_order_row, record, payload):
    event_at = str(record.get("event_at") or format_db_time(datetime.utcnow())).strip()
    status_update = str(record.get("status_update") or "").strip()
    previous_status = str(mail_order_row["status"] or "").strip()
    status_changed = _openletterconnect_status_changed(previous_status, record.get("display_status"))
    is_qr_scan = str(record.get("display_status") or "").strip().lower() == "qr scanned"
    update_bits = [
        "response_json = ?",
        "last_event_type = ?",
    ]
    params = [
        json.dumps(payload or {}, default=str),
        str(record.get("event_type") or "").strip(),
    ]
    if status_update and status_changed:
        update_bits.extend(["status = ?", "status_updated_at = ?"])
        params.extend([status_update, event_at])
        if status_update == "Mailed":
            update_bits.append("mailed_at = COALESCE(mailed_at, ?)")
            params.append(event_at)
        if status_update == "In Transit":
            update_bits.append("in_transit_at = COALESCE(in_transit_at, ?)")
            params.append(event_at)
        elif status_update == "Delivered":
            update_bits.append("delivered_at = COALESCE(delivered_at, ?)")
            params.append(event_at)
        elif status_update == "Bad Address":
            update_bits.append("bad_address_at = COALESCE(bad_address_at, ?)")
            params.append(event_at)
    if is_qr_scan:
        update_bits.append("qr_scanned_at = ?")
        params.append(event_at)
    order_item_id = str(record.get("order_item_id") or "").strip()
    if order_item_id and not str(mail_order_row["external_order_item_id"] or "").strip():
        update_bits.append("external_order_item_id = ?")
        params.append(order_item_id)
    params.append(int(mail_order_row["id"]))
    db.execute(f"UPDATE mail_orders SET {', '.join(update_bits)} WHERE id = ?", tuple(params))
    if status_update and str(mail_order_row["external_order_id"] or "").strip():
        db.execute(
            """
            UPDATE communications
            SET status = COALESCE(NULLIF(?, ''), status)
            WHERE external_id = ? AND upper(COALESCE(channel, '')) = 'MAIL'
            """,
            (status_update, str(mail_order_row["external_order_id"] or "").strip()),
        )
    return {
        "status_changed": status_changed,
        "is_qr_scan": is_qr_scan,
        "previous_status": previous_status,
        "status_update": status_update,
        "event_at": event_at,
    }


def _process_openletterconnect_event_record(db, record, payload):
    order_id = str(record.get("order_id") or "").strip()
    if not order_id:
        return {"updated_orders": 0, "ignored": True, "reason": "missing_order_id"}
    order_item_id = str(record.get("order_item_id") or "").strip()
    rows = _find_mail_orders_for_openletterconnect_order(db, order_id, order_item_id=order_item_id)
    if not rows:
        return {"updated_orders": 0, "ignored": True, "reason": "unknown_order_id"}

    unique_person_ids = set()
    reisift_targets = {}
    should_emit_local_history = False
    should_emit_bad_address_alert = False
    display_status = str(record.get("display_status") or "").strip()
    mail_contexts = []
    seen_contexts = set()
    for row in rows:
        apply_result = _apply_openletterconnect_event_to_mail_order(db, row, record, payload)
        mail_context = _openletterconnect_resolve_mail_context(db, row, record)
        context_key = (
            mail_context.get("mail_order_id"),
            mail_context.get("property_id"),
            mail_context.get("person_id"),
            mail_context.get("mailing_address"),
        )
        if mail_context and context_key not in seen_contexts:
            seen_contexts.add(context_key)
            mail_contexts.append(mail_context)
        for pid in _mail_order_person_ids(row):
            unique_person_ids.add(int(pid))
        property_id = int(row["property_id"] or 0) if row["property_id"] else 0
        if property_id:
            property_uuid = _get_local_property_uuid(db, property_id)
            if property_uuid:
                if apply_result["is_qr_scan"]:
                    reisift_targets[property_uuid] = property_id
                elif (
                    apply_result["status_changed"]
                    and _should_emit_reisift_mail_status(display_status)
                    and not _property_has_mail_status_on_day(
                        db,
                        property_id,
                        display_status,
                        apply_result["event_at"],
                        exclude_mail_order_id=row["id"],
                    )
                ):
                    reisift_targets[property_uuid] = property_id
        emit_history = bool(apply_result["status_changed"] or apply_result["is_qr_scan"] or not str(record.get("status_update") or "").strip())
        if emit_history:
            should_emit_local_history = True
            db.execute(
                """
                INSERT INTO activity_log (property_id, person_id, activity_type, outcome, note)
                VALUES (?, ?, 'Direct Mail Webhook', ?, ?)
                """,
                (
                    row["property_id"],
                    (row["person_id"] or (next(iter(unique_person_ids)) if unique_person_ids else None)),
                    display_status or "Update",
                    json.dumps({"record": record, "payload": payload, "mail_context": mail_context}, default=str),
                ),
            )
        if display_status.lower() == "bad address" and apply_result["status_changed"]:
            should_emit_bad_address_alert = True

    if mail_contexts:
        record["mail_contexts"] = mail_contexts
    note_text = _openletterconnect_build_note_text(record)
    if should_emit_local_history:
        for pid in sorted(unique_person_ids):
            add_person_note(
                db,
                pid,
                "OpenLetterConnect Webhook",
                note_text,
                {"record": record, "payload": payload},
            )
    if should_emit_bad_address_alert:
        _notify_openletterconnect_bad_address(db, rows, record, "/webhooks/openletterconnect/events")

    tag_plan = build_reisift_mail_status_tag_plan(display_status, when=parse_db_time(record.get("event_at")))
    if reisift_targets:
        reisift_note_text = _openletterconnect_build_reisift_note_text(record)
        try:
            token = reisift_get_access_token()
            for property_uuid in sorted(reisift_targets):
                reisift_append_property_note(token, property_uuid, reisift_note_text)
                if tag_plan.get("add") or tag_plan.get("remove_prefixes"):
                    reisift_sync_property_tags(
                        token,
                        property_uuid,
                        tags_to_add=tag_plan.get("add"),
                        remove_prefixes=tag_plan.get("remove_prefixes"),
                    )
        except Exception as exc:
            log_app_error(
                db,
                source="openletterconnect_reisift_sync",
                error_message=str(exc),
                details=traceback.format_exc(),
                route="/webhooks/openletterconnect/events",
                status_code=500,
            )
    return {"updated_orders": len(rows), "ignored": False, "reason": ""}


def _summarize_property_mail_orders(db, property_id):
    rows = db.execute(
        """
        SELECT id, mode, external_order_id, status, status_updated_at, mailed_at, in_transit_at,
               delivered_at, bad_address_at, qr_scanned_at, created_at, response_json
        FROM mail_orders
        WHERE property_id = ?
        ORDER BY COALESCE(status_updated_at, created_at) DESC, id DESC
        LIMIT 10
        """,
        (property_id,),
    ).fetchall()
    items = []
    for row in rows:
        response_payload = {}
        raw_response = str(row["response_json"] or "").strip()
        if raw_response:
            try:
                response_payload = json.loads(raw_response)
            except Exception:
                response_payload = {}
        order_fields = extract_openletterconnect_order_fields(response_payload)
        status_label = _normalize_openletterconnect_status((row["status"] or order_fields["status"] or "Pending"))
        status_at = (
            row["bad_address_at"]
            if status_label == "Bad Address" and row["bad_address_at"]
            else row["delivered_at"]
            if status_label == "Delivered" and row["delivered_at"]
            else row["in_transit_at"]
            if status_label == "In Transit" and row["in_transit_at"]
            else row["mailed_at"]
            if status_label == "Mailed" and row["mailed_at"]
            else row["status_updated_at"]
            or row["created_at"]
        )
        items.append(
            {
                "id": int(row["id"]),
                "mode": str(row["mode"] or "").strip(),
                "external_order_id": str(row["external_order_id"] or order_fields["order_id"] or "").strip(),
                "status": status_label,
                "status_at": str(status_at or "").strip(),
                "mailed_at": str(row["mailed_at"] or "").strip(),
                "qr_scanned_at": str(row["qr_scanned_at"] or "").strip(),
            }
        )
    return {
        "has_mail": bool(items),
        "latest": items[0] if items else None,
        "items": items,
        "count": len(items),
    }


def _summarize_property_skiptrace_runs(db, property_id):
    rows = db.execute(
        """
        SELECT sr.id, sr.provider, sr.created_at, sr.summary_json, sr.person_id, p.first_name, p.last_name
        FROM skiptrace_runs sr
        LEFT JOIN people p ON p.id = sr.person_id
        WHERE sr.property_id = ?
        ORDER BY sr.id DESC
        LIMIT 10
        """,
        (property_id,),
    ).fetchall()
    items = []
    for row in rows:
        summary = parse_json_object(row["summary_json"] or "{}", default={})
        items.append(
            {
                "id": int(row["id"]),
                "provider": str(row["provider"] or "").strip() or "Skip trace",
                "created_at": str(row["created_at"] or "").strip(),
                "person_name": " ".join([str(row["first_name"] or "").strip(), str(row["last_name"] or "").strip()]).strip(),
                "phones_added": int(summary.get("phones_added") or 0),
                "emails_added": int(summary.get("emails_added") or 0),
                "addresses_added": int(summary.get("addresses_added") or 0),
                "relatives_added": int(summary.get("relatives_added") or 0),
            }
        )
    return {
        "has_runs": bool(items),
        "latest": items[0] if items else None,
        "items": items,
        "count": len(items),
    }


@app.route("/webhooks/openletterconnect/events", methods=["POST"])
def openletterconnect_events_webhook():
    ensure_db()
    db = get_db()
    payload = request.get_json(silent=True) or request.form.to_dict() or {}
    payload = payload if isinstance(payload, dict) else {}
    safe_headers = _openletterconnect_safe_header_map(request)
    safe_payload = _redact_clever_log_value("root", payload)
    event_type = str(payload.get("event") or payload.get("type") or payload.get("event_type") or "").strip()
    payload_hash = _openletterconnect_payload_hash(payload)

    existing = db.execute(
        """
        SELECT id, processing_status
        FROM openletterconnect_webhook_events
        WHERE event_key = ?
        ORDER BY id DESC
        LIMIT 1
        """,
        (payload_hash,),
    ).fetchone()
    if existing and str(existing["processing_status"] or "").strip().lower() == "processed":
        return jsonify({"ok": True, "duplicate": True, "event_key": payload_hash}), 200

    records = _extract_openletterconnect_events(payload)
    first_record = records[0] if records else {}
    log_cur = db.execute(
        """
        INSERT INTO openletterconnect_webhook_events
        (event_key, event_type, external_order_id, external_order_item_id, verification_status, processing_status, error_text, payload_json, headers_json)
        VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)
        """,
        (
            payload_hash,
            event_type,
            str(first_record.get("order_id") or "").strip(),
            str(first_record.get("order_item_id") or "").strip(),
            "unverified",
            "received",
            "",
            json.dumps(safe_payload or {}, default=str),
            json.dumps(safe_headers or {}, default=str),
        ),
    )
    log_id = int(log_cur.lastrowid or 0)

    expected_secret = get_openletterconnect_webhook_secret(db)
    provided_secret = str(payload.get("token") or "").strip()
    verification_status = "verified"
    if expected_secret:
        if not provided_secret or not hmac.compare_digest(provided_secret, expected_secret):
            verification_status = "unauthorized"
        else:
            verification_status = "verified"
    else:
        verification_status = "unverified"

    if verification_status == "unauthorized":
        db.execute(
            """
            UPDATE openletterconnect_webhook_events
            SET verification_status = ?, processing_status = ?, error_text = ?
            WHERE id = ?
            """,
            ("unauthorized", "unauthorized", "Webhook secret mismatch", log_id),
        )
        db.commit()
        return jsonify({"error": "Invalid webhook secret"}), 401

    if not records:
        db.execute(
            """
            UPDATE openletterconnect_webhook_events
            SET verification_status = ?, processing_status = ?, error_text = ?
            WHERE id = ?
            """,
            (verification_status, "ignored", "No recognizable OpenLetterConnect order id found in payload", log_id),
        )
        db.commit()
        return jsonify({"ok": True, "ignored": True, "reason": "missing_order_id"}), 200

    try:
        processed_orders = 0
        ignored_records = 0
        ignored_reasons = []
        for record in records:
            result = _process_openletterconnect_event_record(db, record, payload)
            processed_orders += int(result.get("updated_orders") or 0)
            if result.get("ignored"):
                ignored_records += 1
                if result.get("reason"):
                    ignored_reasons.append(str(result.get("reason")))
        processing_status = "processed" if processed_orders > 0 else "ignored"
        error_text = "; ".join(sorted(set(ignored_reasons)))[:500]
        db.execute(
            """
            UPDATE openletterconnect_webhook_events
            SET verification_status = ?, processing_status = ?, error_text = ?, external_order_id = ?, external_order_item_id = ?
            WHERE id = ?
            """,
            (
                verification_status,
                processing_status,
                error_text,
                str(first_record.get("order_id") or "").strip(),
                str(first_record.get("order_item_id") or "").strip(),
                log_id,
            ),
        )
        db.commit()
        return jsonify(
            {
                "ok": True,
                "event_key": payload_hash,
                "records_seen": len(records),
                "updated_orders": processed_orders,
                "ignored_records": ignored_records,
            }
        ), 200
    except Exception as exc:
        db.execute(
            """
            UPDATE openletterconnect_webhook_events
            SET verification_status = ?, processing_status = ?, error_text = ?
            WHERE id = ?
            """,
            (verification_status, "error", str(exc)[:500], log_id),
        )
        log_app_error(
            db,
            source="openletterconnect_events_webhook",
            error_message=str(exc),
            details=traceback.format_exc(),
            route="/webhooks/openletterconnect/events",
            status_code=500,
        )
        db.commit()
        return jsonify({"error": str(exc)}), 500


@app.route("/webhooks/openletterconnect/order-status", methods=["POST"])
def openletterconnect_order_status_webhook():
    ensure_db()
    db = get_db()
    payload = request.get_json(silent=True) or request.form.to_dict() or {}
    external_order_id = str(
        payload.get("id")
        or payload.get("orderId")
        or payload.get("order_id")
        or payload.get("external_order_id")
        or ""
    ).strip()
    status = str(
        payload.get("status")
        or payload.get("orderStatus")
        or payload.get("order_status")
        or payload.get("state")
        or ""
    ).strip()
    if not external_order_id:
        return jsonify({"ok": True, "ignored": True, "reason": "missing order id"}), 200
    rows = _find_mail_orders_for_openletterconnect_order(db, external_order_id)
    if not rows:
        return jsonify({"ok": True, "ignored": True, "reason": "unknown order id"}), 200

    now_txt = format_db_time(datetime.utcnow())
    note_status = status or "Update received"
    normalized_status = _normalize_openletterconnect_status(status)
    for row in rows:
        db.execute(
            "UPDATE mail_orders SET status = COALESCE(NULLIF(?, ''), status), response_json = ? WHERE id = ?",
            (status, json.dumps(payload), row["id"]),
        )
        if external_order_id:
            db.execute(
                """
                UPDATE communications
                SET status = COALESCE(NULLIF(?, ''), status)
                WHERE external_id = ? AND upper(COALESCE(channel, '')) = 'MAIL'
                """,
                (status, external_order_id),
            )
        person_ids = _mail_order_person_ids(row)
        for pid in person_ids:
            add_person_note(
                db,
                pid,
                "OpenLetterConnect Webhook",
                f"Direct mail order {external_order_id} status: {note_status} ({now_txt}).",
                payload,
            )
        db.execute(
            """
            INSERT INTO activity_log (property_id, person_id, activity_type, outcome, note)
            VALUES (?, ?, 'Direct Mail Webhook', ?, ?)
            """,
            (
                row["property_id"],
                (person_ids[0] if person_ids else row["person_id"]),
                note_status or "Status Update",
                json.dumps(payload),
            ),
        )
    synthetic_record = {
        "display_status": normalized_status,
        "raw_status": status,
        "order_id": external_order_id,
        "order_item_id": "",
        "contact_name": "",
        "event_type": "order_status_webhook",
        "event_at": now_txt,
    }
    _notify_openletterconnect_bad_address(db, rows, synthetic_record, "/webhooks/openletterconnect/order-status")
    db.commit()
    return jsonify({"ok": True, "updated_orders": len(rows)}), 200


@app.route("/webhooks/slybroadcast/status", methods=["POST"])
def slybroadcast_status_webhook():
    ensure_db()
    db = get_db()
    expected_key = get_integration_api_key(db)
    provided_key = (request.args.get("integration_key") or "").strip()
    if expected_key and provided_key and not hmac.compare_digest(provided_key, expected_key):
        return "OK", 200, {"Content-Type": "text/plain; charset=utf-8"}

    raw_line = _extract_slybroadcast_callback_line(request)
    parsed = _parse_slybroadcast_callback_line(raw_line)
    session_id = (parsed.get("session_id") or "").strip()
    if not session_id:
        return "OK", 200, {"Content-Type": "text/plain; charset=utf-8"}

    rows = db.execute(
        """
        SELECT *
        FROM communications
        WHERE external_id = ? AND upper(COALESCE(channel, '')) = 'VM_DROP'
        ORDER BY id DESC
        """,
        (session_id,),
    ).fetchall()
    if not rows:
        return "OK", 200, {"Content-Type": "text/plain; charset=utf-8"}

    status_value = (parsed.get("status") or "").strip()
    failure_reason = (parsed.get("failure_reason") or "").strip()
    normalized_status = "Delivered" if status_value.upper() in {"OK", "SENT", "DELIVERED"} else (f"Failed: {failure_reason}" if failure_reason else (status_value or "Failed"))
    payload_json = json.dumps({"raw": raw_line, "parsed": parsed})
    for row in rows:
        db.execute("UPDATE communications SET status = ? WHERE id = ?", (normalized_status, row["id"]))
        db.execute(
            """
            INSERT INTO activity_log (property_id, person_id, activity_type, outcome, note)
            VALUES (?, ?, 'Voicemail Drop Webhook', ?, ?)
            """,
            (
                row["property_id"],
                row["person_id"],
                normalized_status,
                payload_json,
            ),
        )
    db.commit()
    return "OK", 200, {"Content-Type": "text/plain; charset=utf-8"}


