@app.route("/api/integrations/agents/rerun-today", methods=["POST"])
def integrations_agents_rerun_today_api():
    ensure_db()
    db = get_db()
    if not integration_auth_ok(db, request):
        return jsonify({"ok": False, "error": "Unauthorized"}), 401
    lock_acquired = AGENT_PIPELINE_LOCK.acquire(timeout=20)
    if not lock_acquired:
        return jsonify({"ok": False, "error": "agent_pipeline_busy"}), 409
    errors = []

    try:
        def _safe_run(step_name, fn):
            try:
                return fn()
            except Exception as exc:
                err = {"step": step_name, "error": str(exc)}
                errors.append(err)
                log_app_error(
                    db,
                    source="integrations_agents_rerun_today_api",
                    error_message=str(exc),
                    details=traceback.format_exc(),
                    route=f"/api/integrations/agents/rerun-today:{step_name}",
                    status_code=500,
                )
                return {"error": str(exc)}

        # Agent 1: force rerun calls in the lead-watch window (yesterday 12:00 AM ET onward).
        call_rerun = _safe_run("call_rerun", lambda: rerun_call_analysis_for_today(db, limit=800))
        db.commit()
        # Agent 1 SMS pass for the same lead-watch window.
        sms_res = _safe_run(
            "sms_analysis",
            lambda: run_sms_analysis_once(lookback_days=2, limit_threads=250, start_utc=est_yesterday_start_utc()),
        )
        # Agent 2 refresh across full touched lead set (UUID-only + local property leads).
        lead_monitor_res = _safe_run("lead_monitor", lambda: run_lead_monitor_once(db, source="rerun_today", property_id=None))
        # Agent 3 reconciliation + snapshot.
        recon = _safe_run("reconcile", lambda: run_agent3_lead_watch_reconcile(db, limit=200))
        snapshot = _safe_run("snapshot", lambda: build_today_lead_watch_snapshot(db, limit=200))
        db.commit()
        return jsonify(
            {
                "ok": len(errors) == 0,
                "call_cutoff": call_rerun.get("cutoff", ""),
                "call_rerun": call_rerun,
                "sms": sms_res,
                "lead_monitor": lead_monitor_res,
                "reconcile": recon,
                "snapshot": snapshot,
                "errors": errors,
            }
        )
    finally:
        AGENT_PIPELINE_LOCK.release()


@app.route("/api/integrations/agents/reset-associations", methods=["POST"])
def integrations_agents_reset_associations_api():
    ensure_db()
    db = get_db()
    if not integration_auth_ok(db, request):
        return jsonify({"ok": False, "error": "Unauthorized"}), 401
    payload = request.get_json(silent=True) or {}
    property_id = int(payload.get("property_id") or 0)
    person_id = int(payload.get("person_id") or 0)
    if property_id <= 0:
        return jsonify({"ok": False, "error": "property_id is required"}), 400
    rerun = bool(payload.get("rerun", True))
    counts = {}

    def _count_update(sql, params):
        cur = db.execute(sql, params)
        return int(cur.rowcount or 0)

    # Remove hard links that were collapsing many leads into Property 2 / Person 4.
    counts["communications_deleted_property"] = _count_update(
        "DELETE FROM communications WHERE property_id = ?",
        (property_id,),
    )
    counts["communications_deleted_person"] = _count_update(
        "DELETE FROM communications WHERE person_id = ?",
        (person_id,),
    )
    counts["call_jobs_property_null"] = _count_update(
        "UPDATE call_recording_jobs SET property_id = NULL WHERE property_id = ?",
        (property_id,),
    )
    counts["call_jobs_person_null"] = _count_update(
        "UPDATE call_recording_jobs SET person_id = NULL WHERE person_id = ?",
        (person_id,),
    )
    counts["signals_unlink"] = _count_update(
        """
        UPDATE agent_signals
        SET property_id = NULL, person_id = NULL, routing_status = 'new', updated_at = CURRENT_TIMESTAMP
        WHERE property_id = ? OR person_id = ?
        """,
        (property_id, person_id),
    )
    counts["thread_state_unlink"] = _count_update(
        "UPDATE sms_thread_state SET property_id = NULL, person_id = NULL, updated_at = CURRENT_TIMESTAMP WHERE property_id = ? OR person_id = ?",
        (property_id, person_id),
    )
    counts["contact_context_unlink"] = _count_update(
        """
        UPDATE external_contact_context
        SET property_id = NULL,
            person_id = NULL,
            reisift_property_uuid = NULL,
            reisift_full_address = NULL,
            reisift_property_status = NULL,
            last_reisift_lookup_at = NULL,
            source = 'agent_reset_associations',
            notes = 'Association reset by integration endpoint',
            last_seen_at = CURRENT_TIMESTAMP
        WHERE property_id = ? OR person_id = ?
        """,
        (property_id, person_id),
    )
    counts["lead_actions_deleted"] = _count_update(
        """
        DELETE FROM lead_management_actions
        WHERE property_id = ? OR person_id = ? OR dedupe_key LIKE ?
        """,
        (property_id, person_id, f"leadwatch:property:{property_id}:%"),
    )
    counts["agent3_resolutions_deleted"] = _count_update(
        """
        DELETE FROM agent3_lead_resolutions
        WHERE approved_property_id = ? OR suggested_property_id = ? OR lead_key = ?
        """,
        (property_id, property_id, f"property:{property_id}"),
    )
    counts["refresh_queue_deleted"] = _count_update(
        "DELETE FROM agent_refresh_queue WHERE property_id = ?",
        (property_id,),
    )

    result = {"ok": True, "property_id": property_id, "person_id": person_id, "counts": counts}
    if rerun:
        call_rerun = rerun_call_analysis_for_today(db, limit=1200)
        sms_res = run_sms_analysis_once(lookback_days=2, limit_threads=350, start_utc=est_yesterday_start_utc())
        lead_monitor = run_lead_monitor_once(db, source="reset_associations", property_id=None)
        reconcile = run_agent3_lead_watch_reconcile(db, limit=300)
        snapshot = build_today_lead_watch_snapshot(db, limit=250)
        result["rerun"] = {
            "call_rerun": call_rerun,
            "sms": sms_res,
            "lead_monitor": lead_monitor,
            "reconcile": reconcile,
            "snapshot_count": int(snapshot.get("count") or 0),
        }
    db.commit()
    return jsonify(result)


def _agent_trace_for_property(db, property_id, limit=20):
    try:
        n = max(1, min(200, int(limit)))
    except (TypeError, ValueError):
        n = 20
    prop = db.execute(
        """
        SELECT p.id, p.status, p.notes, p.created_at,
               a.street, a.city, a.state, a.postal_code
        FROM properties p
        LEFT JOIN addresses a ON a.id = p.property_address_id
        WHERE p.id = ?
        """,
        (property_id,),
    ).fetchone()
    if not prop:
        return None
    comms = []
    signals = []
    actions = []
    calls = []
    try:
        comm_rows = db.execute(
            """
            SELECT c.id, c.person_id, c.channel, c.direction, c.body, c.status, c.sent_at, c.created_at,
                   c.from_number, c.to_number,
                   p.first_name, p.middle_name, p.last_name
            FROM communications c
            LEFT JOIN people p ON p.id = c.person_id
            WHERE c.property_id = ?
            ORDER BY COALESCE(c.sent_at, c.created_at) DESC, c.id DESC
            LIMIT ?
            """,
            (property_id, n),
        ).fetchall()
        for r in comm_rows:
            d = dict(r)
            d["person_name"] = person_display_name(d.get("first_name"), d.get("middle_name"), d.get("last_name"))
            comms.append(d)
    except Exception:
        pass
    try:
        sig_rows = db.execute(
            """
            SELECT id, source_type, source_key, person_id, channel, intent, sentiment, confidence,
                   recommended_next_step, summary_text, routing_status, created_at, updated_at
            FROM agent_signals
            WHERE property_id = ?
            ORDER BY COALESCE(updated_at, created_at) DESC, id DESC
            LIMIT ?
            """,
            (property_id, n),
        ).fetchall()
        signals = [dict(r) for r in sig_rows]
    except Exception:
        pass
    try:
        action_rows = db.execute(
            """
            SELECT id, person_id, action_type, priority, status, reason, created_at, updated_at
            FROM lead_management_actions
            WHERE property_id = ?
            ORDER BY COALESCE(updated_at, created_at) DESC, id DESC
            LIMIT ?
            """,
            (property_id, n),
        ).fetchall()
        actions = [dict(r) for r in action_rows]
    except Exception:
        pass
    try:
        call_rows = db.execute(
            """
            SELECT id, call_sid, person_id, from_number, to_number, recording_url, fetch_status, analysis_status,
                   summary_text, created_at, updated_at
            FROM call_recording_jobs
            WHERE property_id = ?
            ORDER BY COALESCE(updated_at, created_at) DESC, id DESC
            LIMIT ?
            """,
            (property_id, n),
        ).fetchall()
        calls = [dict(r) for r in call_rows]
    except Exception:
        pass
    return {
        "property": dict(prop),
        "communications": comms,
        "signals": signals,
        "actions": actions,
        "calls": calls,
        "counts": {
            "communications": len(comms),
            "signals": len(signals),
            "actions": len(actions),
            "calls": len(calls),
        },
    }


@app.route("/api/integrations/agent-trace/search", methods=["GET"])
def integrations_agent_trace_search_api():
    ensure_db()
    db = get_db()
    if not integration_auth_ok(db, request):
        return jsonify({"ok": False, "error": "Unauthorized"}), 401
    q = (request.args.get("q") or "").strip()
    limit_raw = (request.args.get("limit") or "10").strip()
    trace_limit_raw = (request.args.get("trace_limit") or "20").strip()
    try:
        limit = max(1, min(50, int(limit_raw)))
    except ValueError:
        limit = 10
    try:
        trace_limit = max(1, min(200, int(trace_limit_raw)))
    except ValueError:
        trace_limit = 20
    if not q:
        return jsonify({"ok": False, "error": "q is required"}), 400
    like = f"%{q.lower()}%"
    rows = db.execute(
        """
        SELECT p.id
        FROM properties p
        LEFT JOIN addresses a ON a.id = p.property_address_id
        LEFT JOIN people op ON op.id = p.owner_person_id
        WHERE lower(COALESCE(a.street, '')) LIKE ?
           OR lower(COALESCE(a.city, '')) LIKE ?
           OR lower(COALESCE(a.state, '')) LIKE ?
           OR lower(COALESCE(a.postal_code, '')) LIKE ?
           OR lower(COALESCE(p.notes, '')) LIKE ?
           OR lower(COALESCE(op.first_name, '') || ' ' || COALESCE(op.last_name, '')) LIKE ?
        ORDER BY p.id DESC
        LIMIT ?
        """,
        (like, like, like, like, like, like, limit),
    ).fetchall()
    results = []
    for r in rows:
        trace = _agent_trace_for_property(db, int(r["id"]), trace_limit)
        if trace:
            results.append(trace)
    return jsonify({"ok": True, "query": q, "count": len(results), "results": results})


@app.route("/api/integrations/agent-trace/property", methods=["GET"])
def integrations_agent_trace_property_api():
    ensure_db()
    db = get_db()
    if not integration_auth_ok(db, request):
        return jsonify({"ok": False, "error": "Unauthorized"}), 401
    pid_raw = (request.args.get("property_id") or "").strip()
