@app.route("/api/webhooks/propertyleads/events", methods=["GET"])
def propertyleads_webhook_events_api():
    ensure_db()
    db = get_db()
    if not integration_auth_ok(db, request):
        return jsonify({"ok": False, "error": "Unauthorized"}), 401
    try:
        limit = max(1, min(int(request.args.get("limit") or "50"), 200))
    except Exception:
        limit = 50
    rows = db.execute(
        """
        SELECT id, event_key, payload_json, created_at
        FROM integration_events
        WHERE source = ?
        ORDER BY id DESC
        LIMIT ?
        """,
        (PROPERTYLEADS_PPL_EVENT_SOURCE, limit),
    ).fetchall()
    return jsonify(
        {
            "ok": True,
            "source": PROPERTYLEADS_PPL_EVENT_SOURCE,
            "count": len(rows),
            "events": [dict(row) for row in rows],
        }
    ), 200


@app.route("/api/email/poll-now", methods=["POST"])
def email_poll_now():
    try:
        ensure_db()
        db = get_db()
        provider = (get_email_settings(db).get("provider") or "gmail_api").strip().lower()
        if provider == "gmail_api":
            result = process_gmail_api_inbound_once(max_messages=12)
            return jsonify({"ok": bool(result.get("ok")), "result": result}), (200 if result.get("ok") else 500)
        return jsonify({"ok": False, "error": "API-only mode enabled. Select gmail_api or resend."}), 400
    except Exception as exc:
        ensure_db()
        db = get_db()
        log_app_error(
            db,
            source="email_poll_now",
            error_message=str(exc),
            details=traceback.format_exc(),
            route=request.path,
            status_code=500,
        )
        db.commit()
        return jsonify({"ok": False, "error": str(exc)}), 500


@app.route("/api/email/test-login", methods=["POST"])
def email_test_login():
    ensure_db()
