@app.route("/api/provider-alerts/recent", methods=["GET"])
def api_recent_provider_alerts():
    ensure_db()
    db = get_db()
    limit_raw = (request.args.get("limit") or "15").strip()
    try:
        limit = max(1, min(50, int(limit_raw)))
    except ValueError:
        limit = 15
    rows = db.execute(
        """
        SELECT id, source, route, status_code, error_message, details, created_at
        FROM app_errors
        WHERE source LIKE ?
          AND COALESCE(dismissed_at, '') = ''
        ORDER BY id DESC
        LIMIT ?
        """,
        (f"{PROVIDER_ALERT_SOURCE_PREFIX}%", limit),
    ).fetchall()
    items = []
    for row in rows:
        items.append(
            {
                "id": int(row["id"]),
                "source": row["source"],
                "provider_label": _provider_alert_label(row["source"]),
                "route": row["route"] or "",
                "status_code": row["status_code"],
                "error_message": row["error_message"] or "",
                "details": row["details"] or "",
                "created_at": row["created_at"] or "",
            }
        )
    return jsonify({"ok": True, "items": items, "count": len(items)})


@app.route("/api/provider-alerts/dismiss-all", methods=["POST"])
def dismiss_all_provider_alerts():
    ensure_db()
    db = get_db()
    cur = db.execute(
        """
        UPDATE app_errors
        SET dismissed_at = CURRENT_TIMESTAMP
        WHERE source LIKE ?
          AND COALESCE(dismissed_at, '') = ''
        """,
        (f"{PROVIDER_ALERT_SOURCE_PREFIX}%",),
    )
    db.commit()
    return jsonify({"ok": True, "dismissed": int(cur.rowcount or 0)})


@app.errorhandler(Exception)
def handle_unhandled_exception(exc):
    if isinstance(exc, HTTPException):
        return exc
    ensure_db()
    db = get_db()
    status_code = 500
    route = request.path if request else ""
    log_app_error(
        db,
        source="unhandled_exception",
        error_message=str(exc),
        details=traceback.format_exc(),
        route=route,
        status_code=status_code,
    )
    db.commit()
    if request.path.startswith("/api/"):
        payload = {"error": "Internal server error"}
        if env_flag("EXPOSE_API_ERRORS", False):
            payload["detail"] = str(exc)
        return jsonify(payload), status_code
    return render_template("error.html", message=str(exc)), status_code


